// The Weekly Review tab: GTD's weekly review as seven calm steps, one on
// screen at a time.
//
//   1. Empty the inbox          - the triage walk (Triage.tsx)
//   2. Projects with no next action - make one of its tasks NEXT, or write one
//   3. Waiting for              - chase it, finish it, or give it a date
//   4. Last week's time         - clocked against planned, per project and tag
//   5. Stale scheduled items    - reschedule, unschedule, done or archive
//   6. Someday sweep            - the triage walk over the someday pile
//   7. Done                     - what changed, and the review written down
//
// Everything the steps show comes from the server (`/review/weekly`), every
// change is an undoable `POST /review/act`, and the step a review is on is
// kept on the server per user, so a review left half way resumes here or in
// `orgs review week` alike.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Input from '@mui/joy/Input';
import Chip from '@mui/joy/Chip';
import Alert from '@mui/joy/Alert';
import Table from '@mui/joy/Table';
import Tooltip from '@mui/joy/Tooltip';
import CircularProgress from '@mui/joy/CircularProgress';
import KeyboardArrowLeftRoundedIcon from '@mui/icons-material/KeyboardArrowLeftRounded';
import KeyboardArrowRightRoundedIcon from '@mui/icons-material/KeyboardArrowRightRounded';
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import UndoRoundedIcon from '@mui/icons-material/UndoRounded';
import LaunchRoundedIcon from '@mui/icons-material/LaunchRounded';
import CelebrationRoundedIcon from '@mui/icons-material/CelebrationRounded';
import RestartAltRoundedIcon from '@mui/icons-material/RestartAltRounded';

import { useNav } from '../NavContext';
import { ReviewApi } from '../reviewApi';
import {
    ReviewItem, ReviewLast, WeeklyReview as Weekly, ReviewTimeRow, WEEK_STEPS, resumeStep, lastReviewText,
    waitedFor, hm, timeBar, timeVerdict, tallyLine,
} from '../review';
import Triage from './Triage';
import { ItemCard, StatusChip, whereOf, DatePicker, AskText, useReviewActs, Acts } from './TriageParts';

const DAYS_KEY = 'worg.weeklyReviewWaitingDays';

function stored<T>(key: string, fallback: T): T {
    try {
        const v = localStorage.getItem(key);
        return v ? JSON.parse(v) as T : fallback;
    } catch {
        return fallback;
    }
}
function store(key: string, v: any) {
    try {
        if (v === null) localStorage.removeItem(key); else localStorage.setItem(key, JSON.stringify(v));
    } catch { /* private window: forget it */ }
}

export default function WeeklyReview(_props: any) {
    const [last, setLast] = React.useState<ReviewLast | null>(null);
    const [step, setStep] = React.useState(0);
    const [resumed, setResumed] = React.useState(false);
    // What this review has done so far. Kept on the server with the step, so
    // a review resumed here or in the terminal still adds up at the end.
    const [tally, setTally] = React.useState<{ [k: string]: number }>({});
    const stepRef = React.useRef(0);
    const [days, setDays] = React.useState<number | null>(() => stored<number | null>(DAYS_KEY, null));
    const [weekly, setWeekly] = React.useState<Weekly | null>(null);
    const [finished, setFinished] = React.useState<ReviewLast | null>(null);

    React.useEffect(() => {
        ReviewApi.last().then(l => {
            setLast(l);
            const s = resumeStep(l.State);
            stepRef.current = s;
            setStep(s);
            setResumed(s > 1);
            if (s > 1) setTally(l.State.tally || {});
        });
    }, []);

    const onTally = React.useCallback((name: string, delta: number) => {
        setTally(t => {
            const next = { ...t, [name]: Math.max(0, (t[name] || 0) + delta) };
            ReviewApi.step(stepRef.current, next);
            return next;
        });
    }, []);
    const acts = useReviewActs('weekly', onTally);

    const loadWeekly = React.useCallback(async () => {
        setWeekly(await ReviewApi.weekly(days === null ? undefined : days));
    }, [days]);
    React.useEffect(() => {
        if (step >= 2 && step <= 5) loadWeekly();
    }, [step, loadWeekly]);

    const go = (n: number, t: { [k: string]: number } = tally) => {
        stepRef.current = n;
        setStep(n);
        setResumed(false);
        acts.clearMessage();
        ReviewApi.step(n, t);
    };
    const startOver = () => {
        setTally({});
        setFinished(null);
        go(1, {});
    };
    const finish = async () => {
        const r = await ReviewApi.done(tally);
        if (r.Ok) {
            setFinished(r);
            setLast(r);
            setTally({});
        }
    };

    if (!last || step === 0) return <CircularProgress sx={{ display: 'block', mx: 'auto', my: 8 }} />;
    const meta = WEEK_STEPS[step - 1];

    return (
        <Box sx={{ p: { xs: 2, md: 4 }, height: '100%', overflow: 'auto' }}>
            <Box sx={{ maxWidth: 900, mx: 'auto' }}>
                <Stepper step={step} onGo={go} />

                <Box sx={{ mt: 3, mb: 2, display: 'flex', alignItems: 'flex-end', gap: 2, flexWrap: 'wrap' }}>
                    <Box sx={{ flex: 1, minWidth: 240 }}>
                        <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>Step {step} of {WEEK_STEPS.length}</Typography>
                        <Typography level="h2">{meta.title}</Typography>
                        <Typography level="body-md" sx={{ color: 'text.secondary' }}>{meta.blurb}</Typography>
                    </Box>
                    {step >= 2 && step <= 5 && acts.canUndo && (
                        <Button size="sm" variant="plain" startDecorator={<UndoRoundedIcon />}
                            onClick={async () => { await acts.undo(); loadWeekly(); }}>Undo</Button>
                    )}
                </Box>

                {step === 1 && (
                    <Alert variant="soft" color={last.DaysAgo > 10 ? 'warning' : 'neutral'} sx={{ mb: 2 }}
                        endDecorator={resumed ? <Button size="sm" variant="plain" startDecorator={<RestartAltRoundedIcon />} onClick={startOver}>Start over</Button> : null}>
                        {lastReviewText(last.DaysAgo)}
                    </Alert>
                )}
                {resumed && step > 1 && (
                    <Alert variant="soft" sx={{ mb: 2 }}
                        endDecorator={<Button size="sm" variant="plain" startDecorator={<RestartAltRoundedIcon />} onClick={startOver}>Start over</Button>}>
                        Picking up where you left off.
                    </Alert>
                )}

                {step >= 2 && step <= 5 && acts.message && (
                    <Typography level="body-sm" sx={{ mb: 1.5 }}
                        color={acts.message.tone === 'danger' ? 'danger' : acts.message.tone === 'success' ? 'success' : 'neutral'}>
                        {acts.message.tone === 'success' ? '✓ ' : ''}{acts.message.text}
                    </Typography>
                )}
                {step >= 2 && step <= 5 && weekly && !weekly.Ok && <Alert color="danger" sx={{ mb: 2 }}>{weekly.Msg}</Alert>}
                {step >= 2 && step <= 5 && !weekly && <CircularProgress sx={{ display: 'block', mx: 'auto', my: 6 }} />}

                {step === 1 && <Triage mode="inbox" embedded onTally={onTally} backApp="WeeklyReview" />}
                {step === 2 && weekly?.Ok && <StepProjects data={weekly} acts={acts} reload={loadWeekly} />}
                {step === 3 && weekly?.Ok && (
                    <StepWaiting data={weekly} acts={acts} reload={loadWeekly} days={days ?? weekly.WaitingDays}
                        setDays={d => { setDays(d); store(DAYS_KEY, d); }} />
                )}
                {step === 4 && weekly?.Ok && <StepTime data={weekly} />}
                {step === 5 && weekly?.Ok && <StepStale data={weekly} acts={acts} reload={loadWeekly} />}
                {step === 6 && <Triage mode="someday" embedded onTally={onTally} backApp="WeeklyReview" />}
                {step === 7 && <StepDone tally={tally} finished={finished} onFinish={finish} onAgain={startOver} />}

                <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 4, pt: 2, borderTop: '1px solid', borderColor: 'divider' }}>
                    <Button variant="plain" color="neutral" disabled={step === 1} startDecorator={<KeyboardArrowLeftRoundedIcon />}
                        onClick={() => go(step - 1)}>{step > 1 ? WEEK_STEPS[step - 2].title : 'Back'}</Button>
                    {step < WEEK_STEPS.length && (
                        <Button endDecorator={<KeyboardArrowRightRoundedIcon />} onClick={() => go(step + 1)}>
                            {WEEK_STEPS[step].title}
                        </Button>
                    )}
                </Box>
            </Box>
        </Box>
    );
}

// The steps across the top: where you are, what is behind and ahead. Any of
// them can be clicked - a review is a checklist, not a form.
function Stepper(props: { step: number; onGo: (n: number) => void }) {
    return (
        <Box sx={{ display: 'flex', alignItems: 'flex-start' }}>
            {WEEK_STEPS.map((s, i) => {
                const n = i + 1;
                const done = n < props.step;
                const here = n === props.step;
                return (
                    <React.Fragment key={s.key}>
                        {i > 0 && <Box sx={{ flex: 1, height: 2, mt: '13px', bgcolor: done || here ? 'primary.300' : 'neutral.outlinedBorder', minWidth: 8 }} />}
                        <Box onClick={() => props.onGo(n)} title={s.title}
                            sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', cursor: 'pointer', width: { xs: 28, md: 84 } }}>
                            <Box sx={{
                                width: 28, height: 28, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                fontSize: 'sm', fontWeight: 'lg', transition: 'all .2s',
                                bgcolor: here ? 'primary.solidBg' : done ? 'primary.softBg' : 'background.level1',
                                color: here ? 'primary.solidColor' : done ? 'primary.softColor' : 'text.tertiary',
                                boxShadow: here ? 'md' : 'none',
                            }}>{done ? <CheckRoundedIcon sx={{ fontSize: 18 }} /> : n}</Box>
                            <Typography level="body-xs" sx={{
                                display: { xs: 'none', md: 'block' }, textAlign: 'center', mt: 0.5, lineHeight: 1.2,
                                color: here ? 'text.primary' : 'text.tertiary', fontWeight: here ? 'lg' : 'md',
                            }}>{s.title}</Typography>
                        </Box>
                    </React.Fragment>
                );
            })}
        </Box>
    );
}

function OpenButton(props: { item: ReviewItem }) {
    const nav = useNav();
    return (
        <Tooltip title="Open it in the Files tab">
            <IconButton size="sm" variant="plain" onClick={() => nav.toFile({
                filename: props.item.Filename, line: props.item.LineNum, heading: props.item.Headline,
                back: { app: 'WeeklyReview', label: 'Back to the review' },
            })}><LaunchRoundedIcon /></IconButton>
        </Tooltip>
    );
}

function Clear(props: { text: string }) {
    return (
        <Box sx={{ textAlign: 'center', py: 5 }}>
            <CheckRoundedIcon sx={{ fontSize: 48, color: 'success.400' }} />
            <Typography level="title-lg" sx={{ mt: 1 }}>{props.text}</Typography>
        </Box>
    );
}

// One heading as a row of a step's list: what it is, where, a line saying
// why it is here, and the step's buttons.
function Row(props: { item: ReviewItem; why?: React.ReactNode; children?: React.ReactNode }) {
    const it = props.item;
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'md', p: 1.5, display: 'flex', gap: 1.5, alignItems: 'center', flexWrap: 'wrap' }}>
            <Box sx={{ flex: 1, minWidth: 220 }}>
                <Typography component="div" level="title-md" sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
                    <StatusChip status={it.Status} />{it.Headline}
                    {(it.Tags || []).map(t => <Chip key={t} size="sm" variant="soft" color="primary">{t}</Chip>)}
                </Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{whereOf(it)}</Typography>
                {props.why && <Typography level="body-sm" sx={{ color: 'warning.plainColor', mt: 0.25 }}>{props.why}</Typography>}
            </Box>
            <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                {props.children}
                <OpenButton item={it} />
            </Box>
        </Sheet>
    );
}

// ── 2. Projects with no next action ─────────────────────────────────────────

function StepProjects(props: { data: Weekly; acts: Acts; reload: () => void }) {
    const stuck = props.data.Stuck || [];
    const [adding, setAdding] = React.useState<{ [hash: string]: string }>({});
    const act = async (it: ReviewItem, req: Parameters<Acts['act']>[1]) => {
        await props.acts.act(it, req);
        props.reload();
    };
    if (stuck.length === 0) return <Clear text="Every project has a next action." />;
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {stuck.map(p => (
                <ItemCard key={p.Project.Hash} item={{ ...p.Project, Body: '' }} extra={
                    <Box sx={{ mt: 1.5 }}>
                        {(p.Open || []).length > 0 && (
                            <>
                                <Typography level="body-sm" sx={{ color: 'text.tertiary', mb: 0.5 }}>Is one of these the next thing to do?</Typography>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, mb: 1.5 }}>
                                    {(p.Open || []).map(c => (
                                        <Box key={c.Hash} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                            <StatusChip status={c.Status} />
                                            <Typography level="body-md" sx={{ flex: 1 }}>{c.Headline}</Typography>
                                            <Button size="sm" variant="soft" onClick={() => act(c, { Action: 'status', Keyword: 'NEXT' })}>Make it NEXT</Button>
                                        </Box>
                                    ))}
                                </Box>
                            </>
                        )}
                        <Input size="sm" placeholder="…or write the next action, and press Enter"
                            value={adding[p.Project.Hash] || ''}
                            onChange={e => setAdding({ ...adding, [p.Project.Hash]: e.target.value })}
                            onKeyDown={e => {
                                const text = (adding[p.Project.Hash] || '').trim();
                                if (e.key === 'Enter' && text) {
                                    setAdding({ ...adding, [p.Project.Hash]: '' });
                                    act(p.Project, { Action: 'next', Text: text });
                                }
                            }} />
                    </Box>
                } />
            ))}
        </Box>
    );
}

// ── 3. Waiting for ──────────────────────────────────────────────────────────

function StepWaiting(props: { data: Weekly; acts: Acts; reload: () => void; days: number; setDays: (d: number) => void }) {
    const items = props.data.Waiting || [];
    const [dateFor, setDateFor] = React.useState<ReviewItem | null>(null);
    const [chaseFor, setChaseFor] = React.useState<ReviewItem | null>(null);
    const act = async (it: ReviewItem, req: Parameters<Acts['act']>[1]) => {
        setDateFor(null);
        setChaseFor(null);
        await props.acts.act(it, req);
        props.reload();
    };
    return (
        <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                <Typography level="body-md">Waiting longer than</Typography>
                <Input type="number" size="sm" value={props.days} sx={{ width: 80 }}
                    slotProps={{ input: { min: 0, max: 365 } }}
                    onChange={e => { const n = parseInt(e.target.value, 10); if (!isNaN(n) && n >= 0) props.setDays(n); }} />
                <Typography level="body-md">days</Typography>
            </Box>
            {items.length === 0 ? <Clear text="Nothing has waited too long." /> : (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                    {items.map(it => (
                        <Row key={it.Hash} item={it} why={waitedFor(it)}>
                            <Button size="sm" variant="soft" color="primary" onClick={() => setChaseFor(it)}>Chase</Button>
                            <Button size="sm" variant="soft" color="success" onClick={() => act(it, { Action: 'done' })}>Done</Button>
                            <Button size="sm" variant="soft" onClick={() => setDateFor(it)}>Reschedule</Button>
                        </Row>
                    ))}
                </Box>
            )}
            <AskText open={!!chaseFor} title={`Chased “${chaseFor?.Headline || ''}”`} allowEmpty
                placeholder="a note to keep with it: who, how (optional)"
                onClose={() => setChaseFor(null)} onSubmit={text => chaseFor && act(chaseFor, { Action: 'chase', Text: text })} />
            <DatePicker open={!!dateFor} title={`Follow up “${dateFor?.Headline || ''}” on`} current={dateFor?.Scheduled}
                onClose={() => setDateFor(null)} onPick={when => dateFor && act(dateFor, { Action: 'schedule', When: when })} />
        </Box>
    );
}

// ── 4. Last week's time ─────────────────────────────────────────────────────

function StepTime(props: { data: Weekly }) {
    const t = props.data.Time;
    if (!t || (t.Clocked === 0 && t.Planned === 0)) {
        return <Clear text="Nothing was clocked, and nothing with an EFFORT was planned, last week." />;
    }
    const over = t.Clocked - t.Planned;
    return (
        <Box>
            <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 3 }}>
                <Big label="clocked" value={hm(t.Clocked)} />
                <Big label="planned" value={hm(t.Planned)} />
                <Big label={over >= 0 ? 'over the plan' : 'under the plan'} value={hm(Math.abs(over))} />
                <Typography level="body-sm" sx={{ color: 'text.tertiary', alignSelf: 'flex-end' }}>{t.From} – {t.To}</Typography>
            </Box>
            <TimeTable title="By project" rows={t.Projects || []} />
            <Box sx={{ height: 24 }} />
            <TimeTable title="By tag" rows={t.Tags || []}
                note="A heading counts once for each of its tags, so these do not add up to the total." />
            <Box sx={{ display: 'flex', gap: 2, mt: 2, alignItems: 'center' }}>
                <Swatch color="primary.500" label="clocked, within the plan" />
                <Swatch color="primary.softBg" label="planned, not spent" />
                <Swatch color="warning.400" label="clocked over the plan" />
            </Box>
        </Box>
    );
}

function Big(props: { label: string; value: string }) {
    return (
        <Sheet variant="soft" sx={{ borderRadius: 'md', px: 2, py: 1, minWidth: 110 }}>
            <Typography level="h3" sx={{ fontVariantNumeric: 'tabular-nums' }}>{props.value}</Typography>
            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{props.label}</Typography>
        </Sheet>
    );
}

function Swatch(props: { color: string; label: string }) {
    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
            <Box sx={{ width: 12, height: 12, borderRadius: '3px', bgcolor: props.color }} />
            <Typography level="body-xs">{props.label}</Typography>
        </Box>
    );
}

function TimeTable(props: { title: string; rows: ReviewTimeRow[]; note?: string }) {
    if (props.rows.length === 0) return null;
    const most = Math.max(...props.rows.map(r => Math.max(r.Clocked, r.Planned)));
    return (
        <Box>
            <Typography level="title-md" sx={{ mb: 0.5 }}>{props.title}</Typography>
            {props.note && <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.5 }}>{props.note}</Typography>}
            <Table size="sm" sx={{ '& td': { verticalAlign: 'middle' }, tableLayout: 'fixed' }}>
                <thead>
                    <tr>
                        <th style={{ width: '32%' }}></th>
                        <th style={{ width: 70, textAlign: 'right' }}>clocked</th>
                        <th style={{ width: 70, textAlign: 'right' }}>planned</th>
                        <th></th>
                        <th style={{ width: 130 }}></th>
                    </tr>
                </thead>
                <tbody>
                    {props.rows.map(r => {
                        const b = timeBar(r.Clocked, r.Planned, most);
                        return (
                            <tr key={r.Kind + r.Name + (r.Hash || r.Filename || '')}>
                                <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={r.Name}>
                                    {r.Name}{r.Kind === 'file' && <Typography level="body-xs" sx={{ color: 'text.tertiary' }} component="span"> (no project)</Typography>}
                                </td>
                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hm(r.Clocked)}</td>
                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hm(r.Planned)}</td>
                                <td>
                                    <Box sx={{ display: 'flex', height: 10, borderRadius: '5px', overflow: 'hidden', bgcolor: 'background.level1' }}>
                                        <Box sx={{ width: `${b.within}%`, bgcolor: 'primary.500' }} />
                                        <Box sx={{ width: `${b.unspent}%`, bgcolor: 'primary.softBg' }} />
                                        <Box sx={{ width: `${b.over}%`, bgcolor: 'warning.400' }} />
                                    </Box>
                                </td>
                                <td><Typography level="body-xs" sx={{ color: 'text.secondary' }}>{timeVerdict(r)}</Typography></td>
                            </tr>
                        );
                    })}
                </tbody>
            </Table>
        </Box>
    );
}

// ── 5. Stale scheduled items ────────────────────────────────────────────────

function StepStale(props: { data: Weekly; acts: Acts; reload: () => void }) {
    const items = props.data.Stale || [];
    const [dateFor, setDateFor] = React.useState<ReviewItem | null>(null);
    const act = async (it: ReviewItem, req: Parameters<Acts['act']>[1]) => {
        setDateFor(null);
        await props.acts.act(it, req);
        props.reload();
    };
    if (items.length === 0) return <Clear text="Nothing scheduled has slipped by untouched." />;
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            {items.map(it => (
                <Row key={it.Hash} item={it} why={`scheduled ${it.Scheduled}, ${it.Days} day${it.Days === 1 ? '' : 's'} ago, untouched since`}>
                    <Button size="sm" variant="soft" color="primary" onClick={() => setDateFor(it)}>Reschedule</Button>
                    <Button size="sm" variant="soft" onClick={() => act(it, { Action: 'unschedule' })}>Unschedule</Button>
                    <Button size="sm" variant="soft" color="success" onClick={() => act(it, { Action: 'done' })}>Done</Button>
                    <Button size="sm" variant="soft" color="danger" onClick={() => act(it, { Action: 'archive' })}>Archive</Button>
                </Row>
            ))}
            <DatePicker open={!!dateFor} title={`Reschedule “${dateFor?.Headline || ''}”`} current={dateFor?.Scheduled}
                onClose={() => setDateFor(null)} onPick={when => dateFor && act(dateFor, { Action: 'schedule', When: when })} />
        </Box>
    );
}

// ── 7. Done ─────────────────────────────────────────────────────────────────

function StepDone(props: { tally: { [k: string]: number }; finished: ReviewLast | null; onFinish: () => void; onAgain: () => void }) {
    const line = tallyLine(props.tally);
    if (props.finished) {
        const next = new Date();
        next.setDate(next.getDate() + 7);
        const history = props.finished.State.history || [];
        return (
            <Box sx={{ textAlign: 'center', py: 4 }}>
                <CelebrationRoundedIcon sx={{ fontSize: 64, color: 'success.400' }} />
                <Typography level="h3" sx={{ mt: 1 }}>Weekly review done.</Typography>
                <Typography level="body-md" sx={{ color: 'text.secondary' }}>
                    Recorded. The next one is due around {next.toDateString()}.
                </Typography>
                {history.length > 1 && (
                    <Typography level="body-sm" sx={{ color: 'text.tertiary', mt: 2 }}>
                        {history.length} reviews on record, the one before this on {new Date(history[1].done).toDateString()}.
                    </Typography>
                )}
                <Button variant="plain" sx={{ mt: 2 }} startDecorator={<RestartAltRoundedIcon />} onClick={props.onAgain}>Review again</Button>
            </Box>
        );
    }
    return (
        <Box sx={{ textAlign: 'center', py: 4 }}>
            <Typography level="title-lg">{line ? 'This review:' : 'Nothing needed changing this week.'}</Typography>
            {line && <Typography level="h4" sx={{ mt: 1 }}>{line}</Typography>}
            <Button size="lg" sx={{ mt: 3 }} startDecorator={<CheckRoundedIcon />} onClick={props.onFinish}>Finish the review</Button>
        </Box>
    );
}
