// The bell in the page header: what the watched saved queries have found.
//
// A watch is a saved query the server re-runs whenever the org files change
// (and every few minutes, for queries that move with the clock), saying when it
// finds a heading it had not found before. The bell carries the unread count;
// a click opens the list - which watch, the headings it gained (each opens in
// the Files tab), the ones that left it for a watch that asked, and when.
//
// Nothing at all when nothing is watched and nothing has been found, like the
// focus chip: the header shows a feature at work, it does not advertise one.
// Watches are made with the bell beside each query in the Saved Queries tab,
// or `orgs q watch` in the terminal.
//
// The header sits outside NavContext's provider, so opening a heading goes
// through the same window event the focus chip uses (focusNavigate).
//
// `compact` is the phone header: the button only, and a panel that fits.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Badge from '@mui/joy/Badge';
import Divider from '@mui/joy/Divider';
import Switch from '@mui/joy/Switch';
import Chip from '@mui/joy/Chip';
import Popper from '@mui/material/Popper';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import BellIcon from '@mui/icons-material/NotificationsNone';
import BellActiveIcon from '@mui/icons-material/NotificationsActive';
import ManageIcon from '@mui/icons-material/TuneRounded';

import { focusNavigate, notificationsSupported } from '../focusApi';
import {
    useWatches, markRead, clearNotifications, watchNotificationsOn, setWatchNotifications,
} from '../querywatchApi';
import { badgeText, relativeTime, whereOf, WatchMatch, WatchNotice } from '../querywatch';

function HeadingLine({ m, gone, onOpen }: { m: WatchMatch; gone?: boolean; onOpen: (m: WatchMatch) => void }) {
    return (
        <Box
            component={gone ? 'div' : 'button'}
            onClick={gone ? undefined : () => onOpen(m)}
            title={gone ? 'No longer matches' : `Open ${m.headline} in the Files tab`}
            sx={{
                display: 'block', width: '100%', textAlign: 'left', font: 'inherit',
                border: 0, bgcolor: 'transparent', borderRadius: 'sm', px: 0.75, py: 0.25,
                cursor: gone ? 'default' : 'pointer', color: 'inherit',
                '&:hover': gone ? {} : { bgcolor: 'background.level1' },
                '&:focus-visible': { outline: '2px solid', outlineColor: 'focusVisible' },
            }}
        >
            <Typography
                level="body-sm"
                sx={{
                    overflowWrap: 'anywhere',
                    textDecoration: gone ? 'line-through' : 'none',
                    color: gone ? 'text.tertiary' : 'text.primary',
                }}
                startDecorator={m.status
                    ? <Chip size="sm" variant="soft" color={gone ? 'neutral' : 'warning'} sx={{ fontSize: 10, minHeight: 18 }}>{m.status}</Chip>
                    : undefined}
            >
                {m.headline}
            </Typography>
            <Typography level="body-xs" sx={{ color: 'text.tertiary', overflowWrap: 'anywhere' }}>
                {whereOf(m)}
            </Typography>
        </Box>
    );
}

function NoticeItem({ n, onOpen }: { n: WatchNotice; onOpen: (n: WatchNotice, m: WatchMatch) => void }) {
    const gained = n.gained || [];
    const left = n.left || [];
    return (
        <Box sx={{
            px: 1, py: 0.75, borderRadius: 'sm',
            borderLeft: '3px solid',
            borderLeftColor: n.read ? 'transparent' : 'primary.500',
            bgcolor: n.read ? 'transparent' : 'primary.softBg',
        }}>
            <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1 }}>
                <Typography level="title-sm" noWrap sx={{ minWidth: 0 }}>{n.label}</Typography>
                <Typography level="body-xs" sx={{ ml: 'auto', flexShrink: 0, color: 'text.tertiary' }} title={n.at}>
                    {relativeTime(n.at)}
                </Typography>
            </Box>
            <Typography level="body-xs" sx={{ color: 'text.secondary', mb: 0.25 }}>
                {gained.length > 0 && `${gained.length} new`}
                {gained.length > 0 && left.length > 0 && ' · '}
                {left.length > 0 && `${left.length} gone`}
                {` · ${n.count} matching now`}
            </Typography>
            {gained.map(m => <HeadingLine key={'g' + m.key} m={m} onOpen={m2 => onOpen(n, m2)} />)}
            {left.map(m => <HeadingLine key={'l' + m.key} m={m} gone onOpen={() => {}} />)}
        </Box>
    );
}

export default function NotificationBell({ compact = false }: { compact?: boolean }) {
    const { notices, watches, loaded } = useWatches();
    const anchor = React.useRef<HTMLButtonElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const [browser, setBrowser] = React.useState(watchNotificationsOn());

    const unread = notices.unread;
    const watching = watches.watches.filter(w => !w.paused).length;
    if (!loaded || (watches.watches.length === 0 && notices.total === 0)) return null;

    const openHeading = (n: WatchNotice, m: WatchMatch) => {
        setOpen(false);
        if (!n.read) markRead([n.id]);
        focusNavigate({ app: 'Files', filename: m.file, heading: m.headline });
    };

    const label = unread > 0
        ? `${unread} unread notification${unread === 1 ? '' : 's'} from watched queries`
        : 'Notifications from watched queries';

    return (
        <>
            <Badge
                badgeContent={badgeText(unread)}
                invisible={unread === 0}
                color="danger"
                size="sm"
                badgeInset="14%"
            >
                <IconButton
                    ref={anchor}
                    size="sm"
                    variant={open ? 'soft' : 'plain'}
                    color={unread > 0 ? 'primary' : 'neutral'}
                    aria-label={label}
                    title={label}
                    onClick={() => setOpen(o => !o)}
                >
                    {unread > 0 ? <BellActiveIcon /> : <BellIcon />}
                </IconButton>
            </Badge>
            <Popper
                open={open}
                anchorEl={anchor.current}
                placement="bottom-end"
                style={{ zIndex: 10000 }}
                modifiers={[{ name: 'offset', options: { offset: [0, 8] } }]}
            >
                <ClickAwayListener onClickAway={() => setOpen(false)}>
                    <Sheet
                        variant="outlined"
                        onKeyDown={e => { if (e.key === 'Escape') setOpen(false); }}
                        sx={{
                            p: 1, borderRadius: 'md', boxShadow: 'lg',
                            width: compact ? 'min(340px, calc(100vw - 16px))' : 380,
                            maxHeight: '70vh', display: 'flex', flexDirection: 'column', gap: 0.75,
                        }}
                    >
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 0.5 }}>
                            <Typography level="title-md">Notifications</Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                {watching} watch{watching === 1 ? '' : 'es'}
                            </Typography>
                            <Button size="sm" variant="plain" sx={{ ml: 'auto' }} disabled={unread === 0}
                                onClick={() => markRead('all')}>
                                Mark all read
                            </Button>
                        </Box>
                        <Divider />
                        <Box sx={{ overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 0.75, minHeight: 0 }}>
                            {notices.notices.length === 0 ? (
                                <Typography level="body-sm" sx={{ color: 'text.secondary', p: 1.5, textAlign: 'center' }}>
                                    Nothing new yet. When a watched query finds a heading it did not find before, it shows up here.
                                </Typography>
                            ) : notices.notices.map(n => <NoticeItem key={n.id} n={n} onOpen={openHeading} />)}
                        </Box>
                        <Divider />
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', px: 0.5 }}>
                            <Button size="sm" variant="plain" color="neutral" startDecorator={<ManageIcon />}
                                onClick={() => { setOpen(false); focusNavigate({ app: 'StoredQueries' }); }}>
                                Manage watches
                            </Button>
                            {notices.total > 0 && (
                                <Button size="sm" variant="plain" color="neutral" onClick={() => clearNotifications()}>
                                    Clear
                                </Button>
                            )}
                            {notificationsSupported() && (
                                <Typography
                                    component="label"
                                    level="body-xs"
                                    sx={{ ml: 'auto', display: 'flex', alignItems: 'center', gap: 0.75, cursor: 'pointer' }}
                                    title="Also show a notification from this browser when a watch finds something"
                                    endDecorator={
                                        <Switch
                                            size="sm"
                                            checked={browser}
                                            onChange={async e => setBrowser(await setWatchNotifications(e.target.checked))}
                                        />
                                    }
                                >
                                    Browser alerts
                                </Typography>
                            )}
                        </Box>
                    </Sheet>
                </ClickAwayListener>
            </Popper>
        </>
    );
}
