// The focus session as the rest of worg sees it: the endpoints, and one live
// copy of the state that every view shares.
//
// There is one store, not one per component, because the header chip, the
// phone header's chip and the Focus tab are all on screen at once and three
// event streams, three pollers and three notifications for one pomodoro would
// be silly. The store opens the stream when the first view subscribes and
// closes it when the last one goes.
//
// How it stays current:
//  1. GET /events (EventSource), narrowed to the focus kinds. Any of them means
//     "ask again". EventSource cannot send an Authorization header, so the
//     stream rests on the `orgstoken` cookie login sets; across origins that
//     needs a credentialed request, and a server whose CORS will not allow one
//     refuses it - so a stream that fails before it ever opened is tried once
//     more without credentials (enough under noAuth), and after that polling
//     carries it alone.
//  2. A poll: every 30 seconds with the stream up, every 10 without it, and
//     whenever the tab comes back into view.
//  3. A one second tick, only while a phase runs, that moves the countdown on
//     locally and keeps the tab's title showing it. When the countdown passes
//     zero the server is asked straight away rather than waiting for the event.

import * as React from 'react';
import { ODb } from './db';
import { Sets } from './config';
import {
    FocusState, FocusHistory, IDLE, localEnd, remainingAt, isRunning, tabTitle, transitionNotice,
} from './focus';

function url(path: string): URL {
    return new URL(Sets.orgsConnection + path);
}

export async function getFocus(): Promise<FocusState> {
    return answer(await ODb.doGet<FocusState>(url('/focus')));
}

export async function focusHistory(days = 1): Promise<FocusHistory> {
    const u = url('/focus/history');
    u.searchParams.set('days', String(days));
    const h = await ODb.doGet<FocusHistory>(u);
    return h && Array.isArray(h.Records) ? h : { Ok: false, Today: 0, TodayMinutes: 0, Records: [] };
}

export type StartOptions = { hash?: string; work?: number; short?: number; long?: number; longEvery?: number; autoNext?: boolean };

export async function startFocus(o: StartOptions = {}): Promise<FocusState> {
    const body: any = {};
    if (o.hash) body.Hash = o.hash;
    if (o.work) body.Work = o.work;
    if (o.short) body.Short = o.short;
    if (o.long) body.Long = o.long;
    if (o.longEvery) body.LongEvery = o.longEvery;
    if (o.autoNext !== undefined) body.AutoNext = o.autoNext;
    return accept(await ODb.doPost<FocusState>(url('/focus/start'), body));
}

export async function stopFocus(): Promise<FocusState> {
    return accept(await ODb.doPost<FocusState>(url('/focus/stop'), {}));
}

export async function extendFocus(minutes = 5): Promise<FocusState> {
    return accept(await ODb.doPost<FocusState>(url('/focus/extend'), { Minutes: minutes }));
}

export async function skipFocus(): Promise<FocusState> {
    return accept(await ODb.doPost<FocusState>(url('/focus/skip'), {}));
}

// doGet/doPost answer [] when the request itself failed; make that a state
// that says so rather than something every caller has to check the shape of.
const NO_ANSWER = 'The server did not answer.';

function answer(s: any): FocusState {
    if (!s || Array.isArray(s) || !s.Phase) {
        return { ...IDLE, Ok: false, Msg: NO_ANSWER };
    }
    return s as FocusState;
}

// A write's answer is the state after it, so it is taken into the store at
// once - the button that was pressed redraws without waiting for the event.
function accept(s: any): FocusState {
    const st = answer(s);
    // A refusal still carries the real state; only a missing answer does not.
    if (st.Msg !== NO_ANSWER) store.take(st);
    return st;
}

// ---------------------------------------------------------------------------
// The store
// ---------------------------------------------------------------------------

export type FocusSnapshot = {
    state: FocusState;
    // Seconds left, ticked locally.
    remaining: number;
    // The stream is up.
    live: boolean;
    // Bumped whenever the state is taken, so a view can re-read history.
    version: number;
};

type Listener = (s: FocusSnapshot) => void;

const KINDS = 'focusstart,focusend,breakstart,breakend,focusstop,focusextend';
const NOTIFY_KEY = 'focusNotify';

class FocusStore {
    private snap: FocusSnapshot = { state: IDLE, remaining: 0, live: false, version: 0 };
    private loaded = false;
    private end = 0;
    private listeners = new Set<Listener>();
    private es: EventSource | null = null;
    private credentialed = true;
    private everOpened = false;
    private poll: ReturnType<typeof setInterval> | null = null;
    private ticker: ReturnType<typeof setInterval> | null = null;
    private baseTitle: string | null = null;
    private asking = false;

    get(): FocusSnapshot {
        return this.snap;
    }

    subscribe(l: Listener): () => void {
        this.listeners.add(l);
        if (this.listeners.size === 1) this.open();
        l(this.snap);
        return () => {
            this.listeners.delete(l);
            if (this.listeners.size === 0) this.close();
        };
    }

    take(st: FocusState) {
        const prev = this.snap.state;
        const first = !this.loaded;
        this.loaded = true;
        this.end = localEnd(st, Date.now());
        this.snap = { ...this.snap, state: st, remaining: remainingAt(this.end, Date.now()), version: this.snap.version + 1 };
        if (!first) this.notify(prev, st);
        this.runTicker();
        this.emit();
    }

    async refresh() {
        if (this.asking) return;
        this.asking = true;
        try {
            const st = await getFocus();
            if (st.Msg !== NO_ANSWER) this.take(st);
        } finally {
            this.asking = false;
        }
    }

    private emit() {
        this.updateTitle();
        this.listeners.forEach(l => l(this.snap));
    }

    private open() {
        this.refresh();
        this.connect();
        this.schedulePoll();
        document.addEventListener('visibilitychange', this.onVisible);
    }

    private close() {
        this.es?.close();
        this.es = null;
        if (this.poll) clearInterval(this.poll);
        this.poll = null;
        if (this.ticker) clearInterval(this.ticker);
        this.ticker = null;
        document.removeEventListener('visibilitychange', this.onVisible);
        this.restoreTitle();
    }

    private onVisible = () => {
        if (document.visibilityState === 'visible') this.refresh();
    };

    private connect() {
        if (typeof EventSource === 'undefined') return;
        let es: EventSource;
        try {
            es = new EventSource(Sets.orgsConnection + '/events?kinds=' + KINDS, { withCredentials: this.credentialed });
        } catch {
            return;
        }
        this.es = es;
        es.onopen = () => {
            this.everOpened = true;
            this.setLive(true);
        };
        es.onmessage = () => {
            // Every kind asked for means the state moved: ask what it is now.
            // (`hello` arrives on connect; asking then also catches up on
            // whatever happened while the stream was down.)
            this.refresh();
        };
        es.onerror = () => {
            this.setLive(false);
            if (!this.everOpened && this.credentialed) {
                // Probably refused over CORS credentials; try once without.
                es.close();
                this.credentialed = false;
                this.connect();
            } else if (!this.everOpened) {
                // Never worked either way: leave it to the poller.
                es.close();
                this.es = null;
            }
            // Otherwise EventSource reconnects by itself.
        };
    }

    private setLive(live: boolean) {
        if (this.snap.live === live) return;
        this.snap = { ...this.snap, live };
        this.schedulePoll();
        this.emit();
    }

    private schedulePoll() {
        if (this.poll) clearInterval(this.poll);
        if (this.listeners.size === 0) return;
        this.poll = setInterval(() => this.refresh(), this.snap.live ? 30000 : 10000);
    }

    private runTicker() {
        const running = isRunning(this.snap.state);
        if (running && !this.ticker) {
            this.ticker = setInterval(() => this.tick(), 1000);
        } else if (!running && this.ticker) {
            clearInterval(this.ticker);
            this.ticker = null;
        }
    }

    private tick() {
        const remaining = remainingAt(this.end, Date.now());
        // Out of time: the server moves the phase on within a second and says
        // so; asking here as well covers an event that went missing.
        if (remaining <= 0 && this.snap.remaining > 0) setTimeout(() => this.refresh(), 1200);
        if (remaining <= 0 && Math.floor(Date.now() / 1000) % 5 === 0) this.refresh();
        this.snap = { ...this.snap, remaining };
        this.emit();
    }

    private updateTitle() {
        const t = tabTitle(this.snap.state, this.snap.remaining);
        if (t) {
            if (this.baseTitle === null) this.baseTitle = document.title;
            document.title = t;
        } else {
            this.restoreTitle();
        }
    }

    private restoreTitle() {
        if (this.baseTitle !== null) {
            document.title = this.baseTitle;
            this.baseTitle = null;
        }
    }

    private notify(prev: FocusState, next: FocusState) {
        const n = transitionNotice(prev, next);
        if (!n || !notificationsOn()) return;
        try {
            const note = new Notification(n.title, { body: n.body, tag: 'orgs-focus' });
            note.onclick = () => { window.focus(); note.close(); };
        } catch {
            // Some browsers only allow notifications from a service worker.
        }
    }
}

export const store = new FocusStore();

// The session, live, for a component. Subscribing is what opens the stream.
export function useFocus(): FocusSnapshot {
    const [snap, setSnap] = React.useState<FocusSnapshot>(store.get());
    React.useEffect(() => store.subscribe(setSnap), []);
    return snap;
}

// ---------------------------------------------------------------------------
// Notifications
// ---------------------------------------------------------------------------

export function notificationsSupported(): boolean {
    return typeof window !== 'undefined' && 'Notification' in window;
}

export function notificationsOn(): boolean {
    if (!notificationsSupported() || Notification.permission !== 'granted') return false;
    try {
        return localStorage.getItem(NOTIFY_KEY) !== 'off';
    } catch {
        return true;
    }
}

// Asked from a click, never on load: browsers ignore (and some penalise) a
// permission prompt nobody asked for.
export async function setNotifications(on: boolean): Promise<boolean> {
    try {
        localStorage.setItem(NOTIFY_KEY, on ? 'on' : 'off');
    } catch {
        // private mode; the permission alone decides
    }
    if (!on || !notificationsSupported()) return false;
    if (Notification.permission === 'default') {
        await Notification.requestPermission();
    }
    return notificationsOn();
}

// ---------------------------------------------------------------------------
// Getting from the header to the rest of worg
// ---------------------------------------------------------------------------

// The header chip sits outside NavContext's provider (it is part of the page
// chrome, not of a panel), so it asks App to move by a window event.
export const FOCUS_NAV_EVENT = 'worg:focus-nav';
export type FocusNav = { app: string; filename?: string; heading?: string };

export function focusNavigate(nav: FocusNav) {
    window.dispatchEvent(new CustomEvent<FocusNav>(FOCUS_NAV_EVENT, { detail: nav }));
}
