// The Insights endpoints (internal/app/orgs/insights.go): effort against the
// clock, and dependency health. Kept out of db.ts so the tab's calls live
// together.

import { ODb } from './db';
import { Sets } from './config';
import { EstimateReport, DepReport, EstimateAsk, estimateParams } from './insights';

function url(path: string, params: Record<string, string>): URL {
    const u = new URL(Sets.orgsConnection + path);
    for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
    return u;
}

// A failed fetch comes back from doGet as `[]`; say so instead of letting a
// report that is not there read as "nothing measured".
function failed<T extends { Ok: boolean; Msg?: string }>(r: any, what: string): T {
    if (!r || Array.isArray(r)) return { Ok: false, Msg: `could not reach the server for ${what}` } as T;
    return r as T;
}

export class InsightsApi {
    static async estimates(ask: EstimateAsk, signal: AbortSignal | null = null): Promise<EstimateReport> {
        return failed<EstimateReport>(await ODb.doGet<EstimateReport>(url('/insights/estimates', estimateParams(ask)), signal), 'the estimates');
    }

    static async deps(query: string, min: number, signal: AbortSignal | null = null): Promise<DepReport> {
        const p: Record<string, string> = { min: String(min) };
        if (query.trim()) p.query = query.trim();
        return failed<DepReport>(await ODb.doGet<DepReport>(url('/insights/deps', p), signal), 'the dependencies');
    }
}
