// The Inbox tab: triage, and the someday sweep, one heading at a time.
//
// What the inbox is comes from the server (`review.inbox`, by default the top
// of every inbox.org); the walk itself is Triage.tsx, shared with the weekly
// review. The toggle is remembered in this browser only.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Button from '@mui/joy/Button';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import InboxRoundedIcon from '@mui/icons-material/InboxRounded';
import WbTwilightRoundedIcon from '@mui/icons-material/WbTwilightRounded';

import Triage, { TriageMode } from './Triage';

const KEY = 'worg.inboxMode';

function remembered(): TriageMode {
    try {
        return localStorage.getItem(KEY) === 'someday' ? 'someday' : 'inbox';
    } catch {
        return 'inbox';
    }
}

export default function Inbox(_props: any) {
    const [mode, setMode] = React.useState<TriageMode>(remembered);
    const choose = (m: TriageMode | null) => {
        if (!m) return;
        setMode(m);
        try { localStorage.setItem(KEY, m); } catch { /* private window: forget it */ }
    };
    return (
        <Box sx={{ p: { xs: 2, md: 4 }, height: '100%', overflow: 'auto' }}>
            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
                {/* Buttons straight inside the group: a Tooltip between them breaks the toggle. */}
                <ToggleButtonGroup value={mode} onChange={(_e, v) => choose(v as TriageMode | null)} size="sm">
                    <Button value="inbox" startDecorator={<InboxRoundedIcon />} title="Decide about what came in">Inbox</Button>
                    <Button value="someday" startDecorator={<WbTwilightRoundedIcon />} title="Keep, bring back or let go of the someday pile">Someday sweep</Button>
                </ToggleButtonGroup>
            </Box>
            <Triage key={mode} mode={mode} backApp="Inbox" />
        </Box>
    );
}
