// What inbox triage and the weekly review share: the heading drawn large, the
// three small pickers (where it goes, when, which tags), the key legend, and
// the act-and-undo hook every decision goes through.
//
// The pickers are small modals rather than menus because each holds a text box
// and a list, and a menu takes the arrow keys and the typing for itself.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import ChipDelete from '@mui/joy/ChipDelete';
import Input from '@mui/joy/Input';
import Button from '@mui/joy/Button';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import ListItemContent from '@mui/joy/ListItemContent';
import CircularProgress from '@mui/joy/CircularProgress';

import { ODb } from '../db';
import * as MoveTypes from '../move';
import { filterTargets, targetLabel, targetDetail, targetKey, toApiTarget } from '../move';
import { parseWhen } from '../ganttquick';
import { getStatusColor, getStatusIcon } from './statuslook';
import { ReviewApi } from '../reviewApi';
import {
    ReviewItem, ReviewAct, ReviewActResult, itemKey, orgStamp, relativeDay, tallyName,
    suggestTags, cleanTag,
} from '../review';

// ── Acting, and taking it back ──────────────────────────────────────────────

export type Undoable = { token: string; key: string; action: ReviewAct['Action']; did: string };

// The undo stack outlives the component: leaving the tab to look at a heading
// in the Files tab and coming back should still be able to take the last
// decision back.
const undoStacks: { [scope: string]: Undoable[] } = {};

export type Acts = {
    // Send one decision. Answers with the result; the message is set either way.
    act: (it: ReviewItem, req: Omit<ReviewAct, 'Hash'> & { Hash?: string }) => Promise<ReviewActResult>;
    // Take the last decision back; answers with the key of the item it was
    // about, or null.
    undo: () => Promise<string | null>;
    canUndo: boolean;
    busy: boolean;
    message: { tone: 'success' | 'danger' | 'neutral'; text: string } | null;
    clearMessage: () => void;
};

export function useReviewActs(scope: string, onTally?: (name: string, delta: number) => void): Acts {
    const [busy, setBusy] = React.useState(false);
    const [message, setMessage] = React.useState<Acts['message']>(null);
    const [, bump] = React.useState(0);
    const stack = (undoStacks[scope] = undoStacks[scope] || []);

    const act = React.useCallback(async (it: ReviewItem, req: Omit<ReviewAct, 'Hash'> & { Hash?: string }) => {
        setBusy(true);
        const res = await ReviewApi.act({ ...req, Hash: req.Hash || it.Hash } as ReviewAct);
        setBusy(false);
        if (res.Undo) {
            stack.push({ token: res.Undo, key: itemKey(it), action: req.Action, did: res.Did || req.Action });
            bump(n => n + 1);
        }
        if (res.Ok) {
            onTally?.(tallyName(req.Action), 1);
            setMessage({ tone: 'success', text: res.Did || 'done' });
        } else {
            setMessage({ tone: 'danger', text: res.Msg || 'that did not work' });
        }
        return res;
    }, [stack, onTally]);

    const undo = React.useCallback(async () => {
        const last = stack[stack.length - 1];
        if (!last) {
            setMessage({ tone: 'neutral', text: 'nothing to undo' });
            return null;
        }
        setBusy(true);
        const res = await ReviewApi.undo(last.token);
        setBusy(false);
        if (!res.Ok) {
            setMessage({ tone: 'danger', text: res.Msg || 'could not undo' });
            return null;
        }
        stack.pop();
        bump(n => n + 1);
        onTally?.(tallyName(last.action), -1);
        setMessage({ tone: 'neutral', text: res.Did || 'undone' });
        return last.key;
    }, [stack, onTally]);

    return { act, undo, canUndo: stack.length > 0, busy, message, clearMessage: () => setMessage(null) };
}

// ── The heading ─────────────────────────────────────────────────────────────

export function StatusChip(props: { status: string; size?: 'sm' | 'md' | 'lg' }) {
    if (!props.status) return null;
    return (
        <Chip size={props.size || 'sm'} variant="soft" color={getStatusColor(props.status) || 'neutral'}
            startDecorator={getStatusIcon(props.status)}>{props.status}</Chip>
    );
}

export function whereOf(it: ReviewItem): string {
    return [MoveTypes.baseName(it.Filename), ...(it.Olp || [])].join(' › ');
}

// One heading, drawn to be read and decided about: big title, where it is,
// its tags and dates, and the prose under it.
export function ItemCard(props: { item: ReviewItem; extra?: React.ReactNode; big?: boolean }) {
    const it = props.item;
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: { xs: 2, sm: props.big ? 4 : 2 }, boxShadow: 'sm' }}>
            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.5, wordBreak: 'break-word' }}>{whereOf(it)}</Typography>
            <Typography component="div" level={props.big ? 'h2' : 'title-lg'} sx={{ display: 'flex', gap: 1, alignItems: 'baseline', flexWrap: 'wrap', wordBreak: 'break-word' }}>
                <StatusChip status={it.Status} size={props.big ? 'md' : 'sm'} />
                {it.Priority && <Chip size="sm" color="danger" variant="outlined">#{it.Priority}</Chip>}
                <span>{it.Headline}</span>
            </Typography>
            {((it.Tags && it.Tags.length > 0) || it.Scheduled || it.Effort) && (
                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', mt: 1 }}>
                    {(it.Tags || []).map(t => <Chip key={t} size="sm" variant="soft" color="primary">{t}</Chip>)}
                    {it.Scheduled && <Chip size="sm" variant="outlined">scheduled {it.Scheduled}</Chip>}
                    {it.Effort && <Chip size="sm" variant="outlined">effort {it.Effort}</Chip>}
                </Box>
            )}
            {props.extra}
            {it.Body && it.Body.trim() !== '' && (
                <Box component="pre" sx={{
                    whiteSpace: 'pre-wrap', wordBreak: 'break-word', fontFamily: 'inherit', fontSize: props.big ? 'md' : 'sm',
                    color: 'text.secondary', mt: 2, mb: 0, maxHeight: props.big ? '40vh' : '12em', overflow: 'auto', lineHeight: 1.6,
                }}>{it.Body}</Box>
            )}
            {it.Children > 0 && (
                <Typography level="body-sm" sx={{ mt: 1.5, color: 'text.tertiary' }}>
                    + {it.Children} heading{it.Children === 1 ? '' : 's'} under it, which go{it.Children === 1 ? 'es' : ''} wherever it goes
                </Typography>
            )}
        </Sheet>
    );
}

// ── The legend ──────────────────────────────────────────────────────────────

export type KeyDef = { key: string; label: string; icon?: React.ReactNode; color?: 'primary' | 'neutral' | 'success' | 'danger' | 'warning'; run: () => void; disabled?: boolean };

export function Kbd(props: { children: React.ReactNode }) {
    return (
        <Box component="kbd" sx={{
            fontFamily: 'monospace', fontSize: '0.8em', px: 0.6, py: 0.1, borderRadius: '4px', minWidth: '1.4em',
            display: 'inline-block', textAlign: 'center', border: '1px solid', borderColor: 'neutral.outlinedBorder',
            bgcolor: 'background.level1', lineHeight: 1.5,
        }}>{props.children}</Box>
    );
}

// The keys, as buttons: every one is clickable, and says which key does it.
export function KeyLegend(props: { keys: KeyDef[] }) {
    return (
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', justifyContent: 'center' }}>
            {props.keys.map(k => (
                <Button key={k.key + k.label} size="sm" variant="soft" color={k.color || 'neutral'} disabled={k.disabled}
                    onClick={k.run} startDecorator={<Kbd>{k.key}</Kbd>} endDecorator={k.icon}>
                    {k.label}
                </Button>
            ))}
        </Box>
    );
}

// Whether a key press is meant for the page's shortcuts: no modifier, and not
// typing into something.
export function isShortcut(e: KeyboardEvent): boolean {
    if (e.metaKey || e.ctrlKey || e.altKey || e.defaultPrevented) return false;
    const el = e.target as HTMLElement | null;
    if (!el) return true;
    const tag = (el.tagName || '').toUpperCase();
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable) return false;
    // A key on a button would press it as well as run the shortcut.
    if ((e.key === 'Enter' || e.key === ' ') && tag === 'BUTTON') return false;
    return true;
}

// ── Where it goes ───────────────────────────────────────────────────────────

let targetCache: MoveTypes.RefileTarget[] | null = null;

// Type to filter, arrows to move, Enter to pick: the refile destinations from
// /refile/targets, matched as the move dialog matches them.
export function RefilePicker(props: { open: boolean; item: ReviewItem | null; onClose: () => void; onPick: (to: { Type: string; Filename: string; Id: string }, label: string) => void }) {
    const [targets, setTargets] = React.useState<MoveTypes.RefileTarget[] | null>(targetCache);
    const [q, setQ] = React.useState('');
    const [at, setAt] = React.useState(0);
    const [err, setErr] = React.useState('');
    const listRef = React.useRef<HTMLUListElement | null>(null);

    React.useEffect(() => {
        if (!props.open) return;
        setQ('');
        setAt(0);
        // Asked again each time it opens - a refile just made a new place -
        // but the last list is shown straight away while that happens.
        ODb.refileTargets(4).then(r => {
            if (r && (r as any).Ok !== false && Array.isArray(r.Targets)) {
                targetCache = r.Targets;
                setTargets(r.Targets);
                setErr('');
            } else {
                setErr((r as any)?.Msg || 'could not list where things can go');
            }
        });
    }, [props.open]);

    const own = props.item?.Hash;
    const shown = React.useMemo(() => filterTargets((targets || []).filter(t => t.Hash !== own), q, 60), [targets, q, own]);
    React.useEffect(() => { setAt(0); }, [q]);
    React.useEffect(() => {
        const el = listRef.current?.querySelector(`[data-at="${at}"]`) as HTMLElement | null;
        el?.scrollIntoView({ block: 'nearest' });
    }, [at]);

    const pick = (t: MoveTypes.RefileTarget | undefined) => {
        if (!t) return;
        props.onPick(toApiTarget(t), targetLabel(t));
    };
    const onKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); setAt(a => Math.min(a + 1, shown.length - 1)); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); setAt(a => Math.max(a - 1, 0)); }
        else if (e.key === 'Enter') { e.preventDefault(); pick(shown[at]); }
        else if (e.key === 'Escape') { e.preventDefault(); props.onClose(); }
    };

    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(620px, 94vw)', top: '12vh', transform: 'translateX(-50%)', p: 1.5 }}>
                <Typography level="title-md">Refile “{props.item?.Headline}”</Typography>
                <Input autoFocus value={q} onChange={e => setQ(e.target.value)} onKeyDown={onKey}
                    placeholder="where does it belong? type to filter" />
                {err && <Typography level="body-sm" color="danger">{err}</Typography>}
                {!targets && !err && <CircularProgress size="sm" />}
                <List ref={listRef} size="sm" sx={{ maxHeight: '50vh', overflow: 'auto', '--ListItem-radius': '6px' }}>
                    {shown.map((t, i) => (
                        <ListItem key={targetKey(t)} data-at={i}>
                            <ListItemButton selected={i === at} onMouseEnter={() => setAt(i)} onClick={() => pick(t)}>
                                <ListItemContent>
                                    <Typography component="div" level="body-sm" sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                                        {t.Todo && <StatusChip status={t.Todo} />}
                                        <span>{targetLabel(t)}</span>
                                        {(t.Tags || []).map(x => <Chip key={x} size="sm" variant="soft">{x}</Chip>)}
                                    </Typography>
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{targetDetail(t)}</Typography>
                                </ListItemContent>
                            </ListItemButton>
                        </ListItem>
                    ))}
                    {targets && shown.length === 0 && <Typography level="body-sm" sx={{ p: 1 }}>Nothing matches.</Typography>}
                </List>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>↑↓ to move · Enter to refile · Esc to cancel</Typography>
            </ModalDialog>
        </Modal>
    );
}

// ── When ────────────────────────────────────────────────────────────────────

const QUICK_DAYS = ['today', 'tomorrow', 'mon', 'fri', '+1w', '+1m'];

// A date typed the way it is said - "fri", "+2w", "tomorrow" - read by the
// same parseWhen the gantt's quick add uses, with what it means shown before
// it is written. Anything it cannot read (a time: "fri 14:00") is sent as typed
// and read by the server's own reader instead.
export function DatePicker(props: {
    open: boolean; title: string; current?: string; onClose: () => void;
    onPick: (when: string) => void; onClear?: () => void;
}) {
    const [text, setText] = React.useState('');
    React.useEffect(() => { if (props.open) setText(''); }, [props.open]);
    const day = text.trim() ? parseWhen(text) : null;
    const submit = (t: string) => {
        const d = parseWhen(t);
        if (d) props.onPick(orgStamp(d));
        else if (t.trim()) props.onPick(t.trim());
    };
    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(460px, 94vw)', top: '16vh', transform: 'translateX(-50%)' }}>
                <Typography level="title-md">{props.title}</Typography>
                <Input autoFocus value={text} onChange={e => setText(e.target.value)} placeholder="tomorrow, fri, +2w, 2026-11-02"
                    onKeyDown={e => {
                        if (e.key === 'Enter') { e.preventDefault(); submit(text); }
                        if (e.key === 'Escape') { e.preventDefault(); props.onClose(); }
                    }} />
                <Typography level="body-sm" sx={{ minHeight: '1.5em', color: day ? 'success.plainColor' : 'text.tertiary' }}>
                    {day ? `${day.toDateString()} · ${relativeDay(day)}` : text.trim() ? 'the server will read this one' : props.current ? `now ${props.current}` : ' '}
                </Typography>
                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap' }}>
                    {QUICK_DAYS.map(q => <Chip key={q} variant="outlined" onClick={() => submit(q)}>{q}</Chip>)}
                </Box>
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 1 }}>
                    {props.onClear && props.current && <Button variant="plain" color="danger" onClick={props.onClear}>Remove the date</Button>}
                    <Button variant="plain" color="neutral" onClick={props.onClose}>Cancel</Button>
                    <Button disabled={!text.trim()} onClick={() => submit(text)}>Set</Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}

// ── Which tags ──────────────────────────────────────────────────────────────

let knownTags: string[] | null = null;

// The heading's own tags as chips to take off, a box to type one, and the
// tags already in use offered as you type. Enter on an empty box saves.
export function TagPicker(props: { open: boolean; item: ReviewItem | null; onClose: () => void; onSave: (tags: string[]) => void }) {
    const [tags, setTags] = React.useState<string[]>([]);
    const [text, setText] = React.useState('');
    const [known, setKnown] = React.useState<string[]>(knownTags || []);
    React.useEffect(() => {
        if (!props.open) return;
        setTags([...(props.item?.Tags || [])]);
        setText('');
        ODb.getAllTags().then(t => { if (Array.isArray(t)) { knownTags = t; setKnown(t); } });
    }, [props.open, props.item]);
    const offer = suggestTags(known, tags, text, 14);
    const add = (t: string) => {
        const c = cleanTag(t);
        if (c && !tags.some(x => x.toLowerCase() === c.toLowerCase())) setTags([...tags, c]);
        setText('');
    };
    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(520px, 94vw)', top: '16vh', transform: 'translateX(-50%)' }}>
                <Typography level="title-md">Tags</Typography>
                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', minHeight: '1.8em' }}>
                    {tags.length === 0 && <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>no tags</Typography>}
                    {tags.map(t => (
                        <Chip key={t} color="primary" variant="soft"
                            endDecorator={<ChipDelete onDelete={() => setTags(tags.filter(x => x !== t))} />}>{t}</Chip>
                    ))}
                </Box>
                <Input autoFocus value={text} onChange={e => setText(e.target.value)} placeholder="type a tag, Enter adds it; Enter on nothing saves"
                    onKeyDown={e => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            if (text.trim()) add(offer.length > 0 && offer[0].toLowerCase().startsWith(text.trim().toLowerCase()) ? offer[0] : text);
                            else props.onSave(tags);
                        } else if (e.key === 'Escape') { e.preventDefault(); props.onClose(); }
                        else if (e.key === 'Backspace' && text === '' && tags.length > 0) setTags(tags.slice(0, -1));
                    }} />
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                    {offer.map(t => <Chip key={t} variant="outlined" size="sm" onClick={() => add(t)}>{t}</Chip>)}
                </Box>
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 1 }}>
                    <Button variant="plain" color="neutral" onClick={props.onClose}>Cancel</Button>
                    <Button onClick={() => props.onSave(text.trim() ? [...tags, cleanTag(text)] : tags)}>Save</Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}

// ── A one-line question ─────────────────────────────────────────────────────

export function AskText(props: { open: boolean; title: string; placeholder?: string; allowEmpty?: boolean; onClose: () => void; onSubmit: (text: string) => void }) {
    const [text, setText] = React.useState('');
    React.useEffect(() => { if (props.open) setText(''); }, [props.open]);
    const ok = props.allowEmpty || text.trim() !== '';
    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(480px, 94vw)', top: '16vh', transform: 'translateX(-50%)' }}>
                <Typography level="title-md">{props.title}</Typography>
                <Input autoFocus value={text} onChange={e => setText(e.target.value)} placeholder={props.placeholder}
                    onKeyDown={e => {
                        if (e.key === 'Enter' && ok) { e.preventDefault(); props.onSubmit(text.trim()); }
                        if (e.key === 'Escape') { e.preventDefault(); props.onClose(); }
                    }} />
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                    <Button variant="plain" color="neutral" onClick={props.onClose}>Cancel</Button>
                    <Button disabled={!ok} onClick={() => props.onSubmit(text.trim())}>OK</Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
