// The Focus tab: a pomodoro timer that is also the clock.
//
// Pick a task, press start: the server clocks in on it and runs the work
// phase; when that is up it clocks out (the CLOCK line), notes the pomodoro in
// the task's logbook, and runs the break. The timer is the server's
// (internal/app/orgs/focus.go), so closing this tab - or the laptop - changes
// nothing, and `orgs focus` in a terminal shows the same session.
//
// Left: a large ring for the phase under way, and its controls. Right: the
// task to work on (recent ones first, fuzzy filter as you type) and today's
// sessions. Keys, when not typing: space starts (or skips a break), s stops,
// + adds five minutes, / goes to the task filter.
//
// The arithmetic is src/focus.ts (tested), the requests and the live state
// src/focusApi.ts.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import Input from '@mui/joy/Input';
import Switch from '@mui/joy/Switch';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import ListItemContent from '@mui/joy/ListItemContent';
import Divider from '@mui/joy/Divider';
import Tooltip from '@mui/joy/Tooltip';
import PlayIcon from '@mui/icons-material/PlayArrowRounded';
import StopIcon from '@mui/icons-material/StopRounded';
import AddIcon from '@mui/icons-material/Add';
import SkipIcon from '@mui/icons-material/SkipNextRounded';
import SearchIcon from '@mui/icons-material/Search';
import OpenIcon from '@mui/icons-material/LaunchOutlined';
import BellIcon from '@mui/icons-material/NotificationsNoneOutlined';

import { ODb } from '../db';
import { useNav } from '../NavContext';
import { isTyping } from './Capture';
import {
    useFocus, startFocus, stopFocus, extendFocus, skipFocus, focusHistory,
    notificationsSupported, notificationsOn, setNotifications,
} from '../focusApi';
import {
    FocusState, FocusTask, FocusRecord, PRESETS, formatCountdown, formatMinutes, progress, phaseColor, phaseLabel,
    isRunning, presetOf, rankTasks, recentHashes, setPosition, todaysRecords,
} from '../focus';

export default function Focus() {
    const { state, remaining, version, live } = useFocus();
    const nav = useNav();
    const [tasks, setTasks] = React.useState<FocusTask[]>([]);
    const [records, setRecords] = React.useState<FocusRecord[]>([]);
    const [recent, setRecent] = React.useState<string[]>([]);
    const [filter, setFilter] = React.useState('');
    const [picked, setPicked] = React.useState<string>('');
    const [custom, setCustom] = React.useState(false);
    const [busy, setBusy] = React.useState(false);
    const [msg, setMsg] = React.useState('');
    const [notify, setNotify] = React.useState(notificationsOn());
    const filterRef = React.useRef<HTMLInputElement | null>(null);

    // The lengths the next start will use. Seeded from the server's settings,
    // which are whatever was used last from anywhere.
    const [work, setWork] = React.useState(25);
    const [short, setShort] = React.useState(5);
    const [long, setLong] = React.useState(15);
    const [every, setEvery] = React.useState(4);
    const [autoNext, setAutoNext] = React.useState(false);
    const seeded = React.useRef(false);
    React.useEffect(() => {
        if (seeded.current || !state.Now) return;
        seeded.current = true;
        const s = state.Settings;
        setWork(s.Work); setShort(s.Short); setLong(s.Long); setEvery(s.LongEvery); setAutoNext(s.AutoNext);
        setCustom(!presetOf(s));
    }, [state]);

    React.useEffect(() => {
        let gone = false;
        ODb.activeTodos<any[]>().then(rows => {
            if (gone || !Array.isArray(rows)) return;
            setTasks(rows.filter(r => r && r.Hash).map(r => ({
                Hash: r.Hash, Headline: r.Headline, Filename: r.Filename, Status: r.Status, Priority: r.Priority,
            })));
        });
        focusHistory(14).then(h => { if (!gone) setRecent(recentHashes(h.Records)); });
        return () => { gone = true; };
    }, []);

    // Today's list, read again whenever the session moved.
    React.useEffect(() => {
        let gone = false;
        focusHistory(1).then(h => { if (!gone) setRecords(todaysRecords(h.Records, new Date())); });
        return () => { gone = true; };
    }, [version]);

    // The task the controls are about: the one picked here, else the running
    // (or last) one.
    const current = picked || state.Hash || '';
    const shown = React.useMemo(() => rankTasks(tasks, filter, recent), [tasks, filter, recent]);
    const pickedTask = tasks.find(t => t.Hash === current);
    const recentSet = React.useMemo(() => new Set(recent.slice(0, 8)), [recent]);

    const act = React.useCallback(async (f: () => Promise<FocusState>) => {
        setBusy(true);
        setMsg('');
        const st = await f();
        setBusy(false);
        if (st.Ok === false) setMsg(st.Msg || 'That did not work.');
        return st;
    }, []);

    const start = React.useCallback(async (hash?: string) => {
        const st = await act(() => startFocus({ hash: hash || current || undefined, work, short, long, longEvery: every, autoNext }));
        if (st.Ok !== false && st.Hash) {
            setPicked('');
            setRecent(r => [st.Hash!, ...r.filter(h => h !== st.Hash)]);
        }
    }, [act, current, work, short, long, every, autoNext]);

    // Keys. Only when nothing is being typed into, and never with a modifier,
    // so the palette's ⌘K and the browser's own keys are left alone.
    React.useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (e.metaKey || e.ctrlKey || e.altKey || isTyping(e.target) || busy) return;
            if (e.key === ' ') {
                // Space on a focused button is that button's own click.
                if ((e.target as HTMLElement | null)?.closest?.('button, [role="button"]')) return;
                e.preventDefault();
                if (state.Phase === 'idle') { if (current) start(); }
                else if (state.Phase === 'break') act(skipFocus);
            } else if (e.key === 's' && isRunning(state)) {
                act(stopFocus);
            } else if ((e.key === '+' || e.key === '=') && isRunning(state)) {
                act(() => extendFocus(5));
            } else if (e.key === '/') {
                e.preventDefault();
                filterRef.current?.focus();
            }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [state, current, busy, start, act]);

    const color = phaseColor(state.Phase);
    const running = isRunning(state);
    const pos = setPosition(state);
    const idleSecs = work * 60;

    const choosePreset = (p: typeof PRESETS[number]) => {
        setWork(p.work); setShort(p.short); setLong(p.long); setCustom(false);
    };

    return (
        <Box sx={{
            display: 'grid', gap: 3, alignItems: 'start',
            gridTemplateColumns: { xs: '1fr', md: 'minmax(320px, 1fr) minmax(320px, 1.1fr)' },
            maxWidth: 1100,
        }}>
            {/* The timer */}
            <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: { xs: 2, sm: 3 }, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                <Ring
                    fraction={running ? progress(state, remaining) : 0}
                    color={color}
                    label={running ? phaseLabel(state) : 'Ready'}
                    time={formatCountdown(running ? remaining : idleSecs)}
                    dim={!running}
                    dots={pos}
                />
                <Box sx={{ textAlign: 'center', minHeight: 48, maxWidth: 420 }}>
                    {running && state.Title ? (
                        <>
                            <Typography level="title-lg">{state.Title}</Typography>
                            <Typography level="body-xs">{base(state.File || '')}</Typography>
                        </>
                    ) : pickedTask ? (
                        <>
                            <Typography level="title-lg">{pickedTask.Headline}</Typography>
                            <Typography level="body-xs">{base(pickedTask.Filename)}</Typography>
                        </>
                    ) : (
                        <Typography level="body-sm" color="neutral">Pick a task to focus on.</Typography>
                    )}
                </Box>

                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', justifyContent: 'center' }}>
                    {state.Phase === 'idle' && (
                        <Button size="lg" color="danger" startDecorator={<PlayIcon />} disabled={busy || !current}
                            onClick={() => start()}>
                            {!picked && state.Hash ? 'Another one' : 'Start'}
                        </Button>
                    )}
                    {state.Phase === 'work' && (<>
                        <Button size="lg" variant="soft" color="neutral" startDecorator={<StopIcon />} disabled={busy} onClick={() => act(stopFocus)}>Stop</Button>
                        <Button size="lg" variant="soft" color="neutral" startDecorator={<AddIcon />} disabled={busy} onClick={() => act(() => extendFocus(5))}>5 min</Button>
                        <Tooltip title="Count it as done and take the break">
                            <Button size="lg" variant="soft" color="danger" startDecorator={<SkipIcon />} disabled={busy} onClick={() => act(skipFocus)}>Done</Button>
                        </Tooltip>
                    </>)}
                    {state.Phase === 'break' && (<>
                        <Button size="lg" color="success" startDecorator={<SkipIcon />} disabled={busy} onClick={() => act(skipFocus)}>Skip break</Button>
                        <Button size="lg" variant="soft" color="neutral" startDecorator={<AddIcon />} disabled={busy} onClick={() => act(() => extendFocus(5))}>5 min</Button>
                        <Button size="lg" variant="soft" color="neutral" startDecorator={<StopIcon />} disabled={busy} onClick={() => act(stopFocus)}>End</Button>
                    </>)}
                    {running && picked && picked !== state.Hash && (
                        <Button size="lg" variant="outlined" color="danger" disabled={busy} onClick={() => start(picked)}>Switch to picked</Button>
                    )}
                </Box>
                {msg && <Typography level="body-sm" color="danger">{msg}</Typography>}

                <Divider sx={{ alignSelf: 'stretch' }} />

                {/* Lengths */}
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', justifyContent: 'center' }}>
                    {PRESETS.map(p => {
                        const on = !custom && p.work === work && p.short === short && p.long === long;
                        return (
                            <Chip key={p.label} variant={on ? 'solid' : 'soft'} color={on ? 'danger' : 'neutral'}
                                onClick={() => choosePreset(p)}>{p.label}</Chip>
                        );
                    })}
                    <Chip variant={custom ? 'solid' : 'soft'} color={custom ? 'danger' : 'neutral'} onClick={() => setCustom(c => !c)}>Custom</Chip>
                </Box>
                {custom && (
                    <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 80px))', gap: 1 }}>
                        <Num label="Work" value={work} set={setWork} />
                        <Num label="Break" value={short} set={setShort} />
                        <Num label="Long" value={long} set={setLong} />
                        <Num label="Every" value={every} set={setEvery} step={1} />
                    </Box>
                )}
                <Box sx={{ display: 'flex', gap: 3, flexWrap: 'wrap', justifyContent: 'center' }}>
                    <Typography component="label" level="body-sm" startDecorator={
                        <Switch size="sm" checked={autoNext} onChange={e => setAutoNext(e.target.checked)} />}>
                        Start the next one after a break
                    </Typography>
                    {notificationsSupported() && (
                        <Typography component="label" level="body-sm" startDecorator={
                            <Switch size="sm" checked={notify}
                                onChange={async e => setNotify(await setNotifications(e.target.checked))} />}
                            endDecorator={<BellIcon fontSize="small" />}>
                            Notify me
                        </Typography>
                    )}
                </Box>
                <Typography level="body-xs" sx={{ opacity: 0.7 }}>
                    space start · s stop · + five more · / find a task{live ? '' : ' · (updating by polling)'}
                </Typography>
            </Sheet>

            {/* The task, and today */}
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 }}>
                <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: 1.5, display: 'flex', flexDirection: 'column', gap: 1 }}>
                    <Input
                        slotProps={{ input: { ref: filterRef } }}
                        placeholder="Find a task…"
                        startDecorator={<SearchIcon />}
                        value={filter}
                        onChange={e => setFilter(e.target.value)}
                        onKeyDown={e => {
                            if (e.key === 'Enter' && shown.length > 0) {
                                setPicked(shown[0].Hash);
                                (e.target as HTMLInputElement).blur();
                            } else if (e.key === 'Escape') {
                                setFilter('');
                                (e.target as HTMLInputElement).blur();
                            }
                        }}
                    />
                    <List size="sm" sx={{ maxHeight: 340, overflow: 'auto', '--ListItem-radius': '8px' }}>
                        {shown.slice(0, 200).map(t => (
                            <ListItem key={t.Hash}
                                endAction={recentSet.has(t.Hash) && !filter ? <Chip size="sm" variant="plain">recent</Chip> : undefined}>
                                <ListItemButton
                                    selected={t.Hash === current}
                                    color={t.Hash === current ? 'danger' : undefined}
                                    onClick={() => setPicked(t.Hash)}
                                    onDoubleClick={() => start(t.Hash)}
                                >
                                    <ListItemContent sx={{ minWidth: 0 }}>
                                        <Typography level="body-sm" noWrap>
                                            {t.Status && <Typography component="span" level="body-xs" fontWeight="lg" sx={{ mr: 0.75 }}>{t.Status}</Typography>}
                                            {t.Headline}
                                        </Typography>
                                        <Typography level="body-xs" noWrap>{base(t.Filename)}</Typography>
                                    </ListItemContent>
                                </ListItemButton>
                            </ListItem>
                        ))}
                        {shown.length === 0 && (
                            <ListItem><Typography level="body-sm">{tasks.length ? 'Nothing matches.' : 'No open tasks found.'}</Typography></ListItem>
                        )}
                    </List>
                </Sheet>

                <Sheet variant="outlined" sx={{ borderRadius: 'lg', p: 2, display: 'flex', flexDirection: 'column', gap: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1 }}>
                        <Typography level="title-md">Today</Typography>
                        <Typography level="body-sm" sx={{ ml: 'auto' }}>
                            {state.Today} {state.Today === 1 ? 'pomodoro' : 'pomodoros'} · {formatMinutes(state.TodayMinutes)}
                        </Typography>
                    </Box>
                    <Box aria-hidden sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', minHeight: 14 }}>
                        {Array.from({ length: state.Today }).map((_, i) => (
                            <Box key={i} sx={{ width: 12, height: 12, borderRadius: '50%', bgcolor: 'danger.400' }} />
                        ))}
                    </Box>
                    {records.length === 0 ? (
                        <Typography level="body-sm" sx={{ opacity: 0.7 }}>Nothing yet today.</Typography>
                    ) : (
                        <List size="sm">
                            {records.map((r, i) => (
                                <ListItem key={r.Start + i}
                                    endAction={r.File ? (
                                        <Tooltip title="Open the task">
                                            <Button size="sm" variant="plain" color="neutral"
                                                onClick={() => nav.toFile({ filename: r.File, heading: r.Title, back: { app: 'Focus', label: 'Back to Focus' } })}>
                                                <OpenIcon fontSize="small" />
                                            </Button>
                                        </Tooltip>
                                    ) : undefined}>
                                    <ListItemContent sx={{ display: 'flex', gap: 1, alignItems: 'baseline', minWidth: 0 }}>
                                        <Typography level="body-xs" sx={{ fontVariantNumeric: 'tabular-nums', flexShrink: 0 }}>{clock(r.Start)}</Typography>
                                        <Typography level="body-xs" color={r.Completed ? 'danger' : 'neutral'} sx={{ flexShrink: 0 }}>
                                            {r.Completed ? '●' : '○'} {formatMinutes(r.Minutes)}
                                        </Typography>
                                        <Typography level="body-sm" noWrap sx={{ minWidth: 0 }}>{r.Title}</Typography>
                                    </ListItemContent>
                                </ListItem>
                            ))}
                        </List>
                    )}
                </Sheet>
            </Box>
        </Box>
    );
}

// The big ring: a track, an arc for the time gone, the countdown inside, and
// a dot per pomodoro of the set of four.
function Ring({ fraction, color, label, time, dim, dots }: {
    fraction: number; color: 'danger' | 'success' | 'neutral'; label: string; time: string; dim: boolean; dots: { n: number; of: number };
}) {
    const size = 260, stroke = 10, r = (size - stroke) / 2, c = 2 * Math.PI * r;
    const ink = color === 'neutral' ? 'var(--joy-palette-neutral-400)' : `var(--joy-palette-${color}-500)`;
    return (
        <Box sx={{ position: 'relative', width: { xs: 220, sm: size }, aspectRatio: '1 / 1' }}>
            <svg viewBox={`0 0 ${size} ${size}`} width="100%" height="100%" role="img" aria-label={`${label} ${time}`}>
                <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="var(--joy-palette-neutral-outlinedBorder)" strokeWidth={stroke} />
                <circle
                    cx={size / 2} cy={size / 2} r={r} fill="none"
                    stroke={ink} strokeWidth={stroke} strokeLinecap="round"
                    strokeDasharray={c} strokeDashoffset={c * (1 - fraction)}
                    transform={`rotate(-90 ${size / 2} ${size / 2})`}
                    style={{ transition: 'stroke-dashoffset 1s linear, stroke 300ms' }}
                />
            </svg>
            <Box sx={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 0.5 }}>
                <Typography level="body-sm" sx={{ textTransform: 'uppercase', letterSpacing: '0.12em', opacity: 0.75 }}>{label}</Typography>
                <Typography sx={{ fontSize: { xs: 48, sm: 60 }, fontWeight: 300, lineHeight: 1, fontVariantNumeric: 'tabular-nums', opacity: dim ? 0.55 : 1 }}>
                    {time}
                </Typography>
                <Box sx={{ display: 'flex', gap: 0.75, mt: 1 }} aria-label={`${dots.n} of ${dots.of}`}>
                    {Array.from({ length: dots.of }).map((_, i) => (
                        <Box key={i} sx={{
                            width: 8, height: 8, borderRadius: '50%',
                            bgcolor: i < dots.n ? 'danger.400' : 'neutral.outlinedBorder',
                        }} />
                    ))}
                </Box>
            </Box>
        </Box>
    );
}

function Num({ label, value, set, step = 0.5 }: { label: string; value: number; set: (n: number) => void; step?: number }) {
    return (
        <FormControl size="sm">
            <FormLabel>{label}</FormLabel>
            <Input type="number" size="sm" value={value}
                slotProps={{ input: { min: step, step } }}
                onChange={e => { const n = parseFloat(e.target.value); if (n > 0) set(n); }} />
        </FormControl>
    );
}

function base(p: string): string {
    const i = Math.max(p.lastIndexOf('/'), p.lastIndexOf('\\'));
    return i >= 0 ? p.slice(i + 1) : p;
}

function clock(iso: string): string {
    const d = new Date(iso);
    return isNaN(d.getTime()) ? '' : `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}
