// The Diff tab. Two ways in, one viewer:
//
//  - History: pick an org file, see every commit that touched it as a graph,
//    with the uncommitted copies on top; click one to see what it changed,
//    shift-click another to compare any two points in its life.
//  - Compare: any two things against each other - an org file at any
//    revision, a file from this computer, or text pasted in.
//
// The diffing is all done here (orgdiff.ts); the server only answers which
// commits touched a file and what the file said at one (filehistory.go).

function baseName(f: string): string {
    const i = f.lastIndexOf('/');
    return i >= 0 ? f.slice(i + 1) : f;
}
function dirName(f: string): string {
    const i = f.lastIndexOf('/');
    return i >= 0 ? f.slice(0, i) : '';
}

type Loaded = { text: string; missing: boolean };

// What the server said a file held at a revision. Commits never change, so
// those are kept; the working copy and the index are asked again each time.
const textCache = new Map<string, Loaded>();

async function loadText(file: string, rev: string): Promise<Loaded> {
    if (rev === EMPTY) return { text: '', missing: true };
    const key = `${file}\u0000${rev}`;
    const fixed = rev !== WORKING && rev !== INDEX;
    if (fixed && textCache.has(key)) return textCache.get(key) as Loaded;
    const res = await ODb.getFileAt(file, rev);
    if (!res || !res.Ok) throw new Error(res?.Msg || 'could not read ' + file);
    const out = { text: res.Text || '', missing: !!res.Missing };
    if (fixed) textCache.set(key, out);
    return out;
}

function FilePicker({ files, value, onChange, placeholder }: {
    files: string[]; value: string; onChange: (f: string) => void; placeholder?: string;
}) {
    return (
        <Autocomplete
            size="sm"
            placeholder={placeholder || 'Pick an org file'}
            options={files}
            value={value || null}
            onChange={(_e, v) => onChange(v || '')}
            getOptionLabel={o => baseName(o)}
            filterOptions={(opts, s) => {
                const q = s.inputValue.trim().toLowerCase();
                if (q === '') return opts;
                return opts.filter(o => o.toLowerCase().includes(q));
            }}
            renderOption={(props, o) => (
                <li {...props} key={o}>
                    <Box sx={{ minWidth: 0 }}>
                        <Typography level="body-sm">{baseName(o)}</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {dirName(o)}
                        </Typography>
                    </Box>
                </li>
            )}
            startDecorator={<DescriptionOutlinedIcon sx={{ fontSize: 18 }} />}
            sx={{ minWidth: 220, flex: 1 }}
        />
    );
}

// ---------------------------------------------------------------------------
// History
// ---------------------------------------------------------------------------

function describe(rev: string, h: HistoryResult | null, file: string): DiffSide {
    if (rev === WORKING) return { text: '', label: 'Working copy', detail: file };
    if (rev === INDEX) return { text: '', label: 'Staged', detail: 'what the next commit would hold' };
    if (rev === EMPTY) return { text: '', label: '(nothing)', detail: 'before the file existed' };
    const c = (h?.Commits || []).find(x => x.Hash === rev);
    if (!c) return { text: '', label: rev.slice(0, 7) };
    return { text: '', label: c.Short, detail: `${c.Subject} · ${c.Author}, ${relativeTime(c.When)}` };
}

function HistoryMode({ files }: { files: string[] }) {
    const isMobile = useIsMobile();
    const [file, setFile] = useSetting('diffFile');
    const [allBranches, setAllBranches] = useSetting('diffAllBranches');
    const [limit, setLimit] = React.useState(300);
    const [history, setHistory] = React.useState<HistoryResult | null>(null);
    const [error, setError] = React.useState('');
    const [reload, setReload] = React.useState(0);
    const [base, setBase] = React.useState('');
    const [target, setTarget] = React.useState('');
    const [sides, setSides] = React.useState<{ left: Loaded; right: Loaded } | null>(null);
    const [loadingText, setLoadingText] = React.useState(false);

    React.useEffect(() => {
        if (!file) { setHistory(null); return; }
        let live = true;
        setError('');
        ODb.getHistory(file, allBranches, limit).then(h => {
            if (!live) return;
            if (!h || !h.Ok) { setError(h?.Msg || 'could not read the history'); setHistory(null); return; }
            setHistory(h);
        }).catch(e => live && setError(String(e)));
        return () => { live = false; };
    }, [file, allBranches, limit, reload]);

    // A new history picks what to show first: local changes when there are
    // any, otherwise the newest commit.
    const lastFile = React.useRef('');
    React.useEffect(() => {
        if (!history) return;
        const stillThere = (r: string) => r === WORKING || r === INDEX || r === EMPTY
            || (history.Commits || []).some(c => c.Hash === r) || r === history.Last;
        if (lastFile.current === history.File && target && stillThere(target) && stillThere(base)) return;
        lastFile.current = history.File;
        const rows = historyRows(history);
        if (rows.length === 0) { setBase(''); setTarget(''); return; }
        if (rows[0].pseudo) { setTarget(WORKING === rows[0].rev ? WORKING : rows[0].rev); setBase(history.Last || EMPTY); return; }
        setTarget(rows[0].rev);
        setBase(rows[0].parents[0] || EMPTY);
    }, [history]);

    React.useEffect(() => {
        if (!file || !base || !target) { setSides(null); return; }
        let live = true;
        setLoadingText(true);
        Promise.all([loadText(file, base), loadText(file, target)])
            .then(([l, r]) => { if (live) { setSides({ left: l, right: r }); setError(''); } })
            .catch(e => live && setError(String(e.message || e)))
            .finally(() => live && setLoadingText(false));
        return () => { live = false; };
    }, [file, base, target, reload]);

    const onPick = (row: HistoryRow, extend: boolean) => {
        if (!history) return;
        const rows = historyRows(history);
        const order = (r: string) => {
            const i = rows.findIndex(x => x.rev === r);
            return i < 0 ? Number.MAX_SAFE_INTEGER : i; // EMPTY and off-list commits are oldest
        };
        if (extend && target) {
            if (row.rev === target) return;
            // The older of the two goes on the left.
            if (order(row.rev) > order(target)) setBase(row.rev);
            else { setBase(target); setTarget(row.rev); }
            return;
        }
        setTarget(row.rev);
        if (row.rev === WORKING) setBase(history.Staged ? INDEX : history.Last || EMPTY);
        else if (row.rev === INDEX) setBase(history.Last || EMPTY);
        else setBase(row.parents[0] || EMPTY);
    };

    const left: DiffSide = { ...describe(base, history, file), text: sides?.left.text || '', missing: sides?.left.missing };
    const right: DiffSide = { ...describe(target, history, file), text: sides?.right.text || '', missing: sides?.right.missing };

    let placeholder: React.ReactNode = null;
    if (!file) placeholder = <Typography level="body-md">Pick an org file to see its history.</Typography>;
    else if (error) placeholder = <Typography level="body-md" color="danger">{error}</Typography>;
    else if (history && !history.InRepo) placeholder = (
        <Box sx={{ textAlign: 'center', maxWidth: 420 }}>
            <Typography level="title-md">This file is not in a git repository</Typography>
            <Typography level="body-sm" sx={{ mt: 1 }}>
                There is no history to show. Compare it against another file, a local copy or pasted text
                from the Compare mode instead.
            </Typography>
        </Box>
    );
    else if (!sides) placeholder = <Typography level="body-md">Reading…</Typography>;

    const branch = history?.Branch || (history?.Head ? history.Head.slice(0, 7) + ' (detached)' : '');

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Box sx={{ flex: '1 1 260px', maxWidth: 520, display: 'flex' }}>
                    <FilePicker files={files} value={file} onChange={f => { setFile(f); setLimit(300); }} />
                </Box>
                {history?.InRepo && (
                    <Tooltip size="sm" title={history.Repo}>
                        <Chip size="sm" variant="soft" startDecorator={<CallSplitIcon sx={{ fontSize: 14 }} />}>{branch}</Chip>
                    </Tooltip>
                )}
                {history?.InRepo && (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                        <Switch size="sm" checked={allBranches} onChange={e => setAllBranches(e.target.checked)} />
                        <Typography level="body-xs">All branches</Typography>
                    </Box>
                )}
                <Tooltip size="sm" title="Read the history and the files again">
                    <IconButton size="sm" variant="outlined" onClick={() => setReload(k => k + 1)} disabled={!file}>
                        <RefreshIcon />
                    </IconButton>
                </Tooltip>
                {base && target && (
                    <Box sx={{ ml: 'auto', display: 'flex', gap: 0.75 }}>
                        {target !== WORKING && history?.InRepo && (
                            <Tooltip size="sm" title="Compare the selected version with the file as it is now">
                                <Button size="sm" variant="outlined" color="neutral" onClick={() => { setBase(target); setTarget(WORKING); }}>
                                    vs working copy
                                </Button>
                            </Tooltip>
                        )}
                        <Tooltip size="sm" title="Swap the two sides">
                            <IconButton size="sm" variant="outlined" onClick={() => { setBase(target); setTarget(base); }}>
                                <SwapHorizIcon />
                            </IconButton>
                        </Tooltip>
                    </Box>
                )}
            </Box>
            <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: 1.5, flex: 1, minHeight: 0 }}>
                {history?.InRepo && (
                    <Sheet variant="outlined" sx={{
                        width: isMobile ? 'auto' : 380, flex: isMobile ? '0 0 38%' : '0 0 auto',
                        display: 'flex', flexDirection: 'column', minHeight: 0, borderRadius: 'md', p: 1,
                    }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', px: 0.5, pb: 0.75 }}>
                            Click a commit to see what it changed · shift-click another to compare the two
                        </Typography>
                        <DiffHistory history={history} base={base} target={target} onPick={onPick} />
                        {history.Truncated && (
                            <Button size="sm" variant="plain" onClick={() => setLimit(l => l * 2)}>Load older commits</Button>
                        )}
                    </Sheet>
                )}
                <DiffView left={left} right={right} placeholder={placeholder} loading={loadingText} />
            </Box>
        </Box>
    );
}

// ---------------------------------------------------------------------------
// Compare
// ---------------------------------------------------------------------------

type Source =
    | { kind: 'file'; file: string; rev: string }
    | { kind: 'local'; name: string; text: string }
    | { kind: 'paste'; text: string };

function SourceCard({ which, src, onChange, files, histories, wantHistory }: {
    which: 'a' | 'b';
    src: Source;
    onChange: (s: Source) => void;
    files: string[];
    histories: Map<string, HistoryResult>;
    wantHistory: (file: string) => void;
}) {
    const inputRef = React.useRef<HTMLInputElement | null>(null);
    const [over, setOver] = React.useState(false);
    const readFile = (f: File) => {
        f.text().then(text => onChange({ kind: 'local', name: f.name, text }));
    };
    const h = src.kind === 'file' && src.file ? histories.get(src.file) : undefined;
    React.useEffect(() => {
        if (src.kind === 'file' && src.file) wantHistory(src.file);
    }, [src, wantHistory]);

    return (
        <Sheet variant="outlined"
            onDragOver={e => { e.preventDefault(); setOver(true); }}
            onDragLeave={() => setOver(false)}
            onDrop={e => {
                e.preventDefault(); setOver(false);
                const f = e.dataTransfer.files?.[0];
                if (f) readFile(f);
            }}
            sx={{
                p: 1.25, borderRadius: 'md', display: 'flex', flexDirection: 'column', gap: 1,
                borderColor: over ? 'primary.400' : undefined,
                borderTop: '3px solid', borderTopColor: which === 'a' ? 'danger.400' : 'success.400',
            }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Box sx={{
                    width: 20, height: 20, borderRadius: '50%', display: 'grid', placeItems: 'center',
                    fontSize: 11, fontWeight: 800, color: '#fff', bgcolor: which === 'a' ? 'danger.500' : 'success.500',
                }}>{which === 'a' ? 'A' : 'B'}</Box>
                <Typography level="title-sm">{which === 'a' ? 'Before' : 'After'}</Typography>
                <ToggleButtonGroup size="sm" sx={{ ml: 'auto' }} value={src.kind}
                    onChange={(_e, v) => {
                        if (!v || v === src.kind) return;
                        if (v === 'file') onChange({ kind: 'file', file: '', rev: WORKING });
                        else if (v === 'local') inputRef.current?.click();
                        else onChange({ kind: 'paste', text: '' });
                    }}>
                    {/* No Tooltip around these: the group finds its buttons'
                        values on its direct children, and a wrapper hides them. */}
                    <Button value="file" title="An org file the server reads, at any revision" aria-label="Org file"><DescriptionOutlinedIcon sx={{ fontSize: 16 }} /></Button>
                    <Button value="local" title="A file from this computer (or drop one on this card)" aria-label="Local file"><UploadFileOutlinedIcon sx={{ fontSize: 16 }} /></Button>
                    <Button value="paste" title="Paste text" aria-label="Paste text"><ContentPasteOutlinedIcon sx={{ fontSize: 16 }} /></Button>
                </ToggleButtonGroup>
                <input ref={inputRef} type="file" accept=".org,.txt,.md,text/*" style={{ display: 'none' }}
                    onChange={e => { const f = e.target.files?.[0]; if (f) readFile(f); e.target.value = ''; }} />
            </Box>
            {src.kind === 'file' && (
                <>
                    <FilePicker files={files} value={src.file} onChange={f => onChange({ kind: 'file', file: f, rev: WORKING })} />
                    <Select size="sm" value={src.rev} disabled={!src.file}
                        onChange={(_e, v) => v && onChange({ ...src, rev: v as string })}>
                        <Option value={WORKING}>Working copy (on disk)</Option>
                        {h?.Staged && <Option value={INDEX}>Staged</Option>}
                        {(h?.Commits || []).map(c => (
                            <Option key={c.Hash} value={c.Hash} label={`${c.Short} · ${c.Subject}`}>
                                <Box sx={{ minWidth: 0 }}>
                                    <Typography level="body-sm" sx={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                        <Box component="span" sx={{ fontFamily: 'monospace', color: 'text.tertiary', mr: 0.75 }}>{c.Short}</Box>
                                        {c.Subject}
                                    </Typography>
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{c.Author} · {relativeTime(c.When)}</Typography>
                                </Box>
                            </Option>
                        ))}
                    </Select>
                    {h && !h.InRepo && src.file && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Not in git: only the working copy.</Typography>
                    )}
                </>
            )}
            {src.kind === 'local' && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <UploadFileOutlinedIcon sx={{ color: 'text.tertiary' }} />
                    <Box sx={{ minWidth: 0, flex: 1 }}>
                        <Typography level="body-sm" sx={{ fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{src.name}</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {src.text.split('\n').length} lines · from this computer
                        </Typography>
                    </Box>
                    <Button size="sm" variant="plain" onClick={() => inputRef.current?.click()}>Change</Button>
                </Box>
            )}
            {src.kind === 'paste' && (
                <Textarea size="sm" minRows={4} maxRows={10} placeholder="Paste org text here" value={src.text}
                    onChange={e => onChange({ kind: 'paste', text: e.target.value })}
                    sx={{ fontFamily: 'monospace', fontSize: 12 }} />
            )}
            {over && <Typography level="body-xs" color="primary">Drop to compare this file</Typography>}
        </Sheet>
    );
}

function sideOf(src: Source, loaded: Loaded | null, h: HistoryResult | undefined): DiffSide {
    if (src.kind === 'local') return { text: src.text, label: src.name, detail: 'from this computer' };
    if (src.kind === 'paste') return { text: src.text, label: 'Pasted text' };
    const d = describe(src.rev, h || null, src.file);
    return { text: loaded?.text || '', label: baseName(src.file) || '—', detail: d.label + (d.detail && src.rev !== WORKING ? ' · ' + d.detail : ''), missing: loaded?.missing };
}

// The text behind a source that names an org file, read from the server.
function useSourceText(src: Source, reload: number, onError: (msg: string) => void): Loaded | null {
    const [loaded, setLoaded] = React.useState<Loaded | null>(null);
    const file = src.kind === 'file' ? src.file : '';
    const rev = src.kind === 'file' ? src.rev : '';
    React.useEffect(() => {
        setLoaded(null);
        if (!file) return;
        let live = true;
        loadText(file, rev).then(l => live && setLoaded(l)).catch(e => live && onError(String(e.message || e)));
        return () => { live = false; };
    }, [file, rev, reload, onError]);
    return loaded;
}

function CompareMode({ files }: { files: string[] }) {
    const isMobile = useIsMobile();
    const [diffFile] = useSetting('diffFile');
    const [a, setA] = React.useState<Source>({ kind: 'file', file: diffFile, rev: WORKING });
    const [b, setB] = React.useState<Source>({ kind: 'file', file: '', rev: WORKING });
    const [histories, setHistories] = React.useState<Map<string, HistoryResult>>(new Map());
    const [error, setError] = React.useState('');
    const [reload, setReload] = React.useState(0);

    const asked = React.useRef(new Set<string>());
    const wantHistory = React.useCallback((file: string) => {
        if (asked.current.has(file)) return;
        asked.current.add(file);
        ODb.getHistory(file, false, 200).then(h => {
            if (h && h.Ok) setHistories(prev => new Map(prev).set(file, h));
        }).catch(() => { /* a file with no history still compares */ });
    }, []);

    const la = useSourceText(a, reload, setError);
    const lb = useSourceText(b, reload, setError);

    const ready = (s: Source, l: Loaded | null) => s.kind === 'file' ? !!s.file && l !== null : s.kind === 'local' || s.text !== '';
    const left = sideOf(a, la, a.kind === 'file' ? histories.get(a.file) : undefined);
    const right = sideOf(b, lb, b.kind === 'file' ? histories.get(b.file) : undefined);
    const placeholder = error
        ? <Typography color="danger">{error}</Typography>
        : !ready(a, la) || !ready(b, lb)
            ? <Box sx={{ textAlign: 'center' }}>
                <CompareArrowsIcon sx={{ fontSize: 40, opacity: 0.4 }} />
                <Typography level="body-md" sx={{ mt: 1 }}>Pick something for both sides.</Typography>
                <Typography level="body-sm" sx={{ mt: 0.5, opacity: 0.8 }}>
                    An org file at any revision, a file from this computer (drop it on a card), or pasted text.
                </Typography>
            </Box>
            : null;

    return (
        <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: 1.5, flex: 1, minHeight: 0 }}>
            <Box sx={{
                width: isMobile ? 'auto' : 360, flex: '0 0 auto', display: 'flex', flexDirection: 'column', gap: 1,
                overflow: 'auto', minHeight: 0,
            }}>
                <SourceCard which="a" src={a} onChange={s => { setError(''); setA(s); }} files={files} histories={histories} wantHistory={wantHistory} />
                <Box sx={{ display: 'flex', justifyContent: 'center', gap: 1 }}>
                    <Tooltip size="sm" title="Swap the two sides">
                        <IconButton size="sm" variant="outlined" onClick={() => { setA(b); setB(a); }}>
                            <SwapHorizIcon sx={{ transform: 'rotate(90deg)' }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="Read both files again">
                        <IconButton size="sm" variant="outlined" onClick={() => setReload(k => k + 1)}>
                            <RefreshIcon />
                        </IconButton>
                    </Tooltip>
                </Box>
                <SourceCard which="b" src={b} onChange={s => { setError(''); setB(s); }} files={files} histories={histories} wantHistory={wantHistory} />
            </Box>
            <DiffView left={left} right={right} placeholder={placeholder} />
        </Box>
    );
}

// ---------------------------------------------------------------------------

export default function Diff() {
    const [mode, setMode] = useSetting('diffMode');
    const [files, setFiles] = React.useState<string[]>([]);
    React.useEffect(() => {
        ODb.getFiles().then(f => setFiles((Array.isArray(f) ? f : []).slice().sort((x, y) => baseName(x).localeCompare(baseName(y)))))
            .catch(() => setFiles([]));
    }, []);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <ToggleButtonGroup size="sm" value={mode} onChange={(_e, v) => v && setMode(v as any)}>
                    <Button value="history" startDecorator={<HistoryOutlinedIcon />}>History</Button>
                    <Button value="compare" startDecorator={<CompareArrowsIcon />}>Compare</Button>
                </ToggleButtonGroup>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', display: { xs: 'none', md: 'block' } }}>
                    {mode === 'history'
                        ? 'A file’s git history, and what changed at each step'
                        : 'Any two files, revisions or texts, side by side'}
                </Typography>
            </Box>
            {mode === 'history' ? <HistoryMode files={files} /> : <CompareMode files={files} />}
        </Box>
    );
}
