function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

// ---------------------------------------------------------------------------
// One cell being edited
// ---------------------------------------------------------------------------

// An ordinary property, typed with the values already in use offered as it is
// typed: org's own `<PROPERTY>_ALL` list first where the file gives one, then
// every value the property takes elsewhere in the file, most used first - which
// is what keeps "In progress" from becoming "In Progress" on the next heading.
// Anything may still be typed: a new value is written as typed.
type Suggestion = { value: string; count: number };

function PropertyEditor({ cell, suggestions, onDone }: {
    cell: ColumnCell; suggestions: Suggestion[]; onDone: (value: string | null) => void;
}) {
    const [value, setValue] = React.useState(editValue(cell));

    // An editor may be finished in four ways - a value picked from the list,
    // Enter, Escape, or the focus moving away - and exactly one of them must be
    // the one that counts.
    //
    // Clicking an option in the list moves the focus first, so a blur that
    // committed straight away beat the click and put the *old* value back: the
    // list looked like it did nothing. Deferring the blur lets the click land,
    // and the latch is what stops the deferred blur then committing a second
    // time over the top of it.
    const finished = React.useRef(false);
    const finish = React.useCallback((v: string | null) => {
        if (finished.current) return;
        finished.current = true;
        onDone(v);
    }, [onDone]);

    if (suggestions.length > 0) {
        const counts = new Map(suggestions.map(x => [x.value, x.count] as [string, number]));
        return (
            <Autocomplete
                autoFocus openOnFocus freeSolo size="sm"
                options={suggestions.map(x => x.value)}
                value={null}
                inputValue={value}
                onInputChange={(_, v) => setValue(v || '')}
                // A pick from the list. Enter on typed text that matches no
                // option arrives here too (freeSolo), as the typed string.
                onChange={(_, v) => finish(v === null ? value : String(v))}
                onKeyDown={e => {
                    // Enter is left to the list first - it may be picking the
                    // highlighted option - and caught afterwards for a value
                    // the list does not report (typed text equal to nothing new).
                    if (e.key === 'Enter') { const v = value; window.setTimeout(() => finish(v), 0); }
                    else if (e.key === 'Escape') { e.preventDefault(); finish(null); }
                }}
                onBlur={() => { const v = value; window.setTimeout(() => finish(v), 150); }}
                renderOption={(props, option) => (
                    <AutocompleteOption {...props}>
                        <Box sx={{ display: 'flex', width: '100%', gap: 1 }}>
                            <Typography level="body-sm" sx={{ flex: 1 }}>{option as string}</Typography>
                            {(counts.get(option as string) || 0) > 0 && (
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                    {counts.get(option as string)}
                                </Typography>
                            )}
                        </Box>
                    </AutocompleteOption>
                )}
                slotProps={{ input: { 'aria-label': 'Property value' } }}
                sx={{ minWidth: 140, '--Input-minHeight': '26px', fontSize: 12 }}
            />
        );
    }
    const keys = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') { e.preventDefault(); finish(value); }
        else if (e.key === 'Escape') { e.preventDefault(); finish(null); }
    };
    return (
        <Input
            autoFocus size="sm" value={value}
            onChange={e => setValue(e.target.value)}
            onKeyDown={keys}
            onBlur={() => finish(value)}
            sx={{ minWidth: 90, '--Input-minHeight': '26px', fontSize: 12 }}
        />
    );
}

// The columns line, with suggestions as it is typed: property names after
// `%` (org's own and the ones this file uses), summary operators inside `{`,
// worg's options after `+`. Arrow keys move through them, Enter or Tab takes
// one; Enter with nothing offered applies the line.
function SpecInput({ value, onChange, onApply, props, endDecorator }: {
    value: string;
    onChange: (v: string) => void;
    onApply: () => void;
    props: { name: string; count: number }[];
    endDecorator: React.ReactNode;
}) {
    const ref = React.useRef<HTMLInputElement | null>(null);
    const [caret, setCaret] = React.useState(0);
    const [focused, setFocused] = React.useState(false);
    const [cursor, setCursor] = React.useState(0);
    const [dismissed, setDismissed] = React.useState(false);
    const completion = focused && !dismissed ? specCompletion(value, caret, props) : null;
    React.useEffect(() => { setCursor(0); }, [value, caret]);

    const readCaret = () => setCaret(ref.current ? (ref.current.selectionStart ?? value.length) : value.length);
    const accept = (item: string) => {
        if (!completion) return;
        const next = value.slice(0, completion.from) + item + value.slice(completion.to);
        const at = completion.from + item.length;
        onChange(next);
        window.setTimeout(() => {
            if (ref.current) { ref.current.focus(); ref.current.setSelectionRange(at, at); }
            setCaret(at);
        }, 0);
    };
    return (
        <>
            <Input
                size="sm"
                placeholder="%25ITEM %TODO %EFFORT{:} +path"
                value={value}
                slotProps={{ input: { ref, 'aria-label': 'Columns line', spellCheck: false } }}
                onChange={e => { onChange(e.target.value); setDismissed(false); setCaret(e.target.selectionStart ?? e.target.value.length); }}
                onKeyUp={readCaret}
                onClick={readCaret}
                onFocus={() => { setFocused(true); readCaret(); }}
                onBlur={() => window.setTimeout(() => setFocused(false), 150)}
                onKeyDown={e => {
                    const items = completion ? completion.items : [];
                    if (items.length > 0) {
                        if (e.key === 'ArrowDown') { e.preventDefault(); setCursor(c => Math.min(c + 1, items.length - 1)); return; }
                        if (e.key === 'ArrowUp') { e.preventDefault(); setCursor(c => Math.max(c - 1, 0)); return; }
                        if (e.key === 'Enter' || e.key === 'Tab') { e.preventDefault(); accept(items[cursor].value); return; }
                        if (e.key === 'Escape') { e.preventDefault(); setDismissed(true); return; }
                    }
                    if (e.key === 'Enter') onApply();
                }}
                sx={{ flex: '1 1 320px', fontFamily: 'monospace', fontSize: 12 }}
                endDecorator={endDecorator}
            />
            <Popper open={!!completion && !!ref.current} anchorEl={ref.current} placement="bottom-start" style={{ zIndex: 1300 }}>
                <Sheet variant="outlined" role="listbox" data-testid="spec-suggestions"
                    sx={{ borderRadius: 'sm', boxShadow: 'md', py: 0.5, minWidth: 240, maxHeight: 260, overflowY: 'auto' }}>
                    {(completion ? completion.items : []).map((it, i) => (
                        <Box key={it.value} role="option" aria-selected={i === cursor}
                            onMouseDown={e => { e.preventDefault(); accept(it.value); }}
                            onMouseEnter={() => setCursor(i)}
                            sx={{ display: 'flex', gap: 1.5, px: 1, py: 0.25, cursor: 'pointer',
                                bgcolor: i === cursor ? 'primary.softBg' : undefined }}>
                            <Typography level="body-sm" sx={{ fontFamily: 'monospace', minWidth: 90 }}>{it.value}</Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{it.hint}</Typography>
                        </Box>
                    ))}
                </Sheet>
            </Popper>
        </>
    );
}

// A heading's tags, edited as a list: the tags already used in the file are
// offered as they are typed (most used first), anything new can be typed and
// Enter makes it a tag, and Enter on an empty box - or leaving it - writes the
// list. Escape leaves the heading as it was.
function TagsEditor({ tags, suggestions, onDone }: {
    tags: string[]; suggestions: Suggestion[]; onDone: (tags: string[] | null) => void;
}) {
    const [value, setValue] = React.useState<string[]>(tags);
    const [input, setInput] = React.useState('');
    const latest = React.useRef(value);
    latest.current = value;
    const finished = React.useRef(false);
    const finish = React.useCallback((v: string[] | null) => {
        if (finished.current) return;
        finished.current = true;
        onDone(v);
    }, [onDone]);
    const counts = new Map(suggestions.map(x => [x.value, x.count] as [string, number]));
    const clean = (xs: string[]) => Array.from(new Set(xs.map(x => x.trim().replace(/^:+|:+$/g, '')).filter(x => x && !/[\s:]/.test(x))));
    return (
        <Autocomplete
            multiple freeSolo autoFocus openOnFocus size="sm"
            options={suggestions.map(x => x.value).filter(v => !value.includes(v))}
            value={value}
            inputValue={input}
            onInputChange={(_, v) => setInput((v || '').replace(/[\s:]/g, ''))}
            onChange={(_, v) => setValue(clean(v as string[]))}
            onKeyDown={e => {
                if (e.key === 'Escape') { e.preventDefault(); finish(null); }
                // Enter on an empty box writes the list; with text in the box
                // it is the Autocomplete's, which makes the text a tag.
                else if (e.key === 'Enter' && input.trim() === '') {
                    e.preventDefault();
                    window.setTimeout(() => finish(latest.current), 0);
                }
            }}
            onBlur={() => window.setTimeout(() => {
                // Text left in the box when focus goes is a tag too.
                const extra = input.trim() ? clean([...latest.current, input]) : latest.current;
                finish(extra);
            }, 150)}
            renderOption={(props, option) => (
                <AutocompleteOption {...props}>
                    <Box sx={{ display: 'flex', width: '100%', gap: 1 }}>
                        <Typography level="body-sm" sx={{ flex: 1 }}>{option as string}</Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{counts.get(option as string) || ''}</Typography>
                    </Box>
                </AutocompleteOption>
            )}
            placeholder={value.length ? '' : 'add a tag'}
            slotProps={{ input: { 'aria-label': 'Tags' } }}
            sx={{ minWidth: 180, '--Input-minHeight': '26px', fontSize: 12 }}
        />
    );
}

// A look at the file around a heading, after the pointer has rested on its
// title for a moment: a few lines before it, the heading, and what is written
// under it up to the next heading at its level or above (or a screenful).
// Coloured exactly as the Files tab's org view colours it - the same tokens
// (lineTokens, walk) in the reader's own org theme (the orgTheme setting) - so
// a preview reads like the file rather than like a terminal dump.
const PREVIEW_DELAY = 1500;

function previewRange(lines: string[], line: number, level: number): [number, number] {
    const from = Math.max(0, line - 3);
    let to = from;
    for (let i = from; i < lines.length && i - from < 26; i++) {
        if (i > line) {
            const m = lines[i].match(/^(\*+)\s/);
            if (m && m[1].length <= level) break;
        }
        to = i;
    }
    return [from, to];
}

const MONO = '"SFMono-Regular", "JetBrains Mono", Consolas, "Liberation Mono", Menlo, monospace';

function HeadingPreview({ anchor, text, row, onEnter, onLeave }: {
    anchor: HTMLElement | null; text: string | null; row: ColumnRow;
    onEnter: () => void; onLeave: () => void;
}) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [themeKey] = useSetting('orgTheme');
    const p = orgPalette(themeKey, dark);
    // The whole file is walked once per file (not per preview), because a
    // line's colours depend on the blocks and drawers above it.
    const lines = React.useMemo(() => (text === null ? [] : text.replace(/\r\n/g, '\n').split('\n')), [text]);
    const st = React.useMemo(() => todoStates(text || ''), [text]);
    const states = React.useMemo(() => walk(lines), [lines]);
    const [from, to] = text === null ? [0, -1] : previewRange(lines, row.LineNum, row.Level);
    const shown: number[] = [];
    for (let i = from; i <= to; i++) shown.push(i);

    return (
        <Popper
            open={!!anchor} anchorEl={anchor} placement="bottom-start" style={{ zIndex: 1300 }}
            // Kept on screen: flipped above the title when there is no room
            // below, slid sideways rather than run off an edge, and never
            // bigger than the window has room for.
            modifiers={[
                { name: 'offset', options: { offset: [0, 6] } },
                { name: 'flip', options: { padding: 8, fallbackPlacements: ['top-start', 'bottom-end', 'top-end'] } },
                { name: 'preventOverflow', options: { padding: 8, altAxis: true, tether: false } },
            ]}
        >
            <Box
                onMouseEnter={onEnter} onMouseLeave={onLeave} data-testid="heading-preview"
                sx={{
                    borderRadius: '8px', boxShadow: 'lg', border: '1px solid', borderColor: p.gutter,
                    width: 'min(620px, calc(100vw - 32px))', maxHeight: 'min(380px, calc(100vh - 120px))', overflow: 'auto',
                    bgcolor: p.bg, color: p.fg, py: 0.75,
                    fontFamily: MONO, fontSize: 12, lineHeight: 1.5,
                }}
            >
                {text === null ? (
                    <Box sx={{ px: 1.5, color: p.gutter }}>reading the file…</Box>
                ) : (
                    <Box component="pre" sx={{ m: 0, fontFamily: 'inherit', fontSize: 'inherit', lineHeight: 'inherit' }}>
                        {shown.map(i => (
                            <Box key={i} sx={{
                                display: 'flex', alignItems: 'flex-start',
                                bgcolor: i === row.LineNum ? p.selBg : undefined,
                                boxShadow: i === row.LineNum ? `inset 2px 0 0 ${p.h1}` : undefined,
                            }}>
                                <Box component="span" sx={{ flex: '0 0 auto', width: '4.5ch', pr: 1, textAlign: 'right', color: p.gutter, userSelect: 'none' }}>
                                    {i + 1}
                                </Box>
                                <Box component="span" sx={{ flex: 1, minWidth: 0, pr: 1.5, whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>
                                    {lineTokens(lines[i], st, states[i].block, states[i].drawer, states[i].lang, states[i].code).map((t, j) => (
                                        <span key={j} style={{
                                            color: p[t.c] || p.fg,
                                            fontWeight: t.bold ? 700 : undefined,
                                            fontStyle: t.italic ? 'italic' : undefined,
                                            textDecoration: t.strike ? 'line-through' : t.underline ? 'underline' : undefined,
                                        }}>{t.s}</span>
                                    ))}
                                    {lines[i] === '' ? ' ' : null}
                                </Box>
                            </Box>
                        ))}
                    </Box>
                )}
            </Box>
        </Popper>
    );
}

// The keyword, offered from the heading's own file. Asked for when the menu
// opens rather than while three hundred rows are drawn, and asked per heading
// because a file may declare its own `#+TODO:` - offering a keyword the file
// does not have is offering to write something org will not read back.
function StatusEditor({ row, onPick }: { row: ColumnRow; onPick: (status: string) => void }) {
    const [states, setStates] = React.useState<string[] | null>(null);
    const asked = React.useRef(false);

    React.useEffect(() => { asked.current = false; setStates(null); }, [row.Hash]);

    const load = () => {
        if (asked.current) return;
        asked.current = true;
        ODb.validStatus(row.Hash)
            .then(r => setStates([...(r.Active || []), ...(r.Done || [])]))
            .catch(() => setStates([]));
    };

    const custom = getStatusCustomSx(row.Status);
    return (
        <Dropdown onOpenChange={(_, open) => { if (open) load(); }}>
            <MenuButton
                slots={{ root: Box }}
                slotProps={{ root: { sx: { cursor: 'pointer', display: 'inline-flex' } } }}
            >
                {row.Status ? (
                    <Chip
                        size="sm" variant="soft" color={getStatusColor(row.Status)}
                        startDecorator={getStatusIcon(row.Status)}
                        sx={{
                            '--Chip-minHeight': '20px', fontSize: 11, fontWeight: 'lg',
                            pointerEvents: 'none', '& .MuiSvgIcon-root': { fontSize: 12 },
                            ...(custom || {}),
                        }}
                    >{row.Status}</Chip>
                ) : (
                    <Chip
                        size="sm" variant="outlined" color="neutral"
                        sx={{
                            '--Chip-minHeight': '20px', fontSize: 11, borderStyle: 'dashed',
                            color: 'text.tertiary', pointerEvents: 'none', minWidth: 54,
                        }}
                    >none</Chip>
                )}
            </MenuButton>
            <Menu size="sm" placement="bottom-start">
                {states === null && <MenuItem disabled>loading…</MenuItem>}
                {states !== null && states.length === 0 && <MenuItem disabled>no keywords</MenuItem>}
                {/* Each keyword drawn as the chip it becomes - colour and icon -
                    so the menu reads like the column it changes. */}
                {(states || []).map(s => (
                    <MenuItem key={s} selected={s === row.Status} onClick={() => onPick(s)}>
                        <Chip
                            size="sm" variant="soft" color={getStatusColor(s)}
                            startDecorator={getStatusIcon(s)}
                            sx={{
                                '--Chip-minHeight': '20px', fontSize: 11, fontWeight: 'lg',
                                pointerEvents: 'none', '& .MuiSvgIcon-root': { fontSize: 12 },
                                ...(getStatusCustomSx(s) || {}),
                            }}
                        >{s}</Chip>
                    </MenuItem>
                ))}
                {states !== null && states.length > 0 && (
                    <MenuItem onClick={() => onPick('')}>
                        <Typography level="body-xs" sx={{ fontStyle: 'italic' }}>no keyword</Typography>
                    </MenuItem>
                )}
            </Menu>
        </Dropdown>
    );
}

