type Editing = { hash: string; col: number } | null;

// Default widths, in pixels, for a column the line gives none: the item wide
// enough to read, everything else wide enough for a value. The table is laid
// out fixed so a resized column is exactly the width it was dragged to.
// A column the line gives a width (`%25`) is that wide; the rest share what is
// left of the screen - the item taking a good part of it - so the table fills
// the width by default and widening one column narrows the unsized ones
// rather than pushing the table off the side.
const ITEM_SHARE = '34%';
const ITEM_MIN = 220;
const VALUE_MIN = 90;
// A width too small for what the column shows - org's `%3PRIORITY` is three
// characters of terminal, too narrow for a chip or an editor - is raised to
// what it needs. Priority with no width gets a small fixed width rather than
// an equal share of the screen for one letter.
const MIN_PX: Record<string, number> = { priority: 64, todo: 96, tags: 80, item: 160 };
const fixedPx = (s: ColumnSpec): number | undefined => {
    const w = columnWidth(s);
    if (w !== undefined) return Math.max(w, MIN_PX[s.Kind] || 56);
    if (s.Kind === 'priority') return 72;
    return undefined;
};

export default function Columns() {
    const nav = useNav();
    const [files, setFiles] = React.useState<string[]>([]);
    // Which file, kept in the browser settings: a column view is about one
    // project and a tab that forgets which is a tab you set up again each time.
    const [file, setFile] = useSetting('columnsFile');
    // The spec being used, and whether it is the file's own. Empty means "let
    // the server decide", which is how the file's own line and the configured
    // default get a chance to be the answer.
    const [spec, setSpec] = React.useState<string>('');
    const [specDraft, setSpecDraft] = React.useState<string>('');
    const [data, setData] = React.useState<ColumnsResult | null>(null);
    const [values, setValues] = React.useState<ColumnValuesResult | null>(null);
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState<string>('');
    const [folded, setFolded] = React.useState<Set<string>>(new Set());
    const [editing, setEditing] = React.useState<Editing>(null);
    const [sortOn, setSortOn] = React.useState<{ col: number; dir: 'asc' | 'desc' } | null>(null);
    const [saving, setSaving] = React.useState(false);
    // Rows narrowed to one value of one property (by name, so moving columns
    // does not change what it means).
    const [valueFilter, setValueFilter] = React.useState<{ prop: string; value: string } | null>(null);
    // The Values tool's property.
    const [valuesProp, setValuesProp] = React.useState<string>('');

    React.useEffect(() => {
        ODb.getFiles().then(f => setFiles(f || [])).catch(() => setFiles([]));
    }, []);

    const load = React.useCallback((f: string, sp: string) => {
        if (!f) { setData(null); setValues(null); return; }
        setBusy(true);
        setError('');
        ODb.getColumns(f, sp || undefined)
            .then(r => {
                if (!r || !r.Ok) {
                    setError((r && r.Msg) || 'could not read that file');
                    setData(null);
                    return;
                }
                setData(r);
                // The line the server settled on becomes what the box shows, so
                // editing it starts from the file's own rather than from blank.
                setSpecDraft(r.Columns);
            })
            .catch(e => setError(String(e)))
            .finally(() => setBusy(false));
        // The values in use, read alongside: they change with every edit too.
        ODb.getColumnValues(f).then(v => setValues(v && v.Ok ? v : null)).catch(() => setValues(null));
    }, []);

    React.useEffect(() => { load(file, spec); }, [file, spec, load]);

    // Every change to the line made from the table - moving, resizing, an
    // option - is applied at once, for this view: the chip then says
    // "request", and Save writes it into the file.
    const applyLine = React.useCallback((line: string) => {
        setSpecDraft(line);
        setSpec(line);
    }, []);

    const opts = React.useMemo(() => columnOptions(data?.Columns || ''), [data]);
    const tree = !opts.flat;

    const propValues = React.useMemo(() => {
        const m = new Map<string, Suggestion[]>();
        for (const p of values?.Props || []) {
            m.set(p.Name.toUpperCase(), (p.Values || []).map(v => ({ value: v.Value, count: v.Count })));
        }
        return m;
    }, [values]);
    const propNames = React.useMemo(
        () => (values?.Props || []).map(p => ({ name: p.Name, count: p.Count })),
        [values],
    );
    const suggestionsFor = (s: ColumnSpec): Suggestion[] => {
        const used = propValues.get(s.Property) || [];
        const allowed = (s.Allowed || []).filter(a => !used.some(u => u.value === a)).map(a => ({ value: a, count: 0 }));
        // The file's own list of allowed values first, as org offers it.
        const own = (s.Allowed || []).map(a => ({ value: a, count: (used.find(u => u.value === a) || { count: 0 }).count }));
        return s.Allowed && s.Allowed.length ? [...own, ...used.filter(u => !(s.Allowed || []).includes(u.value))] : [...used, ...allowed];
    };

    const ancestors = React.useMemo(() => ancestorsOf(data?.Rows || []), [data]);

    const rows: ColumnRow[] = React.useMemo(() => {
        let all = data?.Rows || [];
        if (valueFilter && data?.Spec) {
            const col = data.Spec.findIndex(s => s.Property === valueFilter.prop);
            if (col >= 0) {
                const keep = rowsWithValue(all, col, valueFilter.value);
                all = all.filter(r => keep.has(r.Hash));
            }
        }
        if (!sortOn || !data?.Spec) return all;
        const s = data.Spec[sortOn.col];
        return sortWithinParents(all, sortOn.col, sortOn.dir, !!s && s.Numbers !== '');
    }, [data, sortOn, valueFilter]);

    const hidden = React.useMemo(() => (tree ? hiddenRows(rows, folded) : new Set<string>()), [rows, folded, tree]);
    const visible = React.useMemo(() => rows.filter(r => !hidden.has(r.Hash)), [rows, hidden]);

    // --- a new entry ---------------------------------------------------------
    //
    // The row clicked last is the selected one; N (or the New entry button)
    // opens a line straight under it, and what is typed there becomes a
    // heading after it - a sibling, after its whole subtree, at its level
    // (POST /gantt/add with AfterHash). With nothing selected it goes at the
    // end of the file. The line reads the gantt chart's quick add syntax
    // (ganttquick.ts): a keyword first, #tags, @person, 3d of effort, ^date,
    // !A, KEY=value. Enter adds it and opens the next line after the new one,
    // so a list is typed straight down; Esc stops.
    const [selRow, setSelRow] = React.useState('');
    // The heading the new line goes after, '' for the end of the file, or
    // null when no line is open.
    const [newAfter, setNewAfter] = React.useState<string | null>(null);
    const [newText, setNewText] = React.useState('');
    const [adding, setAdding] = React.useState(false);
    React.useEffect(() => { setSelRow(''); setNewAfter(null); }, [file]);

    const openNew = React.useCallback(() => {
        if (!file) return;
        setNewText('');
        setNewAfter(selRow && rows.some(r => r.Hash === selRow) ? selRow : '');
    }, [file, selRow, rows]);

    const addNew = React.useCallback(async () => {
        if (newAfter === null || !newText.trim()) return;
        const q = parseQuickAdd(newText, []);
        if (!q.headline) return;
        const after = rows.find(r => r.Hash === newAfter);
        const props: Record<string, string> = { ...q.props };
        if (q.person) props.ASSIGNED = q.person;
        const headline = q.priority ? `[#${q.priority}] ${q.headline}` : q.headline;
        setAdding(true);
        setError('');
        try {
            const res = await ODb.ganttAdd({
                AfterHash: after ? after.Hash : undefined,
                Filename: after ? undefined : file,
                Headline: headline,
                // A sibling of a todo is a todo, unless a keyword was typed.
                Status: q.status || (after && after.Status ? 'TODO' : ''),
                Start: q.start ? `${q.start.getFullYear()}-${String(q.start.getMonth() + 1).padStart(2, '0')}-${String(q.start.getDate()).padStart(2, '0')}` : '',
                Effort: q.effort,
                Tags: q.tags,
                Props: props,
            });
            if (!res || res.Ok === false) { setError((res && res.Msg) || 'could not add that'); return; }
            // Read the file again and carry on from the new heading.
            const r = await ODb.getColumns(file, spec || undefined);
            if (r && r.Ok) {
                setData(r);
                const made = (r.Rows || []).filter(x => x.Headline.replace(/^\[#[A-Za-z]\]\s*/, '') === q.headline);
                const hash = made.length ? made[made.length - 1].Hash : '';
                setSelRow(hash);
                setNewAfter(hash || '');
            }
            setNewText('');
        } catch (e) {
            setError(String(e));
        } finally {
            setAdding(false);
        }
    }, [newAfter, newText, rows, file, spec]);

    React.useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            if (e.key.toLowerCase() !== 'n' || e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
            const el = document.activeElement as HTMLElement | null;
            if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT'
                || el.isContentEditable || el.getAttribute('role') === 'combobox')) return;
            if (document.querySelector('.MuiModal-root') || !data) return;
            e.preventDefault();
            openNew();
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [openNew, data]);

    // The new line is drawn under the last row of the selected one's subtree,
    // which is where the new heading will land.
    const newLineAfter = React.useMemo(() => {
        if (!newAfter) return '';
        const i = visible.findIndex(r => r.Hash === newAfter);
        if (i < 0) return '';
        let j = i;
        while (j + 1 < visible.length && visible[j + 1].Level > visible[i].Level) j++;
        return visible[j].Hash;
    }, [newAfter, visible]);

    const newLine = (colSpan: number, afterName: string) => (
        <tr key="new-entry">
            <td colSpan={colSpan}>
                <Input
                    autoFocus
                    size="sm"
                    disabled={adding}
                    value={newText}
                    placeholder={`New heading ${afterName ? `after ${afterName}` : 'at the end of the file'} - Write the spec #tag @person 3d ^fri`}
                    onChange={e => setNewText(e.target.value)}
                    onKeyDown={e => {
                        if (e.key === 'Enter') { e.preventDefault(); addNew(); }
                        if (e.key === 'Escape') { e.preventDefault(); setNewAfter(null); }
                    }}
                    onBlur={() => { if (!newText.trim() && !adding) setNewAfter(null); }}
                    startDecorator={<AddIcon fontSize="small" />}
                    sx={{ fontFamily: 'monospace' }}
                />
            </td>
        </tr>
    );

    // Totals of a subtree for the number columns the line does not sum (EFFORT
    // with no `{:}`), shown small beside a parent's own value while the
    // outline is drawn. Columns the line does sum already show their total.
    const subtotals = React.useMemo(() => {
        const m = new Map<number, Map<string, number>>();
        if (!tree || !data?.Spec || !data.Rows) return m;
        data.Spec.forEach((s, i) => {
            const summed = s.Summary !== '' || s.Property === 'CLOCKSUM' || s.Property === 'CLOCKSUM_T';
            if (s.Numbers && !summed) m.set(i, subtreeTotals(data.Rows || [], i));
        });
        return m;
    }, [data, tree]);

    const toggleFold = (hash: string) => {
        setFolded(prev => {
            const next = new Set(prev);
            if (next.has(hash)) next.delete(hash); else next.add(hash);
            return next;
        });
    };
    const foldAll = () => setFolded(new Set(foldableRows(rows)));
    const unfoldAll = () => setFolded(new Set());
    // Show the outline down to a level: everything deeper is folded away.
    const foldToLevel = (level: number) =>
        setFolded(new Set(rows.filter(r => r.HasChildren && r.Level >= level).map(r => r.Hash)));
    const maxLevel = React.useMemo(() => rows.reduce((m, r) => Math.max(m, r.Level), 1), [rows]);

    // Every write goes through an endpoint that already existed, and the view is
    // read back afterwards rather than patched in place. A rollup is of the whole
    // subtree, so one edited estimate changes the cell above it, and the one
    // above that - patching locally would mean saying the rollup rule a second
    // time in the browser and getting to keep both versions in step.
    const commit = async (row: ColumnRow, col: number, value: string | null) => {
        setEditing(null);
        if (value === null || !data?.Spec) return;
        const s = data.Spec[col];
        const cell = row.Cells[col];
        if (value === editValue(cell)) return;
        setSaving(true);
        try {
            if (s.Kind === 'property') {
                await ODb.changeProperty(row.Hash, s.Property, value);
            } else if (s.Kind === 'todo') {
                await ODb.changeStatus(row.Hash, value);
            } else if (s.Kind === 'item') {
                await ODb.renameHeadline(row.Hash, value);
            } else if (s.Kind === 'priority') {
                const r = await ODb.setHeadingParts(row.Hash, { Priority: value.trim() });
                if (r && r.Ok === false) setError(r.Msg || 'could not set the priority');
            }
            load(file, spec);
        } catch (e) {
            setError(String(e));
        } finally {
            setSaving(false);
        }
    };

    const commitTags = async (row: ColumnRow, tags: string[] | null) => {
        setEditing(null);
        if (tags === null) return;
        const before = (row.Tags || []).join(':');
        if (tags.join(':') === before) return;
        setSaving(true);
        try {
            const r = await ODb.setHeadingParts(row.Hash, { Tags: tags });
            if (r && r.Ok === false) setError(r.Msg || 'could not set the tags');
            load(file, spec);
        } catch (e) {
            setError(String(e));
        } finally {
            setSaving(false);
        }
    };

    const saveSpecToFile = async () => {
        if (!file) return;
        setSaving(true);
        try {
            const r = await ODb.setFileColumns(file, specDraft);
            if (r && r.Ok === false) { setError(r.Msg || 'could not write the columns line'); }
            else {
                // Written to the file, so the override is no longer needed - and
                // leaving it on would hide the next change anybody made in the
                // file itself.
                setSpec('');
                load(file, '');
            }
        } catch (e) {
            setError(String(e));
        } finally {
            setSaving(false);
        }
    };

    // --- moving and resizing columns -------------------------------------
    //
    // Both rewrite the columns line: a move reorders its `%...` groups, a resize
    // writes the column's `%WIDTH` (in characters, as org counts them - about
    // eight pixels each here). So the arrangement is the line, it goes into the
    // file with Save, and Emacs lays the columns out the same way.
    const [dragFrom, setDragFrom] = React.useState<number | null>(null);
    const [dropAt, setDropAt] = React.useState<number | null>(null);
    const [liveWidths, setLiveWidths] = React.useState<Record<number, number>>({});
    const resizing = React.useRef(false);
    React.useEffect(() => { setLiveWidths({}); }, [data]);

    const dropColumn = (to: number) => {
        const from = dragFrom;
        setDragFrom(null);
        setDropAt(null);
        if (from === null || from === to || !data) return;
        setSortOn(null);
        applyLine(moveColumn(data.Columns, from, to));
    };

    const startResize = (e: React.PointerEvent, i: number) => {
        e.preventDefault();
        e.stopPropagation();
        const th = (e.currentTarget as HTMLElement).parentElement as HTMLElement;
        const x0 = e.clientX;
        const w0 = th.getBoundingClientRect().width;
        resizing.current = true;
        let w = w0;
        const move = (ev: PointerEvent) => {
            w = Math.max(48, Math.round(w0 + ev.clientX - x0));
            setLiveWidths(prev => ({ ...prev, [i]: w }));
        };
        const up = () => {
            window.removeEventListener('pointermove', move);
            window.removeEventListener('pointerup', up);
            // The click that ends a resize must not also sort the column.
            window.setTimeout(() => { resizing.current = false; }, 0);
            if (data && Math.abs(w - w0) >= 2) applyLine(setColumnWidth(data.Columns, i, Math.max(1, Math.round(w / 8))));
        };
        window.addEventListener('pointermove', move);
        window.addEventListener('pointerup', up);
    };

    // --- the hover preview -------------------------------------------------
    const [preview, setPreview] = React.useState<{ row: ColumnRow; anchor: HTMLElement } | null>(null);
    const [fileText, setFileText] = React.useState<{ file: string; text: string } | null>(null);
    const hoverTimer = React.useRef<number | null>(null);
    const leaveTimer = React.useRef<number | null>(null);
    React.useEffect(() => { setFileText(null); setPreview(null); }, [data]);
    const hoverTitle = (row: ColumnRow, el: HTMLElement) => {
        if (leaveTimer.current) { window.clearTimeout(leaveTimer.current); leaveTimer.current = null; }
        if (hoverTimer.current) window.clearTimeout(hoverTimer.current);
        hoverTimer.current = window.setTimeout(() => {
            setPreview({ row, anchor: el });
            if (!fileText || fileText.file !== file) {
                ODb.getOrgFile(file).then(r => setFileText({ file, text: r && r.Ok ? r.Msg : '' })).catch(() => { });
            }
        }, PREVIEW_DELAY);
    };
    const leaveTitle = () => {
        if (hoverTimer.current) { window.clearTimeout(hoverTimer.current); hoverTimer.current = null; }
        if (leaveTimer.current) window.clearTimeout(leaveTimer.current);
        // A moment's grace to move onto the preview itself and read it.
        leaveTimer.current = window.setTimeout(() => setPreview(null), 250);
    };

    const headerCell = (s: ColumnSpec, i: number) => {
        const sorted = sortOn?.col === i;
        const summed = s.Summary !== '' || s.Property === 'CLOCKSUM' || s.Property === 'CLOCKSUM_T';
        return (
            <th
                key={`${s.Property}-${i}`}
                draggable
                onDragStart={e => {
                    if (resizing.current) { e.preventDefault(); return; }
                    setDragFrom(i);
                    e.dataTransfer.effectAllowed = 'move';
                    e.dataTransfer.setData('text/plain', String(i));
                }}
                onDragOver={e => { if (dragFrom !== null) { e.preventDefault(); setDropAt(i); } }}
                onDrop={e => { e.preventDefault(); dropColumn(i); }}
                onDragEnd={() => { setDragFrom(null); setDropAt(null); }}
                data-col={s.Property}
                style={{
                    cursor: 'pointer', whiteSpace: 'nowrap', position: 'relative',
                    opacity: dragFrom === i ? 0.45 : 1,
                    // Where the column being dragged would land: a bar on the
                    // side it would go in on.
                    boxShadow: dropAt === i && dragFrom !== null && dragFrom !== i
                        ? `inset ${dragFrom > i ? 3 : -3}px 0 0 var(--joy-palette-primary-500)` : undefined,
                }}
                onClick={() => {
                    if (resizing.current) return;
                    setSortOn(prev =>
                        prev?.col === i
                            ? (prev.dir === 'asc' ? { col: i, dir: 'desc' } : null)
                            : { col: i, dir: 'asc' });
                }}
            >
                <Tooltip
                    size="sm" enterDelay={500}
                    title={
                        (summed
                            ? `${s.Property} — parents show the total of everything under them`
                            : `${s.Property}${isEditable(s) ? ' — click a cell to edit it' : ' — worked out, not editable'}`)
                        + '. Drag to move the column, drag its right edge to resize.'
                    }
                >
                    <Box sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5, overflow: 'hidden', maxWidth: '100%' }}>
                        <Typography level="body-xs" sx={{ fontWeight: 'lg', overflow: 'hidden', textOverflow: 'ellipsis' }}>{s.Title}</Typography>
                        {summed && (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Σ</Typography>
                        )}
                        {sorted && (sortOn!.dir === 'asc'
                            ? <ArrowUpwardIcon sx={{ fontSize: 12 }} />
                            : <ArrowDownwardIcon sx={{ fontSize: 12 }} />)}
                    </Box>
                </Tooltip>
                {/* The resize grip: the column's right edge. */}
                <Box
                    role="separator"
                    aria-label={`Resize ${s.Title}`}
                    draggable={false}
                    onDragStart={e => e.preventDefault()}
                    onPointerDown={e => startResize(e, i)}
                    onClick={e => e.stopPropagation()}
                    sx={{
                        position: 'absolute', top: 0, right: -3, bottom: 0, width: 7, cursor: 'col-resize', zIndex: 2,
                        '&:hover': { bgcolor: 'primary.softHoverBg' },
                    }}
                />
            </th>
        );
    };

    const itemCell = (row: ColumnRow, s: ColumnSpec, i: number) => {
        const open = editing?.hash === row.Hash && editing?.col === i;
        const path = opts.path > 0 ? (ancestors.get(row.Hash) || []).slice(-opts.path) : [];
        return (
            <td key={i}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25, pl: tree ? `${(row.Level - 1) * 16}px` : 0, minWidth: 0 }}>
                    {tree && (row.HasChildren ? (
                        <IconButton
                            size="sm" variant="plain" color="neutral"
                            aria-label={folded.has(row.Hash) ? 'Open' : 'Fold'}
                            onClick={() => toggleFold(row.Hash)}
                            sx={{ '--IconButton-size': '18px', minWidth: 18 }}
                        >
                            {folded.has(row.Hash)
                                ? <ChevronRightIcon sx={{ fontSize: 15 }} />
                                : <ExpandMoreIcon sx={{ fontSize: 15 }} />}
                        </IconButton>
                    ) : <Box sx={{ width: 18, flex: '0 0 18px' }} />)}
                    {open ? (
                        <PropertyEditor
                            cell={row.Cells[i]}
                            suggestions={[]}
                            onDone={v => commit(row, i, v)}
                        />
                    ) : (
                        <Typography
                            level="body-sm"
                            onClick={() => isEditable(s) && setEditing({ hash: row.Hash, col: i })}
                            onMouseEnter={e => hoverTitle(row, e.currentTarget as HTMLElement)}
                            onMouseLeave={leaveTitle}
                            sx={{
                                cursor: isEditable(s) ? 'text' : 'default',
                                fontWeight: row.HasChildren ? 'lg' : 'md',
                                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', minWidth: 0,
                            }}
                        >
                            {/* A bit of the outline above it, when the line asks
                                for it (+path): the ancestors, dimmed, so a
                                heading still says where it lives once sorted or
                                filtered away from its parents. */}
                            {path.length > 0 && (
                                <Typography component="span" level="body-xs" sx={{ color: 'text.tertiary', fontWeight: 'md', mr: 0.5 }}>
                                    {path.join(' › ') + ' ›'}
                                </Typography>
                            )}
                            {row.Cells[i].Value || <span style={{ opacity: 0.4 }}>(untitled)</span>}
                        </Typography>
                    )}
                    <Tooltip size="sm" enterDelay={500} title="open the file here">
                        <IconButton
                            size="sm" variant="plain" color="neutral"
                            onClick={() => nav.toFile({
                                filename: data!.File, line: row.LineNum,
                                back: { app: 'Columns', label: 'Back to columns' },
                            })}
                            sx={{ '--IconButton-size': '18px', ml: 0.25, opacity: 0.35, '&:hover': { opacity: 1 } }}
                        >
                            <OpenInFileIcon sx={{ fontSize: 13 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </td>
        );
    };

    const valueCell = (row: ColumnRow, s: ColumnSpec, i: number) => {
        const cell = row.Cells[i];
        const open = editing?.hash === row.Hash && editing?.col === i;
        if (s.Kind === 'todo') {
            return (
                <td key={i}><StatusEditor row={row} onPick={v => commit(row, i, v)} /></td>
            );
        }
        if (open && s.Kind === 'property') {
            return (
                <td key={i}>
                    <PropertyEditor cell={cell} suggestions={suggestionsFor(s)} onDone={v => commit(row, i, v)} />
                </td>
            );
        }
        if (open && s.Kind === 'priority') {
            // The letters org uses by default first, then any the file uses.
            const used = propValues.get('PRIORITY') || [];
            const sugg = [...['A', 'B', 'C'].map(p => ({ value: p, count: (used.find(u => u.value === p) || { count: 0 }).count })),
                ...used.filter(u => !['A', 'B', 'C'].includes(u.value))];
            return (
                <td key={i}>
                    <PropertyEditor cell={cell} suggestions={sugg} onDone={v => commit(row, i, v)} />
                </td>
            );
        }
        if (s.Kind === 'tags') {
            const own = (cell.Own || '').split(':').filter(Boolean);
            if (open) {
                return (
                    <td key={i}>
                        <TagsEditor tags={own} suggestions={propValues.get('TAGS') || []} onDone={v => commitTags(row, v)} />
                    </td>
                );
            }
            return (
                <td key={i} onClick={() => setEditing({ hash: row.Hash, col: i })} style={{ cursor: 'text' }}>
                    {own.length ? (
                        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'nowrap', overflow: 'hidden' }}>
                            {own.map(t => (
                                <Chip key={t} size="sm" variant="outlined" sx={{ '--Chip-minHeight': '18px', fontSize: 11 }}>{t}</Chip>
                            ))}
                        </Box>
                    ) : <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>—</Typography>}
                </td>
            );
        }
        // A summed value is drawn differently on purpose: it is the one number in
        // the table that nobody typed, and a total that looks like an entry
        // invites somebody to correct it on the wrong heading.
        const sub = subtotals.get(i)?.get(row.Hash);
        const body = (
            <Typography
                level="body-xs"
                sx={{
                    fontFamily: s.Numbers ? 'monospace' : undefined,
                    color: cell.Summed ? 'primary.plainColor' : (cell.Value ? 'text.primary' : 'text.tertiary'),
                    fontStyle: cell.Summed ? 'italic' : undefined,
                    cursor: isEditable(s) ? 'text' : 'default',
                    whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                }}
                onClick={() => isEditable(s) && setEditing({ hash: row.Hash, col: i })}
            >
                {cell.Value || (isEditable(s) ? '—' : '')}
                {/* The subtree's total beside a parent's own value, for a
                    number column the line does not sum: a bit of rollup while
                    the outline is drawn, without turning the column into
                    org's summed column. */}
                {sub !== undefined && (
                    <Typography component="span" level="body-xs"
                        sx={{ color: 'primary.plainColor', fontStyle: 'italic', ml: 0.75, opacity: 0.8 }}
                        title={`everything under this heading adds up to ${s.Numbers === 'duration' ? hoursMinutes(sub) : sub}`}>
                        {`Σ ${s.Numbers === 'duration' ? hoursMinutes(sub) : (Math.round(sub * 100) / 100)}`}
                    </Typography>
                )}
            </Typography>
        );
        if (!cell.Summed) return <td key={i}>{body}</td>;
        return (
            <td key={i}>
                <Tooltip
                    size="sm" enterDelay={300}
                    title={cell.Own
                        ? `${cell.Value} in total — ${cell.Own} of it on this heading itself`
                        : `${cell.Value} in total, all of it from what is underneath`}
                >
                    <Box sx={{ display: 'inline-block' }}>{body}</Box>
                </Tooltip>
            </td>
        );
    };

    const specIsFileOwn = data ? specDraft === data.Columns && data.From === 'file' : false;
    // When every column has a width there is nothing to take up the rest of
    // the screen, and a fixed table would stretch them all to fill it - so no
    // column would be the width it says. An empty last column takes the slack.
    const allSized = !!data?.Spec && data.Spec.every((s, i) => (liveWidths[i] ?? fixedPx(s)) !== undefined);
    const clearWidths = () => {
        if (!data) return;
        let line = data.Columns;
        (data.Spec || []).forEach((_s, i) => { line = setColumnWidth(line, i, 0); });
        applyLine(line);
    };
    const itemCol = data?.Spec ? data.Spec.findIndex(s => s.Kind === 'item') : -1;
    const valuesOf = valuesProp ? (propValues.get(valuesProp.toUpperCase()) || []) : [];
    const valuesIsColumn = !!data?.Spec && data.Spec.some(s => s.Property === valuesProp.toUpperCase());

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', gap: 1, p: 1, minHeight: 0 }}>
            <Sheet variant="outlined" sx={{ p: 1, borderRadius: 'sm', display: 'flex', flexWrap: 'wrap', gap: 1, alignItems: 'center' }}>
                <Autocomplete
                    size="sm"
                    placeholder="pick a file"
                    options={files}
                    value={file || null}
                    onChange={(_, v) => { setFile((v as string) || ''); setFolded(new Set()); setSortOn(null); setSpec(''); setValueFilter(null); }}
                    getOptionLabel={o => baseName(o as string)}
                    sx={{ minWidth: 220 }}
                />
                <SpecInput
                    value={specDraft}
                    onChange={setSpecDraft}
                    onApply={() => setSpec(specDraft)}
                    props={propNames}
                    endDecorator={
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                            <Button size="sm" variant="plain" onClick={() => setSpec(specDraft)}>Apply</Button>
                            <Tooltip size="sm" title="write this as the file's own #+COLUMNS: line">
                                <Button size="sm" variant="plain" disabled={!file || saving} onClick={saveSpecToFile}>
                                    Save
                                </Button>
                            </Tooltip>
                        </Box>
                    }
                />
                {data && (
                    <Tooltip
                        size="sm"
                        title={{
                            file: "the file's own #+COLUMNS: line",
                            config: 'the server default — this file declares no #+COLUMNS: line',
                            request: 'the line you typed, for this view only',
                            heading: "a heading's own :COLUMNS: property",
                        }[data.From] || data.From}
                    >
                        <Chip size="sm" variant="soft" color={data.From === 'file' ? 'success' : 'neutral'}>
                            {data.From}
                        </Chip>
                    </Tooltip>
                )}
                {specIsFileOwn || !data ? null : (
                    <Tooltip size="sm" title="back to the file's own line">
                        <IconButton size="sm" variant="plain" onClick={() => { setSpec(''); setSpecDraft(data.Columns); }}>
                            <RestartAltIcon />
                        </IconButton>
                    </Tooltip>
                )}
                <Box sx={{ display: 'flex', gap: 0.5, ml: 'auto', alignItems: 'center' }}>
                    {/* Every value a property takes in this file. */}
                    <PanelButton label="Values" icon={<ListAltIcon />} width={340} disabled={!values}
                        title="List every value a property takes in this file">
                        {close => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                                <Autocomplete
                                    size="sm" autoFocus openOnFocus
                                    placeholder="a property"
                                    options={(values?.Props || []).map(p => p.Name)}
                                    value={valuesProp || null}
                                    onChange={(_, v) => setValuesProp((v as string) || '')}
                                    renderOption={(props, option) => (
                                        <AutocompleteOption {...props}>
                                            <Box sx={{ display: 'flex', width: '100%', gap: 1 }}>
                                                <Typography level="body-sm" sx={{ flex: 1 }}>{option as string}</Typography>
                                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                                    {(values?.Props || []).find(p => p.Name === option)?.Count}
                                                </Typography>
                                            </Box>
                                        </AutocompleteOption>
                                    )}
                                    slotProps={{ input: { 'aria-label': 'Property to list' } }}
                                />
                                {valuesProp && (
                                    <>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                            {`${valuesOf.length} value${valuesOf.length === 1 ? '' : 's'}`}
                                            {valuesIsColumn ? ' - click one to show only those headings' : ''}
                                        </Typography>
                                        <Box data-testid="values-list" sx={{ maxHeight: 300, overflowY: 'auto', border: '1px solid',
                                            borderColor: 'neutral.outlinedBorder', borderRadius: 'sm' }}>
                                            {valuesOf.map(v => (
                                                <Box key={v.value}
                                                    onClick={() => {
                                                        if (!valuesIsColumn) return;
                                                        setValueFilter({ prop: valuesProp.toUpperCase(), value: v.value });
                                                        close();
                                                    }}
                                                    sx={{ display: 'flex', gap: 1, px: 1, py: 0.4,
                                                        cursor: valuesIsColumn ? 'pointer' : 'default',
                                                        '&:hover': valuesIsColumn ? { bgcolor: 'neutral.softHoverBg' } : {} }}>
                                                    <Typography level="body-sm" sx={{ flex: 1, wordBreak: 'break-word' }}>{v.value}</Typography>
                                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{v.count}</Typography>
                                                </Box>
                                            ))}
                                        </Box>
                                        {!valuesIsColumn && data && (
                                            <Button size="sm" variant="outlined" onClick={() => {
                                                applyLine(`${data.Columns} %${valuesProp.toUpperCase()}`);
                                                close();
                                            }}>
                                                {`Add ${valuesProp.toUpperCase()} as a column`}
                                            </Button>
                                        )}
                                    </>
                                )}
                            </Box>
                        )}
                    </PanelButton>
                    {/* The outline: indented and foldable (or flat), how much of
                        each heading's ancestry to show, and folding to a level.
                        Each choice is written into the line as a +word. */}
                    <PanelButton label="Outline" icon={<AccountTreeIcon />} width={280} disabled={!data}
                        title="Indentation, folding and ancestors in the item column"
                        badge={opts.flat || opts.path > 0}>
                        {close => (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                                <Checkbox size="sm" label="Indent and fold the outline" checked={tree}
                                    onChange={e => data && applyLine(setColumnOption(data.Columns, 'flat', !e.target.checked))} />
                                <Box>
                                    <Typography level="body-xs" sx={{ mb: 0.5 }}>Show ancestors before each heading</Typography>
                                    <Box sx={{ display: 'flex', gap: 0.5 }}>
                                        {[0, 1, 2, 3].map(n => (
                                            <Button key={n} size="sm" variant={opts.path === n ? 'solid' : 'outlined'}
                                                onClick={() => data && applyLine(setColumnOption(data.Columns, 'path', n === 0 ? null : n))}>
                                                {n === 0 ? 'None' : String(n)}
                                            </Button>
                                        ))}
                                    </Box>
                                </Box>
                                {tree && (
                                    <Box>
                                        <Typography level="body-xs" sx={{ mb: 0.5 }}>Fold to level</Typography>
                                        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                                            {Array.from({ length: Math.min(maxLevel, 6) }, (_, k) => k + 1).map(n => (
                                                <Button key={n} size="sm" variant="outlined" onClick={() => { foldToLevel(n); close(); }}>
                                                    {String(n)}
                                                </Button>
                                            ))}
                                            <Button size="sm" variant="plain" onClick={() => { unfoldAll(); close(); }}>All open</Button>
                                        </Box>
                                    </Box>
                                )}
                                <Button size="sm" variant="outlined" onClick={() => { clearWidths(); close(); }}>
                                    Clear column widths
                                </Button>
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                    Columns without a width share the screen. Options are kept in the columns line as
                                    +path and +flat - words Emacs skips, so Save leaves the file working there.
                                </Typography>
                            </Box>
                        )}
                    </PanelButton>
                    {tree && <Tooltip size="sm" title="fold every branch"><IconButton size="sm" variant="plain" onClick={foldAll}><UnfoldLessIcon /></IconButton></Tooltip>}
                    {tree && <Tooltip size="sm" title="open every branch"><IconButton size="sm" variant="plain" onClick={unfoldAll}><UnfoldMoreIcon /></IconButton></Tooltip>}
                    <Tooltip size="sm" title="A new heading after the selected row (n)">
                        <Button size="sm" variant="outlined" startDecorator={<AddIcon />} disabled={!data} onClick={openNew}>
                            New entry
                        </Button>
                    </Tooltip>
                    <Tooltip size="sm" title="read it again"><IconButton size="sm" variant="plain" onClick={() => load(file, spec)}><RefreshIcon /></IconButton></Tooltip>
                    {(busy || saving) && <CircularProgress size="sm" />}
                </Box>
            </Sheet>

            {valueFilter && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Chip size="sm" variant="soft" color="primary"
                        endDecorator={<IconButton size="sm" variant="plain" aria-label="Clear the value filter"
                            onClick={() => setValueFilter(null)} sx={{ '--IconButton-size': '18px' }}><CloseIcon sx={{ fontSize: 14 }} /></IconButton>}>
                        {`${valueFilter.prop} = ${valueFilter.value}`}
                    </Chip>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        showing the headings with this value, and the headings they sit under
                    </Typography>
                </Box>
            )}

            {error !== '' && <Alert size="sm" color="danger" variant="soft">{error}</Alert>}

            {!file && (
                <Alert size="sm" variant="soft" color="neutral">
                    {/* One block: an Alert is a flex row, and loose text either
                        side of the code became three columns on a phone. */}
                    <div>
                        Pick a file. Its headings are drawn as org's column view, and any column
                        whose spec carries a summary operator — <code>{'%EFFORT{:}'}</code> — shows
                        the total of everything underneath on each parent.
                    </div>
                </Alert>
            )}

            {data && data.Spec && (
                <Sheet variant="outlined" sx={{ flex: 1, minHeight: 0, overflow: 'auto', borderRadius: 'sm' }}>
                    <Table
                        size="sm" stickyHeader hoverRow
                        sx={{
                            // Exactly the columns' widths, not stretched to the
                            // page: a stretched table hands its spare width out to
                            // every column, so no column is the width it says and
                            // a resize drags by more than the pointer moved.
                            tableLayout: 'fixed',
                            width: '100%',
                            // Never narrower than the sized columns plus room
                            // for the rest; past that it scrolls sideways.
                            minWidth: data.Spec.reduce((sum, s, i) =>
                                sum + (liveWidths[i] ?? fixedPx(s) ?? (s.Kind === 'item' ? ITEM_MIN : VALUE_MIN)), 0),
                            '--TableCell-paddingY': '3px',
                            '& thead th': { verticalAlign: 'bottom' },
                            '& td': { verticalAlign: 'middle', overflow: 'hidden' },
                        }}
                    >
                        <colgroup>
                            {data.Spec.map((s, i) => {
                                const px = liveWidths[i] ?? fixedPx(s);
                                // Sized: exactly that. Unsized item: a share of the
                                // screen. Unsized value: an equal part of the rest.
                                return <col key={i} style={{ width: px !== undefined ? px : (s.Kind === 'item' ? ITEM_SHARE : undefined) }} />;
                            })}
                            {allSized && <col />}
                        </colgroup>
                        <thead><tr>{data.Spec.map(headerCell)}{allSized && <th aria-hidden />}</tr></thead>
                        <tbody>
                            {visible.map(row => (
                                <React.Fragment key={row.Hash}>
                                    <tr
                                        onClick={() => setSelRow(row.Hash)}
                                        style={row.Hash === selRow ? { background: 'var(--joy-palette-primary-softBg)' } : undefined}
                                    >
                                        {data.Spec!.map((s, i) =>
                                            i === itemCol
                                                ? itemCell(row, s, i)
                                                : valueCell(row, s, i))}
                                        {allSized && <td aria-hidden />}
                                    </tr>
                                    {newAfter !== null && newLineAfter === row.Hash &&
                                        newLine(data.Spec!.length + (allSized ? 1 : 0), rows.find(r => r.Hash === newAfter)?.Headline || '')}
                                </React.Fragment>
                            ))}
                            {newAfter !== null && newLineAfter === '' &&
                                newLine(data.Spec.length + (allSized ? 1 : 0), '')}
                            {visible.length === 0 && (
                                <tr><td colSpan={data.Spec.length + (allSized ? 1 : 0)}>
                                    <Typography level="body-sm" sx={{ color: 'text.tertiary', p: 1 }}>
                                        {valueFilter ? 'No heading has that value.' : 'This file has no headings.'}
                                    </Typography>
                                </td></tr>
                            )}
                        </tbody>
                    </Table>
                </Sheet>
            )}
            {preview && (
                <HeadingPreview
                    anchor={preview.anchor}
                    text={fileText && fileText.file === file ? fileText.text : null}
                    row={preview.row}
                    onEnter={() => { if (leaveTimer.current) { window.clearTimeout(leaveTimer.current); leaveTimer.current = null; } }}
                    onLeave={leaveTitle}
                />
            )}
        </Box>
    );
}
