// Org's column view, on the client.
//
// The server does all the reading and all the arithmetic - which properties a
// `#+COLUMNS:` line names, what each heading holds, and what a parent's total
// comes to. What is left here is what a *table* needs and a server cannot know:
// which rows are folded away, which column is being sorted on, and whether a
// cell may be typed into.
//
// The one rule worth stating: **a cell's own value is not what the cell shows.**
// On a leaf they are the same. On a parent that rolls up they are not, and an
// editor opened on the shown value would write a project's total effort onto the
// project heading the first time anybody pressed return in it.

export type ColumnSpec = {
    Property: string;
    Title: string;
    Width: number;
    Summary: string;
    // "property" | "todo" | "item" | "tags" | "priority" | "derived"
    Kind: string;
    // "duration" | "number" | ""
    Numbers: string;
    Allowed: string[] | null;
};

export type ColumnCell = {
    Value: string;
    Own: string;
    Summed: boolean;
    Number: number;
};

export type ColumnRow = {
    Hash: string;
    Headline: string;
    Level: number;
    LineNum: number;
    Status: string;
    Priority: string;
    Tags: string[] | null;
    HasChildren: boolean;
    Cells: ColumnCell[];
};

export type ColumnsResult = {
    Ok: boolean;
    Msg: string;
    File: string;
    Columns: string;
    From: string;
    Spec: ColumnSpec[] | null;
    Rows: ColumnRow[] | null;
};

// GET /columns/values: every property the file uses, with its values.
export type ColumnValuesResult = {
    Ok: boolean;
    Msg: string;
    File: string;
    Props: { Name: string; Count: number; Values: { Value: string; Count: number }[] | null }[] | null;
};

// Can this column be typed into, and through which endpoint?
//
// Kept here rather than as a list of property names, because the server already
// decided and a second opinion in the browser is a second thing to keep in step.
export function isEditable(spec: ColumnSpec): boolean {
    return spec.Kind === 'property' || spec.Kind === 'todo' || spec.Kind === 'item'
        || spec.Kind === 'tags' || spec.Kind === 'priority';
}

// What to put in the editor when a cell is opened.
//
// The heading's *own* value, never the rollup. A project showing 31:45 summed
// from its tasks has no effort of its own, and offering 31:45 as the current
// value is offering to write it.
export function editValue(cell: ColumnCell): string {
    return cell.Own || '';
}

// Which rows are hidden because an ancestor is folded.
//
// Folding is by hash and the outline is a flat list with levels, so a row is
// hidden when any row above it that is folded has a smaller level and nothing in
// between has climbed back out. Walking a stack of levels is what makes that one
// pass rather than a lookup per ancestor.
export function hiddenRows(rows: ColumnRow[], folded: Set<string>): Set<string> {
    const hidden = new Set<string>();
    // The levels of the folded ancestors currently in force.
    const shut: number[] = [];
    for (const r of rows) {
        while (shut.length > 0 && r.Level <= shut[shut.length - 1]) shut.pop();
        if (shut.length > 0) {
            hidden.add(r.Hash);
            // A row that is already hidden cannot also be a fold point anybody
            // can see, but its children are hidden by the ancestor either way -
            // so it is not pushed, and the ancestor keeps hiding them.
            continue;
        }
        if (r.HasChildren && folded.has(r.Hash)) shut.push(r.Level);
    }
    return hidden;
}

// Every hash in the list that has something under it, for "fold all".
export function foldableRows(rows: ColumnRow[]): string[] {
    return rows.filter(r => r.HasChildren).map(r => r.Hash);
}

// The rows of one heading's subtree, itself included - what a fold hides and
// what "sum of this branch" is about.
export function subtreeOf(rows: ColumnRow[], hash: string): ColumnRow[] {
    const at = rows.findIndex(r => r.Hash === hash);
    if (at < 0) return [];
    const out = [rows[at]];
    for (let i = at + 1; i < rows.length && rows[i].Level > rows[at].Level; i++) out.push(rows[i]);
    return out;
}

// Sorting a column, without breaking the outline.
//
// A column view is an outline, and sorting it as a flat list would move children
// away from their parents and turn the indentation into a lie. So siblings are
// sorted **within their parent** and the tree is walked back out in order - which
// is what org does when it sorts a subtree, and the only sort that leaves the
// indentation meaning what it says.
export function sortWithinParents(
    rows: ColumnRow[], column: number, dir: 'asc' | 'desc', numeric: boolean,
): ColumnRow[] {
    if (rows.length === 0) return rows;

    type Node = { row: ColumnRow; kids: Node[] };
    const roots: Node[] = [];
    const stack: Node[] = [];
    for (const row of rows) {
        const node: Node = { row, kids: [] };
        while (stack.length > 0 && stack[stack.length - 1].row.Level >= row.Level) stack.pop();
        if (stack.length === 0) roots.push(node);
        else stack[stack.length - 1].kids.push(node);
        stack.push(node);
    }

    const sign = dir === 'asc' ? 1 : -1;
    const cmp = (a: Node, b: Node): number => {
        const ca = a.row.Cells[column];
        const cb = b.row.Cells[column];
        if (!ca || !cb) return 0;
        // An empty cell sorts last whichever way round the column is, because
        // "nothing here" is not a small value - it is an absence, and burying
        // the filled-in rows under a block of blanks is never what was wanted.
        const ea = numeric ? ca.Value === '' : ca.Value.trim() === '';
        const eb = numeric ? cb.Value === '' : cb.Value.trim() === '';
        if (ea !== eb) return ea ? 1 : -1;
        if (ea && eb) return 0;
        if (numeric) return sign * (ca.Number - cb.Number);
        return sign * ca.Value.localeCompare(cb.Value, undefined, { sensitivity: 'base' });
    };

    const out: ColumnRow[] = [];
    const walk = (ns: Node[]) => {
        const sorted = [...ns].sort(cmp);
        for (const n of sorted) {
            out.push(n.row);
            walk(n.kids);
        }
    };
    walk(roots);
    return out;
}

// How wide to draw a column, from the `%25` the spec may carry.
//
// A width is a request rather than a rule: org writes one to stop a long item
// pushing everything else off the screen, and a table that can scroll has less
// need of it than a fixed-width buffer does. So it becomes a maximum, and a
// column with no width gets whatever it needs.
export function columnWidth(spec: ColumnSpec): number | undefined {
    if (!spec.Width || spec.Width <= 0) return undefined;
    // Roughly a character, for a table drawn in the interface font rather than
    // in a terminal. Exactness is not the point: not being pushed off the
    // screen is.
    return spec.Width * 8;
}

// ---------------------------------------------------------------------------
// The columns line: worg's own options, moving and resizing columns
// ---------------------------------------------------------------------------
//
// Emacs reads a `#+COLUMNS:` line by scanning for `%...` groups and skipping
// everything else (org-columns-compile-format), so words without a `%` are
// free for worg to use and harmless to save into the file: `+path` and `+flat`
// below. A `{...}` on ITEM is *not* free - Emacs reads it as a summary
// operator and stops with "Unknown operator".

// One `%...` group: `%25EFFORT(Estimate){:}`.
const COLUMN_RE = /%(\d+)?([A-Za-z_][A-Za-z0-9_-]*)(?:\(([^)]*)\))?(?:\{([^}]*)\})?/g;

export type ColumnToken = { text: string; start: number; end: number; width: number; prop: string };

export function columnTokens(line: string): ColumnToken[] {
    const out: ColumnToken[] = [];
    COLUMN_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = COLUMN_RE.exec(line)) !== null) {
        out.push({ text: m[0], start: m.index, end: m.index + m[0].length, width: m[1] ? Number(m[1]) : 0, prop: m[2].toUpperCase() });
    }
    return out;
}

export type ColumnOptions = {
    // No indentation or folding: a plain table, as when sorting across levels.
    flat: boolean;
    // How many ancestors to show before each heading's title; 0 for none.
    path: number;
};

const OPTION_RE = /(^|\s)\+(flat|path)(?:=(\d+))?(?=\s|$)/g;

export function columnOptions(line: string): ColumnOptions {
    const o: ColumnOptions = { flat: false, path: 0 };
    OPTION_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = OPTION_RE.exec(line || '')) !== null) {
        if (m[2] === 'flat') o.flat = true;
        if (m[2] === 'path') o.path = m[3] ? Math.max(1, Number(m[3])) : 2;
    }
    return o;
}

// The line with an option set (or taken off, with `null`). Columns are left
// exactly as they were.
export function setColumnOption(line: string, name: 'flat' | 'path', value: number | boolean | null): string {
    const without = (line || '').replace(new RegExp(`(^|\\s)\\+${name}(?:=\\d+)?(?=\\s|$)`, 'g'), '$1').replace(/\s+/g, ' ').trim();
    if (value === null || value === false) return without;
    const tok = value === true || (name === 'path' && value === 2) ? `+${name}` : `+${name}=${value}`;
    return `${without} ${tok}`.trim();
}

// The line with column `from` moved to position `to` (positions among the
// columns, as the table shows them). Columns are rejoined with single spaces;
// anything that was not a column - worg's options, stray words - follows them
// in its original order.
export function moveColumn(line: string, from: number, to: number): string {
    const toks = columnTokens(line);
    if (from < 0 || from >= toks.length || to < 0 || to >= toks.length || from === to) return line;
    const order = toks.map(t => t.text);
    const [moved] = order.splice(from, 1);
    order.splice(to, 0, moved);
    let rest = line;
    for (let i = toks.length - 1; i >= 0; i--) rest = rest.slice(0, toks[i].start) + ' ' + rest.slice(toks[i].end);
    const extra = rest.split(/\s+/).filter(Boolean);
    return [...order, ...extra].join(' ');
}

// The line with column `index` given a width (in characters, as org counts
// them); 0 takes the width off.
export function setColumnWidth(line: string, index: number, width: number): string {
    const t = columnTokens(line)[index];
    if (!t) return line;
    const bare = t.text.replace(/^%\d*/, '%');
    const next = width > 0 ? `%${Math.round(width)}${bare.slice(1)}` : bare;
    return line.slice(0, t.start) + next + line.slice(t.end);
}

// ---------------------------------------------------------------------------
// The outline, for the ITEM column
// ---------------------------------------------------------------------------

// Each heading's ancestors' titles, outermost first, from the rows in file
// order. Worked out from the levels, before any sorting reorders the rows.
export function ancestorsOf(rows: ColumnRow[]): Map<string, string[]> {
    const out = new Map<string, string[]>();
    const stack: ColumnRow[] = [];
    for (const r of rows) {
        while (stack.length > 0 && stack[stack.length - 1].Level >= r.Level) stack.pop();
        out.set(r.Hash, stack.map(s => s.Headline));
        stack.push(r);
    }
    return out;
}

// The rows a value filter keeps: those whose cell in `col` is `value`, and
// their ancestors, so each match keeps its place in the outline.
export function rowsWithValue(rows: ColumnRow[], col: number, value: string): Set<string> {
    const keep = new Set<string>();
    const stack: ColumnRow[] = [];
    for (const r of rows) {
        while (stack.length > 0 && stack[stack.length - 1].Level >= r.Level) stack.pop();
        const c = r.Cells[col];
        if (c && (c.Own || '').trim() === value) {
            keep.add(r.Hash);
            for (const a of stack) keep.add(a.Hash);
        }
        stack.push(r);
    }
    return keep;
}

// Minutes as org's H:MM, counting past 24 - the server's hoursMinutes.
export function hoursMinutes(mins: number): string {
    if (mins <= 0) return '';
    const whole = Math.round(mins);
    return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`;
}

// What a subtree adds up to in a column the file did not ask to sum (EFFORT
// with no `{:}`), for showing a small total beside a parent's own value when
// the outline is drawn. The parent's own value counts, as the server's rollup
// counts it. Only parents with something summed under them are in the map.
export function subtreeTotals(rows: ColumnRow[], col: number): Map<string, number> {
    const totals = new Map<string, number>();
    const own = (r: ColumnRow) => {
        const c = r.Cells[col];
        return c && (c.Own || '').trim() !== '' ? c.Number : null;
    };
    // Walk backwards so every child is done before its parent: a row's total
    // is its own value plus its direct children's totals.
    const sums: { level: number; total: number; any: boolean }[] = [];
    for (let i = rows.length - 1; i >= 0; i--) {
        const r = rows[i];
        let total = 0;
        let any = false;
        // Children are the pending entries one level deeper than this row.
        while (sums.length > 0 && sums[sums.length - 1].level > r.Level) {
            const s = sums.pop() as { level: number; total: number; any: boolean };
            total += s.total;
            any = any || s.any;
        }
        const childAny = any;
        const o = own(r);
        if (o !== null) { total += o; any = true; }
        if (r.HasChildren && childAny) totals.set(r.Hash, total);
        sums.push({ level: r.Level, total, any });
    }
    return totals;
}

// ---------------------------------------------------------------------------
// Suggestions while the columns line is typed
// ---------------------------------------------------------------------------

export const SPECIAL_COLUMNS: { value: string; hint: string }[] = [
    { value: 'ITEM', hint: 'the heading' },
    { value: 'TODO', hint: 'its keyword' },
    { value: 'PRIORITY', hint: 'its priority' },
    { value: 'TAGS', hint: 'its own tags' },
    { value: 'ALLTAGS', hint: 'its tags and inherited ones' },
    { value: 'CLOCKSUM', hint: 'time clocked, summed up the tree' },
    { value: 'CLOCKSUM_T', hint: "today's clocked time" },
    { value: 'DEADLINE', hint: 'its deadline' },
    { value: 'SCHEDULED', hint: 'when it is scheduled' },
    { value: 'CLOSED', hint: 'when it was closed' },
    { value: 'CATEGORY', hint: 'its category' },
    { value: 'FILE', hint: 'its file' },
];

// The summary operators the server rolls up (summaryOp in columns.go).
export const SUMMARY_OPERATORS: { value: string; hint: string }[] = [
    { value: ':', hint: 'sum of times (H:MM)' },
    { value: '+', hint: 'sum of numbers' },
    { value: '$', hint: 'sum, as money' },
    { value: 'min', hint: 'smallest number' },
    { value: 'max', hint: 'largest number' },
    { value: 'mean', hint: 'average number' },
    { value: ':min', hint: 'shortest time' },
    { value: ':max', hint: 'longest time' },
    { value: ':mean', hint: 'average time' },
];

export const COLUMN_OPTIONS: { value: string; hint: string }[] = [
    { value: '+path', hint: 'show two ancestors before each heading' },
    { value: '+path=1', hint: 'show the parent before each heading' },
    { value: '+path=3', hint: 'show three ancestors before each heading' },
    { value: '+flat', hint: 'no indentation or folding' },
];

export type SpecCompletion = {
    // The stretch of the line a pick replaces.
    from: number;
    to: number;
    items: { value: string; hint: string }[];
};

// What to offer at the caret: property names after `%` (the special ones and
// those the file uses, most used first), summary operators inside `{`, worg's
// options after `+`. Null where nothing fits (a title in brackets, a space).
export function specCompletion(
    text: string, caret: number, props: { name: string; count: number }[],
): SpecCompletion | null {
    let start = caret;
    while (start > 0 && !/\s/.test(text[start - 1])) start--;
    const word = text.slice(start, caret);
    if (word.startsWith('+')) {
        const part = word.toLowerCase();
        const items = COLUMN_OPTIONS.filter(o => o.value.startsWith(part) && o.value !== word);
        return items.length ? { from: start, to: caret, items } : null;
    }
    const m = word.match(/^%(\d*)([A-Za-z0-9_-]*)(\([^)]*\)?)?(\{([^}]*))?$/);
    if (!m) return null;
    if (m[4] !== undefined) {
        // Inside the braces: operators.
        const part = m[5] || '';
        const items = SUMMARY_OPERATORS.filter(o => o.value.startsWith(part) && o.value !== part);
        return items.length ? { from: caret - part.length, to: caret, items } : null;
    }
    if (m[3] !== undefined) return null;
    const part = (m[2] || '').toUpperCase();
    const from = start + 1 + m[1].length;
    const used = props
        .filter(p => SPECIAL_COLUMNS.every(s => s.value !== p.name))
        .map(p => ({ value: p.name, hint: `on ${p.count} heading${p.count === 1 ? '' : 's'}` }));
    const items = [...SPECIAL_COLUMNS, ...used].filter(o => o.value.startsWith(part) && o.value !== part);
    return items.length ? { from, to: caret, items: items.slice(0, 30) } : null;
}
