// The starmap is its own dark world whichever way the app's colour scheme is set,
// because it is a picture of the night sky. These are the only classes the engine
// writes to - the tooltip and the caption, which it owns because they move with
// the pointer and the frame.
const CSS = {
    '.sm-tip': {
        position: 'absolute', zIndex: 3, pointerEvents: 'none', maxWidth: '320px',
        background: 'rgba(8,12,24,.93)', border: '1px solid rgba(46,230,200,.28)',
        padding: '7px 11px', fontSize: '11px', color: '#DCE6F7', borderRadius: '3px',
        display: 'none', lineHeight: 1.5,
        fontFamily: 'Menlo, Consolas, monospace',
    },
    '.sm-tip .sm-kind': {
        fontSize: '9px', letterSpacing: '.16em', textTransform: 'uppercase',
        color: '#2EE6C8', display: 'block', marginBottom: '2px',
    },
    '.sm-tip .sm-name': { display: 'block', color: '#F2F6FF' },
    '.sm-tip .sm-where': { display: 'block', fontSize: '9px', color: '#6B7A9C', marginTop: '3px' },
    '.sm-caption': {
        position: 'absolute', left: '50%', transform: 'translateX(-50%)', bottom: '86px',
        zIndex: 3, pointerEvents: 'none', maxWidth: '88%', textAlign: 'center',
        fontFamily: 'Georgia, serif', fontStyle: 'italic',
        fontSize: 'clamp(14px,2vw,20px)', color: '#EAF1FC', opacity: 0,
        transition: 'opacity .8s', textShadow: '0 2px 12px rgba(0,0,0,.8)', lineHeight: 1.35,
    },
    '.sm-caption .sm-sub': {
        display: 'block', fontFamily: 'Menlo, Consolas, monospace', fontSize: '9px',
        letterSpacing: '.16em', textTransform: 'uppercase', color: '#8FA0C0',
        marginTop: '5px', fontStyle: 'normal',
    },
    '.sm-caption.sm-show': { opacity: 1 },
} as const;

// A range input styled for the dark panel. Joy's Slider is a much heavier control
// and there are twenty-five of these; a native range is the right tool and the
// one the original used.
function Knob({
    value, min, max, step, onInput,
}: {
    value: number; min: number; max: number; step: number; onInput: (v: number) => void;
}) {
    return (
        <input
            type="range"
            min={min}
            max={max}
            step={step}
            defaultValue={value}
            onInput={e => onInput(parseFloat((e.target as HTMLInputElement).value))}
            style={{ width: '100%', accentColor: '#2EE6C8', cursor: 'pointer', height: 3 }}
        />
    );
}

// One slider row. Its own state, so dragging it re-renders this row and nothing
// else - the value it writes goes straight into the engine's settings object.
function SliderRow({
    label, hint, value, min, max, step, format, onChange,
}: {
    label: string; hint?: string; value: number;
    min: number; max: number; step: number;
    format: (v: number) => string;
    onChange: (v: number) => void;
}) {
    const [shown, setShown] = React.useState(value);
    return (
        <Box sx={{ my: 0.9 }}>
            <Tooltip title={hint || ''} size="sm" placement="left" disableHoverListener={!hint}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: '#93A3C2', mb: 0.4 }}>
                    <span>{label}</span>
                    <span style={{ color: '#DCE6F7' }}>{format(shown)}</span>
                </Box>
            </Tooltip>
            <Knob
                value={value}
                min={min}
                max={max}
                step={step}
                onInput={v => { setShown(v); onChange(v); }}
            />
        </Box>
    );
}

// The constellation list, and the solo it drives. Clicking one narrows the sky to
// it; clicking it again lets the rest back.
function Legend({
    families, palette, solo, onSolo,
}: {
    families: Family[]; palette: Palette; solo: string | null;
    onSolo: (key: string | null) => void;
}) {
    if (families.length === 0) return null;
    return (
        <Box
            sx={{
                position: 'absolute', left: 16, bottom: 74, zIndex: 2,
                display: 'flex', flexDirection: 'column', gap: 0.6,
                fontSize: 10, letterSpacing: '.06em',
                maxHeight: '44%', overflowY: 'auto', pr: 0.8,
                fontFamily: 'Menlo, Consolas, monospace',
                scrollbarWidth: 'thin',
            }}
        >
            {families.map(f => {
                const look = lookOf(palette, f.key);
                const off = solo !== null && solo !== f.key;
                return (
                    <Box
                        key={f.key}
                        onClick={() => onSolo(solo === f.key ? null : f.key)}
                        sx={{
                            display: 'flex', alignItems: 'center', gap: 1,
                            color: '#93A3C2', cursor: 'pointer', userSelect: 'none',
                            opacity: off ? 0.28 : 1, transition: 'opacity .25s',
                            '&:hover': { color: '#EAF1FC' },
                        }}
                    >
                        <Box sx={{
                            width: 8, height: 8, borderRadius: '50%', flex: 'none',
                            background: look.css, boxShadow: `0 0 8px ${look.css}`,
                        }} />
                        <Box component="span" sx={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 170 }}>
                            {f.name.toLowerCase()}
                        </Box>
                        <Box component="span" sx={{ color: '#4C5A78', flex: 'none' }}>{f.count}</Box>
                    </Box>
                );
            })}
        </Box>
    );
}

// The todo keywords in a galaxy, busiest first, in the shape the legend and the
// palette both want. `(none)` is a row rather than a gap: "the headings with no
// keyword" is most of an org database and the most useful thing to solo.
function keywordsOf(g: Galaxy): Family[] {
    const counts = new Map<string, number>();
    for (const n of g.nodes) {
        const k = n.status || '(none)';
        counts.set(k, (counts.get(k) || 0) + 1);
    }
    const out: Family[] = [];
    counts.forEach((count, key) => out.push({ key, name: key, count }));
    out.sort((a, b) => (b.count - a.count) || (a.key < b.key ? -1 : 1));
    return out;
}

export default function Starmap() {
    const nav = useNav();
    const chrome = useChromeToggle();
    const [prefs, setPrefs] = useSetting('starmap');

    const wrapRef = React.useRef<HTMLDivElement | null>(null);
    const canvasRef = React.useRef<HTMLCanvasElement | null>(null);
    const tipRef = React.useRef<HTMLDivElement | null>(null);
    const capRef = React.useRef<HTMLDivElement | null>(null);
    const engineRef = React.useRef<StarmapEngine | null>(null);
    const soundRef = React.useRef<SoundEngine | null>(null);
    // The live tunables. A copy, because the engine mutates what it is handed and
    // the settings store's own object must not be written behind its back.
    const lookRef = React.useRef<StarmapSettings>({ ...prefs.look });
    // The palette and the colour rule, in refs as well as in state: the engine
    // reads them every frame through a closure, and a closure over state would be
    // reading whatever it was created with.
    const palRef = React.useRef<Palette>({});
    const keyPalRef = React.useRef<Palette>({});
    const colorByRef = React.useRef(prefs.colorBy);
    // The last answer from the server, kept so that changing what a constellation
    // is made of does not ask again: the server sent both the folder and the file
    // of every star precisely so that this is arithmetic rather than a request.
    const lastRes = React.useRef<StarmapResult | null>(null);
    // Colour by expression: the rules, what the server said each one finds, and
    // the look each draws in - refs for the engine's per-frame colour function,
    // state for the panel.
    const rules: StarColorRule[] = React.useMemo(() => prefs.colorRules || [], [prefs.colorRules]);
    const rulesRef = React.useRef<StarColorRule[]>(rules);
    const hitsRef = React.useRef<(RuleHits | null)[]>([]);
    const ruleLooksRef = React.useRef<FamilyLook[]>([]);
    const [ruleInfo, setRuleInfo] = React.useState<{ count: number; err: string }[]>([]);
    const [rulesOpen, setRulesOpen] = React.useState(false);

    // What is being drawn.
    const [galaxy, setGalaxy] = React.useState<Galaxy | null>(null);
    // The keywords in the sky, as a legend: what colour means when it means the
    // todo keyword rather than the constellation.
    const [keyFamilies, setKeyFamilies] = React.useState<Family[]>([]);
    const [palette, setPalette] = React.useState<Palette>({});
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState('');

    // The chrome's own state.
    const [query, setQuery] = React.useState('');
    const [matches, setMatches] = React.useState<number[]>([]);
    const [selRes, setSelRes] = React.useState(0);
    const [solo, setSolo] = React.useState<string | null>(null);
    const [panelOpen, setPanelOpen] = React.useState(false);
    const [soundOn, setSoundOn] = React.useState(false);
    const [soundBroken, setSoundBroken] = React.useState(false);
    const [timePos, setTimePos] = React.useState(0);
    const [playing, setPlaying] = React.useState(false);
    const [flying, setFlying] = React.useState(false);
    const [touring, setTouring] = React.useState(false);
    const [shot, setShot] = React.useState('');
    const [menu, setMenu] = React.useState<{ star: StarNode; x: number; y: number } | null>(null);
    // The settings a reload depends on, held apart from `prefs` so typing a query
    // does not refetch on every keystroke.
    const [draftQuery, setDraftQuery] = React.useState(prefs.query);
    const [draftExclude, setDraftExclude] = React.useState(prefs.exclude);
    const [reloadTick, setReloadTick] = React.useState(0);

    // Persisting. Debounced, because a slider drag is a hundred changes.
    const saveTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
    const prefsRef = React.useRef(prefs);
    prefsRef.current = prefs;
    const save = React.useCallback((patch: Partial<StarmapPrefs>) => {
        if (saveTimer.current) clearTimeout(saveTimer.current);
        saveTimer.current = setTimeout(() => {
            setPrefs({ ...prefsRef.current, ...patch, look: { ...lookRef.current } });
        }, 500);
    }, [setPrefs]);

    // What colour a star is. Handed to the engine as a function so the engine
    // never has to know what a todo keyword is: constellation or keyword are both
    // reasonable answers and which one is on is a setting.
    const colourOf = React.useCallback((n: StarNode): FamilyLook => {
        // An expression rule beats both: it is somebody pointing at these stars.
        const ri = ruleFor(n, rulesRef.current, hitsRef.current, prefsRef.current.scope === 'file');
        if (ri >= 0) return ruleLooksRef.current[ri];
        if (colorByRef.current === 'keyword') {
            return lookOf(keyPalRef.current, n.status || '(none)');
        }
        return lookOf(palRef.current, n.fam);
    }, []);

    // ---------------------------------------------------------------------
    // The engine
    // ---------------------------------------------------------------------

    React.useEffect(() => {
        const canvas = canvasRef.current;
        const wrap = wrapRef.current;
        if (!canvas || !wrap) return;

        const sound = createSoundEngine(() => {
            const e = engineRef.current;
            return e === null || e.isDead();
        });
        soundRef.current = sound;

        const host: StarmapHost = {
            onOpen: (star) => {
                nav.toFile({
                    filename: star.filename,
                    heading: star.kind === 'heading' ? star.label : '',
                    line: star.kind === 'heading' ? star.line : undefined,
                    back: { app: 'Starmap', label: 'Back to the starmap' },
                });
            },
            onMenu: (star, x, y) => setMenu({ star, x, y }),
            onTime: (pos, play) => { setTimePos(pos); setPlaying(play); },
            onFlight: (f) => setFlying(f),
            onConstellation: (look) => sound.blip(look.snd),
            onShot: (url) => setShot(url),
        };

        const engine = new StarmapEngine(
            canvas, wrap, tipRef.current, capRef.current,
            lookRef.current, colourOf, host,
        );
        engineRef.current = engine;
        engine.start();

        return () => {
            engine.destroy();
            engineRef.current = null;
            sound.close();
            soundRef.current = null;
        };
        // Mounted once, deliberately. Everything that changes afterwards is
        // pushed in through a method: a remounted engine would lose the layout,
        // and the layout is the thing that cost a second to compute.
    }, []);

    // ---------------------------------------------------------------------
    // The data
    // ---------------------------------------------------------------------

    // Turn an answer into a galaxy and hand it to the engine. Shared by the fetch
    // and by the regrouping, which is the same work over the same answer.
    const apply = React.useCallback((res: StarmapResult, by: GroupBy) => {
        const engine = engineRef.current;
        const g = buildGalaxy(res, by, engine ? engine.memory() : undefined);
        const pal = buildPalette(g.families, lookRef.current.hue);
        // The keyword palette is the same distinct-hue machinery over the keywords
        // instead of the constellations, so the two legends agree about what a
        // swatch means.
        const keywords = keywordsOf(g);
        const keyPal = buildPalette(keywords, lookRef.current.hue);
        palRef.current = pal;
        keyPalRef.current = keyPal;
        setGalaxy(g);
        setPalette(pal);
        setKeyFamilies(keywords);
        if (engine) {
            engine.setPalette(pal);
            engine.setData(g, pal);
            setTimePos(Math.max(0, g.dates.length - 1));
            setPlaying(false);
            setSolo(null);
            engine.setSolo(null);
        }
    }, []);

    React.useEffect(() => {
        const ctrl = new AbortController();
        let cancelled = false;
        setLoading(true);
        (async () => {
            const res: StarmapResult = await ODb.getStarmap({
                scope: prefs.scope,
                query: prefs.query,
                exclude: prefs.exclude,
                noLogs: prefs.noLogs,
                limit: prefs.limit,
            }, ctrl.signal);
            if (cancelled) return;
            setLoading(false);
            if (!res || res.Ok === false) {
                setError((res && res.Msg) || 'the starmap could not be read');
                return;
            }
            setError('');
            lastRes.current = res;
            apply(res, prefsRef.current.groupBy as GroupBy);
        })();
        return () => { cancelled = true; ctrl.abort(); };
        // groupBy is deliberately not a dependency here - see the effect below.
    }, [prefs.scope, prefs.query, prefs.exclude, prefs.noLogs, prefs.limit, reloadTick, apply]);

    // Regrouping is not a refetch. The stars keep their positions through it,
    // which is what makes flipping between folders and files a thing you can do
    // twice in a row to compare them.
    const firstGroup = React.useRef(true);
    React.useEffect(() => {
        if (firstGroup.current) { firstGroup.current = false; return; }
        if (lastRes.current) apply(lastRes.current, prefs.groupBy as GroupBy);
    }, [prefs.groupBy, apply]);

    React.useEffect(() => {
        colorByRef.current = prefs.colorBy;
        const engine = engineRef.current;
        if (!engine) return;
        engine.setColourFn(colourOf);
        // A solo means something different now - "the ian folder" and "NEXT" are
        // not the same kind of key - so it goes rather than quietly matching
        // nothing.
        setSolo(null);
        engine.setSolo(null);
    }, [prefs.colorBy, colourOf]);

    // Each rule's query asked of the server - a moment after the typing stops,
    // and again after a reload, since what a query finds changes with the files.
    // The colours are applied straight away; only the matches wait.
    const ruleQueries = rules.map(r => (r.on ? r.query.trim() : '')).join('\u0000');
    React.useEffect(() => {
        rulesRef.current = rules;
        ruleLooksRef.current = rules.map((r, i) => lookOfColour(r.color, r.query, i));
        engineRef.current?.setColourFn(colourOf);
    }, [rules, colourOf]);
    React.useEffect(() => {
        const ctrl = new AbortController();
        const qs = ruleQueries === '' ? [] : ruleQueries.split('\u0000');
        const timer = setTimeout(async () => {
            const hits: (RuleHits | null)[] = [];
            const info: { count: number; err: string }[] = [];
            for (const q of qs) {
                if (!q) { hits.push(null); info.push({ count: 0, err: '' }); continue; }
                try {
                    const res: any = await ODb.query(q, false, ctrl.signal, '');
                    if (Array.isArray(res)) {
                        hits.push(hitsOf(res));
                        info.push({ count: res.length, err: '' });
                    } else {
                        hits.push(null);
                        info.push({ count: 0, err: (res && res.Msg) || 'the query could not be read' });
                    }
                } catch (e: any) {
                    if (ctrl.signal.aborted) return;
                    hits.push(null);
                    info.push({ count: 0, err: e?.message || 'the query failed' });
                }
            }
            if (ctrl.signal.aborted) return;
            hitsRef.current = hits;
            setRuleInfo(info);
            engineRef.current?.setColourFn(colourOf);
        }, 450);
        return () => { clearTimeout(timer); ctrl.abort(); };
    }, [ruleQueries, reloadTick, colourOf]);

    const setRules = (next: StarColorRule[]) => {
        setPrefs({ ...prefsRef.current, colorRules: next, look: { ...lookRef.current } });
    };
    const addRule = () => setRules([
        ...rules,
        { query: '', color: RULE_SWATCHES[rules.length % RULE_SWATCHES.length], on: true },
    ]);
    const changeRule = (i: number, patch: Partial<StarColorRule>) =>
        setRules(rules.map((r, k) => (k === i ? { ...r, ...patch } : r)));
    const removeRule = (i: number) => setRules(rules.filter((_, k) => k !== i));

    // ---------------------------------------------------------------------
    // Chrome actions
    // ---------------------------------------------------------------------

    const onSearch = (v: string) => {
        setQuery(v);
        setSelRes(0);
        const engine = engineRef.current;
        if (!engine) return;
        setMatches(v.trim() === '' ? [] : engine.search(v));
        if (v.trim() === '') engine.clearFocus();
    };

    const flyTo = (i: number) => {
        const engine = engineRef.current;
        if (!engine) return;
        engine.flyTo(i);
        const star = engine.starAt(i);
        setQuery(star ? star.label : '');
        setMatches([]);
    };

    const onSearchKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            setSelRes(s => Math.min(s + 1, matches.length - 1));
            e.preventDefault();
        } else if (e.key === 'ArrowUp') {
            setSelRes(s => Math.max(s - 1, 0));
            e.preventDefault();
        } else if (e.key === 'Enter' && matches.length) {
            flyTo(matches[selRes]);
            e.preventDefault();
        } else if (e.key === 'Escape') {
            setQuery('');
            setMatches([]);
            engineRef.current?.clearFocus();
        }
        // The engine listens for w/a/s/d on the document to take off. Typing into
        // a box must never launch the ship, and it checks the target for that -
        // but stopping here as well costs nothing and is one less thing to get
        // wrong later.
        e.stopPropagation();
    };

    const toggleSound = async () => {
        const sound = soundRef.current;
        if (!sound) return;
        const now = await sound.toggle(lookRef.current.vol);
        if (!now && !sound.ctx) { setSoundBroken(true); return; }
        setSoundOn(now);
    };

    // A tunable changed. Written into the live object, and whatever else has to be
    // told is told - the palette for the hue, the comet pool for its count, the
    // physics for anything that changes where stars should be.
    const onTunable = (key: keyof StarmapSettings, v: number) => {
        const engine = engineRef.current;
        (lookRef.current as any)[key] = v;
        if (!engine) { save({}); return; }
        const sl = SLIDERS.find(s => s.key === key);
        if (sl && sl.sec === 'forces') engine.reheat();
        if (key === 'hue') {
            const g = engine.data();
            const pal = buildPalette(g.families, v);
            const keyPal = buildPalette(keywordsOf(g), v);
            palRef.current = pal;
            keyPalRef.current = keyPal;
            engine.setPalette(pal);
            setPalette(pal);
        }
        if (key === 'comets') engine.rebuildParticles();
        if (key === 'vol') soundRef.current?.applyVol(v);
        save({});
    };

    const onShape = (name: string) => {
        engineRef.current?.setShape(name);
        lookRef.current.shape = name;
        save({});
    };

    const restoreDefaults = () => {
        lookRef.current = { ...DEF };
        const engine = engineRef.current;
        if (engine) {
            engine.S = lookRef.current;
            engine.reheat(1);
            engine.rebuildParticles();
            const g = engine.data();
            const pal = buildPalette(g.families, DEF.hue);
            palRef.current = pal;
            engine.setPalette(pal);
            setPalette(pal);
        }
        soundRef.current?.applyVol(DEF.vol);
        setPrefs({ ...prefsRef.current, look: { ...DEF } });
    };

    const applyDrafts = () => {
        setPrefs({
            ...prefsRef.current,
            query: draftQuery,
            exclude: draftExclude,
            look: { ...lookRef.current },
        });
    };

    const timeLabel = React.useMemo(() => {
        if (!galaxy || galaxy.dates.length === 0) return { date: '', visible: 0, last: true };
        const date = galaxy.dates[timePos] || '';
        let visible = 0;
        for (const n of galaxy.nodes) if (n.d !== '' && n.d <= date) visible++;
        return { date, visible, last: timePos >= galaxy.dates.length - 1 };
    }, [galaxy, timePos]);

    // How honest the timeline is. On a database where almost nothing carries a
    // written date, the replay is a replay of modification times - which is worth
    // saying out loud rather than implying a history it has not got.
    const datedShare = galaxy && galaxy.nodes.length
        ? galaxy.datedCount / galaxy.nodes.length
        : 0;

    const btn = {
        color: '#8FA0C0',
        borderColor: 'rgba(120,140,185,.3)',
        '--IconButton-size': '30px',
        '&:hover': { borderColor: 'rgba(46,230,200,.6)', color: '#2EE6C8', background: 'rgba(46,230,200,.08)' },
    } as const;
    const btnOn = {
        ...btn,
        borderColor: 'rgba(46,230,200,.6)',
        color: '#2EE6C8',
    } as const;

    return (
        <Sheet
            variant="outlined"
            sx={{
                flex: 1, minHeight: 0, borderRadius: 'sm', overflow: 'hidden',
                display: 'flex', flexDirection: 'column',
                background: '#04060C', borderColor: 'rgba(120,140,185,.22)',
            }}
        >
            <GlobalStyles styles={CSS as any} />

            {/* The toolbar. Everything here is something somebody does; everything
                that is about how the picture looks is behind the gear. */}
            <Box
                sx={{
                    display: 'flex', alignItems: 'center', gap: 1, px: 1, py: 0.75,
                    borderBottom: '1px solid rgba(120,140,185,.18)',
                    flexWrap: 'wrap', flex: 'none',
                }}
            >
                <Box sx={{ position: 'relative', width: { xs: 150, sm: 220 } }}>
                    <Input
                        size="sm"
                        value={query}
                        placeholder="find a star…"
                        startDecorator={<SearchIcon fontSize="small" />}
                        onChange={e => onSearch(e.target.value)}
                        onKeyDown={onSearchKey}
                        spellCheck={false}
                        sx={{
                            background: 'rgba(8,12,24,.85)',
                            borderColor: 'rgba(120,140,185,.3)',
                            color: '#EAF1FC',
                            '--Input-focusedHighlight': 'rgba(46,230,200,.6)',
                            fontFamily: 'Menlo, Consolas, monospace',
                            fontSize: 11,
                        }}
                    />
                    {matches.length > 0 && (
                        <Box sx={{
                            position: 'absolute', top: '100%', left: 0, right: 0, mt: 0.5, zIndex: 20,
                            background: 'rgba(8,12,24,.97)', border: '1px solid rgba(120,140,185,.25)',
                            borderRadius: '3px', maxHeight: 240, overflowY: 'auto',
                        }}>
                            {matches.map((i, k) => {
                                const star = engineRef.current?.starAt(i);
                                if (!star) return null;
                                return (
                                    <Box
                                        key={star.id}
                                        onPointerDown={e => { e.preventDefault(); flyTo(i); }}
                                        sx={{
                                            px: 1.2, py: 0.7, fontSize: 10, cursor: 'pointer',
                                            color: k === selRes ? '#F2F6FF' : '#B9C6DE',
                                            background: k === selRes ? 'rgba(46,230,200,.08)' : 'transparent',
                                            borderLeft: `2px solid ${colourOf(star).css}`,
                                            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                                            fontFamily: 'Menlo, Consolas, monospace',
                                        }}
                                    >
                                        {star.label}
                                    </Box>
                                );
                            })}
                        </Box>
                    )}
                </Box>

                {loading && <CircularProgress size="sm" sx={{ '--CircularProgress-size': '18px' }} />}

                {galaxy && !loading && (
                    <Box sx={{ display: 'flex', gap: 0.7, alignItems: 'center', flexWrap: 'wrap' }}>
                        <Chip size="sm" variant="soft" sx={{ background: 'rgba(46,230,200,.12)', color: '#2EE6C8', fontSize: 10 }}>
                            {galaxy.nodes.length} stars
                        </Chip>
                        <Tooltip
                            size="sm"
                            title={`${galaxy.links.filter(l => l.kind === 'link').length} links, ${galaxy.links.filter(l => l.kind === 'outline').length} outline edges`}
                        >
                            <Chip size="sm" variant="soft" sx={{ background: 'rgba(120,140,185,.12)', color: '#93A3C2', fontSize: 10 }}>
                                {galaxy.links.length} threads
                            </Chip>
                        </Tooltip>
                        <Tooltip
                            size="sm"
                            title={galaxy.eaten.length
                                ? `most recently: ${galaxy.eaten.slice(0, 5).join(', ')}`
                                : 'archived files and headings are never stars'}
                        >
                            <Chip size="sm" variant="soft" sx={{ background: 'rgba(240,179,78,.12)', color: '#F0B34E', fontSize: 10 }}>
                                {galaxy.swallowed} archived
                            </Chip>
                        </Tooltip>
                        {galaxy.truncated && (
                            <Tooltip size="sm" title={`${galaxy.total} matched; raise the star limit in the panel to see the rest`}>
                                <Chip size="sm" variant="soft" color="warning" sx={{ fontSize: 10 }}>
                                    capped at {galaxy.nodes.length} of {galaxy.total}
                                </Chip>
                            </Tooltip>
                        )}
                    </Box>
                )}

                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.6, alignItems: 'center' }}>
                    <Tooltip size="sm" title="recentre — or double-click the sky">
                        <IconButton size="sm" variant="outlined" sx={btn} onClick={() => engineRef.current?.home()}>
                            <HomeIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title={flying ? 'land (esc)' : 'take off — w to fly, wasd thrusts, shift boosts'}>
                        <IconButton
                            size="sm" variant="outlined" sx={flying ? btnOn : btn}
                            onClick={() => {
                                const e = engineRef.current;
                                if (!e) return;
                                if (e.flightMode()) e.exitFlight(); else e.enterFlight();
                            }}
                        >
                            <RocketLaunchIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title={touring ? 'stop the tour' : 'tour the constellations'}>
                        <IconButton
                            size="sm" variant="outlined" sx={touring ? btnOn : btn}
                            onClick={() => setTouring(engineRef.current?.toggleTour() || false)}
                        >
                            <ExploreIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="supernova — blow it apart and watch it re-form">
                        <IconButton
                            size="sm" variant="outlined" sx={btn}
                            onClick={() => { engineRef.current?.boom(); soundRef.current?.supernova(); }}
                        >
                            <AutoAwesomeIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="capture a still">
                        <IconButton size="sm" variant="outlined" sx={btn} onClick={() => engineRef.current?.shot()}>
                            <PhotoCameraIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    {!soundBroken && (
                        <Tooltip size="sm" title={soundOn ? 'silence' : 'ambient sound'}>
                            <IconButton size="sm" variant="outlined" sx={soundOn ? btnOn : btn} onClick={toggleSound}>
                                {soundOn ? <VolumeUpIcon fontSize="small" /> : <VolumeOffIcon fontSize="small" />}
                            </IconButton>
                        </Tooltip>
                    )}
                    <Tooltip size="sm" title="re-read the database">
                        <IconButton size="sm" variant="outlined" sx={btn} onClick={() => setReloadTick(t => t + 1)}>
                            <RefreshIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title={chrome.hidden ? 'show the page title' : 'hand the whole window over'}>
                        <IconButton size="sm" variant="outlined" sx={btn} onClick={() => chrome.setHidden(!chrome.hidden)}>
                            {chrome.hidden ? <CloseFullscreenIcon fontSize="small" /> : <OpenInFullIcon fontSize="small" />}
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="colour by expression — light up whatever an org query finds">
                        <IconButton
                            size="sm" variant="outlined"
                            sx={{ ...(rulesOpen ? btnOn : btn), position: 'relative' }}
                            onClick={() => { setRulesOpen(o => !o); if (rules.length === 0) addRule(); }}
                        >
                            <PaletteIcon fontSize="small" />
                            {rules.some(r => r.on && r.query.trim()) && (
                                <Box sx={{
                                    position: 'absolute', top: 2, right: 2, width: 6, height: 6, borderRadius: '50%',
                                    background: rules.find(r => r.on && r.query.trim())?.color || '#2EE6C8',
                                }} />
                            )}
                        </IconButton>
                    </Tooltip>
                    <Tooltip size="sm" title="what is drawn, and how">
                        <IconButton
                            size="sm" variant="outlined" sx={panelOpen ? btnOn : btn}
                            onClick={() => setPanelOpen(o => !o)}
                        >
                            <SettingsIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>

            {/* The sky. */}
            <Box ref={wrapRef} sx={{ position: 'relative', flex: 1, minHeight: 0, overflow: 'hidden' }}>
                <canvas
                    ref={canvasRef}
                    style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', cursor: 'grab', touchAction: 'none' }}
                />
                <div ref={tipRef} className="sm-tip" />
                <div ref={capRef} className="sm-caption" />

                {rulesOpen && (
                    <RulesPanel
                        rules={rules}
                        info={ruleInfo}
                        onAdd={addRule}
                        onChange={changeRule}
                        onRemove={removeRule}
                        onClose={() => setRulesOpen(false)}
                    />
                )}

                {error !== '' && (
                    <Alert
                        color="danger" variant="soft" size="sm"
                        sx={{ position: 'absolute', top: 12, left: 12, right: 12, zIndex: 6, maxWidth: 520 }}
                    >
                        {error}
                    </Alert>
                )}

                {!loading && galaxy && galaxy.nodes.length === 0 && error === '' && (
                    <Box sx={{
                        position: 'absolute', inset: 0, display: 'flex', alignItems: 'center',
                        justifyContent: 'center', color: '#55648A', fontSize: 12, textAlign: 'center', px: 4,
                    }}>
                        {prefs.query.trim() !== ''
                            ? 'Nothing matched that query, so there is no sky to draw.'
                            : 'Nothing to draw yet — no org files.'}
                    </Box>
                )}

                {/* The legend shows whatever colour currently means, and clicking
                    a row narrows the sky to it - so in keyword mode this is also
                    how you get a galaxy of nothing but what is NEXT. */}
                <Legend
                    families={prefs.colorBy === 'keyword' ? keyFamilies : (galaxy ? galaxy.families : [])}
                    palette={prefs.colorBy === 'keyword' ? keyPalRef.current : palette}
                    solo={solo}
                    onSolo={key => {
                        setSolo(key);
                        engineRef.current?.setSolo(key, prefs.colorBy === 'keyword' ? 'status' : 'fam');
                    }}
                />

                {/* The timeline: the database growing, star by star. */}
                {galaxy && galaxy.dates.length > 1 && (
                    <Box sx={{
                        position: 'absolute', left: '50%', transform: 'translateX(-50%)', bottom: 14, zIndex: 4,
                        display: 'flex', alignItems: 'center', gap: 1.2,
                        width: 'min(520px, 84%)', background: 'rgba(8,12,24,.75)',
                        border: '1px solid rgba(120,140,185,.22)', px: 1.5, py: 1, borderRadius: '4px',
                    }}>
                        <IconButton
                            size="sm" variant="outlined" sx={btn}
                            onClick={() => engineRef.current?.togglePlay()}
                        >
                            {playing ? <PauseIcon fontSize="small" /> : <PlayArrowIcon fontSize="small" />}
                        </IconButton>
                        <input
                            type="range"
                            min={0}
                            max={galaxy.dates.length - 1}
                            value={timePos}
                            onChange={e => engineRef.current?.setTime(parseInt(e.target.value, 10))}
                            style={{ flex: 1, accentColor: '#2EE6C8', cursor: 'pointer' }}
                        />
                        <Tooltip
                            size="sm"
                            placement="top"
                            title={datedShare < 0.5
                                ? `only ${galaxy.datedCount} of ${galaxy.nodes.length} stars carry a written date — for the rest this is when the file was last changed, not when it was written`
                                : 'when each star was written'}
                        >
                            <Box sx={{
                                fontSize: 9, color: '#8FA0C0', letterSpacing: '.1em', flex: 'none',
                                minWidth: 96, textAlign: 'right', fontFamily: 'Menlo, Consolas, monospace',
                            }}>
                                {timeLabel.date}
                                {timeLabel.last ? ' · now' : ` · ${timeLabel.visible}`}
                                {datedShare < 0.5 ? ' ~' : ''}
                            </Box>
                        </Tooltip>
                    </Box>
                )}

                {/* The panel. */}
                {panelOpen && (
                    <Box sx={{
                        position: 'absolute', top: 10, right: 10, zIndex: 5, width: 264,
                        maxHeight: 'calc(100% - 100px)', overflowY: 'auto',
                        background: 'rgba(8,12,24,.96)', border: '1px solid rgba(120,140,185,.28)',
                        borderRadius: '5px', px: 1.75, py: 1.5,
                        fontFamily: 'Menlo, Consolas, monospace',
                        scrollbarWidth: 'thin',
                    }}>
                        <Typography sx={{ fontSize: 9, letterSpacing: '.16em', textTransform: 'uppercase', color: '#2EE6C8', mb: 1 }}>
                            what is drawn
                        </Typography>

                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                            <Box>
                                <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>a star is</Box>
                                <Select
                                    size="sm"
                                    value={prefs.scope}
                                    onChange={(_, v) => v && setPrefs({ ...prefs, scope: v as any, look: { ...lookRef.current } })}
                                >
                                    <Option value="heading">a heading</Option>
                                    <Option value="file">a whole file</Option>
                                </Select>
                            </Box>
                            <Box>
                                <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>a constellation is</Box>
                                <Select
                                    size="sm"
                                    value={prefs.groupBy}
                                    onChange={(_, v) => v && setPrefs({ ...prefs, groupBy: v as any, look: { ...lookRef.current } })}
                                >
                                    <Option value="folder">a folder</Option>
                                    <Option value="file">a file</Option>
                                </Select>
                            </Box>
                            <Box>
                                <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>colour means</Box>
                                <Select
                                    size="sm"
                                    value={prefs.colorBy}
                                    onChange={(_, v) => v && setPrefs({ ...prefs, colorBy: v as any, look: { ...lookRef.current } })}
                                >
                                    <Option value="constellation">which constellation</Option>
                                    <Option value="keyword">the todo keyword</Option>
                                </Select>
                            </Box>
                            <Box>
                                <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>only headings matching</Box>
                                <Input
                                    size="sm"
                                    value={draftQuery}
                                    placeholder='IsTodo() && !IsArchived()'
                                    onChange={e => setDraftQuery(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') applyDrafts(); e.stopPropagation(); }}
                                    onBlur={applyDrafts}
                                    spellCheck={false}
                                    sx={{ fontSize: 10, fontFamily: 'Menlo, Consolas, monospace' }}
                                />
                            </Box>
                            <Box>
                                <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>leave out (folders or files)</Box>
                                <Input
                                    size="sm"
                                    value={draftExclude}
                                    placeholder="templates, archive"
                                    onChange={e => setDraftExclude(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') applyDrafts(); e.stopPropagation(); }}
                                    onBlur={applyDrafts}
                                    spellCheck={false}
                                    sx={{ fontSize: 10, fontFamily: 'Menlo, Consolas, monospace' }}
                                />
                            </Box>
                            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                                <Tooltip size="sm" title="day pages, journals and session records — usually most of a database and rarely what you came to look at">
                                    <Box sx={{ fontSize: 10, color: '#93A3C2' }}>hide the logs</Box>
                                </Tooltip>
                                <Switch
                                    size="sm"
                                    checked={prefs.noLogs}
                                    onChange={e => setPrefs({ ...prefs, noLogs: e.target.checked, look: { ...lookRef.current } })}
                                />
                            </Box>
                            <Box>
                                <Tooltip size="sm" title="the layout is O(n²) — every star pushes on every other one — so this is the setting with a cost behind it">
                                    <Box sx={{ fontSize: 10, color: '#93A3C2', mb: 0.4 }}>at most {prefs.limit} stars</Box>
                                </Tooltip>
                                <input
                                    type="range" min={200} max={20000} step={200}
                                    defaultValue={prefs.limit}
                                    onChange={e => setPrefs({ ...prefs, limit: parseInt(e.target.value, 10), look: { ...lookRef.current } })}
                                    style={{ width: '100%', accentColor: '#2EE6C8', cursor: 'pointer', height: 3 }}
                                />
                            </Box>
                        </Box>

                        <Typography sx={{ fontSize: 9, letterSpacing: '.16em', textTransform: 'uppercase', color: '#2EE6C8', mt: 2, mb: 0.5 }}>
                            galaxy shape
                        </Typography>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.6 }}>
                            {SHAPES.map(name => {
                                const on = (lookRef.current.shape || 'natural') === name;
                                return (
                                    <Box
                                        key={name}
                                        component="button"
                                        onClick={() => onShape(name)}
                                        sx={{
                                            background: 'none', cursor: 'pointer', borderRadius: '3px',
                                            border: `1px solid ${on ? 'rgba(46,230,200,.7)' : 'rgba(120,140,185,.35)'}`,
                                            color: on ? '#2EE6C8' : '#93A3C2',
                                            fontSize: 10, px: 1, py: 0.4,
                                            fontFamily: 'Menlo, Consolas, monospace',
                                        }}
                                    >
                                        {name}
                                    </Box>
                                );
                            })}
                        </Box>

                        {SECTIONS.map(sec => (
                            <Box key={sec}>
                                <Typography sx={{ fontSize: 9, letterSpacing: '.16em', textTransform: 'uppercase', color: '#2EE6C8', mt: 2, mb: 0.5 }}>
                                    {sec}
                                </Typography>
                                {SLIDERS.filter(s => s.sec === sec).map(s => (
                                    <SliderRow
                                        key={s.key}
                                        label={s.label}
                                        hint={s.hint}
                                        value={lookRef.current[s.key] as number}
                                        min={s.min}
                                        max={s.max}
                                        step={s.step}
                                        format={v => formatValue(s.key, v)}
                                        onChange={v => onTunable(s.key, v)}
                                    />
                                ))}
                            </Box>
                        ))}

                        <Button
                            size="sm" variant="outlined" onClick={restoreDefaults}
                            sx={{
                                mt: 2, fontSize: 10, color: '#93A3C2', borderColor: 'rgba(120,140,185,.35)',
                                '&:hover': { borderColor: 'rgba(46,230,200,.5)', color: '#2EE6C8' },
                            }}
                        >
                            restore defaults
                        </Button>
                    </Box>
                )}

                {/* The still. It is a data url in an img, so the browser's own
                    "save image as" is the way it gets saved - there is nowhere in
                    an org database a screenshot of the sky belongs. */}
                {shot !== '' && (
                    <Box sx={{
                        position: 'absolute', inset: 0, zIndex: 9, background: 'rgba(2,4,9,.92)',
                        display: 'flex', flexDirection: 'column', alignItems: 'center',
                        justifyContent: 'center', gap: 1.5, p: '4%',
                    }}>
                        <Box component="img" src={shot} alt="the starmap" sx={{
                            maxWidth: '92%', maxHeight: '74%',
                            border: '1px solid rgba(120,140,185,.35)', borderRadius: '4px',
                        }} />
                        <Typography sx={{ fontSize: 10, letterSpacing: '.1em', color: '#8FA0C0', textTransform: 'uppercase' }}>
                            right-click the image to save it
                        </Typography>
                        <Button
                            size="sm" variant="outlined" startDecorator={<CloseIcon fontSize="small" />}
                            onClick={() => setShot('')}
                            sx={{ fontSize: 10, color: '#2EE6C8', borderColor: 'rgba(46,230,200,.5)' }}
                        >
                            close
                        </Button>
                    </Box>
                )}
            </Box>

            {/* A star's own menu. */}
            <Menu
                open={menu !== null}
                onClose={() => setMenu(null)}
                anchorEl={menu ? {
                    getBoundingClientRect: () => ({
                        x: menu.x, y: menu.y, width: 0, height: 0,
                        top: menu.y, right: menu.x, bottom: menu.y, left: menu.x,
                        toJSON: () => '',
                    }),
                } as any : null}
                size="sm"
            >
                {menu && (
                    <MenuItem onClick={() => {
                        nav.toFile({
                            filename: menu.star.filename,
                            heading: menu.star.kind === 'heading' ? menu.star.label : '',
                            line: menu.star.kind === 'heading' ? menu.star.line : undefined,
                            back: { app: 'Starmap', label: 'Back to the starmap' },
                        });
                        setMenu(null);
                    }}>
                        Open {menu.star.kind === 'heading' ? 'this heading' : 'this file'}
                    </MenuItem>
                )}
                {menu && (
                    <MenuItem onClick={() => {
                        engineRef.current?.setSolo(menu.star.fam);
                        setSolo(menu.star.fam);
                        setMenu(null);
                    }}>
                        Solo its constellation
                    </MenuItem>
                )}
                {menu && menu.star.hash !== '' && (
                    <MenuItem onClick={() => {
                        // The hash is what every other tab addresses a heading by,
                        // so it is worth being able to get at.
                        try { navigator.clipboard.writeText(menu.star.hash); } catch { /* no clipboard */ }
                        setMenu(null);
                    }}>
                        Copy its hash
                    </MenuItem>
                )}
            </Menu>
        </Sheet>
    );
}

// The colour-by-expression panel: one row per rule - on or off, its colour,
// its query, and how many headings it found (or why it found none). Floats
// over the top left of the sky, in the starmap's own dark glass.
function RulesPanel({ rules, info, onAdd, onChange, onRemove, onClose }: {
    rules: StarColorRule[];
    info: { count: number; err: string }[];
    onAdd: () => void;
    onChange: (i: number, patch: Partial<StarColorRule>) => void;
    onRemove: (i: number) => void;
    onClose: () => void;
}) {
    // The query is edited locally and written on a pause, so typing does not
    // write a setting per keystroke.
    const [drafts, setDrafts] = React.useState<string[]>(rules.map(r => r.query));
    React.useEffect(() => { setDrafts(rules.map(r => r.query)); }, [rules]);
    const commit = (i: number) => { if (drafts[i] !== rules[i]?.query) onChange(i, { query: drafts[i] }); };
    return (
        <Box
            onKeyDown={e => e.stopPropagation()}
            sx={{
                position: 'absolute', top: 12, left: 12, zIndex: 6, width: { xs: 'calc(100% - 24px)', sm: 420 },
                background: 'rgba(8,12,24,.92)', border: '1px solid rgba(46,230,200,.25)', borderRadius: '6px',
                boxShadow: '0 10px 30px rgba(0,0,0,.5)', backdropFilter: 'blur(6px)', p: 1.25, color: '#DCE6F7',
            }}
        >
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <Typography sx={{ fontSize: 10, letterSpacing: '.16em', textTransform: 'uppercase', color: '#8FA0C0', flex: 1 }}>
                    Colour by expression
                </Typography>
                <IconButton size="sm" variant="plain" onClick={onClose} sx={{ color: '#8FA0C0', '--IconButton-size': '24px' }}>
                    <CloseIcon sx={{ fontSize: 16 }} />
                </IconButton>
            </Box>
            {rules.map((r, i) => {
                const inf = info[i];
                return (
                    <Box key={i} sx={{ mb: 0.9 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                            <Switch
                                size="sm" checked={r.on}
                                onChange={e => onChange(i, { on: e.target.checked })}
                                sx={{
                                    '--Switch-trackBackground': 'rgba(120,140,185,.3)',
                                    '&.Mui-checked': { '--Switch-trackBackground': r.color },
                                    '&.Mui-checked:hover': { '--Switch-trackBackground': r.color },
                                }}
                            />
                            <Tooltip size="sm" title="the colour these stars are drawn in">
                                <Box component="label" sx={{
                                    position: 'relative', width: 22, height: 22, borderRadius: '50%', flex: 'none',
                                    background: r.color, cursor: 'pointer',
                                    boxShadow: `0 0 0 2px rgba(8,12,24,1), 0 0 0 3px ${r.color}, 0 0 10px ${r.color}88`,
                                }}>
                                    <input
                                        type="color" value={r.color}
                                        onChange={e => onChange(i, { color: e.target.value })}
                                        style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer', width: '100%', height: '100%' }}
                                    />
                                </Box>
                            </Tooltip>
                            <Input
                                size="sm" value={drafts[i] ?? ''} placeholder='HasTags("work") && IsTodo()'
                                autoFocus={r.query === '' && i === rules.length - 1}
                                onChange={e => { const v = e.target.value; setDrafts(d => d.map((x, k) => (k === i ? v : x))); }}
                                onBlur={() => commit(i)}
                                onKeyDown={e => { if (e.key === 'Enter') commit(i); }}
                                spellCheck={false}
                                sx={{
                                    flex: 1, minWidth: 0, background: 'rgba(4,6,12,.9)', borderColor: 'rgba(120,140,185,.3)',
                                    color: '#EAF1FC', fontFamily: 'Menlo, Consolas, monospace', fontSize: 11,
                                    '--Input-focusedHighlight': r.color,
                                }}
                            />
                            <IconButton size="sm" variant="plain" onClick={() => onRemove(i)}
                                sx={{ color: '#6B7A9C', '--IconButton-size': '26px', '&:hover': { color: '#ff6b6b', background: 'transparent' } }}>
                                <DeleteIcon sx={{ fontSize: 16 }} />
                            </IconButton>
                        </Box>
                        <Typography sx={{ fontSize: 10, ml: '52px', mt: 0.3, color: inf && inf.err ? '#ff8a8a' : '#6B7A9C' }}>
                            {!r.query.trim() ? 'an org query, as in Search - e.g. IsTodo() && HasTags("work")'
                                : !r.on ? 'off'
                                    : !inf ? 'asking…'
                                        : inf.err ? inf.err
                                            : `${inf.count} heading${inf.count === 1 ? '' : 's'} match`}
                        </Typography>
                    </Box>
                );
            })}
            <Box sx={{ display: 'flex', alignItems: 'center', mt: 0.5 }}>
                <Button size="sm" variant="plain" startDecorator={<AddIcon sx={{ fontSize: 16 }} />} onClick={onAdd}
                    sx={{ color: '#2EE6C8', fontSize: 11, '&:hover': { background: 'rgba(46,230,200,.08)' } }}>
                    Add a rule
                </Button>
                <Typography sx={{ fontSize: 10, color: '#4C5A78', ml: 'auto' }}>
                    first matching rule wins
                </Typography>
            </Box>
        </Box>
    );
}
