// Focus sessions (pomodoros): the arithmetic and wording, pure so focus.test.ts
// can pin it. The timer itself runs on the server (internal/app/orgs/focus.go);
// the browser only counts down between the server's answers, and the API and
// the event stream are in focusApi.ts.
//
// `orgs focus` says the same things in the terminal (cmd/oc/commands/focus/
// format.go): Countdown and the status line are written to read the same.

import { fuzzyScoreAll, fuzzyTerms } from './fuzzy';

export type FocusPhase = 'work' | 'break' | 'idle';

export type FocusSettings = {
    Work: number;
    Short: number;
    Long: number;
    LongEvery: number;
    AutoNext: boolean;
};

export type FocusState = {
    Ok: boolean;
    Msg?: string;
    Phase: FocusPhase;
    LongBreak?: boolean;
    Hash?: string;
    Title?: string;
    File?: string;
    Started?: string;
    Ends?: string;
    Remaining: number;
    Total: number;
    Now: string;
    Streak: number;
    Today: number;
    TodayMinutes: number;
    Settings: FocusSettings;
};

export type FocusRecord = {
    Hash: string;
    Title: string;
    File: string;
    Start: string;
    End: string;
    Minutes: number;
    Completed: boolean;
    Break?: number;
    LongBreak?: boolean;
};

export type FocusHistory = {
    Ok: boolean;
    Today: number;
    TodayMinutes: number;
    Records: FocusRecord[];
};

export const IDLE: FocusState = {
    Ok: true, Phase: 'idle', Remaining: 0, Total: 0, Now: '', Streak: 0, Today: 0, TodayMinutes: 0,
    Settings: { Work: 25, Short: 5, Long: 15, LongEvery: 4, AutoNext: false },
};

// Seconds as a clock face: 4:07, 25:00, 1:02:03. Rounded up, so the last
// second reads 0:01 while there is still time left - a timer showing 0:00 that
// has not finished looks stuck.
export function formatCountdown(secs: number): string {
    let n = Math.ceil(secs);
    if (!(n > 0)) n = 0;
    const h = Math.floor(n / 3600), m = Math.floor(n / 60) % 60, s = n % 60;
    const ss = String(s).padStart(2, '0');
    if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${ss}`;
    return `${m}:${ss}`;
}

// Minutes as a person says them: 25 min, 1h 40m.
export function formatMinutes(m: number): string {
    if (m < 60) return `${Number.isInteger(m) ? m : m.toFixed(1)} min`;
    const n = Math.round(m);
    return `${Math.floor(n / 60)}h ${String(n % 60).padStart(2, '0')}m`;
}

// When the phase ends on this machine's clock, from the server's Remaining and
// the moment the answer arrived. The server's own Ends is not used: a laptop
// whose clock is two minutes out would count down two minutes wrong.
export function localEnd(state: FocusState, receivedAt: number): number {
    return receivedAt + Math.max(0, state.Remaining) * 1000;
}

export function remainingAt(end: number, now: number): number {
    return Math.max(0, (end - now) / 1000);
}

// How much of the phase has gone by, 0 to 1.
export function progress(state: FocusState, remaining: number): number {
    if (!(state.Total > 0)) return 0;
    return Math.min(1, Math.max(0, 1 - remaining / state.Total));
}

export function isRunning(state: FocusState | null | undefined): boolean {
    return !!state && (state.Phase === 'work' || state.Phase === 'break');
}

export function phaseLabel(state: FocusState): string {
    if (state.Phase === 'break') return state.LongBreak ? 'Long break' : 'Break';
    if (state.Phase === 'work') return 'Focus';
    return 'Idle';
}

export function phaseGlyph(phase: FocusPhase): string {
    return phase === 'work' ? '🍅' : phase === 'break' ? '☕' : '';
}

// The joy colour a phase is drawn in: tomato for work, green for a break.
export function phaseColor(phase: FocusPhase): 'danger' | 'success' | 'neutral' {
    return phase === 'work' ? 'danger' : phase === 'break' ? 'success' : 'neutral';
}

// The browser tab's title while a session runs, so the countdown is visible
// from another tab. Null when idle: put the page's own title back.
export function tabTitle(state: FocusState, remaining: number): string | null {
    if (state.Phase === 'work') return `${phaseGlyph('work')} ${formatCountdown(remaining)} · ${state.Title || 'Focus'}`;
    if (state.Phase === 'break') return `${phaseGlyph('break')} ${formatCountdown(remaining)} · ${phaseLabel(state)}`;
    return null;
}

// What to tell somebody when the session moves on by itself, or null when the
// change is not worth interrupting for (or was their own doing - a stop).
export function transitionNotice(prev: FocusState, next: FocusState): { title: string; body: string } | null {
    if (prev.Phase === next.Phase && prev.Started === next.Started) return null;
    if (prev.Phase === 'work' && next.Phase === 'break') {
        const mins = next.Total / 60;
        return {
            title: 'Pomodoro done',
            body: `${next.Title || ''} · ${next.LongBreak ? 'long break' : 'break'}, ${formatMinutes(round1(mins))}`.replace(/^ · /, ''),
        };
    }
    if (prev.Phase === 'break' && next.Phase === 'idle') {
        return { title: 'Break over', body: next.Title ? `Another on ${next.Title}?` : 'Ready for the next one?' };
    }
    if (prev.Phase === 'break' && next.Phase === 'work') {
        return { title: 'Back to work', body: next.Title || '' };
    }
    return null;
}

function round1(n: number): number {
    return Math.round(n * 10) / 10;
}

// The lengths offered as one click. Custom is the settings form.
export type Preset = { label: string; work: number; short: number; long: number };
export const PRESETS: Preset[] = [
    { label: '25 / 5', work: 25, short: 5, long: 15 },
    { label: '50 / 10', work: 50, short: 10, long: 30 },
    { label: '90 / 20', work: 90, short: 20, long: 30 },
];

export function presetOf(s: FocusSettings): Preset | null {
    return PRESETS.find(p => p.work === s.Work && p.short === s.Short && p.long === s.Long) || null;
}

// A task that can be picked: what /search answers, cut down.
export type FocusTask = { Hash: string; Headline: string; Filename: string; Status?: string; Priority?: string };

// The hashes of recent tasks, newest first, each once.
export function recentHashes(records: FocusRecord[]): string[] {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const r of records) {
        if (r.Hash && !seen.has(r.Hash)) {
            seen.add(r.Hash);
            out.push(r.Hash);
        }
    }
    return out;
}

function baseName(p: string): string {
    const i = Math.max(p.lastIndexOf('/'), p.lastIndexOf('\\'));
    return i >= 0 ? p.slice(i + 1) : p;
}

// The task list as the picker shows it. With nothing typed, recent tasks come
// first in the order they were worked on, then the rest as the server gave
// them. With something typed, fuzzy over the headline (and whole words of the
// file's name, never its path - see worg.md on the palette), recency breaking
// ties only.
export function rankTasks(tasks: FocusTask[], filter: string, recent: string[]): FocusTask[] {
    const rank = new Map<string, number>();
    recent.forEach((h, i) => rank.set(h, i));
    const terms = fuzzyTerms(filter);
    if (terms.length === 0) {
        const idx = new Map<FocusTask, number>();
        tasks.forEach((t, i) => idx.set(t, i));
        return [...tasks].sort((a, b) => {
            const ra = rank.has(a.Hash) ? rank.get(a.Hash)! : Infinity;
            const rb = rank.has(b.Hash) ? rank.get(b.Hash)! : Infinity;
            if (ra !== rb) return ra < rb ? -1 : 1;
            return idx.get(a)! - idx.get(b)!;
        });
    }
    const scored: { t: FocusTask; s: number }[] = [];
    for (const t of tasks) {
        const s = fuzzyScoreAll(terms, t.Headline, `${t.Headline} ${t.Status || ''} ${baseName(t.Filename)}`);
        if (s === null) continue;
        // A nudge, capped, so a recent task wins a tie but never a better match.
        const r = rank.get(t.Hash);
        scored.push({ t, s: s + (r === undefined ? 0 : Math.max(0, 5 - r)) });
    }
    scored.sort((a, b) => b.s - a.s);
    return scored.map(x => x.t);
}

// Today's records only: the history endpoint answers by day already, but a
// tab left open over midnight holds yesterday's.
export function todaysRecords(records: FocusRecord[], now: Date): FocusRecord[] {
    return records.filter(r => {
        const d = new Date(r.End);
        return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
    });
}

// "pomodoro 2 of 4": where in the set of four the running one is.
export function setPosition(state: FocusState): { n: number; of: number } {
    const of = state.Settings.LongEvery || 4;
    const n = state.Phase === 'work' ? state.Streak + 1 : state.Streak === 0 && state.LongBreak ? of : state.Streak;
    return { n: Math.min(Math.max(n, 0), of), of };
}
