export interface DepHeading {
    Hash: string;
    Headline: string;
    Filename: string;
    LineNum: number;
    Status: string;
    Done: boolean;
    Via?: 'AFTER' | 'ORDERED' | '';
    After?: string;
    NoBlocking?: string;
    Chained?: boolean;
}

export type DepKind = 'cycle' | 'waiting-on-done' | 'blocked-chain' | 'dangling' | 'ordered-stuck';
export type Severity = 'error' | 'warn' | 'info';

export interface DepProblem {
    Kind: DepKind;
    Severity: Severity;
    Title: string;
    Suggestion: string;
    Chain: DepHeading[] | null;
    Length?: number;
    Held?: number;
    Missing?: string;
}

export interface DepReport {
    Ok: boolean;
    Msg?: string;
    Query: string;
    Checked: number;
    Problems: DepProblem[] | null;
    Counts: { [kind: string]: number } | null;
}

// ── Estimates ──────────────────────────────────────────────────────────────

export type GroupBy = 'tag' | 'project' | 'file' | 'person';

export const GROUP_BY: { value: GroupBy; label: string }[] = [
    { value: 'tag', label: 'Tag' },
    { value: 'project', label: 'Project' },
    { value: 'file', label: 'File' },
    { value: 'person', label: 'Person' },
];

// The time picker's choices. Each is a request the server already reads: a
// relative `from` (orgdate's -90d) or a clock-table block.
export const RANGES: { value: string; label: string; params: Record<string, string> }[] = [
    { value: 'last30', label: 'Last 30 days', params: { from: '-30d' } },
    { value: 'last90', label: 'Last 90 days', params: { from: '-90d' } },
    { value: 'thismonth', label: 'This month', params: { block: 'thismonth' } },
    { value: 'lastmonth', label: 'Last month', params: { block: 'lastmonth' } },
    { value: 'thisyear', label: 'This year', params: { block: 'thisyear' } },
    { value: 'all', label: 'All time', params: {} },
    { value: 'custom', label: 'Between…', params: {} },
];

export interface EstimateAsk {
    range: string;
    from?: string;
    to?: string;
    by: GroupBy;
    // Hours in a day of EFFORT: 24 is org's own, 8 a working day.
    day: number;
    open: boolean;
    query?: string;
}

// What to put on /insights/estimates for an ask. A custom range with neither
// end set is all time, not an error.
export function estimateParams(a: EstimateAsk): Record<string, string> {
    const out: Record<string, string> = { by: a.by };
    if (a.range === 'custom') {
        if (a.from) out.from = a.from;
        if (a.to) out.to = a.to;
    } else {
        Object.assign(out, (RANGES.find(r => r.value === a.range) || RANGES[1]).params);
    }
    if (a.day && a.day !== 24) out.day = String(a.day);
    if (a.open) out.open = 't';
    if (a.query && a.query.trim()) out.query = a.query.trim();
    return out;
}

// 1.6× - one decimal, always shown, so a column of them lines up.
export function times(x: number): string {
    if (!x || x <= 0 || !isFinite(x)) return '–';
    return `${(Math.round(x * 10) / 10).toFixed(1)}×`;
}

// How a ratio reads: over-runs warm, padding cool, near enough green. The
// band is the same one the server's sentence uses for "about right"
// (0.9 to 1.1 after rounding), widened a little for the colour so a 1.15
// does not shout.
export type Tone = 'success' | 'warning' | 'danger' | 'primary' | 'neutral';

export function ratioTone(r: number): Tone {
    if (!r || r <= 0) return 'neutral';
    if (r > 1.5) return 'danger';
    if (r > 1.15) return 'warning';
    if (r < 0.8) return 'primary';
    return 'success';
}

// Estimate against actual on one scale, as the weekly review draws planned
// against clocked: solid to the smaller, then estimate not used, or time
// over the estimate.
export function estimateBar(est: number, actual: number, most: number) {
    return timeBar(actual, est, most);
}

export function barScale(groups: EstimateGroup[]): number {
    let most = 0;
    for (const g of groups) most = Math.max(most, g.EstMins, g.ActualMins);
    return most;
}

// Where the middle half of a group's tasks fall, as a span on a log scale
// centred on 1×: 0.25× at the left edge, 4× at the right. A log scale, because
// twice as long and half as long are misses of the same size.
export function spreadSpan(p25: number, p75: number, median: number): { left: number; width: number; mid: number } | null {
    if (!(p25 > 0) || !(p75 > 0) || !(median > 0)) return null;
    const pos = (x: number) => Math.min(100, Math.max(0, (Math.log2(x) + 2) / 4 * 100));
    const l = pos(p25), r = pos(p75);
    return { left: l, width: Math.max(r - l, 0.8), mid: pos(median) };
}

// Hours, for the hint under the chart.
export function hoursText(mins: number): string {
    const h = mins / 60;
    return h >= 10 ? `${Math.round(h)}h` : `${Math.round(h * 10) / 10}h`;
}

// ── Dependencies ───────────────────────────────────────────────────────────

export const KINDS: { kind: DepKind; label: string; blurb: string }[] = [
    { kind: 'cycle', label: 'Cycles', blurb: 'headings that wait on each other, so none can start' },
    { kind: 'waiting-on-done', label: 'Waiting on done', blurb: 'still WAITING on something already finished' },
    { kind: 'dangling', label: 'Dangling links', blurb: 'an AFTER that names no heading, or an archived one' },
    { kind: 'ordered-stuck', label: 'Stuck ORDERED projects', blurb: 'the current step is waiting, or steps done out of order' },
    { kind: 'blocked-chain', label: 'Blocked chains', blurb: 'work held up behind one open task' },
];

const SEVERITY_RANK: Record<Severity, number> = { error: 0, warn: 1, info: 2 };

export function worstSeverity(ps: DepProblem[]): Severity {
    let best: Severity = 'info';
    for (const p of ps) if (SEVERITY_RANK[p.Severity] < SEVERITY_RANK[best]) best = p.Severity;
    return best;
}

export interface KindGroup {
    kind: DepKind;
    label: string;
    blurb: string;
    severity: Severity;
    problems: DepProblem[];
}

// Problems under their kind, the kinds in a fixed order (the ones that stop
// work first) with any empty kind left out, and each kind's problems worst
// first, longest first.
export function groupProblems(ps: DepProblem[] | null | undefined): KindGroup[] {
    const out: KindGroup[] = [];
    for (const k of KINDS) {
        const mine = (ps || []).filter(p => p.Kind === k.kind);
        if (mine.length === 0) continue;
        mine.sort((a, b) => SEVERITY_RANK[a.Severity] - SEVERITY_RANK[b.Severity] || (b.Length || 0) - (a.Length || 0));
        out.push({ kind: k.kind, label: k.label, blurb: k.blurb, severity: worstSeverity(mine), problems: mine });
    }
    // Groups that hold an error come first whatever their kind.
    return out.sort((a, b) => SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity]);
}

export function severityColor(s: Severity): 'danger' | 'warning' | 'neutral' {
    return s === 'error' ? 'danger' : s === 'warn' ? 'warning' : 'neutral';
}

function truthy(v?: string): boolean {
    return /^(t|yes|true|1)$/i.test((v || '').trim());
}

// Whether the wait into this heading of a chain can be taken away: it waits
// by an AFTER it holds, or by an ORDERED chain that NOBLOCKING would end.
// The first heading of a chain waits on nothing in it.
export function canUnlink(h: DepHeading, index: number, kind: DepKind): boolean {
    if (kind === 'ordered-stuck') return false;
    if (index === 0 && kind !== 'dangling') return false;
    if (h.After) return true;
    return h.Via === 'ORDERED' && !!h.Chained && !truthy(h.NoBlocking);
}

// The heading as far as ganttops' unlinkOp needs one: its hash, a name for the
// undo label, the AFTER and NOBLOCKING it holds and whether an ORDERED parent
// would chain it. The rest of a GanttTask is a chart's business.
export function asGanttTask(h: DepHeading): GanttTask {
    const props: Record<string, string> = {};
    if (h.After) props['AFTER'] = h.After;
    if (h.NoBlocking) props['NOBLOCKING'] = h.NoBlocking;
    return {
        id: h.Hash, name: h.Headline, section: '', start: new Date(0), end: new Date(0), state: 'default',
        milestone: false, mark: false, days: 0, plannedDays: null, after: [],
        hash: h.Hash, filename: h.Filename, lineNum: h.LineNum, status: h.Status, props, chained: !!h.Chained,
    };
}

export function baseName(path: string): string {
    return (path || '').replace(/^.*[\\/]/, '');
}
