const SECTION_KEY = 'worg.insightsSection';
const ASK_KEY = 'worg.insightsAsk';

function stored<T>(key: string, fallback: T): T {
    try {
        const v = localStorage.getItem(key);
        return v ? { ...fallback, ...JSON.parse(v) } as T : fallback;
    } catch {
        return fallback;
    }
}
function storedStr(key: string, fallback: string): string {
    try { return localStorage.getItem(key) || fallback; } catch { return fallback; }
}
function store(key: string, v: any) {
    try { localStorage.setItem(key, typeof v === 'string' ? v : JSON.stringify(v)); } catch { /* private window */ }
}

type Section = 'estimates' | 'deps';

export default function Insights(_props: any) {
    const [section, setSection] = React.useState<Section>(storedStr(SECTION_KEY, 'estimates') === 'deps' ? 'deps' : 'estimates');
    const pick = (s: Section) => { setSection(s); store(SECTION_KEY, s); };
    return (
        <Box sx={{ width: '100%', display: 'flex', flexDirection: 'column', gap: 1.5, pb: 4 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                <Typography level="h3">Insights</Typography>
                <Tabs value={section} onChange={(_, v) => pick(v as Section)} size="sm" sx={{ borderRadius: 'sm' }}>
                    <TabList variant="outlined">
                        <Tab value="estimates">Estimates</Tab>
                        <Tab value="deps">Dependencies</Tab>
                    </TabList>
                </Tabs>
            </Box>
            {section === 'estimates' ? <Estimates /> : <Dependencies />}
        </Box>
    );
}

