// Asks again whenever the key changes, dropping an answer that arrives after a
// newer question.
function useAnswer<T>(key: string, ask: (signal: AbortSignal) => Promise<T>): { data: T | null; loading: boolean; reload: () => void } {
    const [data, setData] = React.useState<T | null>(null);
    const [loading, setLoading] = React.useState(false);
    const [n, setN] = React.useState(0);
    const askRef = React.useRef(ask);
    askRef.current = ask;
    React.useEffect(() => {
        const ctl = new AbortController();
        setLoading(true);
        askRef.current(ctl.signal).then(d => {
            if (ctl.signal.aborted) return;
            setData(d);
            setLoading(false);
        }).catch(() => { if (!ctl.signal.aborted) setLoading(false); });
        return () => ctl.abort();
    }, [key, n]);
    return { data, loading, reload: () => setN(x => x + 1) };
}

// ── Estimates ──────────────────────────────────────────────────────────────

const DEFAULT_ASK: EstimateAsk = { range: 'last90', by: 'tag', day: 24, open: false, query: '' };

function Estimates() {
    const isMobile = useIsMobile();
    const [ask, setAskState] = React.useState<EstimateAsk>(() => stored(ASK_KEY, DEFAULT_ASK));
    const setAsk = (change: Partial<EstimateAsk>) => setAskState(a => {
        const next = { ...a, ...change };
        store(ASK_KEY, next);
        return next;
    });
    // The query box is sent on Enter, not per keystroke: a half-typed query
    // is a parse error.
    const [queryText, setQueryText] = React.useState(ask.query || '');
    const { data, loading, reload } = useAnswer<EstimateReport>(JSON.stringify(ask), s => InsightsApi.estimates(ask, s));
    const [openGroup, setOpenGroup] = React.useState<string | null>(null);

    const groups = (data && data.Groups) || [];
    const most = barScale(groups);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <Sheet variant="outlined" sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, p: 2, borderRadius: 'sm', alignItems: 'flex-end' }}>
                <FormControl size="sm">
                    <FormLabel>Finished</FormLabel>
                    <Select size="sm" value={ask.range} onChange={(_, v) => v && setAsk({ range: v })} sx={{ minWidth: 140 }}>
                        {RANGES.map(r => <Option key={r.value} value={r.value}>{r.label}</Option>)}
                    </Select>
                </FormControl>
                {ask.range === 'custom' && (
                    <>
                        <FormControl size="sm">
                            <FormLabel>From</FormLabel>
                            <Input size="sm" type="date" value={ask.from || ''} onChange={e => setAsk({ from: e.target.value })} />
                        </FormControl>
                        <FormControl size="sm">
                            <FormLabel>To</FormLabel>
                            <Input size="sm" type="date" value={ask.to || ''} onChange={e => setAsk({ to: e.target.value })} />
                        </FormControl>
                    </>
                )}
                <FormControl size="sm">
                    <FormLabel>Group by</FormLabel>
                    <ToggleButtonGroup size="sm" value={ask.by} onChange={(_, v) => v && setAsk({ by: v as GroupBy })}>
                        {GROUP_BY.map(g => <Button key={g.value} value={g.value}>{g.label}</Button>)}
                    </ToggleButtonGroup>
                </FormControl>
                <FormControl size="sm">
                    <Tooltip title="Org counts a day of EFFORT as 24 hours. If you write 1d meaning a working day, use 8h.">
                        <FormLabel>A day of effort</FormLabel>
                    </Tooltip>
                    <ToggleButtonGroup size="sm" value={String(ask.day)} onChange={(_, v) => v && setAsk({ day: Number(v) })}>
                        <Button value="24">24h</Button>
                        <Button value="8">8h</Button>
                    </ToggleButtonGroup>
                </FormControl>
                <FormControl size="sm" orientation="horizontal" sx={{ gap: 1, alignItems: 'center', pb: 0.5 }}>
                    <Switch size="sm" checked={ask.open} onChange={e => setAsk({ open: e.target.checked })} />
                    <FormLabel sx={{ m: 0 }}>Include open tasks</FormLabel>
                </FormControl>
                <FormControl size="sm" sx={{ flex: 1, minWidth: 180 }}>
                    <FormLabel>Only</FormLabel>
                    <Input size="sm" placeholder='a query, e.g. HasTags("work") — Enter to apply' value={queryText}
                        onChange={e => setQueryText(e.target.value)}
                        onKeyDown={e => { if (e.key === 'Enter') setAsk({ query: queryText }); }}
                        onBlur={() => { if (queryText !== (ask.query || '')) setAsk({ query: queryText }); }} />
                </FormControl>
                <IconButton size="sm" variant="outlined" onClick={reload} title="Ask again"><RefreshRoundedIcon /></IconButton>
            </Sheet>

            {loading && !data && <Box sx={{ textAlign: 'center', py: 4 }}><CircularProgress size="sm" /></Box>}
            {data && !data.Ok && <Alert color="danger">{data.Msg || 'The estimates could not be read.'}</Alert>}
            {data && data.Ok && data.All.Tasks === 0 && (
                <>
                    <Typography level="title-md" sx={{ textAlign: 'center', py: 3, color: 'text.secondary' }}>
                        Nothing measured: no task finished {data.Label === 'all time' ? 'ever' : `(${data.Label})`} has both an EFFORT and clocked time.
                    </Typography>
                    <Unmeasured data={data} onDay={day => setAsk({ day })} />
                </>
            )}
            {data && data.Ok && data.All.Tasks > 0 && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, opacity: loading ? 0.6 : 1 }}>
                    <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                        <Big label={data.All.Tasks === 1 ? 'task measured' : 'tasks measured'} value={String(data.All.Tasks)} />
                        <Big label="estimated" value={hm(data.All.EstMins)} />
                        <Big label="actual" value={hm(data.All.ActualMins)} />
                        <Big label="median actual ÷ estimate" value={times(data.All.Median)}
                            color={`var(--joy-palette-${ratioTone(data.All.Median)}-500)`} />
                        <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>{data.Label}</Typography>
                    </Box>
                    {data.All.Sentence && (
                        <Alert variant="soft" color={ratioTone(data.All.Median) === 'success' ? 'success' : ratioTone(data.All.Median) === 'primary' ? 'primary' : 'warning'}>
                            <Typography level="title-md">{data.All.Sentence}</Typography>
                        </Alert>
                    )}

                    <Box>
                        <Table size="sm" hoverRow sx={{ '& td': { verticalAlign: 'middle' }, tableLayout: 'fixed' }}>
                            <thead>
                                <tr>
                                    <th style={{ width: isMobile ? '40%' : '24%' }}>{GROUP_BY.find(g => g.value === data.By)?.label}</th>
                                    {!isMobile && <th style={{ width: 50, textAlign: 'right' }}>tasks</th>}
                                    {!isMobile && <th style={{ width: 70, textAlign: 'right' }}>estimate</th>}
                                    {!isMobile && <th style={{ width: 70, textAlign: 'right' }}>actual</th>}
                                    <th style={{ width: 64, textAlign: 'right' }}>ratio</th>
                                    <th>estimate against actual</th>
                                    {!isMobile && <th style={{ width: 150 }}>
                                        <Tooltip title="The middle half of the tasks' actual ÷ estimate, on a scale from 0.25× to 4×. The tick is the median; the line is 1×.">
                                            <span>spread</span>
                                        </Tooltip>
                                    </th>}
                                </tr>
                            </thead>
                            <tbody>
                                {groups.map(g => {
                                    const key = g.Kind + g.Name;
                                    const open = openGroup === key;
                                    return (
                                        <React.Fragment key={key}>
                                            <tr style={{ cursor: 'pointer' }} onClick={() => setOpenGroup(open ? null : key)}>
                                                <td style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={g.Name}>
                                                    {open ? <KeyboardArrowDownRoundedIcon sx={{ fontSize: 16, verticalAlign: 'middle' }} />
                                                        : <KeyboardArrowRightRoundedIcon sx={{ fontSize: 16, verticalAlign: 'middle' }} />}
                                                    {groupLabel(g)}
                                                    {g.InProgress > 0 && <Typography level="body-xs" component="span" sx={{ color: 'text.tertiary' }}> · {g.InProgress} open</Typography>}
                                                </td>
                                                {!isMobile && <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{g.Tasks}</td>}
                                                {!isMobile && <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hm(g.EstMins)}</td>}
                                                {!isMobile && <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{hm(g.ActualMins)}</td>}
                                                <td style={{ textAlign: 'right' }}>
                                                    <Chip size="sm" variant="soft" color={ratioTone(g.Ratio)}>{times(g.Ratio)}</Chip>
                                                </td>
                                                <td><EstimateBar est={g.EstMins} actual={g.ActualMins} most={most} /></td>
                                                {!isMobile && <td><Spread g={g} /></td>}
                                            </tr>
                                            {open && (
                                                <tr>
                                                    <td colSpan={isMobile ? 3 : 7} style={{ background: 'var(--joy-palette-background-level1)' }}>
                                                        <GroupDetail g={g} />
                                                    </td>
                                                </tr>
                                            )}
                                        </React.Fragment>
                                    );
                                })}
                            </tbody>
                        </Table>
                        <Box sx={{ display: 'flex', gap: 2, mt: 1, alignItems: 'center', flexWrap: 'wrap' }}>
                            <Swatch color="primary.500" label="actual, within the estimate" />
                            <Swatch color="primary.softBg" label="estimated, not used" />
                            <Swatch color="warning.400" label="actual over the estimate" />
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                {data.By === 'tag' ? 'A task counts once for each of its tags, so the rows do not add up to the total. ' : ''}
                                Click a row for its sentence and worst misses.
                            </Typography>
                        </Box>
                    </Box>

                    <Box sx={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 2 }}>
                        <TaskList title="Worst over-runs" tasks={data.Over || []} empty="Nothing took longer than estimated." />
                        <TaskList title="Biggest under-runs" tasks={data.Under || []} empty="Nothing finished under its estimate." />
                    </Box>
                    <Unmeasured data={data} onDay={day => setAsk({ day })} />
                </Box>
            )}
        </Box>
    );
}

function groupLabel(g: EstimateGroup): string {
    if (g.Kind === 'tag' && !g.Name.startsWith('(')) return `:${g.Name}:`;
    return g.Name;
}

function EstimateBar(props: { est: number; actual: number; most: number }) {
    const b = estimateBar(props.est, props.actual, props.most);
    return (
        <Tooltip title={`estimated ${hm(props.est)}, took ${hm(props.actual)}`}>
            <Box sx={{ display: 'flex', height: 12, borderRadius: '6px', overflow: 'hidden', bgcolor: 'background.level1' }}>
                <Box sx={{ width: `${b.within}%`, bgcolor: 'primary.500' }} />
                <Box sx={{ width: `${b.unspent}%`, bgcolor: 'primary.softBg' }} />
                <Box sx={{ width: `${b.over}%`, bgcolor: 'warning.400' }} />
            </Box>
        </Tooltip>
    );
}

function Spread(props: { g: EstimateGroup }) {
    const s = spreadSpan(props.g.P25, props.g.P75, props.g.Median);
    if (!s) return null;
    return (
        <Tooltip title={`median ${times(props.g.Median)}; half the tasks between ${times(props.g.P25)} and ${times(props.g.P75)}`}>
            <Box sx={{ position: 'relative', height: 14 }}>
                <Box sx={{ position: 'absolute', left: 0, right: 0, top: 6, height: 2, bgcolor: 'background.level2' }} />
                <Box sx={{ position: 'absolute', left: '50%', top: 0, bottom: 0, width: '1px', bgcolor: 'text.tertiary' }} />
                <Box sx={{ position: 'absolute', left: `${s.left}%`, width: `${s.width}%`, top: 3, height: 8, borderRadius: '4px', bgcolor: `${ratioTone(props.g.Median)}.300`, opacity: 0.8 }} />
                <Box sx={{ position: 'absolute', left: `calc(${s.mid}% - 1px)`, top: 1, height: 12, width: 3, borderRadius: '1px', bgcolor: `${ratioTone(props.g.Median)}.600` }} />
            </Box>
        </Tooltip>
    );
}

function GroupDetail(props: { g: EstimateGroup }) {
    const g = props.g;
    return (
        <Box sx={{ py: 1, display: 'flex', flexDirection: 'column', gap: 1 }}>
            {g.Sentence && <Typography level="title-sm">{g.Sentence}</Typography>}
            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                total {times(g.Ratio)} · median {times(g.Median)} · middle half {times(g.P25)} to {times(g.P75)}
                {g.Multiplier > 0 ? ` · plan with ×${g.Multiplier}` : ''}
            </Typography>
            {(g.Worst || []).map(t => <TaskRow key={t.Hash + t.LineNum} t={t} />)}
        </Box>
    );
}

function TaskRow(props: { t: EstimateTask }) {
    const t = props.t;
    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
            <Chip size="sm" variant="soft" color={ratioTone(t.Ratio)} sx={{ minWidth: 52, justifyContent: 'center' }}>{times(t.Ratio)}</Chip>
            <Box sx={{ minWidth: 0, flex: 1 }}>
                <Typography level="body-sm" noWrap title={t.Headline}>
                    {t.Headline}
                    {t.InProgress && <Typography level="body-xs" component="span" sx={{ color: 'warning.500' }}> · still open</Typography>}
                </Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }} noWrap>
                    {hm(t.EstMins)} <ArrowForwardRoundedIcon sx={{ fontSize: 11, verticalAlign: 'middle' }} /> {hm(t.ActualMins)}
                    {' · '}{baseName(t.Filename)}{t.Effort ? ` · EFFORT ${t.Effort}` : ''}
                </Typography>
            </Box>
            <OpenButton filename={t.Filename} line={t.LineNum} heading={t.Headline} />
        </Box>
    );
}

function TaskList(props: { title: string; tasks: EstimateTask[]; empty: string }) {
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 1.5, display: 'flex', flexDirection: 'column', gap: 1 }}>
            <Typography level="title-md">{props.title}</Typography>
            {props.tasks.length === 0
                ? <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>{props.empty}</Typography>
                : props.tasks.slice(0, 8).map(t => <TaskRow key={t.Hash + t.LineNum} t={t} />)}
        </Sheet>
    );
}

// What could not be measured, said rather than dropped.
function Unmeasured(props: { data: EstimateReport; onDay: (hours: number) => void }) {
    const d = props.data;
    const [showUnest, setShowUnest] = React.useState(false);
    const parts: React.ReactNode[] = [];
    if (d.ClockNoEffort > 0) {
        parts.push(
            <Chip key="c" size="sm" variant="soft" color="neutral" onClick={() => setShowUnest(x => !x)}
                endDecorator={showUnest ? <KeyboardArrowDownRoundedIcon /> : <KeyboardArrowRightRoundedIcon />}>
                {d.ClockNoEffort} clocked with no estimate ({hm(d.ClockNoEffortMins)})
            </Chip>);
    }
    if (d.EffortNoClock > 0) parts.push(<Chip key="e" size="sm" variant="soft" color="neutral">{d.EffortNoClock} finished with an estimate and no clock</Chip>);
    if (d.Rollups > 0) parts.push(<Chip key="r" size="sm" variant="soft" color="neutral">{d.Rollups} rollup{d.Rollups === 1 ? '' : 's'} (an EFFORT over estimated subtasks)</Chip>);
    if (parts.length === 0 && !(d.DayEfforts > 0 && d.DayHours === 24)) return null;
    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            {parts.length > 0 && (
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                    <Typography level="body-sm" sx={{ color: 'text.secondary' }}>Not measured:</Typography>
                    {parts}
                </Box>
            )}
            {showUnest && (d.Unestimated || []).length > 0 && (
                <Sheet variant="soft" sx={{ borderRadius: 'sm', p: 1.5, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>The most time with no estimate, biggest first</Typography>
                    {(d.Unestimated || []).map(t => (
                        <Box key={t.Hash + t.LineNum} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Typography level="body-sm" sx={{ fontVariantNumeric: 'tabular-nums', minWidth: 52, textAlign: 'right' }}>{hm(t.ActualMins)}</Typography>
                            <Typography level="body-sm" noWrap sx={{ flex: 1 }}>{t.Headline}</Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{baseName(t.Filename)}</Typography>
                            <OpenButton filename={t.Filename} line={t.LineNum} heading={t.Headline} />
                        </Box>
                    ))}
                </Sheet>
            )}
            {d.DayEfforts > 0 && d.DayHours === 24 && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {d.DayEfforts} estimate{d.DayEfforts === 1 ? ' is' : 's are'} written in days, counted as 24 hours each (org's reading).{' '}
                    <Button size="sm" variant="plain" sx={{ minHeight: 0, py: 0 }} onClick={() => props.onDay(8)}>Read them as 8h working days</Button>
                </Typography>
            )}
        </Box>
    );
}

// ── Dependencies ───────────────────────────────────────────────────────────

const SEVERITY_ICON: Record<Severity, React.ReactNode> = {
    error: <ErrorRoundedIcon />,
    warn: <WarningRoundedIcon />,
    info: <InfoRoundedIcon />,
};

function Dependencies() {
    const [queryText, setQueryText] = React.useState('');
    const [query, setQuery] = React.useState('');
    const [min, setMin] = React.useState(3);
    const { data, loading, reload } = useAnswer<DepReport>(`${query}\u0000${min}`, s => InsightsApi.deps(query, min, s));
    const [done, setDone] = React.useState<GanttOp | null>(null);
    const [err, setErr] = React.useState('');
    const groups = React.useMemo(() => groupProblems(data && data.Problems), [data]);

    const unlink = async (h: DepHeading, from: DepHeading | null) => {
        const op = unlinkOp(asGanttTask(h), from ? asGanttTask(from) : null);
        if (!op) return;
        setErr('');
        try {
            await op.apply();
            setDone(op);
        } catch (e: any) {
            setErr(e.message || String(e));
        }
        reload();
    };
    const undo = async () => {
        if (!done) return;
        try {
            await done.revert();
        } catch (e: any) {
            setErr(e.message || String(e));
        }
        setDone(null);
        reload();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <Sheet variant="outlined" sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, p: 2, borderRadius: 'sm', alignItems: 'flex-end' }}>
                <FormControl size="sm" sx={{ flex: 1, minWidth: 200 }}>
                    <FormLabel>Only problems touching</FormLabel>
                    <Input size="sm" placeholder='a query, e.g. InFile("plan") — Enter to apply' value={queryText}
                        onChange={e => setQueryText(e.target.value)}
                        onKeyDown={e => { if (e.key === 'Enter') setQuery(queryText); }}
                        onBlur={() => setQuery(queryText)} />
                </FormControl>
                <FormControl size="sm">
                    <Tooltip title="A chain of open tasks this long or longer, held up behind one, is worth a look. A chain stuck on something WAITING is shown at any length.">
                        <FormLabel>Chains from</FormLabel>
                    </Tooltip>
                    <Select size="sm" value={min} onChange={(_, v) => v && setMin(v)} sx={{ minWidth: 100 }}>
                        {[2, 3, 4, 5, 8].map(n => <Option key={n} value={n}>{n} long</Option>)}
                    </Select>
                </FormControl>
                <IconButton size="sm" variant="outlined" onClick={reload} title="Check again"><RefreshRoundedIcon /></IconButton>
            </Sheet>

            {done && (
                <Alert color="success" variant="soft" endDecorator={
                    <Button size="sm" variant="soft" color="success" startDecorator={<UndoRoundedIcon />} onClick={undo}>Undo</Button>}>
                    {done.label}
                </Alert>
            )}
            {err && <Alert color="danger" variant="soft">{err}</Alert>}
            {loading && !data && <Box sx={{ textAlign: 'center', py: 4 }}><CircularProgress size="sm" /></Box>}
            {data && !data.Ok && <Alert color="danger">{data.Msg || 'The dependencies could not be read.'}</Alert>}
            {data && data.Ok && groups.length === 0 && (
                <Clear text={`No dependency problems among ${data.Checked} heading${data.Checked === 1 ? '' : 's'} with keywords or links.`} />
            )}
            {data && data.Ok && groups.length > 0 && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, opacity: loading ? 0.6 : 1 }}>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                        {groups.map(g => (
                            <Chip key={g.kind} size="sm" variant="soft" color={severityColor(g.severity)} startDecorator={SEVERITY_ICON[g.severity]}
                                onClick={() => document.getElementById(`insights-${g.kind}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })}>
                                {g.problems.length} {g.label.toLowerCase()}
                            </Chip>
                        ))}
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{data.Checked} headings checked</Typography>
                    </Box>
                    {groups.map(g => (
                        <Box key={g.kind} id={`insights-${g.kind}`} sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1, flexWrap: 'wrap' }}>
                                <Typography level="title-lg" startDecorator={
                                    <Box component="span" sx={{ color: `${severityColor(g.severity)}.500`, display: 'inline-flex' }}>{SEVERITY_ICON[g.severity]}</Box>}>
                                    {g.label}
                                </Typography>
                                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>{g.blurb}</Typography>
                            </Box>
                            {g.problems.map((p, i) => <ProblemCard key={p.Kind + i + p.Title} p={p} onUnlink={unlink} />)}
                        </Box>
                    ))}
                </Box>
            )}
        </Box>
    );
}

function ProblemCard(props: { p: DepProblem; onUnlink: (h: DepHeading, from: DepHeading | null) => void }) {
    const p = props.p;
    // Errors open, the rest folded to their one line: a list of twenty chains
    // drawn in full is a wall.
    const [open, setOpen] = React.useState(p.Severity === 'error');
    const chain = p.Chain || [];
    const color = severityColor(p.Severity);
    return (
        <Sheet variant="outlined" sx={{
            borderRadius: 'sm', borderLeftWidth: 4, borderLeftColor: `${color}.400`, px: 1.5, py: 1,
            display: 'flex', flexDirection: 'column', gap: 1,
        }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, cursor: 'pointer' }} onClick={() => setOpen(o => !o)}>
                {open ? <KeyboardArrowDownRoundedIcon /> : <KeyboardArrowRightRoundedIcon />}
                <Typography level="title-sm" sx={{ flex: 1 }}>{p.Title}</Typography>
                {p.Held ? <Chip size="sm" variant="outlined">{p.Held} held up</Chip> : null}
                {p.Kind === 'blocked-chain' && p.Length ? <Chip size="sm" variant="outlined">{p.Length} long</Chip> : null}
            </Box>
            {open && (
                <>
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 0.5, pl: 4 }}>
                        {p.Kind === 'dangling' && p.Missing && chain.length === 1 && (
                            <>
                                <Chip size="sm" variant="soft" color="danger">{p.Missing} ?</Chip>
                                <Link />
                            </>
                        )}
                        {chain.map((h, i) => (
                            <React.Fragment key={i}>
                                {i > 0 && <Link via={h.Via} onUnlink={canUnlink(h, i, p.Kind) ? () => props.onUnlink(h, chain[i - 1]) : undefined} />}
                                <ChainNode h={h} />
                                {i === 0 && p.Kind === 'dangling' && canUnlink(h, 0, p.Kind) && (
                                    <Tooltip title={`Clear the AFTER on “${h.Headline}”`}>
                                        <IconButton size="sm" variant="soft" color="danger" onClick={() => props.onUnlink(h, null)}><LinkOffRoundedIcon /></IconButton>
                                    </Tooltip>
                                )}
                            </React.Fragment>
                        ))}
                    </Box>
                    <Typography level="body-sm" sx={{ color: 'text.secondary', pl: 4 }}>{p.Suggestion}</Typography>
                </>
            )}
        </Sheet>
    );
}

// One link of a chain: the arrow, what kind of wait it is, and the button
// that takes it away when that can be done.
function Link(props: { via?: string; onUnlink?: () => void }) {
    const arrow = (
        <Box sx={{ display: 'inline-flex', flexDirection: 'column', alignItems: 'center', px: 0.25, color: 'text.tertiary' }}>
            <ArrowForwardRoundedIcon sx={{ fontSize: 18 }} />
            {props.via && <Typography level="body-xs" sx={{ fontSize: 9, lineHeight: 1, letterSpacing: '0.04em' }}>{props.via}</Typography>}
        </Box>
    );
    if (!props.onUnlink) return arrow;
    return (
        <Box sx={{ display: 'inline-flex', alignItems: 'center' }}>
            {arrow}
            <Tooltip title={props.via === 'ORDERED' ? 'Take it out of the ORDERED chain (NOBLOCKING)' : 'Remove this dependency (clear the AFTER)'}>
                <IconButton size="sm" variant="plain" color="neutral" onClick={props.onUnlink} sx={{ minHeight: 0, minWidth: 0, p: 0.25 }}>
                    <LinkOffRoundedIcon sx={{ fontSize: 16 }} />
                </IconButton>
            </Tooltip>
        </Box>
    );
}

function ChainNode(props: { h: DepHeading }) {
    const h = props.h;
    const nav = useNav();
    return (
        <Tooltip title={`${baseName(h.Filename)}:${h.LineNum + 1} — open it`}>
            <Sheet variant="soft" sx={{
                display: 'inline-flex', alignItems: 'center', gap: 0.75, borderRadius: 'sm', px: 1, py: 0.25, cursor: 'pointer',
                opacity: h.Done ? 0.7 : 1, maxWidth: 320, '&:hover': { bgcolor: 'background.level2' },
            }} onClick={() => nav.toFile({
                filename: h.Filename, line: h.LineNum, heading: h.Headline,
                back: { app: 'Insights', label: 'Back to Insights' },
            })}>
                <StatusChip status={h.Status} />
                <Typography level="body-sm" noWrap sx={{ textDecoration: h.Done ? 'line-through' : undefined }}>{h.Headline}</Typography>
            </Sheet>
        </Tooltip>
    );
}
