import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Alert from '@mui/joy/Alert';
import CircularProgress from '@mui/joy/CircularProgress';
import CloseIcon from '@mui/icons-material/Close';
import RepeatIcon from '@mui/icons-material/Repeat';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import ViewSidebarIcon from '@mui/icons-material/ViewSidebarOutlined';
import FlagIcon from '@mui/icons-material/Flag';
import CakeIcon from '@mui/icons-material/CakeOutlined';
import { ODb } from '../db';
import { useIsMobile } from '../useMobile';
import {
    PlanDay, PlanBlock, PlanTask, clockMins, clock, lengthText, snap, clampBlock, taskLength, spanOf, layoutLanes,
    freeSlot, searchFrom, placeLocally, unplanLocally, ymd, SNAP, DAY_MINS,
} from '../planner';
import { getPlanDay, planBlock, planUnblock } from '../plannerApi';
import PlannerList, { DEFAULT_QUERY } from './PlannerList';

// The Agenda's day view as a planner: the day's hours with what is on them,
// and beside them the open tasks that are not. Dragging a task onto an hour
// writes SCHEDULED: <2026-10-12 Mon 10:00-11:00> on it (POST /plan/block);
// dragging a block moves it, its bottom edge resizes it, and dragging it back
// onto the list takes it off the day.
//
// Every change is drawn at once (planner.ts's placeLocally/unplanLocally) and
// written behind it, one write at a time in the order they were made, so a
// quick run of moves lands in that order. A refused write puts the day back
// as it was before that change and says why; after the last write the day is
// asked for again, because the server is the truth (a new hash, a stamp it
// spelled its own way, another client's edit).

const PX_PER_MIN = 1;            // an hour is 60px, as in the week view
const GRID_HEIGHT = DAY_MINS * PX_PER_MIN;
const VIEWPORT_HEIGHT = 660;
const MOBILE_GRID_HEIGHT = 'max(320px, calc(100dvh - 230px))';
const TIME_COL = 52;

// What the planner remembers between visits, per browser: the working day,
// the list's query, whether the list is open.
type Prefs = { start: number; end: number; query: string; list: boolean };
const PREFS_KEY = 'worg.planner';

function loadPrefs(): Prefs {
    const def: Prefs = { start: 9 * 60, end: 17 * 60, query: DEFAULT_QUERY, list: true };
    try {
        const raw = window.localStorage.getItem(PREFS_KEY);
        if (!raw) return def;
        const p = JSON.parse(raw);
        return {
            start: typeof p.start === 'number' ? p.start : def.start,
            end: typeof p.end === 'number' ? p.end : def.end,
            query: typeof p.query === 'string' ? p.query : def.query,
            list: typeof p.list === 'boolean' ? p.list : def.list,
        };
    } catch (e) {
        return def;
    }
}

function savePrefs(p: Prefs) {
    try { window.localStorage.setItem(PREFS_KEY, JSON.stringify(p)); } catch (e) { /* private mode */ }
}

// A pointer drag of a block: moving it, or its bottom edge.
type Drag = {
    kind: 'move' | 'resize';
    hash: string;
    pointerId: number;
    startY: number;
    grabMin: number;       // the minute under the pointer when it went down
    origStart: number;
    origEnd: number;
    start: number;
    end: number;
    moved: boolean;
    overList: boolean;
};

export type DayPlannerItem = { Hash: string; Headline: string; Status: string; Filename: string; LineNum: number; Tags: string[]; Start?: string; End?: string };

export type DayPlannerProps = {
    viewDate: Date;
    // All day things the planner does not know about (birthdays, from the
    // records), drawn in the all day strip.
    extraAllDay?: { key: string; label: string; onClick?: () => void }[];
    onOpen: (item: DayPlannerItem) => void;
};

export default function DayPlanner({ viewDate, extraAllDay = [], onOpen }: DayPlannerProps) {
    const isMobile = useIsMobile();
    const date = ymd(viewDate);
    const [prefs, setPrefsState] = React.useState<Prefs>(loadPrefs);
    const setPrefs = React.useCallback((p: Partial<Prefs>) => {
        setPrefsState(old => { const n = { ...old, ...p }; savePrefs(n); return n; });
    }, []);
    const [day, setDay] = React.useState<PlanDay | null>(null);
    const dayRef = React.useRef<PlanDay | null>(null);
    dayRef.current = day;
    const [loading, setLoading] = React.useState(false);
    const [error, setError] = React.useState<string>('');
    const [notice, setNotice] = React.useState<string>('');
    const [saved, setSaved] = React.useState<{ name: string; query: string }[]>([]);
    const [armed, setArmed] = React.useState<string | null>(null);
    const [dragTask, setDragTask] = React.useState<PlanTask | null>(null);
    const [ghost, setGhost] = React.useState<{ start: number; end: number } | null>(null);
    const [drag, setDrag] = React.useState<Drag | null>(null);
    const dragRef = React.useRef<Drag | null>(null);
    dragRef.current = drag;
    const [now, setNow] = React.useState(new Date());

    const scrollRef = React.useRef<HTMLDivElement>(null);
    const contentRef = React.useRef<HTMLDivElement>(null);
    const listRef = React.useRef<HTMLDivElement>(null);
    const filterRef = React.useRef<HTMLInputElement>(null);
    const blockRefs = React.useRef<Record<string, HTMLDivElement | null>>({});
    const pending = React.useRef(0);
    const queue = React.useRef<Promise<void>>(Promise.resolve());
    const fetchSeq = React.useRef(0);

    const dayStart = clock(prefs.start), dayEnd = clock(prefs.end);

    // ── Reading the day ──

    const refresh = React.useCallback(async () => {
        const seq = ++fetchSeq.current;
        setLoading(true);
        try {
            const d = await getPlanDay(date, { query: prefs.query, dayStart, dayEnd });
            // A write started while this was in flight makes it stale.
            if (seq === fetchSeq.current && pending.current === 0) {
                setDay(d);
                setError('');
            }
        } catch (e: any) {
            if (seq === fetchSeq.current) setError(e?.message || String(e));
        } finally {
            if (seq === fetchSeq.current) setLoading(false);
        }
    }, [date, prefs.query, dayStart, dayEnd]);

    React.useEffect(() => { setArmed(null); refresh(); }, [refresh]);

    React.useEffect(() => {
        const t = setInterval(() => {
            setNow(new Date());
            if (pending.current === 0 && !dragRef.current) refresh();
        }, 30000);
        return () => clearInterval(t);
    }, [refresh]);

    React.useEffect(() => {
        let cancelled = false;
        ODb.getStoredQueries().then(q => { if (!cancelled && Array.isArray(q)) setSaved(q); }).catch(() => { /* none */ });
        return () => { cancelled = true; };
    }, []);

    // Open on the working day, or on now when now is later in it.
    React.useEffect(() => {
        if (!scrollRef.current) return;
        const n = new Date();
        let top = prefs.start - 30;
        if (ymd(n) === date) top = Math.max(top, n.getHours() * 60 + n.getMinutes() - 120);
        scrollRef.current.scrollTop = Math.max(0, top) * PX_PER_MIN;
        // Only when the day changes: not every time the hours are adjusted.
        // eslint-disable-next-line
    }, [date]);

    // ── Writing ──

    const write = React.useCallback((change: (d: PlanDay) => PlanDay, send: () => Promise<unknown>, what: string) => {
        const before = dayRef.current;
        if (!before) return;
        setDay(change(before));
        setNotice('');
        pending.current++;
        fetchSeq.current++; // a read already on its way would undo this
        queue.current = queue.current.then(async () => {
            try {
                await send();
            } catch (e: any) {
                setDay(before);
                setError(`Could not ${what}: ${e?.message || e}`);
            } finally {
                pending.current--;
                if (pending.current === 0) refresh();
            }
        });
    }, [refresh]);

    const place = React.useCallback((hash: string, start: number, end: number) => {
        const d = dayRef.current;
        if (!d) return;
        const b = d.Blocks.find(x => x.Hash === hash && x.Movable);
        if (b && clockMins(b.Start) === start && clockMins(b.End) === end && !b.Implied) return;
        const title = b?.Headline ?? d.Tasks.find(t => t.Hash === hash)?.Headline ?? 'it';
        write(x => placeLocally(x, hash, start, end), () => planBlock(hash, d.Date, clock(start), clock(end)), `place ${title}`);
        setArmed(null);
    }, [write]);

    const unplan = React.useCallback((hash: string) => {
        const d = dayRef.current;
        const b = d?.Blocks.find(x => x.Hash === hash && x.Movable);
        if (!d || !b) return;
        write(x => unplanLocally(x, hash), () => planUnblock(hash), `take ${b.Headline} off the day`);
        if (b.Repeater) setNotice(`${b.Headline} repeats (${b.Repeater}): it keeps its date, only the time came off.`);
    }, [write]);

    // The first free gap long enough, from now on today: where Enter puts a
    // task, and where the server would have put it.
    const placeNext = React.useCallback((t: PlanTask) => {
        const d = dayRef.current;
        if (!d) return;
        const len = taskLength(t.EffortMins, d.DefaultMins || 60);
        const spans = d.Blocks.filter(b => b.Hash !== t.Hash).map(spanOf);
        const at = freeSlot(spans, prefs.start, prefs.end, searchFrom(d, new Date(), prefs.start), len);
        if (at === null) {
            setError(`No free ${lengthText(len)} left in the working day for ${t.Headline}.`);
            return;
        }
        place(t.Hash, at, at + len);
    }, [place, prefs.start, prefs.end]);

    // ── Geometry ──

    const minuteAt = (clientY: number): number => {
        const r = contentRef.current?.getBoundingClientRect();
        if (!r) return 0;
        return Math.max(0, Math.min(DAY_MINS - 1, (clientY - r.top) / PX_PER_MIN));
    };

    const overList = (x: number, y: number): boolean => {
        const r = listRef.current?.getBoundingClientRect();
        return !!r && x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
    };

    // Scroll the grid while a drag is held near its top or bottom edge.
    const edgeScroll = (clientY: number) => {
        const s = scrollRef.current;
        if (!s) return;
        const r = s.getBoundingClientRect();
        if (clientY < r.top + 28) s.scrollTop -= 12;
        else if (clientY > r.bottom - 28) s.scrollTop += 12;
    };

    // ── A task dragged in from the list (HTML5 drag and drop) ──

    const taskLen = (t: PlanTask | null) => taskLength(t?.EffortMins ?? 0, day?.DefaultMins || 60);

    const onGridDragOver = (e: React.DragEvent) => {
        if (!dragTask) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        edgeScroll(e.clientY);
        const len = taskLen(dragTask);
        const { start, end } = clampBlock(Math.floor(minuteAt(e.clientY) / SNAP) * SNAP, len);
        setGhost(g => (g && g.start === start && g.end === end) ? g : { start, end });
    };

    const onGridDrop = (e: React.DragEvent) => {
        const hash = e.dataTransfer.getData('application/x-orgs-plan') || dragTask?.Hash;
        e.preventDefault();
        const g = ghost;
        setGhost(null);
        setDragTask(null);
        if (hash && g) place(hash, g.start, g.end);
    };

    // A click on an empty hour with a task picked in the list puts it there:
    // the phone's way in, where a list item cannot be dragged.
    const onGridClick = (e: React.MouseEvent) => {
        // Only on the grid itself: a click on a block opens the block.
        if (!armed || e.target !== e.currentTarget) return;
        const t = day?.Tasks.find(x => x.Hash === armed);
        const len = taskLen(t ?? null);
        const { start, end } = clampBlock(Math.floor(minuteAt(e.clientY) / SNAP) * SNAP, len);
        place(armed, start, end);
    };

    const onGridMouseMove = (e: React.MouseEvent) => {
        if (!armed || dragTask || drag) return;
        const t = day?.Tasks.find(x => x.Hash === armed);
        const { start, end } = clampBlock(Math.floor(minuteAt(e.clientY) / SNAP) * SNAP, taskLen(t ?? null));
        setGhost(g => (g && g.start === start && g.end === end) ? g : { start, end });
    };

    // ── A block dragged with the pointer ──

    const beginDrag = (e: React.PointerEvent, b: PlanBlock, kind: 'move' | 'resize') => {
        if (e.button !== 0 || b.Pending) return;
        e.stopPropagation();
        const s = clockMins(b.Start), en = clockMins(b.End);
        (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
        setDrag({
            kind, hash: b.Hash, pointerId: e.pointerId, startY: e.clientY, grabMin: minuteAt(e.clientY),
            origStart: s, origEnd: en, start: s, end: en, moved: false, overList: false,
        });
    };

    const moveDrag = (e: React.PointerEvent) => {
        const d = dragRef.current;
        if (!d || e.pointerId !== d.pointerId) return;
        const moved = d.moved || Math.abs(e.clientY - d.startY) > 4;
        if (!moved) return;
        edgeScroll(e.clientY);
        const delta = minuteAt(e.clientY) - d.grabMin;
        let start = d.origStart, end = d.origEnd;
        if (d.kind === 'move') {
            const c = clampBlock(snap(d.origStart + delta), d.origEnd - d.origStart);
            start = c.start; end = c.end;
        } else {
            end = Math.min(DAY_MINS - 1, Math.max(d.origStart + SNAP, snap(d.origEnd + delta)));
        }
        const ol = d.kind === 'move' && overList(e.clientX, e.clientY);
        if (start !== d.start || end !== d.end || ol !== d.overList || !d.moved) {
            setDrag({ ...d, start, end, moved: true, overList: ol });
        }
    };

    const endDrag = (e: React.PointerEvent, b: PlanBlock) => {
        const d = dragRef.current;
        if (!d || e.pointerId !== d.pointerId) return;
        setDrag(null);
        if (!d.moved) {
            if (d.kind === 'move') onOpen(itemOf(b));
            return;
        }
        if (d.overList) unplan(d.hash);
        else place(d.hash, d.start, d.end);
    };

    // ── The keyboard ──

    // On a block: arrows move it a quarter hour, shift+arrows move its end,
    // Delete takes it off, Enter opens it.
    const onBlockKey = (e: React.KeyboardEvent, b: PlanBlock) => {
        const s = clockMins(b.Start), en = clockMins(b.End);
        if (e.key === 'Enter') { e.preventDefault(); onOpen(itemOf(b)); return; }
        if (!b.Movable) return;
        if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
            e.preventDefault();
            e.stopPropagation();
            const step = e.key === 'ArrowUp' ? -SNAP : SNAP;
            if (e.shiftKey) place(b.Hash, s, Math.min(DAY_MINS - 1, Math.max(s + SNAP, en + step)));
            else { const c = clampBlock(s + step, en - s); place(b.Hash, c.start, c.end); }
            // Keep the focus on the block as it moves.
            setTimeout(() => blockRefs.current[b.Hash]?.focus(), 0);
        } else if (e.key === 'Delete' || e.key === 'Backspace') {
            e.preventDefault();
            unplan(b.Hash);
        }
    };

    React.useEffect(() => {
        const h = (e: KeyboardEvent) => {
            const el = e.target as HTMLElement;
            const typing = el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || el?.isContentEditable;
            if (e.key === 'Escape') { setArmed(null); setGhost(null); setDrag(null); return; }
            if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
            if (e.key === '/') {
                e.preventDefault();
                if (!prefs.list) setPrefs({ list: true });
                setTimeout(() => filterRef.current?.focus(), 0);
            } else if (e.key === 'p') {
                setPrefs({ list: !prefs.list });
            }
        };
        window.addEventListener('keydown', h);
        return () => window.removeEventListener('keydown', h);
    }, [prefs.list, setPrefs]);

    React.useEffect(() => {
        const t = setInterval(() => setNow(new Date()), 60000);
        return () => clearInterval(t);
    }, []);

    // The hover preview of a picked task would outlive the pick otherwise.
    React.useEffect(() => { if (!armed && !dragTask) setGhost(null); }, [armed, dragTask]);

    // ── Drawing ──

    // The blocks as drawn: the one being dragged at where it would land.
    const shown: PlanBlock[] = React.useMemo(() => {
        if (!day) return [];
        if (!drag || !drag.moved) return day.Blocks;
        return day.Blocks.map(b => b.Hash === drag.hash && b.Movable
            ? { ...b, Start: clock(drag.start), End: clock(drag.end), Mins: drag.end - drag.start }
            : b);
    }, [day, drag]);
    const spans = shown.map(spanOf);
    const lanes = layoutLanes(spans);
    const overlapping = new Set<number>();
    spans.forEach((a, i) => spans.forEach((b, j) => {
        if (i !== j && a.end > a.start && b.end > b.start && a.start < b.end && b.start < a.end) overlapping.add(i);
    }));

    const load = day?.Load;
    const isToday = date === ymd(now);
    const nowMin = now.getHours() * 60 + now.getMinutes();
    const armedTask = armed ? day?.Tasks.find(t => t.Hash === armed) : undefined;
    const hourOptions = Array.from({ length: 25 }, (_, h) => h);

    const header = (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
            {load && <LoadBar load={load} />}
            <Box sx={{ flex: 1 }} />
            {loading && <CircularProgress size="sm" sx={{ '--CircularProgress-size': '16px' }} />}
            <Tooltip title="The working day: what free and planned are counted in" size="sm">
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <Select size="sm" value={Math.floor(prefs.start / 60)} variant="plain"
                        onChange={(_, v) => { if (v !== null && v * 60 < prefs.end) setPrefs({ start: v * 60 }); }}
                        sx={{ minWidth: 0, fontSize: '12px' }}>
                        {hourOptions.slice(0, 24).map(h => <Option key={h} value={h}>{clock(h * 60)}</Option>)}
                    </Select>
                    <Typography level="body-xs">–</Typography>
                    <Select size="sm" value={Math.floor(prefs.end / 60)} variant="plain"
                        onChange={(_, v) => { if (v !== null && v * 60 > prefs.start) setPrefs({ end: v * 60 }); }}
                        sx={{ minWidth: 0, fontSize: '12px' }}>
                        {hourOptions.slice(1).map(h => <Option key={h} value={h}>{clock(h * 60)}</Option>)}
                    </Select>
                </Box>
            </Tooltip>
            <Tooltip title={prefs.list ? 'Hide the tasks to place (p)' : 'Show the tasks to place (p)'} size="sm">
                <IconButton size="sm" variant={prefs.list ? 'soft' : 'outlined'} onClick={() => setPrefs({ list: !prefs.list })}>
                    <ViewSidebarIcon sx={{ fontSize: 18, transform: 'scaleX(-1)' }} />
                </IconButton>
            </Tooltip>
        </Box>
    );

    const allDay = (
        (day && day.AllDay.length > 0) || extraAllDay.length > 0 ? (
            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                {extraAllDay.map(x => (
                    <AllDayChip key={x.key} onClick={x.onClick} icon={<CakeIcon sx={{ fontSize: 13 }} />} label={x.label} tone="#8e24aa" />
                ))}
                {day?.AllDay.map(b => (
                    <AllDayChip key={`${b.Hash}-${b.Kind}`} onClick={() => onOpen(itemOf(b))}
                        icon={b.Kind === 'deadline' ? <FlagIcon sx={{ fontSize: 13 }} /> : undefined}
                        label={b.Headline + (b.Kind === 'deadline' ? deadlineNote(b) : '')}
                        tone={b.Kind === 'deadline' ? '#d32f2f' : '#57b986'} done={b.Done} />
                ))}
            </Box>
        ) : null
    );

    const grid = (
        <Sheet ref={scrollRef} variant="outlined" sx={{
            width: '100%', height: isMobile ? MOBILE_GRID_HEIGHT : VIEWPORT_HEIGHT, borderRadius: 'sm',
            overflowY: 'auto', overflowX: 'hidden', position: 'relative',
        }}>
            <Box sx={{ display: 'flex', height: GRID_HEIGHT, position: 'relative' }}>
                <Box sx={{ width: TIME_COL, flexShrink: 0, borderRight: '1px solid', borderColor: 'divider', position: 'relative' }}>
                    {Array.from({ length: 24 }, (_, h) => (
                        <Typography key={h} level="body-xs" sx={{
                            position: 'absolute', top: h * 60 * PX_PER_MIN, right: 6, transform: h === 0 ? 'none' : 'translateY(-50%)',
                            fontSize: '10px', color: 'text.tertiary', fontWeight: h * 60 >= prefs.start && h * 60 < prefs.end ? 600 : 400,
                        }}>{clock(h * 60)}</Typography>
                    ))}
                </Box>
                <Box ref={contentRef}
                    onDragOver={onGridDragOver} onDrop={onGridDrop}
                    onDragLeave={e => { if (e.currentTarget === e.target) setGhost(null); }}
                    onClick={onGridClick} onMouseMove={onGridMouseMove} onMouseLeave={() => { if (!dragTask) setGhost(null); }}
                    sx={{ flex: 1, position: 'relative', cursor: armed ? 'copy' : 'default' }}>
                    {/* Outside the working day, shaded. */}
                    <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, height: prefs.start * PX_PER_MIN, backgroundColor: 'background.level1', opacity: 0.55, pointerEvents: 'none' }} />
                    <Box sx={{ position: 'absolute', top: prefs.end * PX_PER_MIN, left: 0, right: 0, bottom: 0, backgroundColor: 'background.level1', opacity: 0.55, pointerEvents: 'none' }} />
                    {Array.from({ length: 48 }, (_, i) => (
                        <Box key={i} sx={{
                            position: 'absolute', top: i * 30 * PX_PER_MIN, left: 0, right: 0, height: 0,
                            borderTop: i % 2 === 0 ? '1px solid' : '1px dotted', borderColor: 'divider', opacity: i % 2 === 0 ? 0.8 : 0.45,
                            pointerEvents: 'none',
                        }} />
                    ))}
                    {isToday && (
                        <>
                            <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, height: nowMin * PX_PER_MIN, background: 'repeating-linear-gradient(135deg, transparent 0 6px, rgba(127,127,127,0.06) 6px 12px)', pointerEvents: 'none' }} />
                            <Box sx={{ position: 'absolute', top: nowMin * PX_PER_MIN, left: 0, right: 0, borderTop: '2px solid #e53935', zIndex: 6, pointerEvents: 'none' }}>
                                <Box sx={{ position: 'absolute', left: -5, top: -6, width: 10, height: 10, borderRadius: '50%', backgroundColor: '#e53935' }} />
                            </Box>
                        </>
                    )}
                    {shown.map((b, i) => {
                        const sp = spans[i];
                        if (b.Kind === 'deadline' || sp.end <= sp.start) {
                            return (
                                <Box key={`${b.Hash}-${b.Kind}-${i}`} onClick={() => onOpen(itemOf(b))} title={`Deadline ${b.Start}: ${b.Headline}`}
                                    sx={{ position: 'absolute', top: sp.start * PX_PER_MIN - 1, left: 0, right: 0, borderTop: '2px dashed', borderColor: 'danger.500', zIndex: 4, cursor: 'pointer' }}>
                                    <Typography level="body-xs" sx={{ position: 'absolute', right: 4, top: -16, fontSize: '10px', color: 'danger.plainColor', fontWeight: 600, backgroundColor: 'background.surface', px: 0.5, borderRadius: 4 }}>
                                        <FlagIcon sx={{ fontSize: 11, verticalAlign: '-1px', mr: 0.25 }} />{b.Start} {b.Headline}
                                    </Typography>
                                </Box>
                            );
                        }
                        const lane = lanes[i];
                        const width = 100 / lane.lanes;
                        const height = Math.max(18, (sp.end - sp.start) * PX_PER_MIN - 2);
                        const dragging = drag?.hash === b.Hash && drag.moved && b.Movable;
                        const clash = overlapping.has(i);
                        return (
                            <BlockBox key={b.Movable ? `${b.Hash}-${b.Kind}` : `${b.Hash}-${b.Kind}-${b.Start}`} b={b} clash={clash} dragging={!!dragging}
                                leaving={!!dragging && !!drag?.overList}
                                refFn={el => { blockRefs.current[b.Hash] = el; }}
                                sx={{ top: sp.start * PX_PER_MIN + 1, height, left: `calc(${lane.lane * width}% + 2px)`, width: `calc(${width}% - 4px)` }}
                                onPointerDown={e => b.Movable ? beginDrag(e, b, 'move') : undefined}
                                onPointerMove={moveDrag}
                                onPointerUp={e => endDrag(e, b)}
                                onPointerCancel={() => setDrag(null)}
                                onResizeDown={e => beginDrag(e, b, 'resize')}
                                onClickFixed={() => onOpen(itemOf(b))}
                                onUnplan={() => unplan(b.Hash)}
                                onKeyDown={e => onBlockKey(e, b)} />
                        );
                    })}
                    {ghost && (dragTask || armed) && (
                        <Box sx={{
                            position: 'absolute', top: ghost.start * PX_PER_MIN + 1, height: (ghost.end - ghost.start) * PX_PER_MIN - 2,
                            left: 2, right: 2, borderRadius: '6px', border: '2px dashed', borderColor: 'primary.400',
                            backgroundColor: 'primary.softBg', opacity: 0.85, zIndex: 7, pointerEvents: 'none', px: 1, py: 0.25,
                        }}>
                            <Typography level="body-xs" sx={{ fontSize: '11px', fontWeight: 600, color: 'primary.plainColor' }}>
                                {clock(ghost.start)}–{clock(ghost.end)} · {(dragTask ?? armedTask)?.Headline}
                            </Typography>
                        </Box>
                    )}
                </Box>
            </Box>
        </Sheet>
    );

    const list = day && prefs.list ? (
        <PlannerList ref={listRef} tasks={day.Tasks} defaultMins={day.DefaultMins || 60} query={prefs.query}
            savedQueries={saved} onQuery={q => setPrefs({ query: q })} armed={armed} onArm={setArmed}
            onPlaceNext={placeNext} onDragTask={t => { setDragTask(t); if (!t) setGhost(null); }}
            onOpen={t => onOpen(t)} dropping={!!drag?.overList}
            backlogMins={day.Load.BacklogMins} backlogNoEst={day.Load.BacklogNoEst} filterRef={filterRef} />
    ) : null;

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, flex: 1, minWidth: 0 }}>
            {header}
            {error && (
                <Alert size="sm" color="danger" variant="soft" endDecorator={
                    <IconButton size="sm" variant="plain" color="danger" onClick={() => setError('')}><CloseIcon sx={{ fontSize: 16 }} /></IconButton>
                }>{error}</Alert>
            )}
            {notice && (
                <Alert size="sm" color="neutral" variant="soft" endDecorator={
                    <IconButton size="sm" variant="plain" onClick={() => setNotice('')}><CloseIcon sx={{ fontSize: 16 }} /></IconButton>
                }>{notice}</Alert>
            )}
            {armedTask && (
                <Typography level="body-xs" sx={{ color: 'primary.plainColor' }}>
                    Click an hour to put <b>{armedTask.Headline}</b> there ({lengthText(taskLen(armedTask))}) · Enter for the first free slot · Esc to cancel
                </Typography>
            )}
            {allDay}
            <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: 1.5, minWidth: 0 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>{grid}</Box>
                {list && (
                    <Box sx={{ width: isMobile ? '100%' : 300, flexShrink: 0, display: 'flex', height: isMobile ? 360 : VIEWPORT_HEIGHT }}>
                        <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>{list}</Box>
                    </Box>
                )}
            </Box>
        </Box>
    );
}

function itemOf(x: PlanBlock | PlanTask): DayPlannerItem {
    const b = x as PlanBlock;
    return { Hash: x.Hash, Headline: x.Headline, Status: x.Status, Filename: x.Filename, LineNum: x.LineNum, Tags: x.Tags, Start: b.Start, End: b.End };
}

function deadlineNote(b: PlanBlock): string {
    if (b.Late > 0) return ` · ${b.Late}d overdue`;
    if (b.DueIn > 0) return ` · due in ${b.DueIn}d`;
    return ' · due';
}

// How full the working day is: one bar, planned against free, with what is
// double-booked and what is still waiting said beside it.
function LoadBar({ load }: { load: PlanDay['Load'] }) {
    const w = Math.max(1, load.WindowMins);
    const planned = Math.min(100, (load.PlannedMins / w) * 100);
    const over = load.PlannedMins + load.BacklogMins > load.WindowMins;
    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
            <Box sx={{ width: 140, height: 8, borderRadius: 4, backgroundColor: 'background.level2', overflow: 'hidden', position: 'relative' }}
                title={`${lengthText(load.PlannedMins)} planned of ${lengthText(load.WindowMins)}`}>
                <Box sx={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: `${planned}%`, backgroundColor: planned >= 100 ? 'warning.500' : 'primary.500' }} />
            </Box>
            <Typography level="body-xs" sx={{ fontWeight: 600 }}>
                {lengthText(load.PlannedMins)} planned
                <Typography component="span" sx={{ color: 'text.tertiary', fontWeight: 400 }}> of {lengthText(load.WindowMins)} · </Typography>
                <Typography component="span" sx={{ color: load.FreeMins > 0 ? 'success.plainColor' : 'warning.plainColor' }}>{lengthText(load.FreeMins)} free</Typography>
            </Typography>
            {load.DoubleMins > 0 && (
                <Typography level="body-xs" sx={{ color: 'danger.plainColor', fontWeight: 600 }}>
                    <WarningAmberIcon sx={{ fontSize: 13, verticalAlign: '-2px', mr: 0.25 }} />{lengthText(load.DoubleMins)} double-booked
                </Typography>
            )}
            {load.OutsideMins > 0 && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{lengthText(load.OutsideMins)} outside hours</Typography>
            )}
            {load.BacklogMins > 0 && (
                <Typography level="body-xs" sx={{ color: over ? 'warning.plainColor' : 'text.tertiary' }}
                    title="The EFFORT of the tasks still to place">
                    {lengthText(load.BacklogMins)} waiting{over ? ' (more than is free)' : ''}
                </Typography>
            )}
        </Box>
    );
}

function AllDayChip({ label, icon, tone, done, onClick }: { label: string; icon?: React.ReactNode; tone: string; done?: boolean; onClick?: () => void }) {
    return (
        <Box onClick={onClick} sx={{
            display: 'flex', alignItems: 'center', gap: 0.5, borderLeft: `3px solid ${tone}`, backgroundColor: `${tone}18`,
            borderRadius: '4px', px: 1, py: 0.25, cursor: onClick ? 'pointer' : 'default', maxWidth: '100%',
            opacity: done ? 0.55 : 1, textDecoration: done ? 'line-through' : 'none',
        }}>
            {icon}
            <Typography level="body-xs" sx={{ fontSize: '11.5px', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{label}</Typography>
        </Box>
    );
}

type BlockBoxProps = {
    b: PlanBlock;
    clash: boolean;
    dragging: boolean;
    leaving: boolean;
    sx: object;
    refFn: (el: HTMLDivElement | null) => void;
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
    onPointerCancel: () => void;
    onResizeDown: (e: React.PointerEvent) => void;
    onClickFixed: () => void;
    onUnplan: () => void;
    onKeyDown: (e: React.KeyboardEvent) => void;
};

// One block on the grid. A movable one (a SCHEDULED of this day) is solid and
// can be dragged by its body and its bottom edge; an appointment or anything
// else fixed is drawn lighter and only opens.
function BlockBox({ b, clash, dragging, leaving, sx, refFn, onPointerDown, onPointerMove, onPointerUp, onPointerCancel,
    onResizeDown, onClickFixed, onUnplan, onKeyDown }: BlockBoxProps) {
    const tone = b.Movable ? 'var(--joy-palette-primary-500)' : 'var(--joy-palette-neutral-400)';
    const short = b.Mins < 40;
    return (
        <Box ref={refFn} tabIndex={0} role="button" onKeyDown={onKeyDown}
            aria-label={`${b.Headline}, ${b.Start} to ${b.End}${b.Movable ? '. Arrows move, shift+arrows resize, Delete unplans' : ''}`}
            onPointerDown={b.Movable ? onPointerDown : undefined}
            onPointerMove={b.Movable ? onPointerMove : undefined}
            onPointerUp={b.Movable ? onPointerUp : undefined}
            onPointerCancel={b.Movable ? onPointerCancel : undefined}
            onClick={b.Movable ? undefined : onClickFixed}
            sx={{
                position: 'absolute', boxSizing: 'border-box', borderRadius: '6px', px: 0.75, py: short ? 0 : 0.25,
                border: clash ? '1px solid var(--joy-palette-danger-400)' : '1px solid transparent',
                borderLeftWidth: 4, borderLeftStyle: 'solid', borderLeftColor: clash ? 'var(--joy-palette-danger-500)' : tone,
                backgroundColor: b.Movable ? 'primary.softBg' : 'background.level2',
                backgroundImage: b.Movable ? 'none' : 'repeating-linear-gradient(135deg, transparent 0 8px, rgba(127,127,127,0.07) 8px 16px)',
                overflow: 'hidden', zIndex: dragging ? 8 : 3, cursor: b.Movable ? (dragging ? 'grabbing' : 'grab') : 'pointer',
                opacity: leaving ? 0.35 : b.Pending ? 0.75 : b.Done ? 0.5 : 1,
                boxShadow: dragging ? 'md' : 'none', touchAction: b.Movable ? 'none' : 'auto', userSelect: 'none',
                transition: dragging ? 'none' : 'top 120ms, height 120ms',
                '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.500', outlineOffset: 1 },
                '&:hover .plan-x': { opacity: 1 },
                ...sx,
            }}>
            <Box sx={{ display: 'flex', alignItems: short ? 'center' : 'flex-start', gap: 0.5, height: short ? '100%' : 'auto' }}>
                <Typography level="body-xs" sx={{
                    fontSize: '12px', fontWeight: 600, lineHeight: 1.25, flex: 1, minWidth: 0,
                    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: short ? 'nowrap' : 'normal',
                    display: '-webkit-box', WebkitLineClamp: short ? 1 : Math.max(1, Math.floor((b.Mins - 18) / 16)), WebkitBoxOrient: 'vertical',
                    textDecoration: b.Done ? 'line-through' : 'none',
                }}>
                    {b.Status && <Typography component="span" sx={{ fontSize: '9.5px', fontWeight: 700, mr: 0.5, color: 'text.tertiary' }}>{b.Status}</Typography>}
                    {b.Headline}
                    {short && <Typography component="span" sx={{ fontSize: '10px', fontWeight: 400, ml: 0.75, color: 'text.tertiary' }}>{b.Start}</Typography>}
                </Typography>
                {clash && <WarningAmberIcon titleAccess="Overlaps another block" sx={{ fontSize: 14, color: 'danger.500', flexShrink: 0 }} />}
                {b.Repeater && <RepeatIcon titleAccess={`Repeats ${b.Repeater}`} sx={{ fontSize: 13, color: 'text.tertiary', flexShrink: 0 }} />}
                {b.Movable && (
                    <IconButton className="plan-x" size="sm" variant="plain" title="Take it off the day (Delete)"
                        onPointerDown={e => e.stopPropagation()}
                        onClick={e => { e.stopPropagation(); onUnplan(); }}
                        sx={{ opacity: 0, minWidth: 18, minHeight: 18, p: 0, '--IconButton-size': '18px' }}>
                        <CloseIcon sx={{ fontSize: 13 }} />
                    </IconButton>
                )}
            </Box>
            {!short && (
                <Typography level="body-xs" sx={{ fontSize: '10.5px', color: 'text.tertiary' }}>
                    {b.Start}–{b.End} · {lengthText(b.Mins)}{b.Implied ? ' (no end written)' : ''}{b.Kind === 'timestamp' ? ' · appointment' : ''}
                </Typography>
            )}
            {b.Movable && (
                <Box onPointerDown={e => { e.stopPropagation(); onResizeDown(e); }}
                    title="Drag to change how long"
                    sx={{
                        position: 'absolute', left: 0, right: 0, bottom: 0, height: 7, cursor: 'ns-resize', touchAction: 'none',
                        '&:hover': { backgroundColor: 'primary.300', opacity: 0.6 },
                    }} />
            )}
        </Box>
    );
}
