// The lock in the Files toolbar: there only while something is open - a
// passphrase held on the server, or text revealed on this screen - and one
// click closes all of it.

import * as React from 'react';
import Button from '@mui/joy/Button';
import Tooltip from '@mui/joy/Tooltip';
import LockOpenIcon from '@mui/icons-material/LockOpenOutlined';

import { useCryptState, lockNow, announceLock } from '../cryptApi';
import { shortLeft } from '../crypt';

export default function CryptLockChip({ revealed }: { revealed: number }) {
    const st = useCryptState(true);
    const held = st !== null && st.Unlocked;
    if (!held && revealed <= 0) return null;
    const label = held ? `Unlocked · ${shortLeft(st!.UnlockIn)}` : 'Revealed';
    const tip = held
        ? 'The server is holding a passphrase. Lock now: forget it, and hide everything revealed here.'
        : 'Hide everything revealed on this screen';
    return (
        <Tooltip size="sm" title={tip}>
            <Button
                size="sm"
                variant="soft"
                color="warning"
                startDecorator={<LockOpenIcon />}
                onClick={() => { if (held) lockNow(); else announceLock(); }}
                sx={{ whiteSpace: 'nowrap' }}
            >
                {label}
            </Button>
        </Tooltip>
    );
}
