// Encrypted headings in the Files tab's rendered view.
//
// That view is an iframe holding the exporter's whole page, which React does
// not draw into, so this is the same locked placeholder as CryptReveal.tsx
// done in plain DOM with inline styles (the app's own styles do not reach into
// the frame; the page's theme does, which is what the revealed text wants).
//
// The ciphertext never reaches the frame: Files.tsx swaps every armoured block
// in the html for a placeholder (`replaceArmorHtml`) before it is handed to
// srcDoc. Revealed html is written into the placeholder and the placeholder's
// own markup put back on hide, so hiding leaves nothing behind in the DOM.

import { CryptLines, PLACEHOLDER_CLASS } from './crypt';

const LOCKED_STYLE = [
    'margin:.7em 0', 'padding:.55em .9em', 'border:1px dashed rgba(128,128,128,.55)',
    'border-radius:6px', 'cursor:pointer', 'user-select:none',
    'font:14px/1.4 system-ui,-apple-system,"Segoe UI",sans-serif',
    'background:rgba(128,128,128,.08)',
].join(';');

const OPEN_STYLE = [
    'margin:.7em 0', 'padding:.35em .9em .5em', 'border-left:3px solid #d99a2b',
    'border-radius:4px', 'background:rgba(217,154,43,.06)',
].join(';');

const BAR_STYLE = 'display:flex;align-items:center;gap:.6em;font:12px/1.4 system-ui,-apple-system,sans-serif;opacity:.8;margin-bottom:.3em';
const BUTTON_STYLE = 'font:12px system-ui,sans-serif;padding:.15em .7em;border-radius:5px;border:1px solid rgba(128,128,128,.5);background:transparent;color:inherit;cursor:pointer';

function lockedInner(busy: boolean = false): string {
    return '<span aria-hidden="true">🔒</span> <b>Encrypted</b> '
        + `<span style="opacity:.65">— ${busy ? 'opening…' : 'click to reveal'}</span>`;
}

// What stands where an armoured block was, before the page is in the frame.
export function placeholderHtml(n: number): string {
    return `<div class="${PLACEHOLDER_CLASS}" data-crypt-n="${n}" role="button" tabindex="0" `
        + `title="Encrypted — click to reveal" style="${LOCKED_STYLE}">${lockedInner()}</div>`;
}

export function frameBlocks(doc: Document): HTMLElement[] {
    return Array.from(doc.querySelectorAll<HTMLElement>('.' + PLACEHOLDER_CLASS));
}

export function isRevealed(el: HTMLElement): boolean {
    return el.dataset.cryptOpen === '1';
}

export function setBusy(el: HTMLElement, busy: boolean) {
    if (!isRevealed(el)) el.innerHTML = lockedInner(busy);
}

// Put the locked placeholder back, dropping whatever was revealed.
export function relockBlock(el: HTMLElement) {
    el.dataset.cryptOpen = '';
    el.setAttribute('style', LOCKED_STYLE);
    el.setAttribute('role', 'button');
    el.setAttribute('tabindex', '0');
    el.title = 'Encrypted — click to reveal';
    el.innerHTML = lockedInner();
}

// Show revealed html in a placeholder, with a Hide button marked so the
// frame's click handler can tell it from a click to reveal.
export function revealBlock(el: HTMLElement, html: string) {
    el.dataset.cryptOpen = '1';
    el.setAttribute('style', OPEN_STYLE);
    el.removeAttribute('role');
    el.removeAttribute('tabindex');
    el.title = '';
    el.innerHTML = `<div style="${BAR_STYLE}"><span aria-hidden="true">🔓</span><span style="flex:1">Revealed — only on this screen</span>`
        + `<button type="button" data-crypt-hide="1" style="${BUTTON_STYLE}">Hide</button></div>`
        + `<div class="orgs-crypt-body">${html}</div>`;
}

export function escapeHtml(s: string): string {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function norm(s: string): string {
    return s.replace(/\s+/g, ' ').trim().toLowerCase();
}

// The heading text above an element: the nearest h1..h6 before it in the page.
function headingAbove(doc: Document, el: HTMLElement): string {
    const heads = Array.from(doc.querySelectorAll('h1,h2,h3,h4,h5,h6'));
    let best = '';
    for (const h of heads) {
        // DOCUMENT_POSITION_FOLLOWING: el comes after h.
        if (h.compareDocumentPosition(el) & 4) best = h.textContent || '';
        else break;
    }
    return norm(best);
}

// Which encrypted heading each placeholder is. The blocks and the encrypted
// headings are both in document order, so when the counts agree that is the
// answer; when they do not (the exporter left a heading out, say), each block
// goes to the encrypted heading whose title the heading above it shows, and a
// block nothing matches is left unclaimed rather than guessed.
export function matchBlocks(doc: Document, els: HTMLElement[], encrypted: CryptLines[]): (CryptLines | null)[] {
    if (els.length === encrypted.length) return encrypted.slice();
    const used = new Set<number>();
    return els.map(el => {
        const above = headingAbove(doc, el);
        for (let i = 0; i < encrypted.length; i++) {
            if (used.has(i)) continue;
            const t = norm(encrypted[i].title);
            if (t !== '' && above.indexOf(t) >= 0) { used.add(i); return encrypted[i]; }
        }
        return null;
    });
}
