// Structural refactors: what the Refactor tab and the palette know about
// them, kept out of the component so it can be tested.
//
// The four operations are worked out on the server (internal/app/orgs/
// refactor.go): a preview that answers with each file's before and after
// text, and an apply that refuses unless the files still come to that same
// change. This file is the client's half of that conversation - the request
// shapes, the token an apply carries, and the small amount of picking and
// naming the page does before it asks.

import { fuzzyScore, fuzzyScoreAll, fuzzyTerms } from './fuzzy';

export type RefactorOp = 'tag' | 'split' | 'merge' | 'list';

// The operations as the page and the palette name them. `hint` is what the
// palette matches on whole words, so it carries the other names people use.
export const REFACTOR_OPS: { op: RefactorOp; name: string; short: string; hint: string }[] = [
    { op: 'tag', name: 'Rename a tag', short: 'Rename tag', hint: 'rename merge or delete a tag across every file, filetags and #+TAGS' },
    { op: 'split', name: 'Split a heading to a file', short: 'Split to file', hint: 'move a heading and its subtree into a new org file, leaving a link behind; extract' },
    { op: 'merge', name: 'Merge two headings', short: 'Merge headings', hint: 'merge one heading into another: body, children, tags, properties; combine duplicate' },
    { op: 'list', name: 'Turn a list into headings', short: 'List to headings', hint: 'convert a plain or checkbox list into child headings, checkboxes become TODO and DONE' },
];

// ---------------------------------------------------------------------------
// The wire (internal/common/refactor.go)
// ---------------------------------------------------------------------------

export type RefactorApply = { Token?: string; Expect?: Record<string, string> };

export type TagRenameRequest = { Old: string; New: string; Delete?: boolean; Files?: string[]; Query?: string } & RefactorApply;
export type SplitRequest = { Hash: string; To?: string; NewId?: string } & RefactorApply;
export type MergeRequest = { Into: string; From: string } & RefactorApply;
export type ListToHeadingsRequest = { Hash: string; Line: number } & RefactorApply;
export type RefactorRequest = TagRenameRequest | SplitRequest | MergeRequest | ListToHeadingsRequest;

export type RefactorFile = {
    Filename: string;
    Created?: boolean;
    Before: string;
    After: string;
    Hash: string;
    Patch: string;
    Added: number;
    Removed: number;
};

export type RefactorMention = { Kind: string; Name: string; Text: string; User?: string };

export type RefactorPlan = {
    Ok: boolean;
    Msg: string;
    Op: string;
    Summary: string;
    Warnings?: string[];
    Mentions?: RefactorMention[];
    Files: RefactorFile[];
    Token: string;
    NewId?: string;
    NewFile?: string;
    Applied?: boolean;
    Stale?: boolean;
};

export type RefactorTag = { Tag: string; Headings: number; Files: number; Defined?: boolean };
export type RefactorList = { Line: number; End: number; Items: number; First: string; Checkboxes: number };

// A heading as /search answers it, the parts the pickers use.
export type HeadingRow = { Hash: string; Headline: string; Filename: string; LineNum?: number; Tags?: string[]; Status?: string; Level?: number };

// ---------------------------------------------------------------------------
// Apply: the preview's request again, with what proves it is the same change
// ---------------------------------------------------------------------------

// The request to apply what a preview showed: its token, the hash each file
// had when it was read (so a refusal can say which file moved), and for a
// split the id the preview made - without it the apply would make another,
// and no longer be the change that was shown.
export function applyRequest<T extends RefactorRequest>(req: T, plan: RefactorPlan): T {
    const Expect: Record<string, string> = {};
    for (const f of plan.Files) Expect[f.Filename] = f.Hash;
    const out: any = { ...req, Token: plan.Token, Expect };
    if (plan.NewId) out.NewId = plan.NewId;
    return out as T;
}

export function planTotals(plan: RefactorPlan | null): { files: number; added: number; removed: number; created: number } {
    const t = { files: 0, added: 0, removed: 0, created: 0 };
    for (const f of plan?.Files || []) {
        t.files++;
        t.added += f.Added;
        t.removed += f.Removed;
        if (f.Created) t.created++;
    }
    return t;
}

// ---------------------------------------------------------------------------
// Tags
// ---------------------------------------------------------------------------

// What the server takes as a tag: letters, digits, _ @ # %.
const TAG_RE = /^[\p{L}\p{N}_@#%]+$/u;

export function cleanTag(t: string): string {
    return t.trim().replace(/^:+|:+$/g, '');
}

export function tagError(t: string): string {
    const c = cleanTag(t);
    if (!c) return '';
    return TAG_RE.test(c) ? '' : 'A tag is letters, digits and _ @ # % - no spaces or colons';
}

// The tags that match what is typed, best first; with nothing typed, the
// most used first (the order the server sends).
export function rankTags(tags: RefactorTag[], filter: string): RefactorTag[] {
    const f = cleanTag(filter).toLowerCase();
    if (!f) return tags;
    const hits: { t: RefactorTag; s: number; i: number }[] = [];
    tags.forEach((t, i) => {
        const s = fuzzyScore(f, t.Tag);
        if (s !== null) hits.push({ t, s: s + Math.min(t.Headings + t.Files, 20) / 4, i });
    });
    hits.sort((a, b) => (b.s - a.s) || (a.i - b.i));
    return hits.map(h => h.t);
}

// What renaming old to nw will mean, in a sentence, or ''.
export function renameNote(old: string, nw: string, tags: RefactorTag[], del: boolean): string {
    const o = cleanTag(old), n = cleanTag(nw);
    const from = tags.find(t => t.Tag === o);
    if (!o) return '';
    if (!from) return `Nothing carries :${o}: yet.`;
    const where = usage(from);
    if (del) return `Takes :${o}: off ${where}.`;
    if (!n) return '';
    if (n === o) return 'That is the same name.';
    const into = tags.find(t => t.Tag === n);
    if (into) return `:${n}: is already in use (${usage(into)}): this merges :${o}: into it, without writing it twice where both are.`;
    return `Renames :${o}: on ${where}.`;
}

export function usage(t: RefactorTag): string {
    const bits: string[] = [];
    if (t.Headings) bits.push(`${t.Headings} heading${t.Headings === 1 ? '' : 's'}`);
    if (t.Files) bits.push(`${t.Files} file${t.Files === 1 ? '' : 's'}' FILETAGS`);
    if (!bits.length && t.Defined) bits.push('a #+TAGS line');
    return bits.join(' and ') || 'nothing';
}

// ---------------------------------------------------------------------------
// Headings
// ---------------------------------------------------------------------------

function escapeRe(s: string): string {
    return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// A loose query for what is typed: every term's letters in order, anywhere in
// the headline - so "aplo lnch" finds "Apollo launch". The server narrows; the
// page ranks what comes back (rankHeadings), the way the palette's fuzzy
// matcher would. Quotes are dropped rather than escaped: the query language's
// strings have no escape for them.
export function headingQuery(text: string): string {
    const terms = fuzzyTerms(text.replace(/['"]/g, ''));
    if (!terms.length) return '';
    return terms
        .map(t => `MatchHeadline('(?i)${Array.from(t).map(escapeRe).join('.*?')}')`)
        .join(' && ');
}

export function baseName(p: string): string {
    return (p || '').split('/').pop() || p;
}

export function rankHeadings(rows: HeadingRow[], text: string): HeadingRow[] {
    const terms = fuzzyTerms(text);
    if (!terms.length) return rows;
    const hits: { r: HeadingRow; s: number; i: number }[] = [];
    rows.forEach((r, i) => {
        const name = r.Headline || '';
        const s = fuzzyScoreAll(terms, name, `${name} ${baseName(r.Filename)}`);
        if (s !== null) hits.push({ r, s, i });
    });
    hits.sort((a, b) => (b.s - a.s) || (a.i - b.i));
    return hits.map(h => h.r);
}

// ---------------------------------------------------------------------------
// Split: where the new file goes
// ---------------------------------------------------------------------------

// A file name from a title, the way the server makes one when no name is
// given: "Apollo: launch plan" is apollo-launch-plan. Said again here only to
// show the name before asking; the server's is the one written.
export function slugOf(title: string): string {
    let s = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    if (s.length > 60) s = s.slice(0, 60).replace(/-+$/, '');
    return s || 'split';
}

// What to send as a split's To: the folder with a trailing slash (the server
// names the file for the heading), or folder/name.org.
export function splitTarget(folder: string, name: string): string {
    const dir = folder.replace(/\/+$/, '');
    const n = name.trim().replace(/^\/+/, '');
    if (!dir && !n) return '';
    if (!n) return dir + '/';
    const file = /\.org$/i.test(n) ? n : `${n}.org`;
    return dir ? `${dir}/${file}` : file;
}

export function splitNameError(name: string): string {
    const n = name.trim();
    if (!n) return '';
    if (/[\\:*?"<>|/]/.test(n)) return 'A file name has no / \\ : * ? " < > |';
    if (n.startsWith('.')) return 'A name starting with . would be hidden';
    return '';
}

// ---------------------------------------------------------------------------
// Coming in from the palette
// ---------------------------------------------------------------------------

const OP_KEY = 'worg.refactor.op';
export const REFACTOR_EVENT = 'worg:refactor-op';

// Ask the Refactor tab to open on one operation. Left in localStorage for a
// tab that is about to be mounted by the switch, and sent as an event for one
// that is already showing (the palette's switch to it does nothing then).
export function requestRefactorOp(op: RefactorOp) {
    try { localStorage.setItem(OP_KEY, op); } catch { /* private window: the event still goes */ }
    window.dispatchEvent(new CustomEvent(REFACTOR_EVENT, { detail: op }));
}

// The operation to open on, taken once.
export function takeRefactorOp(): RefactorOp | null {
    try {
        const v = localStorage.getItem(OP_KEY);
        localStorage.removeItem(OP_KEY);
        return REFACTOR_OPS.some(o => o.op === v) ? (v as RefactorOp) : null;
    } catch {
        return null;
    }
}
