// One EventSource on GET /events, with the fallback focusApi.ts worked out.
//
// EventSource cannot send an Authorization header, so the stream rests on the
// `orgstoken` cookie login sets; across origins that needs a credentialed
// request, and a server whose CORS will not allow one refuses it. So a stream
// that fails before it ever opened is tried once more without credentials
// (enough under noAuth), and after that the caller's poller carries it alone.
//
// focusApi.ts keeps its own copy of this (it came first); new live views use
// this one.

import { Sets } from './config';

export type StreamHandlers = {
    // Every event's parsed JSON. Malformed lines are dropped.
    onEvent: (e: any) => void;
    // Up or down, so the caller can poll faster while it is down.
    onLive?: (live: boolean) => void;
};

// Opens the stream and answers how to close it. Without EventSource at all it
// answers a no-op and never calls onLive(true): polling is the whole story.
export function openEventStream(kinds: string, h: StreamHandlers): () => void {
    if (typeof EventSource === 'undefined') return () => {};
    let es: EventSource | null = null;
    let credentialed = true;
    let everOpened = false;
    let closed = false;

    const connect = () => {
        if (closed) return;
        try {
            es = new EventSource(Sets.orgsConnection + '/events?kinds=' + encodeURIComponent(kinds),
                { withCredentials: credentialed });
        } catch {
            es = null;
            return;
        }
        const me = es;
        me.onopen = () => {
            everOpened = true;
            h.onLive?.(true);
        };
        me.onmessage = (m: MessageEvent) => {
            let e: any;
            try {
                e = JSON.parse(m.data);
            } catch {
                return;
            }
            h.onEvent(e);
        };
        me.onerror = () => {
            h.onLive?.(false);
            if (!everOpened && credentialed) {
                me.close();
                credentialed = false;
                connect();
            } else if (!everOpened) {
                me.close();
                es = null;
            }
            // Otherwise EventSource reconnects by itself.
        };
    };
    connect();
    return () => {
        closed = true;
        es?.close();
        es = null;
    };
}
