// The planner's requests: GET /plan/day, POST /plan/block, POST /plan/unblock
// (internal/app/orgs/planner.go). Each answer is checked for its Ok, because
// doGet/doPost hand back [] when the request itself failed, and a planner
// that took that for an empty day would draw one.

import { ODb } from './db';
import { Sets } from './config';
import { PlanDay, PlanWrite } from './planner';

function url(path: string): URL {
    return new URL(Sets.orgsConnection + path);
}

export async function getPlanDay(date: string, opts: { query?: string; dayStart?: string; dayEnd?: string } = {},
    signal: AbortSignal | null = null): Promise<PlanDay> {
    const u = url('/plan/day');
    u.searchParams.append('date', date);
    if (opts.query) u.searchParams.append('query', opts.query);
    if (opts.dayStart) u.searchParams.append('dayStart', opts.dayStart);
    if (opts.dayEnd) u.searchParams.append('dayEnd', opts.dayEnd);
    const res = await ODb.doGet<PlanDay>(u, signal);
    if (!res || Array.isArray(res) || typeof res !== 'object') throw new Error('the server did not answer');
    if (!res.Ok) throw new Error(res.Msg || 'the planner could not read the day');
    return res;
}

async function write(path: string, body: object): Promise<PlanWrite> {
    const res = await ODb.doPost<PlanWrite>(url(path), body);
    if (!res || Array.isArray(res) || typeof res !== 'object') throw new Error('the server did not answer');
    if (!res.Ok) throw new Error(res.Msg || 'the write was refused');
    return res;
}

// Put a heading at [start, end) on date, HH:MM each.
export function planBlock(hash: string, date: string, start: string, end: string): Promise<PlanWrite> {
    return write('/plan/block', { Hash: hash, Date: date, Start: start, End: end });
}

// Take a heading off the day: SCHEDULED goes, or only its time when it
// repeats or keepDate is set.
export function planUnblock(hash: string, keepDate = false): Promise<PlanWrite> {
    return write('/plan/unblock', { Hash: hash, KeepDate: keepDate });
}
