import * as React from 'react';
import Box from '@mui/joy/Box';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Textarea from '@mui/joy/Textarea';
import Button from '@mui/joy/Button';
import ButtonGroup from '@mui/joy/ButtonGroup';
import Chip from '@mui/joy/Chip';
import Sheet from '@mui/joy/Sheet';
import Divider from '@mui/joy/Divider';
import Tabs from '@mui/joy/Tabs';
import TabList from '@mui/joy/TabList';
import Tab from '@mui/joy/Tab';
import TabPanel from '@mui/joy/TabPanel';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import IconButton from '@mui/joy/IconButton';
import CircularProgress from '@mui/joy/CircularProgress';
import Autocomplete from '@mui/joy/Autocomplete';
import type { ColorPaletteProp } from '@mui/joy/styles';
import AddIcon from '@mui/icons-material/Add';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import EditIcon from '@mui/icons-material/Edit';
import CloseIcon from '@mui/icons-material/Close';
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import AutorenewRoundedIcon from '@mui/icons-material/AutorenewRounded';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import SkipNextRoundedIcon from '@mui/icons-material/SkipNextRounded';
import HourglassEmptyRoundedIcon from '@mui/icons-material/HourglassEmptyRounded';
import PauseRoundedIcon from '@mui/icons-material/PauseRounded';
import CancelRoundedIcon from '@mui/icons-material/CancelRounded';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import PhoneRoundedIcon from '@mui/icons-material/PhoneRounded';
import GroupsRoundedIcon from '@mui/icons-material/GroupsRounded';
import BlockIcon from '@mui/icons-material/Block';
import { ODb } from '../db';

// --- Status helpers (same as Search.tsx) ---

function getStatusIcon(status: string): React.ReactNode {
  switch (status) {
    case 'DONE': return <CheckRoundedIcon />;
    case 'IN-PROGRESS':
    case 'INPROGRESS': return <AutorenewRoundedIcon />;
    case 'TODO': return <RadioButtonUncheckedIcon />;
    case 'NEXT': return <SkipNextRoundedIcon />;
    case 'WAITING':
    case 'BLOCKED': return <HourglassEmptyRoundedIcon />;
    case 'HOLD':
    case 'PAUSED': return <PauseRoundedIcon />;
    case 'CANCELLED':
    case 'CANCELED': return <CancelRoundedIcon />;
    case 'STARTED': return <PlayArrowRoundedIcon />;
    case 'PHONE': return <PhoneRoundedIcon />;
    case 'MEETING': return <GroupsRoundedIcon />;
    default: return <BlockIcon />;
  }
}

function getStatusColor(status: string): ColorPaletteProp | undefined {
  switch (status) {
    case 'DONE': return 'success';
    case 'IN-PROGRESS':
    case 'INPROGRESS':
    case 'STARTED': return 'warning';
    case 'TODO': return 'danger';
    default: return 'neutral';
  }
}

function getStatusCustomSx(status: string): object | null {
  switch (status) {
    case 'HOLD':
    case 'PAUSED':
      return { bgcolor: 'rgba(155, 89, 182, 0.15)', color: 'rgb(125, 60, 152)' };
    case 'WAITING':
    case 'BLOCKED':
      return { bgcolor: 'rgba(243, 156, 18, 0.15)', color: 'rgb(211, 120, 0)' };
    case 'PHONE':
    case 'MEETING':
      return { bgcolor: 'rgba(63, 81, 181, 0.15)', color: 'rgb(48, 63, 159)' };
    case 'CANCELLED':
    case 'CANCELED':
      return { bgcolor: 'rgba(142, 68, 173, 0.12)', color: 'rgb(142, 68, 173)' };
    case 'BACKLOG':
      return { bgcolor: 'rgba(184, 148, 0, 0.12)', color: 'rgb(164, 128, 0)' };
    case 'NEXT':
      return { bgcolor: 'rgba(0, 188, 212, 0.12)', color: 'rgb(0, 151, 167)' };
    default:
      return null;
  }
}

// --- Props ---

interface OrgEditorBaseProps {
  open: boolean;
  onClose: () => void;
}

interface OrgEditorNodeProps extends OrgEditorBaseProps {
  mode: 'node';
  hash: string;
  initialData?: {
    Headline?: string;
    Status?: string;
    Tags?: string[] | null;
    Props?: Record<string, string>;
    Date?: { Start: string; End: string };
    Filename?: string;
  };
  onMutate?: (update: { hash: string; field: string; value: any }) => void;
}

interface OrgEditorFileProps extends OrgEditorBaseProps {
  mode: 'file';
  filename: string;
}

type OrgEditorProps = OrgEditorNodeProps | OrgEditorFileProps;

// --- Node Editor ---

function NodeEditor({ hash, initialData, onMutate }: {
  hash: string;
  initialData?: OrgEditorNodeProps['initialData'];
  onMutate?: OrgEditorNodeProps['onMutate'];
}) {
  const [headline, setHeadline] = React.useState(initialData?.Headline || '');
  const [savedHeadline, setSavedHeadline] = React.useState(initialData?.Headline || '');
  const [status, setStatus] = React.useState(initialData?.Status || '');
  const [tags, setTags] = React.useState<string[]>(initialData?.Tags || []);
  const [props, setProps] = React.useState<Record<string, string>>(initialData?.Props || {});
  const [bodyHtml, setBodyHtml] = React.useState('<p>Loading...</p>');
  const [bodyOrg, setBodyOrg] = React.useState('');
  const [savedBodyOrg, setSavedBodyOrg] = React.useState('');
  const [bodyMode, setBodyMode] = React.useState<'preview' | 'edit'>('preview');
  const [bodySaving, setBodySaving] = React.useState(false);
  const [validStatuses, setValidStatuses] = React.useState<string[]>([]);
  const [allTags, setAllTags] = React.useState<string[]>([]);
  const [showStatusPicker, setShowStatusPicker] = React.useState(false);
  const [showTagInput, setShowTagInput] = React.useState(false);
  const [loading, setLoading] = React.useState(true);

  // Date state
  const [dateValue, setDateValue] = React.useState('');
  const [timeValue, setTimeValue] = React.useState('');
  const [dateType, setDateType] = React.useState('TIMESTAMP');

  // New property state
  const [newPropName, setNewPropName] = React.useState('');
  const [newPropValue, setNewPropValue] = React.useState('');

  // Fetch data on mount
  React.useEffect(() => {
    let cancelled = false;
    const fetchData = async () => {
      try {
        const [htmlData, fullData, statusData, tagsData] = await Promise.all([
          ODb.todoHtml(hash),
          ODb.todoFull(hash),
          ODb.validStatus(hash),
          ODb.getAllTags(),
        ]);
        if (cancelled) return;
        if (htmlData) {
          setHeadline(htmlData.Headline || headline);
          setSavedHeadline(htmlData.Headline || headline);
          setBodyHtml(htmlData.Content || '<p>No content</p>');
          if (htmlData.Tags) setTags(htmlData.Tags);
          if (htmlData.Props) setProps(htmlData.Props);
        }
        if (fullData) {
          setBodyOrg(fullData.Content || '');
          setSavedBodyOrg(fullData.Content || '');
        }
        const combined = [...(statusData?.Active || []), ...(statusData?.Done || [])];
        setValidStatuses(combined);
        setAllTags(tagsData || []);
      } catch (e) {
        console.error('OrgEditor fetch error:', e);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    fetchData();
    return () => { cancelled = true; };
    // eslint-disable-next-line
  }, [hash]);

  // Init date from initialData
  React.useEffect(() => {
    if (initialData?.Date?.Start && !initialData.Date.Start.startsWith('0001-01-01')) {
      const d = new Date(initialData.Date.Start);
      setDateValue(d.toISOString().slice(0, 10));
      if (d.getHours() !== 0 || d.getMinutes() !== 0) {
        setTimeValue(`${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`);
      }
    }
  }, [initialData?.Date?.Start]);

  const handleHeadlineBlur = async () => {
    const trimmed = headline.trim();
    if (!trimmed || trimmed === savedHeadline) return;
    try {
      await ODb.renameHeadline(hash, trimmed);
      setSavedHeadline(trimmed);
      onMutate?.({ hash, field: 'headline', value: trimmed });
    } catch (e) { console.error('Rename failed:', e); }
  };

  const handleHeadlineKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      (e.target as HTMLElement).blur();
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    try {
      await ODb.changeStatus(hash, newStatus);
      setStatus(newStatus);
      setShowStatusPicker(false);
      onMutate?.({ hash, field: 'status', value: newStatus });
    } catch (e) { console.error('Status change failed:', e); }
  };

  const handleTagToggle = async (tag: string) => {
    try {
      await ODb.toggleTag(hash, tag);
      setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
      onMutate?.({ hash, field: 'tags', value: tags.includes(tag) ? tags.filter(t => t !== tag) : [...tags, tag] });
    } catch (e) { console.error('Tag toggle failed:', e); }
  };

  const handleDateApply = async () => {
    if (!dateValue) return;
    const dateStr = timeValue ? `${dateValue} ${timeValue}` : dateValue;
    try {
      await ODb.changeDate(hash, dateType, dateStr);
      onMutate?.({ hash, field: 'date', value: { type: dateType, date: dateStr } });
    } catch (e) { console.error('Date change failed:', e); }
  };

  const handleDateRemove = async () => {
    try {
      await ODb.removeDate(hash, dateType);
      setDateValue('');
      setTimeValue('');
      onMutate?.({ hash, field: 'date', value: null });
    } catch (e) { console.error('Date remove failed:', e); }
  };

  const handlePropChange = async (name: string, value: string) => {
    try {
      await ODb.changeProperty(hash, name, value);
      setProps(prev => ({ ...prev, [name]: value }));
      onMutate?.({ hash, field: 'props', value: { ...props, [name]: value } });
    } catch (e) { console.error('Property change failed:', e); }
  };

  const handlePropDelete = async (name: string) => {
    try {
      await ODb.changeProperty(hash, name, '');
      setProps(prev => {
        const next = { ...prev };
        delete next[name];
        return next;
      });
      onMutate?.({ hash, field: 'props', value: { ...props, [name]: undefined } });
    } catch (e) { console.error('Property delete failed:', e); }
  };

  const handleBodySave = async () => {
    if (bodyOrg === savedBodyOrg) return;
    setBodySaving(true);
    try {
      await ODb.changeBody(hash, bodyOrg);
      setSavedBodyOrg(bodyOrg);
      // Refresh HTML preview
      const htmlData = await ODb.todoHtml(hash);
      if (htmlData) setBodyHtml(htmlData.Content || '<p>No content</p>');
      setBodyMode('preview');
    } catch (e) { console.error('Body save failed:', e); }
    setBodySaving(false);
  };

  const handleBodyCancel = () => {
    setBodyOrg(savedBodyOrg);
    setBodyMode('preview');
  };

  const handlePropAdd = async () => {
    const name = newPropName.trim();
    const value = newPropValue.trim();
    if (!name) return;
    try {
      await ODb.changeProperty(hash, name, value);
      setProps(prev => ({ ...prev, [name]: value }));
      setNewPropName('');
      setNewPropValue('');
      onMutate?.({ hash, field: 'props', value: { ...props, [name]: value } });
    } catch (e) { console.error('Property add failed:', e); }
  };

  const statusChipSx = getStatusCustomSx(status);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, pt: 1 }}>
      {/* Headline */}
      <Input
        value={headline}
        onChange={e => setHeadline(e.target.value)}
        onBlur={handleHeadlineBlur}
        onKeyDown={handleHeadlineKeyDown}
        variant="plain"
        sx={{ fontSize: '1.25rem', fontWeight: 600, '--Input-focusedThickness': '0px' }}
        placeholder="Headline"
      />

      {/* Status + Tags row */}
      <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
        {/* Status */}
        <Box sx={{ position: 'relative' }}>
          <Chip
            size="sm"
            variant="soft"
            color={getStatusColor(status)}
            startDecorator={getStatusIcon(status)}
            onClick={() => setShowStatusPicker(!showStatusPicker)}
            sx={{ cursor: 'pointer', ...(statusChipSx || {}) }}
          >
            {status || 'No Status'}
          </Chip>
          {showStatusPicker && validStatuses.length > 0 && (
            <Sheet
              variant="outlined"
              sx={{
                position: 'absolute',
                top: '100%',
                left: 0,
                zIndex: 1100,
                mt: 0.5,
                p: 0.5,
                borderRadius: 'sm',
                display: 'flex',
                flexDirection: 'column',
                gap: 0.25,
                maxHeight: 250,
                overflow: 'auto',
                minWidth: 160,
              }}
            >
              {validStatuses.map(s => {
                const sx = getStatusCustomSx(s);
                return (
                  <Chip
                    key={s}
                    size="sm"
                    variant={s === status ? 'solid' : 'soft'}
                    color={getStatusColor(s)}
                    startDecorator={getStatusIcon(s)}
                    onClick={() => handleStatusChange(s)}
                    sx={{ cursor: 'pointer', justifyContent: 'flex-start', ...(sx || {}) }}
                  >
                    {s}
                  </Chip>
                );
              })}
            </Sheet>
          )}
        </Box>

        {/* Tags */}
        {tags.map(tag => (
          <Chip
            key={tag}
            size="sm"
            variant="outlined"
            onClick={() => handleTagToggle(tag)}
            sx={{ cursor: 'pointer', '&:hover': { textDecoration: 'line-through' } }}
          >
            {tag}
          </Chip>
        ))}

        {/* Add tag */}
        {showTagInput ? (
          <Autocomplete
            size="sm"
            placeholder="Add tag..."
            freeSolo
            options={allTags.filter(t => !tags.includes(t))}
            sx={{ minWidth: 140 }}
            onChange={(_e, value) => {
              if (value) {
                handleTagToggle(value as string);
                setShowTagInput(false);
              }
            }}
            onBlur={() => setShowTagInput(false)}
            autoFocus
          />
        ) : (
          <Chip
            size="sm"
            variant="soft"
            color="neutral"
            onClick={() => setShowTagInput(true)}
            sx={{ cursor: 'pointer' }}
            startDecorator={<AddIcon sx={{ fontSize: 14 }} />}
          >
            Tag
          </Chip>
        )}
      </Box>

      {initialData?.Filename && (
        <Typography level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', fontSize: '11px' }}>
          {initialData.Filename}
        </Typography>
      )}

      <Divider />

      {/* Tabs */}
      <Tabs defaultValue="body" sx={{ flex: 1 }}>
        <TabList>
          <Tab value="body">Body</Tab>
          <Tab value="dates">Dates</Tab>
          <Tab value="properties">Properties</Tab>
        </TabList>

        {/* Body tab */}
        <TabPanel value="body" sx={{ p: 1.5 }}>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
              <CircularProgress size="sm" />
            </Box>
          ) : (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {/* Edit/Preview toggle */}
              <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                <ButtonGroup size="sm" variant="outlined">
                  <Button
                    color={bodyMode === 'preview' ? 'primary' : 'neutral'}
                    variant={bodyMode === 'preview' ? 'solid' : 'outlined'}
                    onClick={() => setBodyMode('preview')}
                  >
                    Preview
                  </Button>
                  <Button
                    color={bodyMode === 'edit' ? 'primary' : 'neutral'}
                    variant={bodyMode === 'edit' ? 'solid' : 'outlined'}
                    onClick={() => setBodyMode('edit')}
                  >
                    Edit
                  </Button>
                </ButtonGroup>
                {bodyMode === 'edit' && (
                  <>
                    <Button size="sm" onClick={handleBodySave} loading={bodySaving} disabled={bodyOrg === savedBodyOrg}>
                      Save
                    </Button>
                    <Button size="sm" variant="plain" color="neutral" onClick={handleBodyCancel}>
                      Cancel
                    </Button>
                  </>
                )}
              </Box>

              {bodyMode === 'preview' ? (
                <Box sx={{
                  '& h1, & h2, & h3, & h4': { mt: 1.5, mb: 0.5 },
                  '& p': { my: 0.5 },
                  '& ul, & ol': { pl: 2.5 },
                  '& pre': { backgroundColor: 'background.level1', p: 1, borderRadius: 'sm', overflow: 'auto', fontSize: '12px' },
                  '& code': { fontSize: '12px' },
                  '& a': { color: 'primary.plainColor' },
                  fontSize: '14px',
                  lineHeight: 1.6,
                  cursor: 'pointer',
                }} dangerouslySetInnerHTML={{ __html: bodyHtml }}
                  onClick={() => setBodyMode('edit')}
                  title="Click to edit"
                />
              ) : (
                <Textarea
                  value={bodyOrg}
                  onChange={e => setBodyOrg(e.target.value)}
                  minRows={10}
                  maxRows={30}
                  sx={{
                    fontFamily: 'monospace',
                    fontSize: '13px',
                    lineHeight: 1.5,
                    '--Textarea-focusedThickness': '1px',
                  }}
                  placeholder="Enter org-mode content..."
                  autoFocus
                />
              )}
            </Box>
          )}
        </TabPanel>

        {/* Dates tab */}
        <TabPanel value="dates" sx={{ p: 1.5 }}>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            <Select
              size="sm"
              value={dateType}
              onChange={(_e, val) => val && setDateType(val)}
              sx={{ maxWidth: 200 }}
            >
              <Option value="TIMESTAMP">Timestamp</Option>
              <Option value="DEADLINE">Deadline</Option>
              <Option value="SCHEDULED">Scheduled</Option>
            </Select>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              <Input
                size="sm"
                type="date"
                value={dateValue}
                onChange={e => setDateValue(e.target.value)}
                sx={{ minWidth: 160 }}
              />
              <Input
                size="sm"
                type="time"
                value={timeValue}
                onChange={e => setTimeValue(e.target.value)}
                sx={{ minWidth: 120 }}
              />
            </Box>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Button size="sm" onClick={handleDateApply} disabled={!dateValue}>
                Apply
              </Button>
              <Button size="sm" variant="soft" color="danger" onClick={handleDateRemove}>
                Remove
              </Button>
            </Box>
          </Box>
        </TabPanel>

        {/* Properties tab */}
        <TabPanel value="properties" sx={{ p: 1.5 }}>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            {Object.entries(props).map(([name, value]) => (
              <PropertyRow
                key={name}
                name={name}
                value={value}
                onSave={(val) => handlePropChange(name, val)}
                onDelete={() => handlePropDelete(name)}
              />
            ))}
            {Object.keys(props).length === 0 && (
              <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>No properties</Typography>
            )}
            <Divider sx={{ my: 0.5 }} />
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-end' }}>
              <Input
                size="sm"
                placeholder="Name"
                value={newPropName}
                onChange={e => setNewPropName(e.target.value)}
                sx={{ flex: 1 }}
              />
              <Input
                size="sm"
                placeholder="Value"
                value={newPropValue}
                onChange={e => setNewPropValue(e.target.value)}
                sx={{ flex: 2 }}
              />
              <Button size="sm" variant="soft" onClick={handlePropAdd} disabled={!newPropName.trim()}>
                Add
              </Button>
            </Box>
          </Box>
        </TabPanel>
      </Tabs>
    </Box>
  );
}

// --- Property Row ---

function PropertyRow({ name, value, onSave, onDelete }: {
  name: string;
  value: string;
  onSave: (val: string) => void;
  onDelete: () => void;
}) {
  const [editValue, setEditValue] = React.useState(value);

  const handleBlur = () => {
    if (editValue.trim() !== value) {
      onSave(editValue.trim());
    }
  };

  return (
    <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
      <Typography level="body-sm" sx={{ fontFamily: 'monospace', fontSize: '12px', minWidth: 100, fontWeight: 600 }}>
        {name}
      </Typography>
      <Input
        size="sm"
        value={editValue}
        onChange={e => setEditValue(e.target.value)}
        onBlur={handleBlur}
        sx={{ flex: 1, fontFamily: 'monospace', fontSize: '12px' }}
      />
      <IconButton size="sm" variant="plain" color="danger" onClick={onDelete}>
        <DeleteOutlineIcon sx={{ fontSize: 16 }} />
      </IconButton>
    </Box>
  );
}

// --- Heading Outline Row ---

function HeadingRow({ node, allTags }: { node: any; allTags: string[] }) {
  const [expanded, setExpanded] = React.useState(false);
  const [editing, setEditing] = React.useState(false);
  const [headline, setHeadline] = React.useState(node.Headline || '');
  const [savedHeadline, setSavedHeadline] = React.useState(node.Headline || '');
  const [status, setStatus] = React.useState(node.Status || '');
  const [tags, setTags] = React.useState<string[]>(node.Tags || []);
  const [bodyHtml, setBodyHtml] = React.useState('');
  const [bodyOrg, setBodyOrg] = React.useState('');
  const [savedBodyOrg, setSavedBodyOrg] = React.useState('');
  const [bodyMode, setBodyMode] = React.useState<'preview' | 'edit'>('preview');
  const [bodySaving, setBodySaving] = React.useState(false);
  const [bodyLoading, setBodyLoading] = React.useState(false);
  const [showStatusPicker, setShowStatusPicker] = React.useState(false);
  const [validStatuses, setValidStatuses] = React.useState<string[]>([]);
  const [showTagInput, setShowTagInput] = React.useState(false);
  const [props, setProps] = React.useState<Record<string, string>>(node.Props || {});
  const [showProps, setShowProps] = React.useState(false);
  const [newPropName, setNewPropName] = React.useState('');
  const [newPropValue, setNewPropValue] = React.useState('');
  const hash = node.Hash;
  const level = node.Level || 1;

  const handleExpand = async () => {
    const next = !expanded;
    setExpanded(next);
    if (next && !bodyHtml) {
      setBodyLoading(true);
      try {
        const [htmlData, fullData] = await Promise.all([
          ODb.todoHtml(hash),
          ODb.todoFull(hash),
        ]);
        setBodyHtml(htmlData?.Content || '');
        if (htmlData?.Props) setProps(htmlData.Props);
        setBodyOrg(fullData?.Content || '');
        setSavedBodyOrg(fullData?.Content || '');
      } catch (e) { console.error(e); }
      setBodyLoading(false);
    }
  };

  const handleHeadlineBlur = async () => {
    const trimmed = headline.trim();
    if (!trimmed || trimmed === savedHeadline) { setEditing(false); return; }
    try {
      await ODb.renameHeadline(hash, trimmed);
      setSavedHeadline(trimmed);
    } catch (e) { console.error(e); }
    setEditing(false);
  };

  const handleStatusClick = async () => {
    if (validStatuses.length === 0) {
      try {
        const result = await ODb.validStatus(hash);
        setValidStatuses([...(result?.Active || []), ...(result?.Done || [])]);
      } catch (e) { console.error(e); }
    }
    setShowStatusPicker(!showStatusPicker);
  };

  const handleStatusChange = async (s: string) => {
    try {
      await ODb.changeStatus(hash, s);
      setStatus(s);
      setShowStatusPicker(false);
    } catch (e) { console.error(e); }
  };

  const handleTagToggle = async (tag: string) => {
    try {
      await ODb.toggleTag(hash, tag);
      setTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    } catch (e) { console.error(e); }
  };

  const handlePropChange = async (name: string, value: string) => {
    try {
      await ODb.changeProperty(hash, name, value);
      setProps(prev => ({ ...prev, [name]: value }));
    } catch (e) { console.error(e); }
  };

  const handlePropDelete = async (name: string) => {
    try {
      await ODb.changeProperty(hash, name, '');
      setProps(prev => { const next = { ...prev }; delete next[name]; return next; });
    } catch (e) { console.error(e); }
  };

  const handlePropAdd = async () => {
    const n = newPropName.trim(); const v = newPropValue.trim();
    if (!n) return;
    try {
      await ODb.changeProperty(hash, n, v);
      setProps(prev => ({ ...prev, [n]: v }));
      setNewPropName(''); setNewPropValue('');
    } catch (e) { console.error(e); }
  };

  const handleBodySave = async () => {
    if (bodyOrg === savedBodyOrg) return;
    setBodySaving(true);
    try {
      await ODb.changeBody(hash, bodyOrg);
      setSavedBodyOrg(bodyOrg);
      const htmlData = await ODb.todoHtml(hash);
      if (htmlData) setBodyHtml(htmlData.Content || '');
      setBodyMode('preview');
    } catch (e) { console.error('Body save failed:', e); }
    setBodySaving(false);
  };

  const statusSx = getStatusCustomSx(status);
  const headingSize = level <= 1 ? '1rem' : level === 2 ? '0.9rem' : '0.85rem';

  return (
    <Box sx={{ borderBottom: '1px solid', borderColor: 'divider' }}>
      {/* Heading row */}
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 0.5,
          pl: (level - 1) * 2.5,
          py: 0.75,
          pr: 1,
          '&:hover': { bgcolor: 'background.level1' },
          cursor: 'pointer',
          transition: 'background-color 0.1s',
        }}
        onClick={handleExpand}
      >
        {/* Expand icon */}
        <IconButton size="sm" variant="plain" sx={{ minWidth: 24, minHeight: 24, p: 0 }} onClick={(e) => { e.stopPropagation(); handleExpand(); }}>
          {expanded ? <ExpandMoreIcon sx={{ fontSize: 18 }} /> : <ChevronRightIcon sx={{ fontSize: 18 }} />}
        </IconButton>

        {/* Level stars */}
        <Typography sx={{ fontFamily: 'monospace', fontSize: '12px', color: 'text.tertiary', mr: 0.5, userSelect: 'none' }}>
          {'*'.repeat(level)}
        </Typography>

        {/* Status chip */}
        {status && (
          <Box sx={{ position: 'relative' }} onClick={e => e.stopPropagation()}>
            <Chip
              size="sm"
              variant="soft"
              color={getStatusColor(status)}
              startDecorator={getStatusIcon(status)}
              onClick={handleStatusClick}
              sx={{ cursor: 'pointer', fontSize: '11px', height: 22, ...(statusSx || {}) }}
            >
              {status}
            </Chip>
            {showStatusPicker && validStatuses.length > 0 && (
              <Sheet
                variant="outlined"
                sx={{
                  position: 'absolute', top: '100%', left: 0, zIndex: 1200, mt: 0.5, p: 0.5,
                  borderRadius: 'sm', display: 'flex', flexDirection: 'column', gap: 0.25,
                  maxHeight: 200, overflow: 'auto', minWidth: 140,
                }}
              >
                {validStatuses.map(s => (
                  <Chip key={s} size="sm" variant={s === status ? 'solid' : 'soft'} color={getStatusColor(s)}
                    startDecorator={getStatusIcon(s)} onClick={() => handleStatusChange(s)}
                    sx={{ cursor: 'pointer', justifyContent: 'flex-start', ...(getStatusCustomSx(s) || {}) }}
                  >{s}</Chip>
                ))}
              </Sheet>
            )}
          </Box>
        )}

        {/* Headline */}
        {editing ? (
          <Input
            size="sm"
            value={headline}
            onChange={e => setHeadline(e.target.value)}
            onBlur={handleHeadlineBlur}
            onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); (e.target as HTMLElement).blur(); } if (e.key === 'Escape') { setHeadline(savedHeadline); setEditing(false); } }}
            autoFocus
            onClick={e => e.stopPropagation()}
            sx={{ flex: 1, fontSize: headingSize, fontWeight: 600, '--Input-focusedThickness': '1px' }}
          />
        ) : (
          <Typography
            sx={{ flex: 1, fontSize: headingSize, fontWeight: level <= 2 ? 600 : 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
          >
            {savedHeadline}
          </Typography>
        )}

        {/* Tags */}
        {tags.length > 0 && (
          <Box sx={{ display: 'flex', gap: 0.25 }} onClick={e => e.stopPropagation()}>
            {tags.map(tag => (
              <Chip key={tag} size="sm" variant="outlined" sx={{ fontSize: '10px', height: 20 }}>
                {tag}
              </Chip>
            ))}
          </Box>
        )}

        {/* Edit button */}
        <IconButton size="sm" variant="plain" color="neutral" onClick={(e) => { e.stopPropagation(); setEditing(!editing); }}
          sx={{ minWidth: 24, minHeight: 24, p: 0, ml: 0.5 }}
        >
          {editing ? <CloseIcon sx={{ fontSize: 14 }} /> : <EditIcon sx={{ fontSize: 14 }} />}
        </IconButton>
      </Box>

      {/* Expanded content */}
      {expanded && (
        <Box sx={{ pl: (level - 1) * 2.5 + 3.5, pr: 1, pb: 1.5 }}>
          {/* Tags editing row */}
          <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', alignItems: 'center', mb: 1 }}>
            {tags.map(tag => (
              <Chip key={tag} size="sm" variant="outlined" onClick={() => handleTagToggle(tag)}
                sx={{ cursor: 'pointer', fontSize: '11px', '&:hover': { textDecoration: 'line-through' } }}
              >{tag}</Chip>
            ))}
            {showTagInput ? (
              <Autocomplete size="sm" placeholder="Add tag..." freeSolo options={allTags.filter(t => !tags.includes(t))}
                sx={{ minWidth: 120, fontSize: '12px' }}
                onChange={(_e, value) => { if (value) { handleTagToggle(value as string); setShowTagInput(false); } }}
                onBlur={() => setShowTagInput(false)} autoFocus
              />
            ) : (
              <Chip size="sm" variant="soft" color="neutral" onClick={() => setShowTagInput(true)}
                sx={{ cursor: 'pointer', fontSize: '11px' }} startDecorator={<AddIcon sx={{ fontSize: 12 }} />}
              >Tag</Chip>
            )}
          </Box>

          {/* Properties toggle */}
          <Box sx={{ mb: 1 }}>
            <Button size="sm" variant="plain" color="neutral" onClick={() => { setShowProps(!showProps); if (!showProps && !bodyHtml) handleExpand(); }}
              sx={{ fontSize: '11px', px: 0.5, minHeight: 22 }}
            >
              {showProps ? 'Hide' : 'Show'} Properties ({Object.keys(props).length})
            </Button>
            {showProps && (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, mt: 0.5, pl: 1 }}>
                {Object.entries(props).map(([name, value]) => (
                  <PropertyRow key={name} name={name} value={value} onSave={val => handlePropChange(name, val)} onDelete={() => handlePropDelete(name)} />
                ))}
                <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center', mt: 0.5 }}>
                  <Input size="sm" placeholder="Name" value={newPropName} onChange={e => setNewPropName(e.target.value)} sx={{ flex: 1, fontSize: '11px' }} />
                  <Input size="sm" placeholder="Value" value={newPropValue} onChange={e => setNewPropValue(e.target.value)} sx={{ flex: 2, fontSize: '11px' }} />
                  <Button size="sm" variant="soft" onClick={handlePropAdd} disabled={!newPropName.trim()} sx={{ fontSize: '11px', minHeight: 24 }}>Add</Button>
                </Box>
              </Box>
            )}
          </Box>

          {/* Body content */}
          {bodyLoading ? (
            <CircularProgress size="sm" />
          ) : (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
              <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                <ButtonGroup size="sm" variant="outlined" sx={{ '& button': { fontSize: '11px', minHeight: 22, px: 1 } }}>
                  <Button
                    color={bodyMode === 'preview' ? 'primary' : 'neutral'}
                    variant={bodyMode === 'preview' ? 'solid' : 'outlined'}
                    onClick={() => setBodyMode('preview')}
                  >Preview</Button>
                  <Button
                    color={bodyMode === 'edit' ? 'primary' : 'neutral'}
                    variant={bodyMode === 'edit' ? 'solid' : 'outlined'}
                    onClick={() => setBodyMode('edit')}
                  >Edit</Button>
                </ButtonGroup>
                {bodyMode === 'edit' && (
                  <>
                    <Button size="sm" onClick={handleBodySave} loading={bodySaving} disabled={bodyOrg === savedBodyOrg}
                      sx={{ fontSize: '11px', minHeight: 22 }}>Save</Button>
                    <Button size="sm" variant="plain" color="neutral" onClick={() => { setBodyOrg(savedBodyOrg); setBodyMode('preview'); }}
                      sx={{ fontSize: '11px', minHeight: 22 }}>Cancel</Button>
                  </>
                )}
              </Box>
              {bodyMode === 'preview' ? (
                bodyHtml ? (
                  <Box sx={{
                    '& h1, & h2, & h3, & h4': { mt: 1, mb: 0.25, fontSize: '0.9rem' },
                    '& p': { my: 0.25 },
                    '& ul, & ol': { pl: 2, my: 0.25 },
                    '& pre': { backgroundColor: 'background.level1', p: 1, borderRadius: 'sm', overflow: 'auto', fontSize: '11px' },
                    '& code': { fontSize: '11px' },
                    '& a': { color: 'primary.plainColor' },
                    fontSize: '13px', lineHeight: 1.5,
                    cursor: 'pointer',
                  }} dangerouslySetInnerHTML={{ __html: bodyHtml }}
                    onClick={() => setBodyMode('edit')}
                    title="Click to edit"
                  />
                ) : (
                  <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic', cursor: 'pointer' }}
                    onClick={() => setBodyMode('edit')}>Click to add content...</Typography>
                )
              ) : (
                <Textarea
                  value={bodyOrg}
                  onChange={e => setBodyOrg(e.target.value)}
                  minRows={5}
                  maxRows={20}
                  sx={{ fontFamily: 'monospace', fontSize: '12px', lineHeight: 1.4, '--Textarea-focusedThickness': '1px' }}
                  placeholder="Enter org-mode content..."
                  autoFocus
                />
              )}
            </Box>
          )}
        </Box>
      )}
    </Box>
  );
}

// --- File Editor ---

function FileEditor({ filename }: { filename: string }) {
  const [headings, setHeadings] = React.useState<any[]>([]);
  const [allTags, setAllTags] = React.useState<string[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState('');

  React.useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError('');
    Promise.all([
      ODb.getFileHeadings(filename),
      ODb.getAllTags(),
    ]).then(([headingsData, tagsData]) => {
      if (cancelled) return;
      setHeadings(headingsData || []);
      setAllTags(tagsData || []);
    }).catch(e => {
      if (!cancelled) setError(e.message || 'Failed to load file');
    }).finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => { cancelled = true; };
  }, [filename]);

  const basename = filename.split('/').pop() || filename;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, pt: 1, height: '100%' }}>
      <Typography level="title-lg">{basename}</Typography>
      <Typography level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', fontSize: '11px' }}>
        {filename}
      </Typography>
      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
          <CircularProgress size="sm" />
        </Box>
      ) : error ? (
        <Sheet variant="soft" color="danger" sx={{ borderRadius: 'sm', p: 2 }}>
          <Typography level="body-sm">{error}</Typography>
        </Sheet>
      ) : headings.length === 0 ? (
        <Typography level="body-sm" sx={{ color: 'text.tertiary', textAlign: 'center', p: 3 }}>
          No headings found in this file.
        </Typography>
      ) : (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', overflow: 'auto', flex: 1 }}>
          {headings.map((node, i) => (
            <HeadingRow key={node.Hash || i} node={node} allTags={allTags} />
          ))}
        </Sheet>
      )}
    </Box>
  );
}

// --- Main OrgEditor ---

export default function OrgEditor(props: OrgEditorProps) {
  const { open, onClose } = props;
  const isFile = props.mode === 'file';

  return (
    <Modal open={open} onClose={onClose}>
      <ModalDialog sx={{
        maxWidth: isFile ? 800 : 700,
        width: '95vw',
        maxHeight: '85vh',
        overflow: 'auto',
      }}>
        <ModalClose />
        {props.mode === 'node' ? (
          <NodeEditor
            hash={props.hash}
            initialData={props.initialData}
            onMutate={props.onMutate}
          />
        ) : (
          <FileEditor filename={props.filename} />
        )}
      </ModalDialog>
    </Modal>
  );
}
