// Asking for a passphrase, for one encrypted heading.
//
// One dialog for the three things that need one - reveal, encrypt, save an
// edit - because what it must get right is the same for all of them:
//
//  - the passphrase lives in this dialog's state while it is open and nowhere
//    else, and is cleared the moment it closes, whichever way it closes;
//  - a wrong passphrase keeps the dialog open with the reason under the field,
//    rather than closing and reopening it, which loses the place and the focus;
//  - "keep unlocked" is offered only when the server is configured to hold a
//    passphrase at all (crypt.unlockSeconds), names how long, and is off by
//    default, because holding one is the trade the server's own settings call
//    a cost;
//  - encrypting asks twice. A passphrase mistyped once while encrypting is a
//    note nobody can ever read again.

import * as React from 'react';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import Box from '@mui/joy/Box';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Checkbox from '@mui/joy/Checkbox';
import Alert from '@mui/joy/Alert';
import LockIcon from '@mui/icons-material/LockOutlined';
import KeyIcon from '@mui/icons-material/KeyOutlined';

import { CryptState } from '../cryptApi';
import { shortLeft } from '../crypt';

export type CryptDialogMode = 'reveal' | 'seal' | 'save';

export type CryptAsk = {
    mode: CryptDialogMode;
    headline: string;
    // What the server says about holding passphrases, and the mode it is in.
    state: CryptState | null;
    // Runs with what was typed. Answers null when it worked (the dialog
    // closes), or what to say under the field (the dialog stays).
    submit: (passphrase: string, keep: boolean) => Promise<string | null>;
};

const TITLES: Record<CryptDialogMode, string> = {
    reveal: 'Reveal',
    seal: 'Encrypt',
    save: 'Save encrypted',
};

export default function CryptDialog({ ask, onClose }: { ask: CryptAsk | null; onClose: () => void }) {
    const [pass, setPass] = React.useState('');
    const [again, setAgain] = React.useState('');
    const [keep, setKeep] = React.useState(false);
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');

    // A new question starts clean, and so does closing: nothing typed here
    // outlives the dialog it was typed into.
    React.useEffect(() => {
        setPass(''); setAgain(''); setKeep(false); setBusy(false); setError('');
    }, [ask]);

    if (ask === null) return null;

    const keyMode = ask.state !== null && ask.state.Mode === 'key';
    // In key mode the server encrypts to a public key and needs nothing typed.
    const needPass = !(keyMode && ask.mode === 'seal');
    const twice = ask.mode === 'seal' && !keyMode;
    const windowSecs = ask.state ? ask.state.UnlockSeconds : 0;
    const canKeep = windowSecs > 0 && needPass;

    const close = () => {
        setPass(''); setAgain('');
        onClose();
    };

    const go = async () => {
        if (busy) return;
        if (needPass && pass === '') { setError('Type the passphrase.'); return; }
        if (twice && pass !== again) { setError('Those two do not match.'); return; }
        setBusy(true);
        setError('');
        let msg: string | null;
        try {
            msg = await ask.submit(needPass ? pass : '', canKeep && keep);
        } catch (e: any) {
            msg = (e && e.message) || 'That did not work.';
        }
        setBusy(false);
        if (msg === null) { close(); return; }
        setError(msg);
        // A wrong passphrase is retyped, not edited.
        setPass(''); setAgain('');
    };

    return (
        <Modal open onClose={busy ? undefined : close}>
            <ModalDialog
                size="sm"
                sx={{ width: 400, maxWidth: '92vw' }}
                // Enter submits from either field; the form element would also
                // do it, but would offer to save the password, which is the
                // one thing a browser must not do with this.
                onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter') { e.preventDefault(); go(); } }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {keyMode ? <KeyIcon sx={{ color: 'warning.500' }} /> : <LockIcon sx={{ color: 'warning.500' }} />}
                    <Typography level="title-md" sx={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {TITLES[ask.mode]} “{ask.headline || 'this heading'}”
                    </Typography>
                </Box>

                {ask.mode === 'seal' && (
                    <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                        Everything under the heading, children included, becomes ciphertext in the file.
                        The heading line, its dates and its properties stay readable, as org-crypt leaves them.
                        {keyMode
                            ? " It is encrypted to the server's key; only that key's owner can read it back."
                            : ' Lose the passphrase and the note is gone: nothing can recover it.'}
                    </Typography>
                )}
                {ask.mode === 'save' && (
                    <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                        The new text is encrypted before it is written; it never reaches the disk in the clear.
                    </Typography>
                )}

                {needPass && (
                    <Input
                        autoFocus
                        type="password"
                        // Not a login: no autofill, and nothing for a password
                        // manager to offer to remember.
                        autoComplete="off"
                        slotProps={{ input: { 'data-lpignore': 'true', 'data-1p-ignore': 'true', spellCheck: false } as any }}
                        placeholder={ask.mode === 'seal' ? 'A passphrase for this heading' : 'Passphrase'}
                        value={pass}
                        disabled={busy}
                        onChange={e => setPass(e.target.value)}
                    />
                )}
                {twice && (
                    <Input
                        type="password"
                        autoComplete="off"
                        slotProps={{ input: { 'data-lpignore': 'true', 'data-1p-ignore': 'true', spellCheck: false } as any }}
                        placeholder="The same again"
                        value={again}
                        disabled={busy}
                        onChange={e => setAgain(e.target.value)}
                    />
                )}
                {canKeep && (
                    <Checkbox
                        size="sm"
                        checked={keep}
                        disabled={busy}
                        onChange={e => setKeep(e.target.checked)}
                        label={`Keep unlocked on the server for ${shortLeft(windowSecs)}`}
                    />
                )}
                {error !== '' && <Alert size="sm" color="danger" variant="soft">{error}</Alert>}

                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, mt: 0.5 }}>
                    <Button size="sm" variant="plain" color="neutral" disabled={busy} onClick={close}>Cancel</Button>
                    <Button size="sm" color={ask.mode === 'seal' ? 'warning' : 'primary'} loading={busy} onClick={go}>
                        {ask.mode === 'reveal' ? 'Reveal' : ask.mode === 'seal' ? 'Encrypt' : 'Save'}
                    </Button>
                </Box>
            </ModalDialog>
        </Modal>
    );
}

// A dialog and the function that puts a question to it, for a component that
// would otherwise carry the same three lines of state.
export function useCryptDialog(): [React.ReactNode, (a: CryptAsk) => void] {
    const [ask, setAsk] = React.useState<CryptAsk | null>(null);
    const node = <CryptDialog ask={ask} onClose={() => setAsk(null)} />;
    return [node, setAsk];
}
