import * as MoveTypes from './move';
function pad2(num: number): string {
    return String(num).padStart(2, '0');
}

// A date as the server writes one, in *local* time. toISOString would hand
// over the UTC day, which is the day before for anybody west of Greenwich -
// and a birthday on the wrong day is the whole point of the feature missed.
function isoDay(d: Date): string {
    return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

