// One file a heading owns.
//
// This is org-attach: the folder is the one emacs uses - the heading's :ID:
// split two characters deep under `data/`, or whatever its :DIR: property
// names - so a database attached to here is one emacs can read.
export type Attachment = {
    Name: string;
    Size: number;
    Modified: string;
    // image | audio | video | pdf | text | binary, worked out from the
    // extension by the server, so one list says what a picture is.
    Media: string;
    Lang: string;
    // Where to fetch it. Through the server rather than as a path under
    // /images, because a heading's folder can be anywhere its :DIR: says.
    Url: string;
    // The org link that reaches it, ready to paste.
    Link: string;
};

export type AttachList = {
    Ok: boolean;
    Msg: string;
    Hash: string;
    Filename: string;
    Headline: string;
    Dir: string;
    // dir when a :DIR: property named the folder, id when it came from the
    // heading's :ID:, empty when the heading owns nothing yet. A view showing
    // an empty list wants to know which of those it is looking at.
    From: string;
    Id: string;
    Attachments: Attachment[] | null;
};

export type AttachResult = Attachment & {
    Ok: boolean;
    Msg: string;
    Filename: string;
    Line: number;
    // Attaching can edit more than the body: a heading with no :ID: has to be
    // given one to own a folder at all, and it is tagged the first time.
    NewId: string;
    Tagged: string;
};

export type AttachHeading = {
    Hash: string;
    Headline: string;
    Filename: string;
    Olp: string[] | null;
    Dir: string;
    Count: number;
    Size: number;
    Newest: string;
    Attachments: Attachment[] | null;
};

export type AttachAll = {
    Ok: boolean;
    Msg: string;
    Headings: AttachHeading[] | null;
    Count: number;
    Size: number;
    // Folders under the attachment root that no heading claims. Reported
    // rather than cleaned up: they are somebody's files.
    Orphans: string[] | null;
};

