// A chart as somebody set it up, kept by name on the server
// (`GanttView` in internal/app/orgs/ganttviews.go). A field added here and not
// there is dropped on save.
export type GanttMarkerStyle = 'solid' | 'dashed' | 'dotted' | 'dashdot';

// The tests a rule can make; see HeadingTest in gantt.ts.
export type GanttRuleTest = 'value' | 'has' | 'tag' | 'tagmatch' | 'status' | 'unscheduled' | 'done';

export type GanttMarkers = {
    // A marker set's name (the main markers have none) and whether it is
    // drawn; see markersets.ts.
    label?: string;
    hidden?: boolean;
    storedQuery?: string;
    // A query written for the markers rather than a saved one; wins when set.
    query?: string;
    // scheduled | deadline | either
    dateKind?: string;
    color?: string;
    style?: GanttMarkerStyle;
    width?: number;
    // The symbol on a marker's line when no rule says otherwise.
    shape?: string;
    // First match wins; see markerLookFor in gantt.ts.
    rules?: GanttMarkerRule[];
};

export type GanttMarkerRule = {
    when: GanttRuleTest;
    key: string;
    value?: string;
    shape: string;
    // Empty keeps the markers' own colour.
    color?: string;
};

export type GanttFilterMode = 'regex' | 'notregex' | 'query';

export type GanttView = {
    name: string;
    storedQuery: string;
    // The query as edited on the chart, when it is no longer the saved one's.
    query?: string;
    // What narrows which rows are shown, read as filterMode says: a regexp
    // the heading must match, one it must not, or a second org query. A view
    // with a filter and no mode was saved when filters were only queries.
    filter?: string;
    filterMode?: GanttFilterMode;
    // Overdue and slipping work highlighted.
    health?: boolean;
    // How far each task could slip, drawn after its bar.
    slack?: boolean;
    // Each person's load per day under the chart, and the property that
    // names the person.
    workload?: boolean;
    workloadProp?: string;
    // The time clocked on each task, drawn under its bar.
    actual?: boolean;
    // Snapshots of the plan's dates, and which one is drawn under the bars.
    baselines?: GanttBaselineData[];
    baseline?: string;
    renderer?: string;
    title?: string;
    colorBy?: string;
    colorProp?: string;
    laneProp?: string;
    skipWeekends: boolean;
    criticalPath: boolean;
    dayWidth?: number;
    quarter?: number | null;
    from?: string;
    to?: string;
    colors?: Record<string, string>;
    shutLanes?: string[];
    markers?: GanttMarkers | null;
    // More marker queries, each drawn its own way.
    markerSets?: GanttMarkers[];
    // How bars are drawn - outline, fill, shape - by property value,
    // property presence or tag. `outlines` is the name these had while they
    // could only outline; a view saved then is read from it.
    barRules?: GanttBarRule[];
    outlines?: GanttBarRule[];
};

export type GanttBarRule = {
    when: GanttRuleTest;
    key: string;
    value?: string;
    // Outline colour; empty means no outline from this rule.
    color?: string;
    width?: number;
    fill?: string;
    shape?: string;
    // Set on a rule a preset added, so turning the preset off takes back
    // exactly what it put in.
    preset?: string;
};

export type GanttBaselineData = {
    name: string;
    taken: string;
    tasks: { hash: string; headline: string; filename: string; start: string; end: string }[];
};

// ---------------------------------------------------------------------------
// Kanban boards
// ---------------------------------------------------------------------------

// One column of a board. Value is what puts a card here, read against whatever
// the board groups by: the grouping property's value, the tag name, or the todo
// keyword.
export type KanbanColumn = {
    value: string;
    title: string;
    color: string;
    limit: number;
    // Whether the column is drawn folded. Worked out from the board's own
    // `folded` list when the columns are built, not stored per column: a board
    // that reads its columns off the server's todo keywords has no stored
    // column to write the flag on.
    collapsed: boolean;
    // Other spellings this column also claims. IN-PROGRESS and INPROGRESS are
    // the same state to everyone except a string comparison, and a board that
    // shows them as two columns is showing a typo rather than a workflow. The
    // column's own `value` is what a card dropped on it is set to unless a
    // particular alias is aimed at.
    aliases?: string[];
};

// A saved board: where its cards come from, what splits them into columns, and
// how they are drawn. It holds no cards - every one of them is worked out from
// the query each time the board is opened.
export type KanbanBoard = {
    name: string;
    storedQuery: string;
    query: string;
    includeArchived: boolean;
    groupBy: 'property' | 'tag' | 'status';
    groupKey: string;
    columns: KanbanColumn[];
    showUnset: boolean;
    unsetTitle: string;
    colorBy: 'none' | 'property' | 'tag' | 'status' | 'priority';
    colorKey: string;
    colors: Record<string, string>;
    // The thin bar across the top of a card, and what decides its colour: a
    // property to read, and a map from that property's values to colours.
    // Empty key means the default, which is a card's own :COLOUR:.
    headerKey: string;
    headerColors: Record<string, string>;
    // Drawn as a board of columns, or as one grouped list. The same cards, the
    // same groups and the same drag - only laid out differently.
    layout: 'board' | 'list';
    // The fields the list lays out beside a heading, in order. Keys from
    // LIST_FIELDS, or `prop:NAME` for a property of your own.
    listFields: string[];
    // The coloured bars across a card, for categorising at a glance.
    //
    // They come either from the heading's tags or from one property holding
    // several values, and `labelColors` maps a value to a colour. `labelOrder`
    // is the set the card's own menu offers - the ones this board is about -
    // so that adding a label is a choice from a short list rather than typing.
    labelSource: 'none' | 'tags' | 'property';
    labelKey: string;
    labelColors: Record<string, string>;
    labelOrder: string[];
    // The sections put away out of sight, by value. Different from folded: a
    // folded section is still on the list with its count, a hidden one is not
    // there at all and is brought back from the toolbar.
    hidden: string[];
    // The columns drawn folded, by value. Kept on the board rather than on the
    // columns because the columns may not be the board's own, and because the
    // catch-all column is appended rather than stored and so has nowhere of its
    // own to remember it.
    folded: string[];
    badges: string[];
    backShows: 'body' | 'properties' | 'both';
    sort: 'headline' | 'priority' | 'deadline' | 'scheduled' | 'file' | 'manual';
    orderKey: string;
};

