    // One file run through pdflatex, as the pdf itself.
    //
    // Fetched as a blob rather than pointed at with a src, because the request
    // has to carry the Authorization header and an <iframe> cannot be given
    // one. The caller makes an object url out of it - and must revoke it, or
    // every look at a book leaks a pdf into the tab.
    //
    // The failure is read as well as the success, which is why this does not
    // go through doGetBlob: a document that does not compile is the ordinary
    // way for this to fail, and pdflatex's reason for it is the only useful
    // thing on the screen at that point.
    public static async pdfBlob(filename: string, refresh: boolean = false): Promise<{ Ok: boolean; Msg: string; Blob: Blob | null }> {
        var url: URL = new URL(Sets.orgsConnection + "/pdf");
        url.searchParams.append('query', filename);
        if (refresh) {
            url.searchParams.append('refresh', 't');
        }
        const headers: Headers = new Headers();
        const token = Auth.get().getToken();
        if (token) {
            headers.set('Authorization', 'Bearer ' + token);
        }
        try {
            const res = await window.fetch(new Request(url, { method: 'GET', headers }));
            if (!res.ok) {
                const why = await res.text();
                return { Ok: false, Msg: why.trim() || `The server said ${res.status}.`, Blob: null };
            }
            return { Ok: true, Msg: '', Blob: await res.blob() };
        } catch (error: any) {
            return { Ok: false, Msg: (error && error.message) || 'The request did not go through.', Blob: null };
        }
    }

