import * as React from 'react';
import GlobalStyles from '@mui/joy/GlobalStyles';
import Avatar from '@mui/joy/Avatar';
import Divider from '@mui/joy/Divider';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import ListItemButton from '@mui/joy/ListItemButton';
import Sheet from '@mui/joy/Sheet';
// icons
import HomeRoundedIcon from '@mui/icons-material/HomeRounded';
import DashboardRoundedIcon from '@mui/icons-material/DashboardRounded';
import DynamicFeedRoundedIcon from '@mui/icons-material/DynamicFeedRounded';
import SettingsRoundedIcon from '@mui/icons-material/SettingsRounded';
import SupportRoundedIcon from '@mui/icons-material/SupportRounded';
import EditNoteIcon from '@mui/icons-material/EditNote';
import KeyboardCommandKeyIcon from '@mui/icons-material/KeyboardCommandKey';
import NoteAddOutlinedIcon from '@mui/icons-material/NoteAddOutlined';

import MyLogo from './MyLogo';
import { openSidebar, toggleSidebar } from '../utils';
import QrCode from './QrCode';
import { useIsMobile } from '../useMobile';

export default function FunctionBar({
  navOpen = true,
  onToggleNav,
  onCapture,
  onPalette,
  onNewFile,
}: {
  navOpen?: boolean;
  onToggleNav?: () => void;
  onCapture?: () => void;
  onPalette?: () => void;
  onNewFile?: () => void;
} = {}) {
  const isMobile = useIsMobile();
  // The application button works the same way on either size of screen, it is
  // just that the two sizes show the panel differently: toggleSidebar drives
  // the off-canvas drawer a narrow screen gets, onToggleNav slides the panel
  // that is in the flow on a wide one. Whichever one is not in play does
  // nothing, so both can be told every time.
  const toggleNav = () => {
    toggleSidebar();
    if (onToggleNav) onToggleNav();
  };
  return (
    <Sheet
      className="FunctionBar"
      sx={{
        // Off-canvas in the phone layout, in the flow otherwise - and driven by
        // `isMobile` rather than a breakpoint of its own so that the forced
        // phone layout is the real thing rather than an approximation of it.
        // Left on a raw breakpoint, the rail stayed in the flow while the fixed
        // header slid under it, and the header's hamburger - the only way to the
        // nav once the rail is the thing being hidden - was behind the rail.
        position: isMobile ? 'fixed' : 'sticky',
        transform: isMobile
          ? 'translateX(calc(100% * (var(--SideNavigation-slideIn, 0) - 1)))'
          : 'none',
        transition: 'transform 0.4s',
        zIndex: 10000,
        height: '100dvh',
        width: 'var(--FunctionBar-width)',
        top: 0,
        p: 2,
        flexShrink: 0,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 1,
        borderRight: '1px solid',
        borderColor: 'divider',
        // A phone in landscape is about 390px tall. The rail's two lists, the
        // logo and the avatar come to more than that at touch row heights, and
        // without this the foot of it is simply unreachable.
        overflowY: 'auto',
      }}
    >
      <GlobalStyles
        styles={{
          ':root': {
            '--FunctionBar-width': '68px',
          },
        }}
      />
      <MyLogo />
      <List
        size="sm"
        sx={{
          '--ListItem-radius': '6px',
          '--List-gap': '8px',
          // Touch targets. The rail is 68px wide, so there is room for a 44px
          // square without the bar changing size - it is only the row height
          // that has to give.
          ...(isMobile ? { '--ListItem-minHeight': '44px' } : null),
        }}
      >
        <ListItem>
          <ListItemButton>
            <HomeRoundedIcon />
          </ListItemButton>
        </ListItem>
        <ListItem>
          <ListItemButton
            selected={navOpen}
            variant={navOpen ? 'soft' : 'plain'}
            onClick={toggleNav}
            title={navOpen ? 'Hide the application panel' : 'Show the application panel'}
          >
            <DashboardRoundedIcon />
          </ListItemButton>
        </ListItem>
        <ListItem>
          <ListItemButton onClick={() => openSidebar()}>
            <DynamicFeedRoundedIcon />
          </ListItemButton>
        </ListItem>
        {/* Quick capture. Near the top of the rail because it is the one
            button that is never about the page you are on. */}
        <ListItem>
          <ListItemButton
            onClick={() => onCapture?.()}
            title="Capture something (c)"
            sx={{ color: 'primary.500' }}
          >
            <EditNoteIcon />
          </ListItemButton>
        </ListItem>
        {/* A new org file, from a template, in a folder picked fzf-style.
            Beside capture: both make something new wherever you are. */}
        {onNewFile && (
          <ListItem>
            <ListItemButton onClick={() => onNewFile()} title="New org file">
              <NoteAddOutlinedIcon />
            </ListItemButton>
          </ListItem>
        )}
        {/* The command palette. Beside capture because the two are the same
            kind of thing - the buttons that are never about the page you are
            on - and because a palette nobody knows the shortcut for may as
            well not exist. */}
        <ListItem>
          <ListItemButton
            onClick={() => onPalette?.()}
            title="Everything, in one box (⌘K)"
          >
            <KeyboardCommandKeyIcon />
          </ListItemButton>
        </ListItem>
      </List>
      <List
        sx={{
          mt: 'auto',
          flexGrow: 0,
          '--ListItem-radius': '8px',
          '--List-gap': '4px',
        }}
      >
        {/* The way onto a phone. At the foot of the rail because it is a thing
            you reach for once and then leave alone. */}
        <QrCode />
        <ListItem>
          <ListItemButton>
            <SupportRoundedIcon />
          </ListItemButton>
        </ListItem>
        <ListItem>
          <ListItemButton>
            <SettingsRoundedIcon />
          </ListItemButton>
        </ListItem>
      </List>
      <Divider />
      <Avatar variant="outlined" size="sm" src="/static/images/avatar/3.jpg" />
    </Sheet>
  );
}
