// The running focus session, in the page header: a small chip with a ring for
// the time gone, the countdown and the task. Nothing at all when idle - the
// header is not the place to advertise a feature, only to show one at work.
//
// A click opens a little panel to act on it without leaving the page: stop,
// five more minutes, skip the break (or finish early), open the task, or go to
// the Focus tab. The state comes from the shared store in focusApi.ts, which
// follows /events, so the chip moves when the session is changed from the
// terminal or another window.
//
// `compact` is the phone header: ring and countdown only, since the title
// beside it already uses the room.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import CircularProgress from '@mui/joy/CircularProgress';
import Divider from '@mui/joy/Divider';
import Popper from '@mui/material/Popper';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import StopIcon from '@mui/icons-material/StopRounded';
import AddIcon from '@mui/icons-material/Add';
import SkipIcon from '@mui/icons-material/SkipNextRounded';
import OpenIcon from '@mui/icons-material/LaunchOutlined';
import TimerIcon from '@mui/icons-material/TimerOutlined';

import { useFocus, stopFocus, extendFocus, skipFocus, focusNavigate } from '../focusApi';
import { formatCountdown, progress, phaseColor, phaseLabel, phaseGlyph, isRunning, setPosition } from '../focus';

export default function FocusStatus({ compact = false }: { compact?: boolean }) {
    const { state, remaining } = useFocus();
    const anchor = React.useRef<HTMLButtonElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const [busy, setBusy] = React.useState(false);
    const [msg, setMsg] = React.useState('');

    if (!isRunning(state)) return null;

    const color = phaseColor(state.Phase);
    const done = progress(state, remaining) * 100;
    const pos = setPosition(state);

    const act = async (f: () => Promise<any>, close = true) => {
        setBusy(true);
        setMsg('');
        const st = await f();
        setBusy(false);
        if (st && st.Ok === false) setMsg(st.Msg || 'That did not work.');
        else if (close) setOpen(false);
    };

    return (
        <>
            <Box
                component="button"
                ref={anchor}
                onClick={() => setOpen(o => !o)}
                aria-label={`${phaseLabel(state)}: ${formatCountdown(remaining)} left${state.Title ? ' on ' + state.Title : ''}`}
                title={state.Title ? `${phaseLabel(state)} · ${state.Title}` : phaseLabel(state)}
                sx={{
                    display: 'inline-flex', alignItems: 'center', gap: 0.75,
                    minWidth: 0, maxWidth: compact ? 120 : 300,
                    height: 30, pl: 0.5, pr: 1.25,
                    border: '1px solid', borderRadius: 999, cursor: 'pointer',
                    font: 'inherit',
                    borderColor: `${color}.outlinedBorder`,
                    bgcolor: `${color}.softBg`,
                    color: `${color}.softColor`,
                    transition: 'background-color 200ms',
                    '&:hover': { bgcolor: `${color}.softHoverBg` },
                    '&:focus-visible': { outline: '2px solid', outlineColor: 'focusVisible', outlineOffset: 2 },
                    flexShrink: compact ? 0 : 1,
                }}
            >
                <CircularProgress
                    determinate
                    value={done}
                    color={color}
                    size="sm"
                    thickness={2.5}
                    sx={{ '--CircularProgress-size': '22px', fontSize: 11 }}
                >
                    <span aria-hidden>{phaseGlyph(state.Phase)}</span>
                </CircularProgress>
                <Typography
                    level="body-sm"
                    fontWeight="lg"
                    sx={{ color: 'inherit', fontVariantNumeric: 'tabular-nums', flexShrink: 0 }}
                >
                    {formatCountdown(remaining)}
                </Typography>
                {!compact && (
                    <Typography
                        level="body-sm"
                        noWrap
                        sx={{ color: 'inherit', opacity: 0.85, minWidth: 0 }}
                    >
                        {state.Phase === 'work' ? state.Title : phaseLabel(state).toLowerCase()}
                    </Typography>
                )}
            </Box>
            <Popper
                open={open}
                anchorEl={anchor.current}
                placement="bottom-end"
                style={{ zIndex: 10000 }}
                modifiers={[{ name: 'offset', options: { offset: [0, 8] } }]}
            >
                <ClickAwayListener onClickAway={() => setOpen(false)}>
                    <Sheet
                        variant="outlined"
                        sx={{ p: 1.5, borderRadius: 'md', boxShadow: 'lg', width: 280, display: 'flex', flexDirection: 'column', gap: 1 }}
                        onKeyDown={e => { if (e.key === 'Escape') setOpen(false); }}
                    >
                        <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1 }}>
                            <Typography level="title-sm" color={color}>{phaseLabel(state)}</Typography>
                            <Typography level="body-xs" sx={{ ml: 'auto' }}>
                                {pos.n} of {pos.of} · {state.Today} today
                            </Typography>
                        </Box>
                        <Typography level="h3" sx={{ fontVariantNumeric: 'tabular-nums', lineHeight: 1 }}>
                            {formatCountdown(remaining)}
                        </Typography>
                        {state.Title && (
                            <Typography level="body-sm" sx={{ overflowWrap: 'anywhere' }}>{state.Title}</Typography>
                        )}
                        {msg && <Typography level="body-xs" color="danger">{msg}</Typography>}
                        <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap' }}>
                            <Button size="sm" variant="solid" color={color} disabled={busy}
                                startDecorator={<StopIcon />} onClick={() => act(stopFocus)}>
                                {state.Phase === 'work' ? 'Stop' : 'End break'}
                            </Button>
                            <Button size="sm" variant="soft" color="neutral" disabled={busy}
                                startDecorator={<AddIcon />} onClick={() => act(() => extendFocus(5), false)}>
                                5 min
                            </Button>
                            <Button size="sm" variant="soft" color="neutral" disabled={busy}
                                startDecorator={<SkipIcon />} onClick={() => act(skipFocus, false)}
                                title={state.Phase === 'work' ? 'Count it as done and take the break' : 'Skip the break and start the next one'}>
                                {state.Phase === 'work' ? 'Done' : 'Skip'}
                            </Button>
                        </Box>
                        <Divider />
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                            {state.File && (
                                <Button size="sm" variant="plain" color="neutral" startDecorator={<OpenIcon />}
                                    onClick={() => { setOpen(false); focusNavigate({ app: 'Files', filename: state.File, heading: state.Title }); }}>
                                    Open task
                                </Button>
                            )}
                            <Button size="sm" variant="plain" color="neutral" startDecorator={<TimerIcon />} sx={{ ml: 'auto' }}
                                onClick={() => { setOpen(false); focusNavigate({ app: 'Focus' }); }}>
                                Focus tab
                            </Button>
                        </Box>
                    </Sheet>
                </ClickAwayListener>
            </Popper>
        </>
    );
}
