// An encrypted heading's body, as a locked placeholder that opens on a click.
//
// Used where a heading's text is shown as React: the Files tab's source view
// (in place of the armoured rows) and the search tab's inspect dialog. The
// rendered view is an iframe of exported html, which React cannot draw into,
// so Files.tsx does the same there with plain DOM and the same flows - the
// flows are exported from here so the two cannot drift.
//
// Revealed text lives in this component's state and nowhere else: not in
// localStorage, not in a cache, not in a parent. Hiding sets it to null. It
// hides itself when anything locks (the toolbar's lock, another tab's lock
// seen by the poll, the server's unlock window running out), when the browser
// tab is hidden, and after a while with nobody touching it - unless an edit is
// in progress, which only a lock closes, because throwing away somebody's
// typing because they glanced at another tab is not safety, it is loss.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import Textarea from '@mui/joy/Textarea';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import Alert from '@mui/joy/Alert';
import LockIcon from '@mui/icons-material/LockOutlined';
import LockOpenIcon from '@mui/icons-material/LockOpenOutlined';
import EnhancedEncryptionIcon from '@mui/icons-material/EnhancedEncryptionOutlined';

import ThemedHtml from './ThemedHtml';
import { CryptAsk, useCryptDialog } from './CryptDialog';
import {
    CryptTarget, CryptOpResult, CryptState, revealHeading, sealHeading, editHeading,
    refreshCryptState, onCryptLock, useCryptState,
} from '../cryptApi';
import { revealIdleMs } from '../crypt';

// ---------------------------------------------------------------------------
// The flows, shared with the rendered view
// ---------------------------------------------------------------------------

function why(res: CryptOpResult): string {
    if (res.WrongPassphrase) return 'That passphrase does not open this heading.';
    return res.Msg || 'That did not work.';
}

// Reveal one heading: straight away when the server is holding a passphrase
// (or encrypts to a key), otherwise through the dialog.
export async function revealFlow(
    t: CryptTarget, headline: string, html: boolean, ask: (a: CryptAsk) => void,
    done: (res: CryptOpResult) => void, fail: (msg: string) => void,
) {
    const st = await refreshCryptState();
    if (st.Ok && st.Mode === 'off') { fail('This server has no gpg, so it cannot decrypt anything.'); return; }
    if (st.Unlocked || st.Mode === 'key') {
        const res = await revealHeading(t, '', false, html);
        if (res.Ok) { done(res); return; }
        if (!res.NeedPassphrase && !res.WrongPassphrase) { fail(why(res)); return; }
    }
    ask({
        mode: 'reveal', headline, state: st,
        submit: async (pass, keep) => {
            const res = await revealHeading(t, pass, keep, html);
            if (!res.Ok) return why(res);
            done(res);
            if (keep) refreshCryptState();
            return null;
        },
    });
}

// Encrypt one heading. Always asks in symmetric mode, even with a passphrase
// held: which passphrase a note is locked under is worth saying out loud.
export async function sealFlow(
    t: CryptTarget, headline: string, ask: (a: CryptAsk) => void,
    done: (res: CryptOpResult) => void, fail: (msg: string) => void,
) {
    const st = await refreshCryptState();
    if (st.Ok && st.Mode === 'off') { fail('This server has no gpg, so it cannot encrypt anything.'); return; }
    ask({
        mode: 'seal', headline, state: st,
        submit: async (pass, keep) => {
            const res = await sealHeading(t, pass, keep);
            if (!res.Ok) return why(res);
            done(res);
            refreshCryptState();
            return null;
        },
    });
}

// Save an edit of revealed text. A held passphrase is used when there is one:
// the server checks it opens what is there before writing, so it cannot put
// the note under a different passphrase than it had.
export async function saveFlow(
    t: CryptTarget, headline: string, text: string, base: string, ask: (a: CryptAsk) => void,
    done: (res: CryptOpResult) => void, fail: (msg: string) => void,
) {
    const st = await refreshCryptState();
    if (st.Unlocked) {
        const res = await editHeading(t, text, base, '', false);
        if (res.Ok) { done(res); return; }
        if (!res.NeedPassphrase && !res.WrongPassphrase) { fail(why(res)); return; }
    }
    ask({
        mode: 'save', headline, state: st,
        submit: async (pass, keep) => {
            const res = await editHeading(t, text, base, pass, keep);
            if (!res.Ok) return why(res);
            done(res);
            return null;
        },
    });
}

// Close something revealed on every signal that should close it. `idleMs` is
// restarted by `poke`; `keepOpen` (an edit in progress) holds off everything
// but a lock.
export function useAutoHide(open: boolean, hide: () => void, keepOpen: boolean, state: CryptState | null): () => void {
    const hideRef = React.useRef(hide);
    hideRef.current = hide;
    const keepRef = React.useRef(keepOpen);
    keepRef.current = keepOpen;
    const timer = React.useRef(0);
    const idle = revealIdleMs(state ? state.UnlockSeconds : 0);

    const poke = React.useCallback(() => {
        if (!open) return;
        window.clearTimeout(timer.current);
        timer.current = window.setTimeout(() => { if (!keepRef.current) hideRef.current(); }, idle);
    }, [open, idle]);

    React.useEffect(() => {
        if (!open) return;
        poke();
        const off = onCryptLock(() => hideRef.current());
        const vis = () => { if (document.visibilityState === 'hidden' && !keepRef.current) hideRef.current(); };
        document.addEventListener('visibilitychange', vis);
        return () => {
            off();
            document.removeEventListener('visibilitychange', vis);
            window.clearTimeout(timer.current);
        };
    }, [open, poke]);
    return poke;
}

// ---------------------------------------------------------------------------
// The block
// ---------------------------------------------------------------------------

export default function CryptReveal({ target, headline, encrypted, initialView = 'html', onChanged, onOpenChange }: {
    target: CryptTarget;
    headline: string;
    // Ciphertext now. When false the heading is tagged and in the clear, and
    // what is offered is encrypting it.
    encrypted: boolean;
    // What a reveal shows first: the exporter's rendering, or the org text.
    initialView?: 'html' | 'text';
    // The file changed: a seal or a saved edit.
    onChanged?: (res: CryptOpResult) => void;
    // Revealed or hidden, for a parent that shows a "hide all" control.
    onOpenChange?: (open: boolean) => void;
}) {
    const state = useCryptState(true);
    const [dialog, ask] = useCryptDialog();
    const [res, setRes] = React.useState<CryptOpResult | null>(null);
    const [view, setView] = React.useState<'html' | 'text'>(initialView);
    const [draft, setDraft] = React.useState<string | null>(null);
    const [error, setError] = React.useState('');
    const [busy, setBusy] = React.useState(false);

    const open = res !== null;
    const dirty = draft !== null && res !== null && draft !== res.Text;
    const hide = React.useCallback(() => { setRes(null); setDraft(null); setError(''); }, []);
    const poke = useAutoHide(open, hide, dirty, state);

    const openChange = React.useRef(onOpenChange);
    openChange.current = onOpenChange;
    React.useEffect(() => {
        if (openChange.current) openChange.current(open);
    }, [open]);
    // Gone from the page is hidden, as far as a parent counting is concerned.
    React.useEffect(() => () => { if (openChange.current) openChange.current(false); }, []);

    const reveal = async () => {
        if (busy) return;
        setBusy(true);
        setError('');
        try {
            await revealFlow(target, headline, true, ask, r => setRes(r), setError);
        } finally {
            setBusy(false);
        }
    };
    const seal = () => {
        setError('');
        sealFlow(target, headline, ask, r => { if (onChanged) onChanged(r); }, setError);
    };
    const save = () => {
        if (res === null || draft === null) return;
        setError('');
        saveFlow(target, headline, draft, res.Base, ask, r => {
            // What was written is what is shown; the server says its new base.
            setRes({ ...res, Text: draft, Html: '', Base: r.Base });
            setView('text');
            setDraft(null);
            if (onChanged) onChanged(r);
        }, setError);
    };

    if (!encrypted) {
        return (
            <>
                <Sheet
                    variant="soft"
                    color="warning"
                    sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 1.25, py: 0.75, borderRadius: 'sm', fontFamily: 'body', whiteSpace: 'normal' }}
                >
                    <LockOpenIcon sx={{ fontSize: 18 }} />
                    <Typography level="body-sm" sx={{ flex: 1, minWidth: 0 }}>
                        Marked :{(state && state.Tag) || 'crypt'}: but sitting in the clear on disk.
                    </Typography>
                    <Button size="sm" variant="solid" color="warning" startDecorator={<EnhancedEncryptionIcon />} onClick={seal}>
                        Encrypt
                    </Button>
                </Sheet>
                {error !== '' && <Alert size="sm" color="danger" variant="soft" sx={{ mt: 0.5 }}>{error}</Alert>}
                {dialog}
            </>
        );
    }

    if (!open) {
        const held = state !== null && state.Unlocked;
        return (
            <>
                <Sheet
                    variant="soft"
                    color="neutral"
                    role="button"
                    tabIndex={0}
                    aria-label={`Encrypted: reveal ${headline}`}
                    onClick={reveal}
                    onKeyDown={(e: React.KeyboardEvent) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); reveal(); } }}
                    sx={{
                        display: 'flex', alignItems: 'center', gap: 1, px: 1.5, py: 1,
                        borderRadius: 'sm', cursor: busy ? 'progress' : 'pointer',
                        border: '1px dashed', borderColor: 'neutral.outlinedBorder',
                        fontFamily: 'body', whiteSpace: 'normal',
                        transition: 'background-color 0.15s',
                        '&:hover, &:focus-visible': { bgcolor: 'neutral.softHoverBg', outline: 'none' },
                    }}
                >
                    <LockIcon sx={{ fontSize: 18, color: 'warning.500' }} />
                    <Typography level="body-sm" sx={{ fontWeight: 600 }}>Encrypted</Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {busy ? 'opening…' : held ? '— click to reveal (unlocked)' : '— click to reveal'}
                    </Typography>
                </Sheet>
                {error !== '' && <Alert size="sm" color="danger" variant="soft" sx={{ mt: 0.5 }}>{error}</Alert>}
                {dialog}
            </>
        );
    }

    return (
        <Sheet
            variant="outlined"
            onPointerMove={poke}
            onKeyDown={poke}
            sx={{
                borderRadius: 'sm', borderLeft: '3px solid', borderLeftColor: 'warning.400',
                px: 1.25, py: 1, fontFamily: 'body', whiteSpace: 'normal',
            }}
        >
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.75, flexWrap: 'wrap' }}>
                <LockOpenIcon sx={{ fontSize: 18, color: 'warning.500' }} />
                <Typography level="body-sm" sx={{ fontWeight: 600 }}>Revealed</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', flex: 1, minWidth: 120 }}>
                    only on this screen; hides when you lock, leave the tab, or leave it alone
                </Typography>
                {draft === null && (
                    <ToggleButtonGroup
                        size="sm"
                        value={view}
                        onChange={(_e, v) => { if (v) setView(v as 'html' | 'text'); }}
                    >
                        <Button value="html" disabled={!res.Html}>Rendered</Button>
                        <Button value="text">Org</Button>
                    </ToggleButtonGroup>
                )}
                {draft === null && (
                    <Button size="sm" variant="outlined" onClick={() => setDraft(res.Text)}>Edit</Button>
                )}
                <Tooltip size="sm" title={dirty ? 'Hide, and throw away this edit' : 'Hide it again'}>
                    <IconButton size="sm" variant="soft" color="warning" aria-label="Hide" onClick={hide}>
                        <LockIcon />
                    </IconButton>
                </Tooltip>
            </Box>
            {draft !== null ? (
                <Box>
                    <Textarea
                        autoFocus
                        minRows={4}
                        maxRows={24}
                        value={draft}
                        onChange={e => setDraft(e.target.value)}
                        slotProps={{ textarea: { spellCheck: false } }}
                        sx={{ fontFamily: '"SFMono-Regular", Menlo, Consolas, monospace', fontSize: 13 }}
                    />
                    <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 0.75 }}>
                        <Button size="sm" variant="plain" color="neutral" onClick={() => setDraft(null)}>Cancel</Button>
                        <Button size="sm" disabled={!dirty} onClick={save}>Save encrypted</Button>
                    </Box>
                </Box>
            ) : view === 'html' && res.Html ? (
                <ThemedHtml html={res.Html} />
            ) : (
                <Box component="pre" sx={{
                    m: 0, fontFamily: '"SFMono-Regular", Menlo, Consolas, monospace', fontSize: 13,
                    whiteSpace: 'pre-wrap', overflowWrap: 'anywhere',
                }}>
                    {res.Text}
                </Box>
            )}
            {error !== '' && <Alert size="sm" color="danger" variant="soft" sx={{ mt: 0.75 }}>{error}</Alert>}
            {dialog}
        </Sheet>
    );
}

// A small action on a heading that is not secret yet: encrypt it. Faint until
// its row is pointed at, so a file of fifty headings does not grow fifty
// lock buttons.
export function CryptSealButton({ target, headline, onChanged, loud = false }: {
    target: CryptTarget;
    headline: string;
    onChanged?: (res: CryptOpResult) => void;
    // A heading tagged for encryption and still in the clear: say so, rather
    // than waiting to be pointed at.
    loud?: boolean;
}) {
    const [dialog, ask] = useCryptDialog();
    const [error, setError] = React.useState('');
    const go = (e: React.MouseEvent) => {
        e.stopPropagation();
        setError('');
        sealFlow(target, headline, ask, r => { if (onChanged) onChanged(r); }, setError);
    };
    if (loud) {
        return (
            <>
                <Tooltip size="sm" title={error || 'Tagged to be encrypted, but the text is in the clear on disk. Encrypt it now.'} color={error ? 'danger' : 'warning'}>
                    <Box
                        component="span"
                        role="button"
                        aria-label="Encrypt this heading"
                        onClick={go}
                        sx={{
                            ml: 1.5, px: 0.75, borderRadius: 'sm', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: 0.5,
                            verticalAlign: 'middle', fontFamily: 'body', fontSize: 12, lineHeight: 1.6,
                            color: 'warning.softColor', bgcolor: 'warning.softBg',
                            '&:hover': { bgcolor: 'warning.softHoverBg' },
                        }}
                    >
                        <LockOpenIcon sx={{ fontSize: 14 }} /> in the clear · encrypt
                    </Box>
                </Tooltip>
                {dialog}
            </>
        );
    }
    return (
        <>
            <Tooltip size="sm" title={error || 'Encrypt this heading (org-crypt)'} color={error ? 'danger' : 'neutral'}>
                <Box
                    component="span"
                    role="button"
                    tabIndex={-1}
                    aria-label="Encrypt this heading"
                    className="row-action"
                    onClick={go}
                    sx={{ ml: 1, cursor: 'pointer', display: 'inline-flex', verticalAlign: 'middle', opacity: 0, transition: 'opacity 0.15s' }}
                >
                    <EnhancedEncryptionIcon sx={{ fontSize: 15 }} />
                </Box>
            </Tooltip>
            {dialog}
        </>
    );
}
