// The links panel: for the heading being read (or the whole file), what links
// to it, what it links to, and where it is named without a link - with a
// button that makes any of those a link.
//
// It follows the reader. Files hands it the heading at the cursor or at the
// top of the page, and the panel asks again when that changes. Following an
// entry pins it, because going to look at a mention scrolls the page to some
// other heading, and a panel that then switched to *that* heading's mentions
// would lose the list being worked through. The pin is in the header; let go
// of it and the panel follows again.
//
// A target is sent as file + line rather than by hash. Linking a mention that
// sits in a headline changes the hash of that heading and everything under
// it, and an id drawer is written *below* the target's headline, so its line
// is the one thing about it that the panel's own writes never move.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import Tooltip from '@mui/joy/Tooltip';
import Alert from '@mui/joy/Alert';
import CircularProgress from '@mui/joy/CircularProgress';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import CloseIcon from '@mui/icons-material/Close';
import CallReceivedIcon from '@mui/icons-material/CallReceived';
import CallMadeIcon from '@mui/icons-material/CallMade';
import LinkOffIcon from '@mui/icons-material/LinkOff';
import AddLinkIcon from '@mui/icons-material/AddLink';
import PushPinIcon from '@mui/icons-material/PushPin';
import PushPinOutlinedIcon from '@mui/icons-material/PushPinOutlined';
import TravelExploreIcon from '@mui/icons-material/TravelExplore';
import DescriptionOutlinedIcon from '@mui/icons-material/DescriptionOutlined';

import {
    LinksAround, LinkInContext, Mention, MentionsResult, OutlineHeading,
    groupMentions, mentionKey, refOf, snippet, splitOn, linkWords, targetLabel, searchedNote,
} from '../mentions';
import { linksAround, mentionsOf, linkMentions, PanelTarget } from '../mentionsApi';

function baseName(p: string): string {
    const parts = p.split(/[\\/]/);
    return parts[parts.length - 1] || p;
}

// What is being looked at: a file, and the heading in it, or none.
type Place = { filename: string; heading: OutlineHeading | null };

function samePlace(a: Place | null, b: Place | null): boolean {
    if (a === null || b === null) return a === b;
    return a.filename === b.filename && (a.heading?.LineNum ?? -1) === (b.heading?.LineNum ?? -1);
}

// The marked part of a line.
function Mark({ children }: { children: React.ReactNode }) {
    return (
        <Box component="span" sx={{
            background: 'var(--joy-palette-warning-softBg)',
            color: 'var(--joy-palette-warning-plainColor)',
            borderRadius: '2px', px: '1px', fontWeight: 600,
        }}>
            {children}
        </Box>
    );
}

// A line of text with one part of it marked, cut down to fit.
function Sentence({ before, match, after, width = 64 }: { before: string; match: string; after: string; width?: number }) {
    const [b, m, a] = snippet(before, match, after, width);
    return (
        <Typography level="body-xs" sx={{ color: 'text.secondary', overflowWrap: 'anywhere', lineHeight: 1.45 }}>
            {b}<Mark>{m}</Mark>{a}
        </Typography>
    );
}

function SectionTitle({ title, count, action }: { title: string; count: number; action?: React.ReactNode }) {
    return (
        <Box sx={{ px: 1.5, pt: 1.25, pb: 0.5, display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography level="title-sm" sx={{ color: 'text.secondary', flex: 1 }}>
                {title} <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>({count})</Typography>
            </Typography>
            {action}
        </Box>
    );
}

// One link, read from the end that is not this target.
function LinkEntry({ link, side, onGo }: { link: LinkInContext; side: 'in' | 'out'; onGo: (file: string, line: number, heading: string) => void }) {
    const far = side === 'in' ? link.From : link.To;
    const canGo = far.Filename !== '';
    const title = far.Headline || (far.Filename !== '' ? baseName(far.Filename) : link.Raw);
    // The link itself marked where the server could cut the line at it, and
    // otherwise the first place its words appear.
    const parts: [string, string, string] | null = link.Shown
        ? [link.Before, link.Shown, link.After]
        : splitOn(link.Context, linkWords(link));
    return (
        <Box
            role="button"
            tabIndex={canGo ? 0 : -1}
            onClick={() => canGo && onGo(far.Filename, side === 'in' ? link.From.Line : far.Line, far.Headline)}
            onKeyDown={e => { if (canGo && e.key === 'Enter') onGo(far.Filename, side === 'in' ? link.From.Line : far.Line, far.Headline); }}
            sx={{
                display: 'flex', gap: 1, px: 1.5, py: 0.75, cursor: canGo ? 'pointer' : 'default',
                '&:hover': { background: canGo ? 'var(--joy-palette-background-level1)' : undefined },
            }}
        >
            <Box sx={{ mt: '2px', flexShrink: 0 }}>
                {link.Broken
                    ? <LinkOffIcon sx={{ fontSize: 15, color: 'danger.400' }} />
                    : side === 'in'
                        ? <CallReceivedIcon sx={{ fontSize: 15, color: 'primary.400' }} />
                        : <CallMadeIcon sx={{ fontSize: 15, color: 'success.400' }} />}
            </Box>
            <Box sx={{ minWidth: 0, flex: 1 }}>
                <Typography level="body-sm" sx={{ fontWeight: 600, overflowWrap: 'anywhere' }}>{title}</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', overflowWrap: 'anywhere' }}>
                    {side === 'in'
                        ? `${baseName(link.From.Filename)}:${link.From.Line + 1}`
                        : far.Filename !== '' ? baseName(far.Filename) : link.Kind}
                    {link.Broken ? ' · broken' : ''}
                </Typography>
                {link.Context !== '' && (parts !== null
                    ? <Sentence before={parts[0]} match={parts[1]} after={parts[2]} width={90} />
                    : <Typography level="body-xs" sx={{ color: 'text.secondary', overflowWrap: 'anywhere' }}>{link.Context}</Typography>)}
            </Box>
        </Box>
    );
}

export default function LinksPanel({
    filename, heading, onGo, onChanged, onClose,
}: {
    // The file being read, and the heading the reader is on in it - null when
    // they are above the first heading, or the view cannot say.
    filename: string | null;
    heading: OutlineHeading | null;
    // Go somewhere: a file, a zero based line, and the heading's text for a
    // rendered view that has no lines.
    onGo: (file: string, line: number, heading: string) => void;
    // Something was written; the reader should read the file again.
    onChanged?: (files: string[]) => void;
    onClose?: () => void;
}) {
    const live: Place | null = filename === null ? null : { filename, heading };
    const [pinned, setPinned] = React.useState<Place | null>(null);
    const place = pinned ?? live;
    const [scope, setScope] = React.useState<'heading' | 'file'>('heading');
    const onHeading = scope === 'heading' && place !== null && place.heading !== null;

    // Following moves with every scroll; asking is held back until the reader
    // stops, so a quick scroll down a long file is one request rather than
    // thirty.
    const [asked, setAsked] = React.useState<Place | null>(place);
    React.useEffect(() => {
        if (samePlace(asked, place)) return;
        const t = window.setTimeout(() => setAsked(place), 250);
        return () => window.clearTimeout(t);
    });

    const target: PanelTarget | null = asked === null ? null
        : scope === 'heading' && asked.heading !== null
            ? { filename: asked.filename, line: asked.heading.LineNum }
            : { filename: asked.filename };
    const targetKey = target === null ? '' : JSON.stringify(target);

    const [links, setLinks] = React.useState<LinksAround | null>(null);
    const [mentions, setMentions] = React.useState<MentionsResult | null>(null);
    const [loading, setLoading] = React.useState(false);
    const [common, setCommon] = React.useState(false);
    const [busy, setBusy] = React.useState<Set<string>>(new Set());
    const [note, setNote] = React.useState<{ ok: boolean; text: string } | null>(null);
    const [again, setAgain] = React.useState(0);

    // Asking for a name made of common words is for one target, not a mode.
    React.useEffect(() => { setCommon(false); setNote(null); }, [targetKey]);

    React.useEffect(() => {
        if (target === null) { setLinks(null); setMentions(null); return; }
        const ctrl = new AbortController();
        setLoading(true);
        Promise.all([linksAround(target, ctrl.signal), mentionsOf(target, common, ctrl.signal)])
            .then(([l, m]) => {
                if (ctrl.signal.aborted) return;
                setLinks(l && l.Target ? l : null);
                setMentions(m && m.Target ? m : null);
            })
            .catch(() => { })
            .finally(() => { if (!ctrl.signal.aborted) setLoading(false); });
        return () => ctrl.abort();
        // targetKey stands for target.
    }, [targetKey, common, again]);

    const go = (file: string, line: number, head: string) => {
        if (pinned === null && place !== null) setPinned(place);
        onGo(file, line, head);
    };

    const link = async (ms: Mention[]) => {
        if (mentions === null || ms.length === 0) return;
        const keys = ms.map(m => mentionKey(m));
        setBusy(prev => new Set([...Array.from(prev), ...keys]));
        const t = mentions.Target;
        const res = await linkMentions({
            Hash: t.Kind === 'heading' ? t.Hash : '',
            Filename: t.Kind === 'file' ? t.Filename : '',
            Mentions: ms.map(refOf),
        });
        setBusy(prev => { const n = new Set(prev); keys.forEach(k => n.delete(k)); return n; });
        if (!res || res.Ok === undefined) {
            setNote({ ok: false, text: 'The server did not answer.' });
            return;
        }
        const failed = (res.Results || []).filter(r => !r.Ok);
        let text = res.Linked === 1 ? 'Linked one mention.' : `Linked ${res.Linked} mentions.`;
        if (res.NewId) text += ` ${targetLabel(t)} was given an :ID: to link to.`;
        if (failed.length > 0) text += ` ${failed.length} could not be: ${failed[0].Msg}`;
        setNote({ ok: res.Ok && failed.length === 0, text: res.Linked === 0 ? (res.Msg || 'Nothing was linked.') : text });
        setAgain(n => n + 1);
        if (res.Linked > 0 && onChanged) {
            const files = Array.from(new Set((res.Results || []).filter(r => r.Ok).map(r => r.Filename).concat(t.Filename)));
            onChanged(files);
        }
    };

    const t = (links && links.Ok ? links.Target : null) || (mentions && mentions.Ok ? mentions.Target : null);
    const inLinks = (links && links.Ok && links.In) || [];
    const outLinks = (links && links.Ok && links.Out) || [];
    const ms = (mentions && mentions.Ok && mentions.Mentions) || [];
    const groups = React.useMemo(() => groupMentions(ms), [ms]);
    const skipped = (t && t.Skipped) || [];
    const failMsg = (links && !links.Ok && links.Msg) || (mentions && !mentions.Ok && mentions.Msg) || '';

    return (
        <Sheet variant="outlined" sx={{ height: '100%', display: 'flex', flexDirection: 'column', minHeight: 0, borderRadius: 'sm' }}>
            <Box sx={{ p: 1.25, pb: 0.75, display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                <Box sx={{ minWidth: 0, flex: 1 }}>
                    <Typography level="title-sm" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {t ? targetLabel(t) : place ? baseName(place.filename) : 'Links'}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {t && t.Kind === 'heading'
                            ? `${(t.Olp || []).slice(0, -1).join(' › ') || baseName(t.Filename)} · line ${t.Line + 1}`
                            : place ? baseName(place.filename) : 'Open a file to see what links to it.'}
                    </Typography>
                </Box>
                {loading && <CircularProgress size="sm" sx={{ '--CircularProgress-size': '18px' }} />}
                <Tooltip size="sm" title={pinned ? 'Pinned here — click to follow the page again' : 'Following the page — click to stay on this one'}>
                    <IconButton size="sm" variant={pinned ? 'soft' : 'plain'} color={pinned ? 'primary' : 'neutral'}
                        onClick={() => setPinned(p => (p ? null : place))} disabled={place === null}>
                        {pinned ? <PushPinIcon /> : <PushPinOutlinedIcon />}
                    </IconButton>
                </Tooltip>
                {onClose && (
                    <IconButton size="sm" variant="plain" color="neutral" onClick={onClose} aria-label="Close the links panel">
                        <CloseIcon />
                    </IconButton>
                )}
            </Box>
            <Box sx={{ px: 1.25, pb: 1 }}>
                <ToggleButtonGroup size="sm" value={onHeading ? 'heading' : 'file'}
                    onChange={(_e, v) => v && setScope(v as 'heading' | 'file')}>
                    <Button value="heading" disabled={place === null || place.heading === null}>This heading</Button>
                    <Button value="file" startDecorator={<DescriptionOutlinedIcon />}>Whole file</Button>
                </ToggleButtonGroup>
            </Box>
            <Divider />

            <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto', pb: 1 }}>
                {failMsg !== '' && <Alert size="sm" color="warning" variant="soft" sx={{ m: 1 }}>{failMsg}</Alert>}
                {note !== null && (
                    <Alert size="sm" variant="soft" color={note.ok ? 'success' : 'warning'} sx={{ m: 1 }}
                        endDecorator={<IconButton size="sm" variant="plain" onClick={() => setNote(null)}><CloseIcon /></IconButton>}>
                        {note.text}
                    </Alert>
                )}

                <SectionTitle title="Linked from" count={inLinks.length} />
                {inLinks.length === 0 && (
                    <Typography level="body-xs" sx={{ px: 1.5, color: 'text.tertiary' }}>Nothing links here yet.</Typography>
                )}
                {inLinks.map((l, i) => <LinkEntry key={`in${i}`} link={l} side="in" onGo={go} />)}

                <SectionTitle title="Links out" count={outLinks.length} />
                {outLinks.length === 0 && (
                    <Typography level="body-xs" sx={{ px: 1.5, color: 'text.tertiary' }}>No links written here.</Typography>
                )}
                {outLinks.map((l, i) => <LinkEntry key={`out${i}`} link={l} side="out" onGo={go} />)}

                <SectionTitle
                    title="Unlinked mentions"
                    count={mentions ? mentions.Total : 0}
                    action={ms.length > 1 ? (
                        <Tooltip size="sm" title={`Link all ${ms.length} to ${t ? targetLabel(t) : 'this'}`}>
                            <Button size="sm" variant="soft" color="primary" startDecorator={<AddLinkIcon />}
                                disabled={busy.size > 0} onClick={() => link(ms)}>
                                Link all
                            </Button>
                        </Tooltip>
                    ) : undefined}
                />
                {t && searchedNote(t) !== '' && (
                    <Typography level="body-xs" sx={{ px: 1.5, pb: 0.5, color: 'text.tertiary' }}>{searchedNote(t)}</Typography>
                )}
                {skipped.length > 0 && !common && (
                    <Box sx={{ px: 1.5, pb: 0.5 }}>
                        <Button size="sm" variant="plain" startDecorator={<TravelExploreIcon />} onClick={() => setCommon(true)}>
                            Search for it anyway
                        </Button>
                    </Box>
                )}
                {mentions && mentions.Ok && ms.length === 0 && (t?.Terms || []).length > 0 && (
                    <Typography level="body-xs" sx={{ px: 1.5, color: 'text.tertiary' }}>
                        Every place it is named is already a link.
                    </Typography>
                )}
                {groups.map(g => (
                    <Box key={g.file} sx={{ mb: 0.5 }}>
                        <Box sx={{ px: 1.5, pt: 0.75, display: 'flex', alignItems: 'center', gap: 0.75 }}>
                            <DescriptionOutlinedIcon sx={{ fontSize: 14, color: 'text.tertiary' }} />
                            <Tooltip size="sm" title={g.file} placement="top-start">
                                <Typography level="body-xs" sx={{ fontWeight: 'lg', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                    {baseName(g.file)}
                                </Typography>
                            </Tooltip>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{g.count}</Typography>
                        </Box>
                        {g.headings.map(h => (
                            <Box key={`${g.file}:${h.hash}:${h.mentions[0].Line}`} sx={{ pl: 1 }}>
                                <Typography level="body-xs" sx={{ px: 1.5, pt: 0.25, color: 'text.tertiary', fontStyle: h.headline ? 'normal' : 'italic' }}>
                                    {h.headline || 'top of the file'}
                                </Typography>
                                {h.mentions.map(m => {
                                    const k = mentionKey(m);
                                    return (
                                        <Box key={k} sx={{
                                            display: 'flex', alignItems: 'flex-start', gap: 0.75, px: 1.5, py: 0.5,
                                            '&:hover': { background: 'var(--joy-palette-background-level1)' },
                                        }}>
                                            <Box role="button" tabIndex={0} sx={{ minWidth: 0, flex: 1, cursor: 'pointer' }}
                                                onClick={() => go(m.Filename, m.Line, m.Headline)}
                                                onKeyDown={e => { if (e.key === 'Enter') go(m.Filename, m.Line, m.Headline); }}>
                                                <Sentence before={m.Before} match={m.Text} after={m.After} />
                                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                                    line {m.Line + 1}
                                                    {m.InHeadline && (
                                                        <Chip size="sm" variant="soft" color="neutral" sx={{ ml: 0.75, fontSize: 10, minHeight: 14 }}>headline</Chip>
                                                    )}
                                                </Typography>
                                            </Box>
                                            <Tooltip size="sm" title={m.InHeadline
                                                ? 'Make this a link (it is in a headline, so that heading’s hash changes)'
                                                : 'Make this a link'}>
                                                <span>
                                                    <IconButton size="sm" variant="outlined" color="primary"
                                                        disabled={busy.has(k)} onClick={() => link([m])} aria-label="Link">
                                                        {busy.has(k) ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '14px' }} /> : <AddLinkIcon />}
                                                    </IconButton>
                                                </span>
                                            </Tooltip>
                                        </Box>
                                    );
                                })}
                            </Box>
                        ))}
                    </Box>
                ))}
                {mentions && mentions.Truncated && (
                    <Typography level="body-xs" sx={{ px: 1.5, pt: 0.5, color: 'text.tertiary' }}>
                        Showing {ms.length} of {mentions.Total}. Link these and the rest come up.
                    </Typography>
                )}
            </Box>
        </Sheet>
    );
}
