import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Chip from '@mui/joy/Chip';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import SearchIcon from '@mui/icons-material/Search';
import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import KeyboardReturnIcon from '@mui/icons-material/KeyboardReturn';
import { PlanTask, filterTasks, lengthText, taskNote, taskLength } from '../planner';
import { getStatusColor } from './statuslook';

// The tasks waiting to be placed, beside the day's hours.
//
// A task goes onto the day three ways, because each suits a different hand:
// dragged onto an hour (a mouse), picked here and then an hour tapped (a
// phone, where a list item cannot be dragged), or Enter on it (the
// keyboard), which puts it in the first free gap. The list is also where a
// block is dragged back to, to take it off the day - it lights up while one
// is over it.

export const DEFAULT_QUERY = '';
const CUSTOM = '\u0000custom';
const DEFAULT_OPT = '\u0000default';

export type PlannerListProps = {
    tasks: PlanTask[];
    defaultMins: number;
    query: string;
    savedQueries: { name: string; query: string }[];
    onQuery: (q: string) => void;
    armed: string | null;
    onArm: (hash: string | null) => void;
    onPlaceNext: (task: PlanTask) => void;
    onDragTask: (task: PlanTask | null) => void;
    onOpen: (task: PlanTask) => void;
    // A block is being dragged over the list: dropping it unplans it.
    dropping: boolean;
    backlogMins: number;
    backlogNoEst: number;
    filterRef: React.RefObject<HTMLInputElement>;
};

const PlannerList = React.forwardRef<HTMLDivElement, PlannerListProps>(function PlannerList(props, ref) {
    const { tasks, defaultMins, query, savedQueries, onQuery, armed, onArm, onPlaceNext, onDragTask, onOpen, dropping } = props;
    const [filter, setFilter] = React.useState('');
    const [custom, setCustom] = React.useState(false);
    const [draft, setDraft] = React.useState(query);
    const [cursor, setCursor] = React.useState(0);
    const shown = React.useMemo(() => filterTasks(tasks, filter), [tasks, filter]);
    const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);

    React.useEffect(() => { setCursor(c => Math.min(c, Math.max(0, shown.length - 1))); }, [shown.length]);

    const isSaved = query === DEFAULT_QUERY || savedQueries.some(q => q.query === query);
    const selectValue = custom || !isSaved ? CUSTOM : query === DEFAULT_QUERY ? DEFAULT_OPT : query;

    const focusRow = (i: number) => {
        const n = Math.max(0, Math.min(shown.length - 1, i));
        setCursor(n);
        rowRefs.current[n]?.focus();
    };

    // The filter box hands the arrows and Enter to the list, so typing a few
    // letters and pressing Enter places the best match.
    const onFilterKey = (e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); focusRow(0); }
        else if (e.key === 'Enter' && shown.length > 0) { e.preventDefault(); onPlaceNext(shown[0]); }
        else if (e.key === 'Escape') { setFilter(''); onArm(null); }
    };

    const onRowKey = (e: React.KeyboardEvent, t: PlanTask, i: number) => {
        if (e.key === 'ArrowDown') { e.preventDefault(); focusRow(i + 1); }
        else if (e.key === 'ArrowUp') {
            e.preventDefault();
            if (i === 0) props.filterRef.current?.focus(); else focusRow(i - 1);
        }
        else if (e.key === 'Enter') { e.preventDefault(); onPlaceNext(t); }
        else if (e.key === ' ') { e.preventDefault(); onArm(armed === t.Hash ? null : t.Hash); }
        else if (e.key === 'o') { e.preventDefault(); onOpen(t); }
        else if (e.key === 'Escape') { onArm(null); }
    };

    return (
        <Sheet ref={ref} variant="outlined" sx={{
            borderRadius: 'sm', p: 1, display: 'flex', flexDirection: 'column', gap: 0.75, minHeight: 0,
            outline: dropping ? '2px dashed' : 'none', outlineColor: 'primary.400',
            backgroundColor: dropping ? 'primary.softBg' : 'background.surface', transition: 'background-color 120ms',
        }}>
            <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1 }}>
                <Typography level="title-sm">To place</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {tasks.length} · {lengthText(props.backlogMins)}{props.backlogNoEst > 0 ? ` + ${props.backlogNoEst} unestimated` : ''}
                </Typography>
            </Box>
            <Select size="sm" value={selectValue} onChange={(_, v) => {
                if (v === CUSTOM) { setCustom(true); setDraft(query); return; }
                setCustom(false);
                onQuery(!v || v === DEFAULT_OPT ? DEFAULT_QUERY : (v as string));
            }}>
                <Option value={DEFAULT_OPT}>Open tasks</Option>
                {savedQueries.map(q => <Option key={q.name} value={q.query}>{q.name}</Option>)}
                <Option value={CUSTOM}>Query…</Option>
            </Select>
            {selectValue === CUSTOM && (
                <Input size="sm" placeholder='IsTask() && IsStatus("NEXT")' value={draft}
                    onChange={e => setDraft(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') onQuery(draft.trim()); }}
                    onBlur={() => { if (draft.trim() !== query) onQuery(draft.trim()); }}
                    sx={{ fontFamily: 'monospace', fontSize: '12px' }} />
            )}
            <Input size="sm" slotProps={{ input: { ref: props.filterRef } }} startDecorator={<SearchIcon sx={{ fontSize: 16 }} />}
                placeholder="Filter  ( / )" value={filter} onChange={e => setFilter(e.target.value)} onKeyDown={onFilterKey} />
            {dropping && (
                <Typography level="body-xs" sx={{ color: 'primary.plainColor', fontWeight: 600, textAlign: 'center', py: 0.5 }}>
                    Drop to take it off the day
                </Typography>
            )}
            <Box sx={{ overflowY: 'auto', minHeight: 0, flex: 1, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                {shown.length === 0 && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', p: 1, textAlign: 'center' }}>
                        {tasks.length === 0 ? 'Nothing left to place.' : 'Nothing matches the filter.'}
                    </Typography>
                )}
                {shown.map((t, i) => {
                    const note = taskNote(t);
                    const urgent = t.Late > 0 || (!!t.Deadline && t.DueIn <= 0);
                    const isArmed = armed === t.Hash;
                    return (
                        <Box key={t.Hash} ref={(el: HTMLDivElement | null) => { rowRefs.current[i] = el; }}
                            role="button" tabIndex={i === cursor ? 0 : -1} draggable
                            onDragStart={e => {
                                e.dataTransfer.setData('text/plain', t.Headline);
                                e.dataTransfer.setData('application/x-orgs-plan', t.Hash);
                                e.dataTransfer.effectAllowed = 'move';
                                onDragTask(t);
                            }}
                            onDragEnd={() => onDragTask(null)}
                            onClick={() => { setCursor(i); onArm(isArmed ? null : t.Hash); }}
                            onDoubleClick={() => onPlaceNext(t)}
                            onKeyDown={e => onRowKey(e, t, i)}
                            onFocus={() => setCursor(i)}
                            title="Drag onto an hour · click, then click an hour · Enter: first free slot · o: open"
                            sx={{
                                display: 'flex', alignItems: 'center', gap: 0.5, px: 0.75, py: 0.5, borderRadius: 'sm',
                                cursor: 'grab', userSelect: 'none', border: '1px solid',
                                borderColor: isArmed ? 'primary.outlinedBorder' : 'divider',
                                backgroundColor: isArmed ? 'primary.softBg' : 'background.level1',
                                '&:hover': { backgroundColor: isArmed ? 'primary.softHoverBg' : 'background.level2' },
                                '&:focus-visible': { outline: '2px solid', outlineColor: 'primary.500' },
                                '&:hover .plan-enter': { opacity: 1 },
                            }}>
                            <DragIndicatorIcon sx={{ fontSize: 16, color: 'text.tertiary', flexShrink: 0 }} />
                            <Box sx={{ minWidth: 0, flex: 1 }}>
                                <Typography level="body-sm" sx={{ fontSize: '12.5px', fontWeight: 500, lineHeight: 1.25, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                    {t.Status && (
                                        <Typography component="span" color={getStatusColor(t.Status) ?? 'neutral'}
                                            sx={{ fontSize: '10px', fontWeight: 700, mr: 0.5 }}>{t.Status}</Typography>
                                    )}
                                    {t.Priority && <Typography component="span" sx={{ fontSize: '10px', fontWeight: 700, mr: 0.5, color: 'warning.plainColor' }}>[#{t.Priority}]</Typography>}
                                    {t.Headline}
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                                    <Typography level="body-xs" sx={{ fontSize: '10.5px', color: t.EffortMins > 0 ? 'text.secondary' : 'text.tertiary' }}>
                                        {t.EffortMins > 0 ? lengthText(t.EffortMins) : `~${lengthText(taskLength(0, defaultMins))}`}
                                    </Typography>
                                    {note && <Typography level="body-xs" sx={{ fontSize: '10.5px', color: urgent ? 'danger.plainColor' : 'text.tertiary', fontWeight: urgent ? 600 : 400 }}>{note}</Typography>}
                                    <Typography level="body-xs" sx={{ fontSize: '10.5px', color: 'text.tertiary', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                        {(t.Filename.split('/').pop() || '')}
                                    </Typography>
                                </Box>
                            </Box>
                            {t.Tags.length > 0 && <Chip size="sm" variant="soft" sx={{ fontSize: '9.5px', minHeight: 0, px: 0.5 }}>{t.Tags[0]}</Chip>}
                            <Tooltip title="Put it in the first free slot (Enter)" size="sm">
                                <IconButton className="plan-enter" size="sm" variant="plain" sx={{ opacity: isArmed ? 1 : 0, minWidth: 24, minHeight: 24 }}
                                    onClick={e => { e.stopPropagation(); onPlaceNext(t); }}>
                                    <KeyboardReturnIcon sx={{ fontSize: 14 }} />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    );
                })}
            </Box>
        </Sheet>
    );
});

export default PlannerList;
