// Triage: the inbox (or the someday pile), one heading at a time.
//
// One item on screen, big enough to read without leaning in, and one key per
// decision. A key does the thing at once - refile opens the picker, schedule
// asks for a day in the words you would say - and the next item comes up; the
// wrong key is one `u` away, because every decision is an undoable
// `POST /review/act`. Used by the Inbox tab and by steps one and six of the
// weekly review.
//
// The list is asked for again after every decision rather than patched: a
// refile out of a file changes the hash of every heading after it there. The
// walk keeps its place by the items already shown (file and outline path,
// `itemKey` in review.ts), and remembers them while the tab is away, so a
// look at a heading in the Files tab comes back to the same spot.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import LinearProgress from '@mui/joy/LinearProgress';
import Alert from '@mui/joy/Alert';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import CircularProgress from '@mui/joy/CircularProgress';
import CelebrationRoundedIcon from '@mui/icons-material/CelebrationRounded';
import UndoRoundedIcon from '@mui/icons-material/UndoRounded';
import RestartAltRoundedIcon from '@mui/icons-material/RestartAltRounded';

import { useNav } from '../NavContext';
import { ReviewApi } from '../reviewApi';
import { ReviewItem, itemKey, nextUnseen } from '../review';
import {
    ItemCard, KeyLegend, KeyDef, Kbd, RefilePicker, DatePicker, TagPicker, useReviewActs, isShortcut,
} from './TriageParts';

export type TriageMode = 'inbox' | 'someday';

// What has been walked past, per list, for as long as the page is open.
const walked: { [mode: string]: string[] } = {};

type Picker = null | 'refile' | 'schedule' | 'tags' | 'promote';

export default function Triage(props: {
    mode: TriageMode;
    // Inside the weekly review: no page title, and the review keeps the tally.
    embedded?: boolean;
    onTally?: (name: string, delta: number) => void;
    // The panel to come back to from the Files tab.
    backApp?: string;
}) {
    const { mode } = props;
    const nav = useNav();
    const [items, setItems] = React.useState<ReviewItem[] | null>(null);
    const [error, setError] = React.useState('');
    const [seen, setSeen] = React.useState<Set<string>>(() => new Set(walked[mode] || []));
    const [picker, setPicker] = React.useState<Picker>(null);
    const acts = useReviewActs('triage-' + mode, props.onTally);

    const load = React.useCallback(async () => {
        const r = mode === 'someday' ? await ReviewApi.someday() : await ReviewApi.inbox();
        if (!r.Ok) {
            setError(r.Msg);
            return;
        }
        setError('');
        setItems(r.Items || []);
    }, [mode]);
    React.useEffect(() => { load(); }, [load]);
    React.useEffect(() => { setSeen(new Set(walked[mode] || [])); }, [mode]);

    const markSeen = (key: string, on: boolean) => {
        setSeen(prev => {
            const next = new Set(prev);
            if (on) next.add(key); else next.delete(key);
            walked[mode] = Array.from(next);
            return next;
        });
    };

    const { item, pos, total } = nextUnseen(items || [], seen);

    // A decision that ends the item (refile, archive, done) moves on; one that
    // only changes it (a date, a tag) leaves it on screen, changed, because
    // the usual next thing is to refile it.
    const decide = async (req: Parameters<typeof acts.act>[1], moveOn: boolean) => {
        if (!item) return;
        setPicker(null);
        const res = await acts.act(item, req);
        if (res.Ok && moveOn) markSeen(itemKey(item), true);
        await load();
    };
    const skip = () => { if (item) { markSeen(itemKey(item), true); acts.clearMessage(); } };
    const back = () => {
        // The last one walked past that is still in the list.
        const list = (items || []).filter(it => seen.has(itemKey(it)));
        const last = Array.from(seen).reverse().find(k => list.some(it => itemKey(it) === k));
        if (last) markSeen(last, false);
    };
    const undo = async () => {
        const key = await acts.undo();
        if (key) markSeen(key, false);
        await load();
    };
    const open = () => {
        if (!item) return;
        nav.toFile({
            filename: item.Filename, line: item.LineNum, heading: item.Headline,
            back: { app: props.backApp || 'Inbox', label: mode === 'someday' ? 'Back to the sweep' : 'Back to the inbox' },
        });
    };
    const startOver = () => { walked[mode] = []; setSeen(new Set()); };

    const keys: KeyDef[] = mode === 'someday' ? [
        { key: 'k', label: 'keep', run: skip },
        { key: 'p', label: 'promote', color: 'primary', run: () => setPicker('promote') },
        { key: 's', label: 'schedule', run: () => setPicker('schedule') },
        { key: 'a', label: 'drop', color: 'danger', run: () => decide({ Action: 'archive' }, true) },
    ] : [
        { key: 'r', label: 'refile', color: 'primary', run: () => setPicker('refile') },
        { key: 's', label: 'schedule', run: () => setPicker('schedule') },
        { key: 't', label: 'tag', run: () => setPicker('tags') },
        { key: 'a', label: 'archive', run: () => decide({ Action: 'archive' }, true) },
        { key: 'd', label: 'done', color: 'success', run: () => decide({ Action: 'done' }, true) },
    ];
    const always: KeyDef[] = [
        { key: '→', label: 'next', run: skip },
        { key: 'u', label: 'undo', run: undo, disabled: !acts.canUndo },
        { key: 'o', label: 'open', run: open },
    ];

    // The keys. Off while a picker is open (it has its own) and while typing.
    const live = React.useRef({ keys, always, picker, item, skip, back, undo, open });
    live.current = { keys, always, picker, item, skip, back, undo, open };
    React.useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            const l = live.current;
            if (l.picker || !isShortcut(e)) return;
            if (e.key === 'u') { e.preventDefault(); l.undo(); return; }
            if (!l.item) return;
            if (e.key === 'ArrowRight' || e.key === 'n') { e.preventDefault(); l.skip(); return; }
            if (e.key === 'ArrowLeft') { e.preventDefault(); l.back(); return; }
            if (e.key === 'o') { e.preventDefault(); l.open(); return; }
            const k = l.keys.find(x => x.key === e.key);
            if (k && !k.disabled) { e.preventDefault(); k.run(); }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, []);

    const title = mode === 'someday' ? 'Someday sweep' : 'Inbox';
    return (
        <Box sx={{ maxWidth: 820, mx: 'auto', width: '100%' }}>
            <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 2, mb: 1 }}>
                {!props.embedded && <Typography level="h3" sx={{ flex: 1 }}>{title}</Typography>}
                {props.embedded && <Box sx={{ flex: 1 }} />}
                {item && <Typography level="body-md" sx={{ color: 'text.secondary', fontVariantNumeric: 'tabular-nums' }}>{pos} of {total}</Typography>}
            </Box>
            {item && <LinearProgress determinate value={total ? (pos - 1) / total * 100 : 0} sx={{ mb: 2 }} />}

            {error && <Alert color="danger" sx={{ mb: 2 }}>{error}</Alert>}
            {!items && !error && <CircularProgress sx={{ display: 'block', mx: 'auto', my: 6 }} />}

            {items && !item && (
                <Box sx={{ textAlign: 'center', py: 6 }}>
                    <CelebrationRoundedIcon sx={{ fontSize: 64, color: 'success.400' }} />
                    <Typography level="h3" sx={{ mt: 1 }}>
                        {items.length === 0
                            ? (mode === 'someday' ? 'Nothing on the someday list.' : 'Inbox zero.')
                            : `Walked all ${total}.`}
                    </Typography>
                    <Typography level="body-md" sx={{ color: 'text.secondary', mt: 0.5 }}>
                        {items.length === 0
                            ? (mode === 'someday' ? 'Swept clean.' : 'Nothing left to decide. Enjoy it.')
                            : `What is left (${items.length}) is what you chose to leave for now.`}
                    </Typography>
                    <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center', mt: 2 }}>
                        {acts.canUndo && <Button variant="soft" startDecorator={<UndoRoundedIcon />} onClick={undo}>Undo the last one</Button>}
                        {items.length > 0 && <Button variant="plain" startDecorator={<RestartAltRoundedIcon />} onClick={startOver}>Walk them again</Button>}
                    </Box>
                </Box>
            )}

            {item && (
                <>
                    <ItemCard item={item} big />
                    <Box sx={{ mt: 2.5 }}>
                        <KeyLegend keys={[...keys, ...always]} />
                    </Box>
                </>
            )}

            <Box sx={{ minHeight: '2.5em', mt: 2, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 1 }}>
                {acts.message && (
                    <Typography level="body-sm" color={acts.message.tone === 'danger' ? 'danger' : acts.message.tone === 'success' ? 'success' : 'neutral'}>
                        {acts.message.tone === 'success' ? '✓ ' : ''}{acts.message.text}
                    </Typography>
                )}
                {acts.message && acts.message.tone === 'success' && acts.canUndo && (
                    <Button size="sm" variant="plain" startDecorator={<UndoRoundedIcon />} onClick={undo}>Undo</Button>
                )}
                {acts.busy && <CircularProgress size="sm" />}
            </Box>

            <RefilePicker open={picker === 'refile'} item={item} onClose={() => setPicker(null)}
                onPick={to => decide({ Action: 'refile', To: to }, true)} />
            <DatePicker open={picker === 'schedule'} title={`Schedule “${item?.Headline || ''}”`} current={item?.Scheduled}
                onClose={() => setPicker(null)}
                onPick={when => decide({ Action: 'schedule', When: when }, mode === 'someday')}
                onClear={() => decide({ Action: 'unschedule' }, false)} />
            <TagPicker open={picker === 'tags'} item={item} onClose={() => setPicker(null)}
                onSave={tags => decide({ Action: 'tags', Tags: tags }, false)} />
            <PromotePicker open={picker === 'promote'} onClose={() => setPicker(null)}
                onPick={kw => decide({ Action: 'promote', Keyword: kw }, true)} />
        </Box>
    );
}

// Promote to which keyword: n NEXT, t TODO.
function PromotePicker(props: { open: boolean; onClose: () => void; onPick: (kw: string) => void }) {
    React.useEffect(() => {
        if (!props.open) return;
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'n') { e.preventDefault(); props.onPick('NEXT'); }
            if (e.key === 't') { e.preventDefault(); props.onPick('TODO'); }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [props.open, props]);
    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog sx={{ width: 'min(380px, 94vw)' }}>
                <Typography level="title-md">Bring it back as</Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button sx={{ flex: 1 }} startDecorator={<Kbd>n</Kbd>} onClick={() => props.onPick('NEXT')}>NEXT</Button>
                    <Button sx={{ flex: 1 }} variant="soft" startDecorator={<Kbd>t</Kbd>} onClick={() => props.onPick('TODO')}>TODO</Button>
                </Box>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>The someday tag comes off too.</Typography>
            </ModalDialog>
        </Modal>
    );
}
