// Marker sets: more than one marker query on a chart, each drawn in its own
// colour, dash, width and shape - and the generator that makes a set per
// value of a tag or property that a regular expression picks out.
//
// The generator's arithmetic is here, pure and tested, because it writes
// queries: a value that is not escaped right makes a set that silently finds
// nothing, which looks exactly like "no markers there".

import { MarkerRow, markersFrom } from './gantt';
import { categorical } from './ganttstyle';

// One marker set as a view keeps it: a query (written, or a saved query's
// name) and how its markers are drawn.
export interface MarkerSet {
    label?: string;
    hidden?: boolean;
    storedQuery?: string;
    query?: string;
    dateKind?: string;
    color?: string;
    style?: string;
    width?: number;
    shape?: string;
}

// A string as a literal inside a query: the query language reads escapes in
// double-quoted strings, so a backslash has to be doubled to arrive as one -
// `\d` sent as-is reaches the server as a plain `d`.
export function queryString(s: string): string {
    return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}

// A value as a regular expression that matches exactly it.
export function reLiteral(v: string): string {
    return v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// The query that finds the headings a pattern picks out, for "show matches".
export function matchQuery(source: 'tag' | 'prop', prop: string, pattern: string): string {
    return source === 'tag'
        ? `HasTagMatching(${queryString(pattern)})`
        : `MatchProperty(${queryString(prop)}, ${queryString(pattern)})`;
}

// One unique value the pattern picked out, and what it covers.
export interface MatchGroup {
    // The value (or the pattern's first capture group, when it has one).
    key: string;
    // The tags or property values that make up the group - more than one
    // when a capture group gathers several, e.g. ^(M\d+)- over M1-alpha, M1-beta.
    values: string[];
    // The headings with a date of their own, which become markers.
    dated: string[];
    // Headings that match but have no date, so would draw nothing.
    undated: string[];
}

export interface MatchResult {
    groups: MatchGroup[];
    // Headings the server matched through a tag they inherit (a parent's or
    // the file's) rather than carry, which a group cannot be named after.
    inherited: string[];
}

// Group the rows the match query found by the value the pattern picks out.
// Tags are a heading's own; a property is read whatever case its name was
// written in. Groups come back in value order.
export function groupMatches(rows: MarkerRow[], source: 'tag' | 'prop', prop: string, re: RegExp): MatchResult {
    const groups = new Map<string, MatchGroup>();
    const inherited: string[] = [];
    for (const r of rows || []) {
        const name = r.Headline || '';
        const dated = markersFrom([r], 'either').length > 0;
        let picked: { key: string; value: string }[] = [];
        if (source === 'tag') {
            for (const t of r.Tags || []) {
                const m = t.match(re);
                if (m) picked.push({ key: m[1] !== undefined ? m[1] : t, value: t });
            }
        } else {
            const props = r.Props || {};
            const k = Object.keys(props).find(x => x.toUpperCase() === prop.trim().toUpperCase());
            const v = k ? (props[k] || '').trim() : '';
            const m = v ? v.match(re) : null;
            if (m) picked = [{ key: m[1] !== undefined ? m[1] : v, value: v }];
        }
        if (picked.length === 0) {
            if (source === 'tag') inherited.push(name);
            continue;
        }
        for (const p of picked) {
            const g = groups.get(p.key) || { key: p.key, values: [], dated: [], undated: [] };
            if (g.values.indexOf(p.value) < 0) g.values.push(p.value);
            (dated ? g.dated : g.undated).push(name);
            groups.set(p.key, g);
        }
    }
    const out = Array.from(groups.values()).sort((a, b) =>
        a.key.localeCompare(b.key, undefined, { numeric: true, sensitivity: 'base' }));
    return { groups: out, inherited };
}

// The query a group's set runs: the group's own tags, or its property values
// matched exactly.
export function groupQuery(source: 'tag' | 'prop', prop: string, g: MatchGroup): string {
    if (source === 'tag') return g.values.map(v => `HasTags(${queryString(v)})`).join(' || ');
    const alts = g.values.map(reLiteral);
    const re = alts.length === 1 ? `^${alts[0]}$` : `^(?:${alts.join('|')})$`;
    return `MatchProperty(${queryString(prop)}, ${queryString(re)})`;
}

// A set per group, coloured from the categorical palette starting after the
// sets a view already has, so a second generation does not repeat colours.
export function setsFor(source: 'tag' | 'prop', prop: string, groups: MatchGroup[], startColor: number): MarkerSet[] {
    return groups.map((g, i) => ({
        label: g.key,
        query: groupQuery(source, prop, g),
        dateKind: 'either',
        color: categorical(startColor + i),
        style: 'dashed',
        width: 1.5,
        shape: 'none',
    }));
}
