// The links panel's requests: /links/heading, /mentions and /mentions/link.
// Kept beside the panel rather than in db.ts, through ODb's own request
// helpers so the auth header and the login retry are the same as everywhere.

import { ODb } from './db';
import { Sets } from './config';
import { LinksAround, MentionsResult, MentionLinkRequest, MentionLinkResult, OutlineHeading } from './mentions';

// A heading by hash, or a file - and with a line, the heading that line is
// under. A hash goes in the query string, escaped by URLSearchParams, not
// base64'd again the way a path segment is.
export type PanelTarget = { hash: string } | { filename: string; line?: number };

function url(path: string, t: PanelTarget, extra: Record<string, string> = {}): URL {
    const u = new URL(Sets.orgsConnection + path);
    if ('hash' in t) u.searchParams.append('hash', t.hash);
    else {
        u.searchParams.append('filename', t.filename);
        if (t.line !== undefined && t.line >= 0) u.searchParams.append('line', String(t.line));
    }
    for (const [k, v] of Object.entries(extra)) u.searchParams.append(k, v);
    return u;
}

export async function linksAround(t: PanelTarget, signal: AbortSignal | null = null): Promise<LinksAround> {
    return await ODb.doGet<LinksAround>(url('/links/heading', t), signal);
}

export async function mentionsOf(t: PanelTarget, all: boolean = false, signal: AbortSignal | null = null): Promise<MentionsResult> {
    return await ODb.doGet<MentionsResult>(url('/mentions', t, all ? { all: 't' } : {}), signal);
}

export async function linkMentions(req: MentionLinkRequest): Promise<MentionLinkResult> {
    return await ODb.doPost<MentionLinkResult>(new URL(Sets.orgsConnection + '/mentions/link'), req);
}

// The open file's headings, for working out which one the reader is on.
export async function outlineOf(filename: string): Promise<OutlineHeading[]> {
    const res = await ODb.headingsIn(filename);
    return Array.isArray(res) ? res as OutlineHeading[] : [];
}
