// Requests for encrypted headings (crypt.go, cryptui.go), and the little
// shared state the views need about them: whether the server is holding a
// passphrase right now, and a way to tell every revealed block to close.
//
// Nothing here keeps plaintext or a passphrase. Both pass through on their way
// to the component that asked, and that component holds them in its own state
// and drops them on hide.

import * as React from 'react';
import { ODb } from './db';
import { Sets } from './config';

export type CryptState = {
    Ok: boolean;
    Msg: string;
    Mode: 'off' | 'symmetric' | 'key' | string;
    Tag: string;
    Unlocked: boolean;
    UnlockIn: number;
    UnlockSeconds: number;
};

export type CryptHeading = {
    Hash: string;
    Headline: string;
    Filename: string;
    Olp: string[] | null;
    Line: number;
    Encrypted: boolean;
    Key: string;
    Lines: number;
};

export type CryptHeadings = { Ok: boolean; Msg: string; Headings: CryptHeading[] | null; Tagged: number; Plain: number };

// A heading by hash, or by file and its headline's zero based row.
export type CryptTarget = { hash: string } | { filename: string; line: number };

export type CryptOpResult = {
    Ok: boolean;
    Msg: string;
    NeedPassphrase: boolean;
    WrongPassphrase: boolean;
    Hash: string;
    Headline: string;
    Filename: string;
    Line: number;
    Encrypted: boolean;
    Text: string;
    Html: string;
    Base: string;
    Unlocked: boolean;
    UnlockIn: number;
};

function u(path: string): URL {
    return new URL(Sets.orgsConnection + path);
}

// A failed fetch comes back from ODb as an empty array; this turns that into
// an answer the dialog can show.
function answer<T extends { Ok: boolean; Msg: string }>(res: any, what: string): T {
    if (res && typeof res === 'object' && !Array.isArray(res) && 'Ok' in res) return res as T;
    return { Ok: false, Msg: `Could not reach the server to ${what}.` } as T;
}

export async function cryptState(): Promise<CryptState> {
    return answer<CryptState>(await ODb.doGet<CryptState>(u('/crypt/state')), 'ask about encryption');
}

export async function cryptHeadingsIn(filename: string): Promise<CryptHeading[]> {
    const url = u('/crypt/file');
    url.searchParams.append('filename', filename);
    const res = await ODb.doGet<CryptHeadings>(url);
    return (res && Array.isArray(res.Headings)) ? res.Headings : [];
}

// The passphrase travels in a POST body, never in a url: urls end up in logs,
// in history and in the Referer of whatever the page fetches next.
export async function revealHeading(t: CryptTarget, passphrase: string, keep: boolean, html: boolean): Promise<CryptOpResult> {
    return answer<CryptOpResult>(await ODb.doPost<CryptOpResult>(u('/crypt/reveal'), { ...t, passphrase, keep, html }), 'reveal it');
}

export async function sealHeading(t: CryptTarget, passphrase: string, keep: boolean): Promise<CryptOpResult> {
    return answer<CryptOpResult>(await ODb.doPost<CryptOpResult>(u('/crypt/seal'), { ...t, passphrase, keep }), 'encrypt it');
}

export async function editHeading(t: CryptTarget, text: string, base: string, passphrase: string, keep: boolean): Promise<CryptOpResult> {
    return answer<CryptOpResult>(await ODb.doPost<CryptOpResult>(u('/crypt/edit'), { ...t, text, base, passphrase, keep }), 'save it');
}

// ---------------------------------------------------------------------------
// Locking, and the state every view shares
// ---------------------------------------------------------------------------

type Listener = () => void;
const lockListeners = new Set<Listener>();
const stateListeners = new Set<(s: CryptState) => void>();
let lastState: CryptState | null = null;

// Every revealed block subscribes; a lock anywhere closes them all.
export function onCryptLock(l: Listener): () => void {
    lockListeners.add(l);
    return () => { lockListeners.delete(l); };
}

export function announceLock() {
    lockListeners.forEach(l => { try { l(); } catch { /* one bad listener must not keep others open */ } });
}

function publish(s: CryptState) {
    const was = lastState;
    lastState = s;
    stateListeners.forEach(l => l(s));
    // The server's window ran out (or another tab locked it): what was opened
    // under it closes too.
    if (was && was.Unlocked && !s.Unlocked) announceLock();
}

// Forget the held passphrase on the server and close everything revealed here.
export async function lockNow(): Promise<void> {
    announceLock();
    await ODb.doPost(u('/crypt/lock'), {});
    publish(await cryptState());
}

// Asked after anything that may have changed the unlock, so the indicator
// does not wait for its next poll.
export async function refreshCryptState(): Promise<CryptState> {
    const s = await cryptState();
    if (s.Ok) publish(s);
    return s;
}

// One poll for however many views are watching: every few seconds while
// unlocked (a countdown is on screen), slowly otherwise, and not at all while
// the browser tab is hidden.
let pollTimer = 0;
async function poll() {
    pollTimer = 0;
    if (stateListeners.size === 0) return;
    if (document.visibilityState !== 'hidden') {
        try { await refreshCryptState(); } catch { /* the next tick tries again */ }
    }
    if (stateListeners.size === 0 || pollTimer !== 0) return;
    const fast = lastState !== null && lastState.Unlocked;
    pollTimer = window.setTimeout(poll, fast ? 5000 : 30000);
}

// The server's crypt state, kept fresh while a view that shows it is mounted.
export function useCryptState(active: boolean = true): CryptState | null {
    const [st, setSt] = React.useState<CryptState | null>(lastState);
    React.useEffect(() => {
        if (!active) return;
        let gone = false;
        const listen = (s: CryptState) => { if (!gone) setSt(s); };
        const first = stateListeners.size === 0;
        stateListeners.add(listen);
        if (first) poll();
        else if (lastState) setSt(lastState);
        return () => {
            gone = true;
            stateListeners.delete(listen);
            if (stateListeners.size === 0 && pollTimer !== 0) { window.clearTimeout(pollTimer); pollTimer = 0; }
        };
    }, [active]);
    return st;
}
