// The faster ways of working a gantt chart, each a strip or a box the page
// opens: quick add, find, the bar for rows picked up together, the question a
// ripple asks, and what changed since a baseline. They hold no plan of their
// own - each takes the tasks it is shown and hands back what was asked for -
// so the page stays the one place that writes.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import Chip from '@mui/joy/Chip';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Tooltip from '@mui/joy/Tooltip';
import CloseIcon from '@mui/icons-material/Close';
import AddIcon from '@mui/icons-material/Add';
import SearchIcon from '@mui/icons-material/Search';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import { GanttTask, dayKey } from '../gantt';
import { queryNeeds, parseQuickAdd, planQuickAdd, QuickPlan } from '../ganttquick';
import { RippleMove, PlanChange, personOf, propOf } from '../ganttplan';
import { fuzzyScoreAll, fuzzyTerms } from '../fuzzy';

// --- quick add --------------------------------------------------------------

export function QuickAddBar({
    follow, anchor, query, tasks, statuses, personProp, laneProp, busy, onAdd, onClose,
}: {
    // The task the new one goes straight after (the N key), or null.
    follow: GanttTask | null;
    // The task it goes beside when not following one: the selected task.
    anchor: GanttTask | null;
    query: string;
    tasks: GanttTask[];
    statuses: string[];
    personProp: string;
    laneProp: string;
    busy: boolean;
    onAdd: (plan: QuickPlan) => Promise<boolean>;
    onClose: () => void;
}) {
    const [text, setText] = React.useState('');
    const inputRef = React.useRef<HTMLInputElement | null>(null);
    React.useEffect(() => { inputRef.current?.focus(); }, [follow, anchor]);

    const needs = React.useMemo(() => queryNeeds(query), [query]);
    const planFor = React.useCallback((line: string) => planQuickAdd(parseQuickAdd(line, statuses), needs, {
        tasks, anchor: follow || anchor, followAnchor: !!follow, personProp, laneProp, statuses,
    }), [statuses, needs, tasks, follow, anchor, personProp, laneProp]);
    const line = parseQuickAdd(text, statuses);
    const plan = text.trim() ? planFor(text) : null;

    const add = async (lines: string[]) => {
        for (const l of lines) {
            if (!l.trim()) continue;
            const ok = await onAdd(planFor(l));
            if (!ok) return;
        }
        setText('');
        inputRef.current?.focus();
    };

    return (
        <Sheet variant="soft" color="primary" sx={{ borderRadius: 'sm', p: 1, display: 'flex', flexDirection: 'column', gap: 0.75 }}
            data-testid="gantt-quick-add">
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                <AddIcon fontSize="small" />
                <Input
                    size="sm"
                    sx={{ flex: 1, fontFamily: 'monospace' }}
                    placeholder="Write the spec 3d @Sam #design ^fri >kickoff !A RISK=high"
                    value={text}
                    disabled={busy}
                    slotProps={{ input: { ref: inputRef, 'aria-label': 'Quick add a task' } }}
                    onChange={e => setText(e.target.value)}
                    onKeyDown={e => {
                        if (e.key === 'Escape') { e.preventDefault(); onClose(); }
                        if (e.key === 'Enter' && text.trim() && plan && plan.warnings.every(w => !/needs a title|which file/.test(w))) {
                            e.preventDefault();
                            add([text]);
                        }
                    }}
                    // A pasted list is a task per line.
                    onPaste={e => {
                        const pasted = e.clipboardData.getData('text');
                        if (pasted.indexOf('\n') < 0) return;
                        e.preventDefault();
                        add(pasted.split(/\r?\n/));
                    }}
                />
                <Tooltip size="sm" title="Close (Esc)">
                    <IconButton size="sm" variant="plain" onClick={onClose} aria-label="Close quick add"><CloseIcon /></IconButton>
                </Tooltip>
            </Box>
            {follow && (
                <Typography level="body-xs">{`After ${follow.name} - it waits on it, and the next N follows this one.`}</Typography>
            )}
            {plan ? (
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', alignItems: 'center' }}>
                    <Chip size="sm" variant="solid" color="primary">{plan.add.Status}</Chip>
                    <Typography level="body-sm" sx={{ fontWeight: 600 }}>{plan.add.Headline || '…'}</Typography>
                    <Chip size="sm" variant="outlined">{plan.add.Effort}</Chip>
                    {plan.add.Start ? <Chip size="sm" variant="outlined">{plan.add.Start}</Chip> : null}
                    {plan.after ? <Chip size="sm" variant="outlined">{`after ${plan.after.name}`}</Chip> : null}
                    {line.person ? <Chip size="sm" variant="outlined">{`${personProp} ${line.person}`}</Chip> : null}
                    {plan.add.Tags.map(t => <Chip key={t} size="sm" variant="soft">{`:${t}:`}</Chip>)}
                    {Object.entries(line.props).map(([k, v]) => <Chip key={k} size="sm" variant="soft">{`${k}=${v}`}</Chip>)}
                    {plan.filled.map(f => (
                        <Chip key={f} size="sm" variant="soft" color="success">{`+ ${f}`}</Chip>
                    ))}
                    {plan.warnings.map(w => (
                        <Chip key={w} size="sm" variant="soft" color="warning">{w}</Chip>
                    ))}
                </Box>
            ) : (
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    Anything not below is the title. 3d effort · @person · #tag · ^date (fri, tom, +2w, 10-12) · &gt;waits on · !A
                    priority · KEY=value · a keyword first (NEXT ...). Whatever the chart's query needs is filled in. Enter adds and
                    stays open; paste several lines to add several.
                </Typography>
            )}
        </Sheet>
    );
}

// --- find ---------------------------------------------------------------------

export function FindDialog({ open, tasks, onJump, onClose }: {
    open: boolean;
    tasks: GanttTask[];
    onJump: (t: GanttTask) => void;
    onClose: () => void;
}) {
    const [q, setQ] = React.useState('');
    const [at, setAt] = React.useState(0);
    React.useEffect(() => { if (open) { setQ(''); setAt(0); } }, [open]);
    const hits = React.useMemo(() => {
        const terms = fuzzyTerms(q);
        const live = tasks.filter(t => !t.mark);
        if (terms.length === 0) return live.slice(0, 12);
        return live
            .map(t => ({ t, s: fuzzyScoreAll(terms, t.name, `${t.name} ${t.section} ${t.status || ''} ${(t.tags || []).join(' ')}`) }))
            .filter(x => x.s !== null)
            .sort((a, b) => (b.s as number) - (a.s as number))
            .slice(0, 12)
            .map(x => x.t);
    }, [q, tasks]);
    const go = (t: GanttTask | undefined) => { if (t) { onJump(t); onClose(); } };
    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog sx={{ width: 560, maxWidth: '94vw', top: '12vh', transform: 'translateX(-50%)', left: '50%', p: 1.25 }}
                data-testid="gantt-find">
                <Input
                    autoFocus
                    size="md"
                    startDecorator={<SearchIcon />}
                    placeholder="Jump to a task"
                    value={q}
                    onChange={e => { setQ(e.target.value); setAt(0); }}
                    onKeyDown={e => {
                        if (e.key === 'ArrowDown') { e.preventDefault(); setAt(a => Math.min(a + 1, hits.length - 1)); }
                        if (e.key === 'ArrowUp') { e.preventDefault(); setAt(a => Math.max(a - 1, 0)); }
                        if (e.key === 'Enter') { e.preventDefault(); go(hits[at]); }
                        if (e.key === 'Escape') { e.preventDefault(); onClose(); }
                    }}
                />
                <Box sx={{ display: 'flex', flexDirection: 'column', mt: 0.5, maxHeight: '50vh', overflowY: 'auto' }}>
                    {hits.length === 0 && (
                        <Typography level="body-sm" sx={{ color: 'text.tertiary', p: 1 }}>Nothing on the chart is called that.</Typography>
                    )}
                    {hits.map((t, i) => (
                        <Box key={t.id} onMouseEnter={() => setAt(i)} onClick={() => go(t)}
                            sx={{
                                display: 'flex', gap: 1, alignItems: 'baseline', px: 1, py: 0.6, borderRadius: 'sm', cursor: 'pointer',
                                bgcolor: i === at ? 'primary.softBg' : 'transparent',
                            }}>
                            {t.status && <Typography level="body-xs" sx={{ fontWeight: 700, minWidth: 0 }}>{t.status}</Typography>}
                            <Typography level="body-sm" sx={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                {t.name}
                            </Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', whiteSpace: 'nowrap' }}>
                                {`${t.section} · ${dayKey(t.start)}`}
                            </Typography>
                        </Box>
                    ))}
                </Box>
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 0.5 }}>↑ ↓ to choose · Enter to jump · Esc to close</Typography>
            </ModalDialog>
        </Modal>
    );
}

// --- rows picked up together -----------------------------------------------------

export interface BulkActions {
    shift: (days: number) => void;
    status: (s: string) => void;
    person: (p: string) => void;
    lane: (l: string) => void;
    tag: (t: string, add: boolean) => void;
    color: (c: string) => void;
    clear: () => void;
}

const BULK_SWATCHES = ['#4a90d9', '#2ecc71', '#e74c3c', '#f39c12', '#8e44ad', '#16a085', '#7f8c8d'];

export function BulkBar({ tasks, statuses, lanes, personProp, busy, act }: {
    tasks: GanttTask[];
    statuses: string[];
    lanes: string[];
    personProp: string;
    busy: boolean;
    act: BulkActions;
}) {
    const [person, setPerson] = React.useState('');
    const [tag, setTag] = React.useState('');
    const people = React.useMemo(() => {
        const s = new Set<string>();
        tasks.forEach(t => { const p = personOf(propOf(t.props, personProp)); if (p) s.add(p); });
        return Array.from(s).sort();
    }, [tasks, personProp]);
    return (
        <Sheet variant="soft" color="primary" sx={{ borderRadius: 'sm', px: 1.25, py: 0.75, display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}
            data-testid="gantt-bulk">
            <Chip size="sm" variant="solid" color="primary"
                endDecorator={<CloseIcon sx={{ fontSize: 14, cursor: 'pointer' }} onClick={act.clear} />}>
                {`${tasks.length} selected`}
            </Chip>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.25 }}>
                <Tooltip size="sm" title="A working day earlier (ctrl/alt+←)">
                    <IconButton size="sm" variant="outlined" disabled={busy} onClick={() => act.shift(-1)}><ChevronLeftIcon /></IconButton>
                </Tooltip>
                <Typography level="body-xs">move</Typography>
                <Tooltip size="sm" title="A working day later (ctrl/alt+→)">
                    <IconButton size="sm" variant="outlined" disabled={busy} onClick={() => act.shift(1)}><ChevronRightIcon /></IconButton>
                </Tooltip>
            </Box>
            <Select size="sm" placeholder="Keyword" value={null} disabled={busy || statuses.length === 0}
                onChange={(_, v) => v && act.status(v as string)} sx={{ minWidth: 110 }}>
                {statuses.map(s => <Option key={s} value={s}>{s}</Option>)}
            </Select>
            {lanes.length > 1 && (
                <Select size="sm" placeholder="Lane" value={null} disabled={busy}
                    onChange={(_, v) => v !== null && act.lane(v as string)} sx={{ minWidth: 110 }}>
                    {lanes.map(l => <Option key={l} value={l}>{l}</Option>)}
                </Select>
            )}
            <Input size="sm" placeholder={personProp} value={person} disabled={busy}
                sx={{ width: 140 }}
                slotProps={{ input: { list: 'gantt-bulk-people' } }}
                onChange={e => setPerson(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') { act.person(person.trim()); setPerson(''); } }}
                endDecorator={<Button size="sm" variant="plain" disabled={busy} onClick={() => { act.person(person.trim()); setPerson(''); }}>Set</Button>}
            />
            <datalist id="gantt-bulk-people">{people.map(p => <option key={p} value={p} />)}</datalist>
            <Input size="sm" placeholder="tag" value={tag} disabled={busy} sx={{ width: 150 }}
                onChange={e => setTag(e.target.value.replace(/[:\s]/g, ''))}
                onKeyDown={e => { if (e.key === 'Enter' && tag) { act.tag(tag, true); setTag(''); } }}
                endDecorator={
                    <>
                        <Button size="sm" variant="plain" disabled={busy || !tag} onClick={() => { act.tag(tag, true); setTag(''); }}>+</Button>
                        <Button size="sm" variant="plain" disabled={busy || !tag} onClick={() => { act.tag(tag, false); setTag(''); }}>−</Button>
                    </>
                }
            />
            <Box sx={{ display: 'flex', gap: 0.4 }}>
                {BULK_SWATCHES.map(c => (
                    <Box key={c} onClick={() => !busy && act.color(c)} title={`Colour them ${c}`}
                        sx={{ width: 16, height: 16, borderRadius: '50%', bgcolor: c, cursor: 'pointer', border: '1px solid rgba(0,0,0,.2)' }} />
                ))}
                <Box onClick={() => !busy && act.color('')} title="Back to the lane colour"
                    sx={{ width: 16, height: 16, borderRadius: '50%', cursor: 'pointer', border: '1px dashed', borderColor: 'neutral.400' }} />
            </Box>
        </Sheet>
    );
}

// --- the question a ripple asks ------------------------------------------------

export function RippleBar({ what, moves, busy, onAll, onOnly, onCancel }: {
    what: string;
    moves: RippleMove[];
    busy: boolean;
    onAll: () => void;
    onOnly: () => void;
    onCancel: () => void;
}) {
    const pushed = moves.filter(m => m.pushed);
    const follow = moves.filter(m => !m.pushed);
    const list = (ms: RippleMove[]) => ms.slice(0, 6).map(m => `${m.name} ${m.days > 0 ? '+' : ''}${m.days}d`).join(', ')
        + (ms.length > 6 ? `, and ${ms.length - 6} more` : '');
    return (
        <Sheet variant="soft" color="warning" sx={{ borderRadius: 'sm', px: 1.5, py: 1, display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}
            data-testid="gantt-ripple">
            <Box sx={{ flex: 1, minWidth: 260 }}>
                <Typography level="body-sm" sx={{ fontWeight: 600 }}>
                    {`${what} ${/^\d+ tasks$/.test(what) ? 'run' : 'runs'} into ${pushed.length} task${pushed.length === 1 ? '' : 's'} waiting on ${/^\d+ tasks$/.test(what) ? 'them' : 'it'}.`}
                </Typography>
                <Typography level="body-xs">{`Push: ${list(pushed)}`}</Typography>
                {follow.length > 0 && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{`Moves with it anyway (no date of its own): ${list(follow)}`}</Typography>
                )}
            </Box>
            <Button size="sm" disabled={busy} onClick={onAll}>Push them too (Enter)</Button>
            <Button size="sm" variant="outlined" disabled={busy} onClick={onOnly}>Only this</Button>
            <Button size="sm" variant="plain" color="neutral" disabled={busy} onClick={onCancel}>Cancel (Esc)</Button>
        </Sheet>
    );
}

// --- what changed since a baseline --------------------------------------------------

const KIND_COLOR: Record<string, 'primary' | 'warning' | 'success' | 'danger' | 'neutral'> = {
    moved: 'primary', longer: 'warning', shorter: 'success', added: 'neutral', removed: 'danger',
};

function signed(n: number): string {
    return `${n > 0 ? '+' : ''}${n}d`;
}

export function ChangesPanel({ baseline, changes, onJump, onClose }: {
    baseline: string;
    changes: PlanChange[];
    onJump: (hash: string) => void;
    onClose: () => void;
}) {
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 1.25 }} data-testid="gantt-changes">
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.75 }}>
                <Typography level="title-sm" sx={{ flex: 1 }}>{`Changed since ${baseline}`}</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{`${changes.length} change${changes.length === 1 ? '' : 's'}`}</Typography>
                <IconButton size="sm" variant="plain" onClick={onClose} aria-label="Close changes"><CloseIcon /></IconButton>
            </Box>
            {changes.length === 0 && (
                <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>Nothing has moved since this baseline was taken.</Typography>
            )}
            <Box sx={{ display: 'flex', flexDirection: 'column', maxHeight: 260, overflowY: 'auto' }}>
                {changes.map((c, i) => (
                    <Box key={i}
                        onClick={() => c.hash && onJump(c.hash)}
                        sx={{
                            display: 'flex', gap: 1, alignItems: 'center', px: 0.75, py: 0.4, borderRadius: 'sm',
                            cursor: c.hash ? 'pointer' : 'default', '&:hover': { bgcolor: c.hash ? 'background.level1' : undefined },
                        }}>
                        <Chip size="sm" variant="soft" color={KIND_COLOR[c.kind]} sx={{ minWidth: 64, justifyContent: 'center' }}>{c.kind}</Chip>
                        <Typography level="body-sm" sx={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {c.name}
                        </Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', whiteSpace: 'nowrap', fontVariantNumeric: 'tabular-nums' }}>
                            {c.kind === 'moved' ? `starts ${signed(c.startDelta)}${c.lengthDelta ? `, ${signed(c.lengthDelta)} long` : ''}` : ''}
                            {c.kind === 'longer' || c.kind === 'shorter' ? `${signed(c.lengthDelta)} long` : ''}
                            {c.endDelta && c.kind !== 'added' ? ` · ends ${signed(c.endDelta)}` : ''}
                        </Typography>
                    </Box>
                ))}
            </Box>
        </Sheet>
    );
}
