// What a Jupyter notebook holds, read in the browser before it is sent: enough
// for the import dialog to show what is about to arrive (its title, its cells,
// its pictures) and to name the org file after it. The conversion itself is
// the server's (internal/app/orgs/ipynb.go); this only counts.
//
// Pure, and tested in ipynb.test.ts; components/NewFileDialog.tsx draws it.

export type NotebookSummary = {
    title: string;
    // Where the title came from, so the preview can say "from its first
    // heading" rather than leave somebody wondering.
    titleFrom: 'metadata' | 'heading' | 'file';
    language: string;
    nbformat: number;
    cells: number;
    markdown: number;
    code: number;
    raw: number;
    // Code cells with at least one output, pictures among the outputs (and
    // pasted into markdown), and outputs that are errors.
    withOutput: number;
    pictures: number;
    errors: number;
};

type Json = { [k: string]: any };

const text = (v: any): string => Array.isArray(v) ? v.join('') : (typeof v === 'string' ? v : '');

// The first heading of a markdown cell, when the cell starts with one.
export function firstHeading(src: string): { level: number; text: string } | null {
    const lines = src.split('\n');
    for (let i = 0; i < lines.length; i++) {
        const l = lines[i];
        if (!l.trim()) continue;
        const m = /^ {0,3}(#{1,6})\s+(.*?)\s*#*\s*$/.exec(l);
        if (m) return { level: m[1].length, text: plainHeading(m[2]) };
        if (i + 1 < lines.length && /^ {0,3}=+\s*$/.test(lines[i + 1])) return { level: 1, text: plainHeading(l) };
        return null;
    }
    return null;
}

function plainHeading(s: string): string {
    return s.replace(/<a\s[^>]*>\s*<\/a>/gi, '')
        .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
        .replace(/\*\*|__|`|\*/g, '')
        .trim();
}

// The language a kernel names, as org names it - the server's orgLangFor.
export function orgLang(lang: string): string {
    const l = (lang || '').trim().toLowerCase();
    if (!l || l.startsWith('python') || l === 'ipython' || l.startsWith('pyspark')) return 'python';
    if (l === 'r' || l === 'ir') return 'R';
    if (l.startsWith('julia')) return 'julia';
    if (l === 'bash' || l === 'sh' || l === 'zsh') return 'sh';
    if (l === 'javascript' || l.startsWith('node')) return 'js';
    return l;
}

// A notebook's file name without its extension: "Penguins (v2).ipynb" is
// "Penguins (v2)".
export function stemOf(fileName: string): string {
    const base = (fileName || '').split(/[\\/]/).pop() || '';
    return base.replace(/\.ipynb$/i, '');
}

// The org file's name from the notebook's: its stem with the characters a
// file name may not hold taken out and spaces made dashes, so the default is
// one that passes nameError and reads like the notebook.
export function orgNameFor(fileName: string): string {
    const n = stemOf(fileName)
        .replace(/[\\/:*?"<>|]+/g, '')
        .trim()
        .replace(/\s+/g, '-')
        .replace(/^\.+/, '');
    return n || 'notebook';
}

const isPicture = (data: Json | undefined) =>
    !!data && Object.keys(data).some(k => k.startsWith('image/'));

// Reads a notebook, or says why it is not one. Throws nothing.
export function readNotebook(source: string, fileName = ''): { ok: true; nb: NotebookSummary } | { ok: false; error: string } {
    let j: Json;
    try {
        j = JSON.parse(source);
    } catch {
        return { ok: false, error: 'That is not a notebook: it is not json.' };
    }
    if (!j || typeof j !== 'object') return { ok: false, error: 'That is not a notebook.' };
    const nbformat = typeof j.nbformat === 'number' ? j.nbformat : 0;
    let cells: Json[] = Array.isArray(j.cells) ? j.cells : [];
    if (nbformat === 3) {
        // nbformat 3 kept its cells in worksheets, headings as cells of their own.
        cells = [];
        for (const ws of j.worksheets || []) {
            for (const c of ws.cells || []) {
                if (c.cell_type === 'heading') {
                    cells.push({ cell_type: 'markdown', source: '#'.repeat(Math.max(1, c.level || 1)) + ' ' + text(c.source) });
                } else if (c.cell_type === 'code') {
                    cells.push({
                        cell_type: 'code', source: text(c.input),
                        outputs: (c.outputs || []).map((o: Json) => ({
                            output_type: o.output_type === 'pyerr' ? 'error' : o.output_type,
                            data: o.png || o.jpeg ? { 'image/png': o.png || o.jpeg } : undefined,
                        })),
                    });
                } else {
                    cells.push(c);
                }
            }
        }
    } else if (nbformat !== 4 && !(nbformat === 0 && cells.length > 0)) {
        return { ok: false, error: `This is nbformat ${nbformat}; orgs reads 4 (and 3). Save it from a current Jupyter to upgrade it.` };
    }
    const meta: Json = j.metadata || {};
    const lang = orgLang(meta.kernelspec?.language || meta.language_info?.name || meta.kernelspec?.name || '');

    const nb: NotebookSummary = {
        title: '', titleFrom: 'file', language: lang, nbformat,
        cells: cells.length, markdown: 0, code: 0, raw: 0, withOutput: 0, pictures: 0, errors: 0,
    };
    if (typeof meta.title === 'string' && meta.title.trim()) {
        nb.title = meta.title.trim();
        nb.titleFrom = 'metadata';
    } else if (typeof meta.name === 'string' && meta.name.trim()) {
        nb.title = meta.name.trim();
        nb.titleFrom = 'metadata';
    }
    let lookedForHeading = false;
    for (const c of cells) {
        switch (c.cell_type) {
            case 'markdown': {
                nb.markdown++;
                for (const a of Object.values<Json>(c.attachments || {})) if (isPicture(a)) nb.pictures++;
                if (!nb.title && !lookedForHeading) {
                    lookedForHeading = true;
                    const h = firstHeading(text(c.source));
                    if (h && h.level === 1 && h.text) {
                        nb.title = h.text;
                        nb.titleFrom = 'heading';
                    }
                }
                break;
            }
            case 'code': {
                nb.code++;
                const outs: Json[] = c.outputs || [];
                if (outs.length) nb.withOutput++;
                for (const o of outs) {
                    if (o.output_type === 'error') nb.errors++;
                    if (isPicture(o.data)) nb.pictures++;
                }
                break;
            }
            case 'raw':
                nb.raw++;
                break;
        }
    }
    if (!nb.title) {
        const stem = stemOf(fileName).replace(/[_-]+/g, ' ').trim();
        nb.title = stem ? stem[0].toUpperCase() + stem.slice(1) : 'Notebook';
        nb.titleFrom = 'file';
    }
    return { ok: true, nb };
}

// A count with its noun: "1 picture", "3 pictures".
export function count(n: number, what: string): string {
    return `${n} ${what}${n === 1 ? '' : 's'}`;
}
