// Importing contacts from Apple Contacts, Google Contacts or Outlook.
//
// Drop (or pick) one or more .vcf files, choose how people already in the
// address book are treated, read what will happen, then import. The plan on
// screen is the server's own dry run of the same request, so what it says is
// what the import does - nothing here guesses at matching or merging.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import CircularProgress from '@mui/joy/CircularProgress';
import Divider from '@mui/joy/Divider';
import IconButton from '@mui/joy/IconButton';
import Modal from '@mui/joy/Modal';
import ModalClose from '@mui/joy/ModalClose';
import ModalDialog from '@mui/joy/ModalDialog';
import Sheet from '@mui/joy/Sheet';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import Typography from '@mui/joy/Typography';
import UploadFileIcon from '@mui/icons-material/UploadFileOutlined';
import CloseIcon from '@mui/icons-material/Close';
import PersonAddIcon from '@mui/icons-material/PersonAddAlt1Outlined';
import SyncIcon from '@mui/icons-material/SyncOutlined';
import CheckIcon from '@mui/icons-material/CheckCircleOutline';
import ErrorIcon from '@mui/icons-material/ErrorOutline';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';

import { ODb } from '../db';
import { Sets } from '../config';
import {
    ImportMode, MODES, ContactImportRequest, ContactImportResult, ContactImportItem,
    vcfText, countCards, joinVcfTexts, groupPlan, addSummary, importLabel, changedKeys,
} from '../vcardImport';

async function postImport(req: ContactImportRequest): Promise<ContactImportResult> {
    const url = new URL(Sets.orgsConnection + '/contacts/import');
    return await ODb.doPost<ContactImportResult>(url, req);
}

type Picked = { name: string; text: string; cards: number };

// One person in the plan, with the values behind the summary a click away.
function PlanRow({ it }: { it: ContactImportItem }) {
    const [open, setOpen] = React.useState(false);
    const added = changedKeys(it, 'add');
    const replaced = changedKeys(it, 'replace');
    const kept = (it.Changes || []).filter(c => c.How === 'kept');
    const changes = it.Changes || [];
    const icon = it.Action === 'add' ? <PersonAddIcon sx={{ fontSize: 18, color: 'success.500' }} />
        : it.Action === 'update' ? <SyncIcon sx={{ fontSize: 18, color: 'primary.500' }} />
        : it.Action === 'error' ? <ErrorIcon sx={{ fontSize: 18, color: 'danger.500' }} />
        : <CheckIcon sx={{ fontSize: 18, color: 'text.tertiary' }} />;
    const sub = it.Action === 'add' ? addSummary(it) : it.Reason;
    return (
        <Box sx={{ px: 1, py: 0.75, borderRadius: 'sm', '&:hover': { bgcolor: 'background.level1' } }}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                <Box sx={{ pt: 0.25 }}>{icon}</Box>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography level="body-sm" sx={{ fontWeight: 'md' }} noWrap>
                        {it.Name || `Card ${it.Card}`}
                        {it.Cards > 1 && (
                            <Typography component="span" level="body-xs" sx={{ color: 'text.tertiary', ml: 0.75 }}>
                                {it.Cards} cards in the file
                            </Typography>
                        )}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: it.Action === 'error' ? 'danger.500' : 'text.tertiary' }}>
                        {sub}
                    </Typography>
                    {it.Action === 'update' && (
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 0.5 }}>
                            {added.map(k => <Chip key={'a' + k} size="sm" variant="soft" color="success">+ {k}</Chip>)}
                            {replaced.map(k => <Chip key={'r' + k} size="sm" variant="soft" color="warning">{k}</Chip>)}
                            {(it.Tags || []).map(t => <Chip key={'t' + t} size="sm" variant="outlined">:{t}:</Chip>)}
                            {it.Notes && <Chip size="sm" variant="soft" color="success">+ note</Chip>}
                            {kept.map(c => (
                                <Chip key={'k' + c.Key} size="sm" variant="outlined" color="neutral"
                                    title={`Kept "${c.Old}" — the card says "${c.Value}"`}>
                                    keeps {c.Key}
                                </Chip>
                            ))}
                        </Box>
                    )}
                    {(it.Warnings || []).map((w, i) => (
                        <Typography key={i} level="body-xs" sx={{ color: 'warning.600', mt: 0.25 }}>{w}</Typography>
                    ))}
                </Box>
                {changes.length > 0 && (
                    <IconButton size="sm" variant="plain" onClick={() => setOpen(o => !o)}
                        aria-label={open ? 'Hide the values' : 'Show the values'}>
                        {open ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                    </IconButton>
                )}
            </Box>
            {open && (
                <Box component="table" sx={{
                    mt: 0.5, ml: 3.5, fontSize: 12, borderCollapse: 'collapse',
                    '& td': { py: 0.25, pr: 1.5, verticalAlign: 'top' },
                }}>
                    <tbody>
                        {changes.map((c, i) => (
                            <tr key={i}>
                                <Box component="td" sx={{ fontFamily: 'monospace', color: 'text.secondary', whiteSpace: 'nowrap' }}>{c.Key}</Box>
                                <Box component="td" sx={{ wordBreak: 'break-word', color: c.How === 'kept' ? 'text.tertiary' : 'text.primary' }}>
                                    {c.How === 'kept' ? <>keeps <b>{c.Old}</b> (card: {c.Value})</> : c.Value}
                                    {c.How === 'replace' && <Box component="span" sx={{ color: 'text.tertiary' }}> — was {c.Old}</Box>}
                                </Box>
                            </tr>
                        ))}
                    </tbody>
                </Box>
            )}
        </Box>
    );
}

function Section({ title, count, children, folded, onToggle }: {
    title: string; count: number; children: React.ReactNode; folded?: boolean; onToggle?: () => void;
}) {
    if (count === 0) return null;
    return (
        <Box sx={{ mb: 1 }}>
            <Box
                onClick={onToggle}
                sx={{
                    display: 'flex', alignItems: 'center', gap: 0.75, px: 1, py: 0.5,
                    cursor: onToggle ? 'pointer' : 'default',
                }}
            >
                <Typography level="title-sm">{title}</Typography>
                <Chip size="sm" variant="soft">{count}</Chip>
                {onToggle && (folded ? <ExpandMoreIcon sx={{ fontSize: 18 }} /> : <ExpandLessIcon sx={{ fontSize: 18 }} />)}
            </Box>
            {!folded && children}
        </Box>
    );
}

export default function ContactImport({
    open, onClose, onImported, type = 'contact',
}: {
    open: boolean;
    onClose: () => void;
    // Called once something was written, so the list behind can read itself
    // again.
    onImported: () => void;
    type?: string;
}) {
    const [files, setFiles] = React.useState<Picked[]>([]);
    const [mode, setMode] = React.useState<ImportMode>('merge');
    const [plan, setPlan] = React.useState<ContactImportResult | null>(null);
    const [done, setDone] = React.useState<ContactImportResult | null>(null);
    const [busy, setBusy] = React.useState<'' | 'plan' | 'import'>('');
    const [error, setError] = React.useState('');
    const [over, setOver] = React.useState(false);
    const [showSkipped, setShowSkipped] = React.useState(false);
    const inputRef = React.useRef<HTMLInputElement>(null);
    // Each dry run is numbered so a slow answer to an old choice of files or
    // mode cannot land on top of the answer to the new one.
    const asked = React.useRef(0);

    React.useEffect(() => {
        if (!open) return;
        setFiles([]); setPlan(null); setDone(null); setError(''); setBusy(''); setShowSkipped(false);
    }, [open]);

    const text = React.useMemo(() => joinVcfTexts(files.map(f => f.text)), [files]);

    React.useEffect(() => {
        if (!open || done || files.length === 0) { setPlan(null); return; }
        const n = ++asked.current;
        setBusy('plan');
        setError('');
        postImport({ Text: text, Mode: mode, DryRun: true, Type: type })
            .then(res => {
                if (n !== asked.current) return;
                if (!res || res.Ok === false) {
                    setPlan(null);
                    setError((res && res.Msg) || 'The server could not read that.');
                } else {
                    setPlan(res);
                }
            })
            .catch(e => { if (n === asked.current) setError(e?.message || 'Could not reach the server.'); })
            .finally(() => { if (n === asked.current) setBusy(''); });
    }, [open, text, mode, type, files.length, done]);

    const addFiles = async (list: FileList | File[] | null) => {
        if (!list) return;
        const picked: Picked[] = [];
        for (const f of Array.from(list)) {
            const t = vcfText(new Uint8Array(await f.arrayBuffer()));
            picked.push({ name: f.name, text: t, cards: countCards(t) });
        }
        setFiles(prev => {
            const names = new Set(picked.map(p => p.name));
            return [...prev.filter(p => !names.has(p.name)), ...picked];
        });
    };

    const doImport = async () => {
        setBusy('import');
        setError('');
        try {
            const res = await postImport({ Text: text, Mode: mode, DryRun: false, Type: type });
            if (!res || res.Ok === false) {
                setError((res && res.Msg) || 'The import did not go through.');
            } else {
                setDone(res);
                if (res.Added + res.Updated > 0) onImported();
            }
        } catch (e: any) {
            setError(e?.message || 'Could not reach the server.');
        }
        setBusy('');
    };

    const shown = done || plan;
    const g = groupPlan(shown);
    const totalCards = files.reduce((n, f) => n + f.cards, 0);
    const nothing = !!plan && plan.Added + plan.Updated === 0;

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog sx={{ width: 'min(680px, 94vw)', maxHeight: '88vh', display: 'flex', flexDirection: 'column', gap: 1.25 }}>
                <ModalClose />
                <Box>
                    <Typography level="title-lg">Import contacts</Typography>
                    <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                        vCard files (.vcf) from Apple Contacts, Google Contacts or Outlook.
                    </Typography>
                </Box>

                {!done && (
                    <>
                        <Sheet
                            variant="soft"
                            onDragOver={e => { e.preventDefault(); setOver(true); }}
                            onDragLeave={() => setOver(false)}
                            onDrop={e => { e.preventDefault(); setOver(false); addFiles(e.dataTransfer.files); }}
                            onClick={() => inputRef.current?.click()}
                            sx={{
                                borderRadius: 'md', p: 2, cursor: 'pointer', textAlign: 'center',
                                border: '1.5px dashed', borderColor: over ? 'primary.400' : 'neutral.outlinedBorder',
                                bgcolor: over ? 'primary.softBg' : undefined,
                            }}
                        >
                            <UploadFileIcon sx={{ fontSize: 28, color: 'text.tertiary' }} />
                            <Typography level="body-sm">
                                Drop .vcf files here, or <Typography component="span" color="primary" sx={{ fontWeight: 'md' }}>choose</Typography>
                            </Typography>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: 0.25 }}>
                                Apple: select contacts → File → Export → Export vCard. Google: Export → vCard.
                            </Typography>
                            <input
                                ref={inputRef} type="file" multiple
                                accept=".vcf,.vcard,text/vcard,text/x-vcard"
                                style={{ display: 'none' }}
                                onChange={e => { addFiles(e.target.files); e.target.value = ''; }}
                            />
                        </Sheet>

                        {files.length > 0 && (
                            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.75, alignItems: 'center' }}>
                                {files.map(f => (
                                    <Chip
                                        key={f.name} variant="outlined" size="sm"
                                        color={f.cards === 0 ? 'danger' : 'neutral'}
                                        endDecorator={
                                            <IconButton size="sm" variant="plain" aria-label={`Remove ${f.name}`}
                                                onClick={() => setFiles(prev => prev.filter(p => p.name !== f.name))}
                                                sx={{ '--IconButton-size': '18px' }}>
                                                <CloseIcon sx={{ fontSize: 14 }} />
                                            </IconButton>
                                        }
                                    >
                                        {f.name} · {f.cards === 0 ? 'no cards' : `${f.cards} card${f.cards === 1 ? '' : 's'}`}
                                    </Chip>
                                ))}
                                {files.length > 1 && (
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{totalCards} cards in all</Typography>
                                )}
                            </Box>
                        )}

                        <Box>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 0.5 }}>People already in your contacts</Typography>
                            <ToggleButtonGroup
                                size="sm" value={mode}
                                onChange={(_e, v) => v && setMode(v as ImportMode)}
                            >
                                {/* No Tooltip around these: the group reads its
                                    buttons' values off its direct children. */}
                                {MODES.map(m => <Button key={m.value} value={m.value} title={m.hint}>{m.label}</Button>)}
                            </ToggleButtonGroup>
                            <Typography level="body-xs" sx={{ color: 'text.secondary', mt: 0.5 }}>
                                {MODES.find(m => m.value === mode)?.hint}
                            </Typography>
                        </Box>
                    </>
                )}

                {error !== '' && (
                    <Typography level="body-sm" color="danger">{error}</Typography>
                )}

                {shown && (
                    <>
                        <Divider />
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                            <Typography level="title-sm">
                                {done ? 'Imported' : 'What will happen'}
                            </Typography>
                            <Chip size="sm" variant="soft" color="success">{shown.Added} {done ? 'added' : 'new'}</Chip>
                            <Chip size="sm" variant="soft" color="primary">{shown.Updated} {done ? 'updated' : 'to update'}</Chip>
                            <Chip size="sm" variant="soft">{shown.Skipped} {done ? 'skipped' : 'unchanged'}</Chip>
                            {shown.Failed > 0 && <Chip size="sm" variant="soft" color="danger">{shown.Failed} failed</Chip>}
                            {busy === 'plan' && <CircularProgress size="sm" sx={{ '--CircularProgress-size': '16px' }} />}
                        </Box>
                        {shown.Target && shown.Added > 0 && (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: -0.75 }}>
                                New people {done ? 'went' : 'go'} to {shown.Target}
                            </Typography>
                        )}
                        <Box sx={{ overflowY: 'auto', flex: 1, minHeight: 80, mx: -1 }}>
                            <Section title="Errors" count={g.error.length}>
                                {g.error.map(it => <PlanRow key={'e' + it.Card} it={it} />)}
                            </Section>
                            <Section title={done ? 'Added' : 'New'} count={g.add.length}>
                                {g.add.map(it => <PlanRow key={'a' + it.Card} it={it} />)}
                            </Section>
                            <Section title={done ? 'Updated' : 'Will be updated'} count={g.update.length}>
                                {g.update.map(it => <PlanRow key={'u' + it.Card} it={it} />)}
                            </Section>
                            <Section
                                title={done ? 'Skipped' : 'Left as they are'} count={g.skip.length}
                                folded={!showSkipped} onToggle={() => setShowSkipped(s => !s)}
                            >
                                {g.skip.map(it => <PlanRow key={'s' + it.Card} it={it} />)}
                            </Section>
                        </Box>
                    </>
                )}

                <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, pt: 0.5 }}>
                    {done ? (
                        <Button size="sm" onClick={onClose}>Done</Button>
                    ) : (
                        <>
                            <Button size="sm" variant="plain" color="neutral" onClick={onClose}>Cancel</Button>
                            <Button
                                size="sm"
                                disabled={!plan || nothing || busy === 'plan'}
                                loading={busy === 'import'}
                                onClick={doImport}
                            >
                                {importLabel(plan)}
                            </Button>
                        </>
                    )}
                </Box>
            </ModalDialog>
        </Modal>
    );
}
