// ---------------------------------------------------------------------------
// The file, read the way the Org view reads it
// ---------------------------------------------------------------------------

type Analysis = { lines: string[]; states: LineState[]; todo: TodoStates; regions: Map<number, Region> | null };

function analyse(state: EditorState): Analysis {
    const lines = state.doc.toJSON();
    return { lines, states: walk(lines), todo: todoStates(state.doc.toString()), regions: null };
}

// Worked out again on every edit: the block and drawer state is carried down
// the file, so a line typed near the top can recolour everything under it.
const analysisField = StateField.define<Analysis>({
    create: analyse,
    update: (a, tr) => (tr.docChanged ? analyse(tr.state) : a),
});

// The outline is only wanted when something asks about folding, so it is
// worked out then and kept on the analysis it came from.
function regionsOf(a: Analysis): Map<number, Region> {
    if (a.regions === null) a.regions = outline(a.lines, a.states);
    return a.regions;
}

// Headings and drawers fold as they do in the Org view (za / zc / zo / zM /
// zR in vim, TAB on a heading line, or the gutter).
const orgFolding = foldService.of((state, lineStart) => {
    const line = state.doc.lineAt(lineStart);
    const r = regionsOf(state.field(analysisField)).get(line.number - 1);
    if (!r) return null;
    const last = state.doc.line(Math.min(r.end + 1, state.doc.lines));
    return last.to > line.to ? { from: line.to, to: last.to } : null;
});

// Classes rather than inline colours, so a theme change is one reconfigure
// rather than a repaint of every span.
const markCache = new Map<string, Decoration>();
function markFor(cls: string): Decoration {
    let d = markCache.get(cls);
    if (!d) { d = Decoration.mark({ class: cls }); markCache.set(cls, d); }
    return d;
}

const orgHighlight = ViewPlugin.fromClass(class {
    decorations: DecorationSet;
    constructor(view: EditorView) { this.decorations = this.build(view); }
    update(u: ViewUpdate) {
        if (u.docChanged || u.viewportChanged) this.decorations = this.build(u.view);
    }
    build(view: EditorView): DecorationSet {
        const a = view.state.field(analysisField);
        const b = new RangeSetBuilder<Decoration>();
        for (const { from, to } of view.visibleRanges) {
            let pos = from;
            while (pos <= to) {
                const line = view.state.doc.lineAt(pos);
                const st = a.states[line.number - 1];
                if (st) {
                    let at = line.from;
                    for (const t of lineTokens(line.text, a.todo, st.block, st.drawer, st.lang, st.code)) {
                        const end = at + t.s.length;
                        if (t.c !== 'fg' || t.bold || t.italic || t.underline || t.strike) {
                            let cls = `cm-o-${t.c}`;
                            if (t.bold) cls += ' cm-o-b';
                            if (t.italic) cls += ' cm-o-i';
                            if (t.underline) cls += ' cm-o-u';
                            if (t.strike) cls += ' cm-o-s';
                            if (end > at) b.add(at, end, markFor(cls));
                        }
                        at = end;
                    }
                }
                pos = line.to + 1;
            }
        }
        return b.finish();
    }
}, { decorations: v => v.decorations });

function editorTheme(p: Palette, dark: boolean): Extension {
    const mix = (c: string, pct: number) => `color-mix(in srgb, ${c} ${pct}%, transparent)`;
    const spec: Record<string, any> = {
        '&': { height: '100%', backgroundColor: p.bg, color: p.fg, fontSize: '13px' },
        '&.cm-focused': { outline: 'none' },
        '.cm-scroller': { fontFamily: MONO, lineHeight: 1.55 },
        '.cm-content': { caretColor: p.fg },
        '.cm-gutters': { backgroundColor: p.gutterBg, color: p.gutter, border: 'none' },
        '.cm-activeLine': { backgroundColor: mix(p.selBg, 45) },
        '.cm-activeLineGutter': { backgroundColor: mix(p.selBg, 70) },
        '.cm-selectionBackground, &.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground': { backgroundColor: p.selBg },
        '.cm-cursor, .cm-dropCursor': { borderLeftColor: p.fg },
        '.cm-fat-cursor': { background: `${mix(p.h1, 70)} !important`, color: `${p.bg} !important` },
        '&:not(.cm-focused) .cm-fat-cursor': { background: 'none !important', outline: `1px solid ${p.h1}` },
        '.cm-panels': { backgroundColor: p.gutterBg, color: p.fg },
        '.cm-panels input, .cm-panels button': { color: p.fg },
        '.cm-foldPlaceholder': { backgroundColor: 'transparent', border: 'none', color: p.gutter },
        '.cm-searchMatch': { backgroundColor: mix(p.h3 || p.fg, 30) },
        '.cm-selectionMatch': { backgroundColor: mix(p.selBg, 60) },
        '.cm-o-b': { fontWeight: 700 },
        '.cm-o-i': { fontStyle: 'italic' },
        '.cm-o-u': { textDecoration: 'underline' },
        '.cm-o-s': { textDecoration: 'line-through' },
        // Fields of an expansion: every one marked, the one the cursor is in
        // marked harder, and an empty one saying what it is for.
        '.cm-snip-field': { backgroundColor: mix(p.h2 || p.fg, 14), borderRadius: '2px', outline: `1px dashed ${mix(p.h2 || p.fg, 55)}` },
        '.cm-snip-active': { backgroundColor: mix(p.h1 || p.fg, 24), outline: `1px solid ${p.h1 || p.fg}` },
        '.cm-snip-prompt': { color: p.gutter, fontStyle: 'italic', opacity: 0.85, padding: '0 2px' },
        '.cm-tooltip.cm-cap-menu': {
            backgroundColor: p.gutterBg, color: p.fg, border: `1px solid ${mix(p.fg, 25)}`,
            borderRadius: '6px', padding: '4px', minWidth: '260px', maxWidth: '420px',
            boxShadow: '0 6px 24px rgba(0,0,0,0.25)', fontFamily: MONO, fontSize: '12px',
        },
        '.cm-cap-head': { color: p.gutter, padding: '2px 6px 4px' },
        '.cm-cap-item': { padding: '3px 6px', borderRadius: '4px', cursor: 'pointer', display: 'flex', gap: '8px' },
        '.cm-cap-item[aria-selected=true]': { backgroundColor: mix(p.h1 || p.fg, 28) },
        '.cm-cap-num': { color: p.gutter, width: '1.2em', textAlign: 'right' },
        '.cm-cap-where': { color: p.gutter, marginLeft: 'auto', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' },
    };
    for (const k of Object.keys(p)) spec[`.cm-o-${k}`] = { color: p[k] };
    return EditorView.theme(spec, { dark });
}

// ---------------------------------------------------------------------------
// Fields to step through
// ---------------------------------------------------------------------------

type Field = { from: number; to: number; key: string; prompt: string; kind: FieldKind };

type Session = {
    fields: Field[];
    // The fields visited, as indexes into `fields`: the first of each key.
    order: number[];
    active: number;  // index into order
    start: number;
    end: number;
    // A capture can be taken back out whole; a block just stops.
    capture: boolean;
    // A line whose fields were all left empty goes when the step finishes
    // (a property nobody named), and a drawer left empty with it.
    tidy: boolean;
};

const startSession = StateEffect.define<Session>();
const setActive = StateEffect.define<number>();
const endSession = StateEffect.define<null>();

const sessionField = StateField.define<Session | null>({
    create: () => null,
    update(s, tr) {
        for (const e of tr.effects) {
            if (e.is(startSession)) return e.value;
            if (e.is(endSession)) return null;
        }
        if (s === null) return null;
        let next = s;
        if (tr.docChanged) {
            const m = (p: number, assoc: number) => tr.changes.mapPos(p, assoc);
            next = {
                ...s,
                start: m(s.start, -1),
                end: m(s.end, 1),
                fields: s.fields.map(f => ({ ...f, from: m(f.from, -1), to: m(f.to, 1) })),
            };
        }
        for (const e of tr.effects) if (e.is(setActive)) next = { ...next, active: e.value };
        return next;
    },
    provide: f => EditorView.decorations.from(f, s => {
        if (s === null) return Decoration.none;
        const activeField = s.order[s.active];
        const ranges = s.fields
            .map((fl, i) => {
                const cls = i === activeField || (s.fields[activeField] && fl.key === s.fields[activeField].key)
                    ? 'cm-snip-field cm-snip-active' : 'cm-snip-field';
                return fl.to > fl.from
                    ? Decoration.mark({ class: cls }).range(fl.from, fl.to)
                    : Decoration.widget({ widget: new PromptWidget(fl.prompt, cls), side: 1 }).range(fl.from);
            })
            .sort((a, b) => a.from - b.from);
        return Decoration.set(ranges, true);
    }),
});

class PromptWidget extends WidgetType {
    constructor(readonly prompt: string, readonly cls: string) { super(); }
    eq(o: PromptWidget) { return o.prompt === this.prompt && o.cls === this.cls; }
    toDOM() {
        const s = document.createElement('span');
        s.className = `${this.cls} cm-snip-prompt`;
        s.textContent = this.prompt;
        return s;
    }
    ignoreEvent() { return false; }
}

// One value written twice: what is typed into the first of a key is copied to
// the rest as part of the same edit, so undo takes both back together.
const mirrorFields = EditorState.transactionFilter.of(tr => {
    if (!tr.docChanged) return tr;
    const s = tr.state.field(sessionField, false);
    if (!s) return tr;
    const changes: ChangeSpec[] = [];
    const firstOf = new Map<string, Field>();
    for (const f of s.fields) {
        const p = firstOf.get(f.key);
        if (!p) { firstOf.set(f.key, f); continue; }
        const want = tr.state.sliceDoc(p.from, p.to);
        if (tr.state.sliceDoc(f.from, f.to) !== want) changes.push({ from: f.from, to: f.to, insert: want });
    }
    if (changes.length === 0) return tr;
    return [tr, { changes, sequential: true }] as TransactionSpec[];
});

function sessionFrom(exp: Expansion, at: number, capture: boolean): Session {
    const fields = exp.fields.map(f => ({ ...f, from: f.from + at, to: f.to + at }));
    const seen = new Set<string>();
    const order: number[] = [];
    fields.forEach((f, i) => { if (!seen.has(f.key)) { seen.add(f.key); order.push(i); } });
    return { fields, order, active: 0, start: at, end: at + exp.text.length, capture, tidy: false };
}

function selectField(s: Session, i: number): EditorSelection {
    const f = s.fields[s.order[i]];
    return EditorSelection.single(f.from, f.to);
}

// Put an expansion in place of [from, to] and start stepping through it.
function insertExpansion(view: EditorView, from: number, to: number, exp: Expansion, capture: boolean) {
    const s = sessionFrom(exp, from, capture);
    view.dispatch({
        changes: { from, to, insert: exp.text },
        effects: startSession.of(s),
        selection: s.order.length > 0 ? selectField(s, 0) : EditorSelection.cursor(from + exp.text.length),
        userEvent: 'input.complete',
        scrollIntoView: true,
    });
    if (s.order.length === 0) view.dispatch({ effects: endSession.of(null) });
}

function gotoField(view: EditorView, delta: number): boolean {
    const s = view.state.field(sessionField);
    if (!s) return false;
    const i = s.active + delta;
    if (i < 0) return true;
    if (i >= s.order.length) { finishSession(view); return true; }
    view.dispatch({ effects: setActive.of(i), selection: selectField(s, i), scrollIntoView: true });
    return true;
}

// Done stepping: tags are written the way org writes them, and in a capture a
// line that was only a field nobody filled in goes, as it would from the
// capture dialog. The cursor ends after the expansion.
function finishSession(view: EditorView) {
    const s = view.state.field(sessionField);
    if (!s) return;
    const doc = view.state.doc;
    const changes: ChangeSpec[] = [];
    const drop = new Set<number>();
    for (const f of s.fields) {
        const text = doc.sliceString(f.from, f.to);
        if (f.kind === 'tags') {
            // The space before the field is part of the separator.
            const lead = f.from > 0 && doc.sliceString(f.from - 1, f.from) === ' ' ? f.from - 1 : f.from;
            changes.push({ from: lead, to: f.to, insert: formatTags(text) });
            continue;
        }
        if (s.tidy && text.trim() === '') {
            const line = doc.lineAt(f.from);
            const onLine = s.fields.filter(g => g.from >= line.from && g.to <= line.to);
            if (onLine.every(g => doc.sliceString(g.from, g.to).trim() === '')) {
                drop.add(line.number);
                const above = line.number > 1 ? doc.line(line.number - 1) : null;
                const below = line.number < doc.lines ? doc.line(line.number + 1) : null;
                if (above && below && /^\s*:PROPERTIES:\s*$/i.test(above.text) && /^\s*:END:\s*$/i.test(below.text)) {
                    drop.add(above.number);
                    drop.add(below.number);
                }
            }
            continue;
        }
        if (s.capture && text.trim() === '') {
            const line = doc.lineAt(f.from);
            const rest = line.text.slice(0, f.from - line.from) + line.text.slice(f.to - line.from);
            if (isLeftoverLine(rest) && !HEADING.test(line.text)) drop.add(line.number);
        }
    }
    for (const n of Array.from(drop)) {
        const line = doc.line(n);
        if (line.to < doc.length) changes.push({ from: line.from, to: line.to + 1 });
        else if (line.from > 0) changes.push({ from: line.from - 1, to: line.to });
        else changes.push({ from: line.from, to: line.to });
    }
    const set = view.state.changes(changes);
    view.dispatch({
        changes: set,
        effects: endSession.of(null),
        selection: EditorSelection.cursor(set.mapPos(s.end, 1)),
        userEvent: 'input.complete',
    });
}

// ESC in a capture: everything it wrote, `<c` included, comes back out.
function cancelCapture(view: EditorView) {
    const s = view.state.field(sessionField);
    if (!s) return;
    view.dispatch({
        changes: { from: s.start, to: s.end },
        effects: endSession.of(null),
        selection: EditorSelection.cursor(s.start),
        userEvent: 'delete',
    });
}

// Moving off the expansion (a click elsewhere, a search) ends it as if it had
// been tabbed off.
const leaveSession = ViewPlugin.fromClass(class {
    update(u: ViewUpdate) {
        const s = u.state.field(sessionField);
        if (!s || !u.selectionSet) return;
        const h = u.state.selection.main.head;
        if (h < s.start || h > s.end) Promise.resolve().then(() => finishSession(u.view));
    }
});

// ---------------------------------------------------------------------------
// The capture template menu
// ---------------------------------------------------------------------------

type Menu = {
    from: number;     // where `<c` starts
    to: number;       // the cursor, after it
    filter: string;
    index: number;
    items: CaptureTemplate[] | null;  // null while they are being asked for
    error: string;
    level: number;
    indent: string;
};

const openMenu = StateEffect.define<Menu>();
const updateMenu = StateEffect.define<Partial<Menu>>();
const closeMenu = StateEffect.define<null>();

const menuField = StateField.define<Menu | null>({
    create: () => null,
    update(m, tr) {
        for (const e of tr.effects) {
            if (e.is(openMenu)) return e.value;
            if (e.is(closeMenu)) return null;
            if (e.is(updateMenu) && m) m = { ...m, ...e.value };
        }
        // Anything else editing the text under it makes the menu meaningless.
        if (m && tr.docChanged) return null;
        return m;
    },
    provide: f => showTooltip.compute([f], st => {
        const m = st.field(f);
        return m ? menuTooltip(m.to) : null;
    }),
});

// One tooltip object per position, so CodeMirror keeps the same one open and
// updates it rather than rebuilding it on every keystroke.
let lastTip: { pos: number; tip: Tooltip } | null = null;
function menuTooltip(pos: number): Tooltip {
    if (lastTip && lastTip.pos === pos) return lastTip.tip;
    const tip: Tooltip = { pos, above: false, create: createMenuView };
    lastTip = { pos, tip };
    return tip;
}

function menuItems(m: Menu): CaptureTemplate[] {
    const all = m.items || [];
    const terms = fuzzyTerms(m.filter);
    if (terms.length === 0) return all;
    return all
        .map(t => ({ t, n: fuzzyScoreAll(terms, t.Name, `${t.Name} ${targetText(t)}`) }))
        .filter(x => x.n !== null)
        .sort((a, b) => (b.n as number) - (a.n as number))
        .map(x => x.t);
}

function createMenuView(view: EditorView): TooltipView {
    const dom = document.createElement('div');
    dom.className = 'cm-cap-menu';
    const draw = (m: Menu | null) => {
        dom.textContent = '';
        if (!m) return;
        const head = document.createElement('div');
        head.className = 'cm-cap-head';
        head.textContent = m.filter !== ''
            ? `capture: ${m.filter}`
            : 'capture template — type to filter, ↑↓ / 1-9, Enter, Esc';
        dom.appendChild(head);
        if (m.items === null || m.error !== '') {
            const d = document.createElement('div');
            d.className = 'cm-cap-head';
            d.textContent = m.error || 'loading…';
            dom.appendChild(d);
            return;
        }
        const items = menuItems(m);
        if (items.length === 0) {
            const d = document.createElement('div');
            d.className = 'cm-cap-head';
            d.textContent = m.items.length === 0 ? 'the server has no capture templates' : 'nothing matches';
            dom.appendChild(d);
        }
        items.forEach((t, i) => {
            const row = document.createElement('div');
            row.className = 'cm-cap-item';
            row.setAttribute('aria-selected', String(i === m.index));
            const n = document.createElement('span');
            n.className = 'cm-cap-num';
            n.textContent = i < 9 ? String(i + 1) : '';
            const name = document.createElement('span');
            name.textContent = t.Name;
            const where = document.createElement('span');
            where.className = 'cm-cap-where';
            where.textContent = (t.Type || 'entry').toLowerCase();
            row.append(n, name, where);
            // mousedown, not click: a click moves the editor's focus first.
            row.addEventListener('mousedown', ev => { ev.preventDefault(); pickTemplate(view, t); });
            dom.appendChild(row);
        });
    };
    draw(view.state.field(menuField));
    return { dom, update: u => draw(u.state.field(menuField)) };
}

// Asked for once per page; the templates live in the server's config and do
// not change while somebody is typing.
let templatesP: Promise<CaptureTemplate[]> | null = null;
function loadTemplates(): Promise<CaptureTemplate[]> {
    if (!templatesP) templatesP = ODb.captureTemplates().catch(e => { templatesP = null; throw e; });
    return templatesP;
}

function startCaptureMenu(view: EditorView, from: number, to: number, indent: string) {
    const line = view.state.doc.lineAt(from);
    const above: string[] = [];
    for (let n = 1; n < line.number; n++) above.push(view.state.doc.line(n).text);
    view.dispatch({
        effects: openMenu.of({ from, to, filter: '', index: 0, items: null, error: '', level: captureLevel(above), indent }),
    });
    loadTemplates().then(
        items => { if (view.state.field(menuField)) view.dispatch({ effects: updateMenu.of({ items }) }); },
        e => { if (view.state.field(menuField)) view.dispatch({ effects: updateMenu.of({ items: [], error: String((e && e.message) || e) }) }); },
    );
}

function pickTemplate(view: EditorView, t: CaptureTemplate) {
    const m = view.state.field(menuField);
    if (!m) return;
    const exp = captureExpansion(t, m.level, m.indent);
    // A heading starts its line, so an entry takes the indentation with it.
    const from = needsHeadline((t.Type || '').toLowerCase()) ? view.state.doc.lineAt(m.from).from : m.from;
    view.dispatch({ effects: closeMenu.of(null) });
    insertExpansion(view, from, m.to, exp, true);
}

function menuKey(view: EditorView, m: Menu, e: KeyboardEvent): boolean {
    const items = menuItems(m);
    const move = (d: number) => {
        if (items.length === 0) return;
        view.dispatch({ effects: updateMenu.of({ index: (m.index + d + items.length) % items.length }) });
    };
    if (e.key === 'Escape' || (e.ctrlKey && e.key === 'g')) {
        // Nothing was written yet but `<c`, and that goes too.
        view.dispatch({ effects: closeMenu.of(null), changes: { from: m.from, to: m.to }, selection: EditorSelection.cursor(m.from) });
        return true;
    }
    if (e.key === 'ArrowDown' || (e.ctrlKey && e.key === 'n') || (e.key === 'Tab' && !e.shiftKey)) { move(1); return true; }
    if (e.key === 'ArrowUp' || (e.ctrlKey && e.key === 'p') || (e.key === 'Tab' && e.shiftKey)) { move(-1); return true; }
    if (e.key === 'Enter') { if (items[m.index]) pickTemplate(view, items[m.index]); return true; }
    if (e.key === 'Backspace') {
        if (m.filter === '') view.dispatch({ effects: closeMenu.of(null) });
        else view.dispatch({ effects: updateMenu.of({ filter: m.filter.slice(0, -1), index: 0 }) });
        return true;
    }
    if (m.filter === '' && /^[1-9]$/.test(e.key) && !e.ctrlKey && !e.metaKey && !e.altKey) {
        const t = items[Number(e.key) - 1];
        if (t) pickTemplate(view, t);
        return true;
    }
    if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        view.dispatch({ effects: updateMenu.of({ filter: m.filter + e.key, index: 0 }) });
        return true;
    }
    // Anything else (a modifier on its own, say) is let through.
    return e.key === 'Shift' || e.key === 'Control' || e.key === 'Alt' || e.key === 'Meta' ? false : true;
}

// ---------------------------------------------------------------------------
// Keys
// ---------------------------------------------------------------------------

type Keys = 'vim' | 'emacs';

// Whether the keys typed now are text: always in emacs, only in insert (and
// replace) mode in vim.
function typing(view: EditorView): boolean {
    const cm = getCM(view) as any;
    if (!cm || !cm.state || !cm.state.vim) return true;
    return !!cm.state.vim.insertMode;
}

function onHeading(view: EditorView): boolean {
    return HEADING.test(view.state.doc.lineAt(view.state.selection.main.head).text);
}

// What the editor's owner does on a save or a close; one per view, because
// vim's ex commands are defined once for every editor on the page.
type Owner = { save: () => void; close: (force: boolean) => void; saveClose: () => void };
const owners = new WeakMap<EditorView, Owner>();

// ---------------------------------------------------------------------------
// Org's own commands (orgcmds.ts)
// ---------------------------------------------------------------------------

type Ctx = { done: Set<string>; active: Set<string>; seq: string[]; now: Date };
type OrgCmd = (lines: string[], cur: Pos, ctx: Ctx) => Change | null;

function ctxOf(state: EditorState): Ctx {
    const a = state.field(analysisField);
    return { done: a.todo.done, active: a.todo.active, seq: todoSequence(state.doc.toString(), DEFAULT_TODO_STATES), now: new Date() };
}

// Every command by name, so both key sets, the leader and the expansions say
// the same thing. S-arrows do the timestamp under the cursor first, as org's do.
const CMDS: Record<string, OrgCmd> = {
    moveUp: (l, c) => moveThing(l, c, -1),
    moveDown: (l, c) => moveThing(l, c, 1),
    promote: (l, c) => shiftThing(l, c, -1, false),
    demote: (l, c) => shiftThing(l, c, 1, false),
    promoteTree: (l, c) => shiftThing(l, c, -1, true),
    demoteTree: (l, c) => shiftThing(l, c, 1, true),
    next: (l, c) => insertNext(l, c),
    nextTodo: (l, c, x) => insertNext(l, c, { todo: x.seq[0] || 'TODO', checkbox: true }),
    nextHeading: (l, c) => insertNext(l, c, { heading: true }),
    ctrlC: (l, c, x) => ctrlCCtrlC(l, c, x.done, x.active),
    checkbox: (l, c) => toggleHasCheckbox(l, c),
    todoNext: (l, c, x) => cycleTodo(l, c, 1, x.seq, x.done, x.active),
    todoPrev: (l, c, x) => cycleTodo(l, c, -1, x.seq, x.done, x.active),
    priorityUp: (l, c) => cyclePriority(l, c, 1),
    shiftUp: (l, c) => shiftStamp(l, c, 1) || cyclePriority(l, c, 1),
    shiftDown: (l, c) => shiftStamp(l, c, -1) || cyclePriority(l, c, -1),
    shiftLeft: (l, c, x) => (stampAt(l[c.line], c.ch) ? shiftStamp(l, c, -1) : HEADING.test(l[c.line]) ? cycleTodo(l, c, -1, x.seq, x.done, x.active) : null),
    shiftRight: (l, c, x) => (stampAt(l[c.line], c.ch) ? shiftStamp(l, c, 1) : HEADING.test(l[c.line]) ? cycleTodo(l, c, 1, x.seq, x.done, x.active) : null),
    schedule: (l, c, x) => plan(l, c, 'SCHEDULED', x.now),
    deadline: (l, c, x) => plan(l, c, 'DEADLINE', x.now),
    stamp: (l, c, x) => timestamp(l, c, true, x.now),
    stampInactive: (l, c, x) => timestamp(l, c, false, x.now, true),
    property: (l, c) => setProperty(l, c),
    table: (l, c) => tableFromText(l, c),
};

// Line edits on `basis` as CodeMirror changes, in the basis' own offsets.
function lineChanges(basis: string[], edits: LineEdit[]): ChangeSpec[] {
    const start: number[] = [];
    let at = 0;
    for (const l of basis) { start.push(at); at += l.length + 1; }
    const docEnd = at - 1;
    const n = basis.length;
    const doc = basis.join('\n');
    // Only the characters that differ are replaced. A whole-line replacement
    // would carry everything mapped through it (a field being filled in, the
    // end of a snippet, the cursor) to the end of the line or past it.
    const tight = (from: number, to: number, insert: string): { from: number; to: number; insert: string } => {
        const old = doc.slice(from, to);
        let p = 0;
        while (p < old.length && p < insert.length && old[p] === insert[p]) p++;
        let q = 0;
        while (q < old.length - p && q < insert.length - p && old[old.length - 1 - q] === insert[insert.length - 1 - q]) q++;
        return { from: from + p, to: to - q, insert: insert.slice(p, insert.length - q) };
    };
    return edits.map(e => {
        if (e.to < n) return tight(start[e.from], start[e.to], e.lines.map(x => x + '\n').join(''));
        if (e.from < n) {
            if (e.lines.length === 0 && e.from > 0) return { from: start[e.from] - 1, to: docEnd };
            return tight(start[e.from], docEnd, e.lines.join('\n'));
        }
        return { from: docEnd, insert: e.lines.length ? '\n' + e.lines.join('\n') : '' };
    });
}

function enterInsert(view: EditorView) {
    const cm = getCM(view) as any;
    if (cm && cm.state && cm.state.vim && !cm.state.vim.insertMode) Vim.handleKey(cm, 'i', 'mapping');
}

// Apply a command's answer as one transaction, after `pre` (changes to the
// real document that `basis` already has made - the `<p` an expansion took
// away), so the whole thing is one undo.
function applyChange(view: EditorView, basis: string[], c: Change, pre: ChangeSpec[] = []) {
    const after = basis.slice();
    for (const e of c.edits.slice().sort((a, b) => b.from - a.from)) after.splice(e.from, e.to - e.from, ...e.lines);
    const off: number[] = [];
    let at = 0;
    for (const l of after) { off.push(at); at += l.length + 1; }
    const pos = (line: number, ch: number) => (off[line] ?? at - 1) + ch;
    let session: Session | null = null;
    let selection: EditorSelection | undefined;
    if (c.fields && c.fields.length > 0) {
        const fields = c.fields.map(f => ({ from: pos(f.line, f.from), to: pos(f.line, f.to), key: f.key, prompt: f.prompt, kind: 'text' as FieldKind }));
        const seen = new Set<string>();
        const order: number[] = [];
        fields.forEach((f, i) => { if (!seen.has(f.key)) { seen.add(f.key); order.push(i); } });
        session = {
            fields, order, active: 0, capture: false, tidy: !!c.tidy,
            start: Math.min(...fields.map(f => f.from)), end: Math.max(...fields.map(f => f.to)),
        };
        selection = selectField(session, 0);
    } else if (c.cursor) {
        selection = EditorSelection.single(Math.min(pos(c.cursor.line, c.cursor.ch), Math.max(0, at - 1)));
    }
    if (session || c.insert) enterInsert(view);
    const specs: TransactionSpec[] = [];
    if (pre.length > 0) specs.push({ changes: pre });
    specs.push({
        changes: lineChanges(basis, c.edits),
        sequential: pre.length > 0,
        selection,
        effects: session ? [startSession.of(session)] : [],
        scrollIntoView: true,
        userEvent: 'input',
    } as TransactionSpec);
    // A command run on a field that was selected (S-up on a date just put in)
    // leaves it selected, so the next S-up or a typed date still lands on it.
    const before = view.state.field(sessionField);
    const was = view.state.selection.main;
    const held = !session && before ? before.fields.findIndex(f => f.from === was.from && f.to === was.to && f.to > f.from) : -1;
    view.dispatch(view.state.update(...specs));
    const now = view.state.field(sessionField);
    if (held >= 0 && now) view.dispatch({ selection: EditorSelection.single(now.fields[held].from, now.fields[held].to) });
}

function cursorOf(state: EditorState): Pos {
    const head = state.selection.main.head;
    const line = state.doc.lineAt(head);
    return { line: line.number - 1, ch: head - line.from };
}

function runOrg(view: EditorView, name: string): boolean {
    const lines = view.state.doc.toJSON();
    const c = CMDS[name](lines, cursorOf(view.state), ctxOf(view.state));
    if (!c) return false;
    applyChange(view, lines, c);
    return true;
}

// The command with the key that runs it as an emacs binding.
const orgCommand = (name: string): Command => view => runOrg(view, name);

function tryTempo(view: EditorView): boolean {
    const sel = view.state.selection.main;
    if (!sel.empty) return false;
    const line = view.state.doc.lineAt(sel.head);
    const t = tempoBefore(line.text.slice(0, sel.head - line.from));
    if (t === null) return false;
    const from = sel.head - t.key.length - 1;
    if (t.key === 'c') { startCaptureMenu(view, from, sel.head, t.indent); return true; }
    if (Object.prototype.hasOwnProperty.call(SMART, t.key)) {
        // The `<key` goes, and so does its line if that leaves it empty and
        // what it does lands somewhere else (a drawer, a planning line).
        const lines = view.state.doc.toJSON();
        const n = line.number - 1;
        const rest = line.text.slice(0, from - line.from) + line.text.slice(sel.head - line.from);
        const elsewhere = t.key === 'p' || t.key === 'sch' || t.key === 'dl';
        let pre: ChangeSpec;
        let cur: Pos;
        if (elsewhere && rest.trim() === '' && lines.length > 1) {
            pre = n + 1 < lines.length ? { from: line.from, to: line.to + 1 } : { from: line.from - 1, to: line.to };
            lines.splice(n, 1);
            cur = { line: Math.max(0, n - 1), ch: 0 };
        } else {
            pre = { from, to: sel.head };
            lines[n] = rest;
            cur = { line: n, ch: from - line.from };
        }
        const name = { p: 'property', sch: 'schedule', dl: 'deadline', t: 'stamp', i: 'stampInactive' }[t.key] as string;
        const c = CMDS[name](lines, cur, ctxOf(view.state));
        if (!c) return false;
        applyChange(view, lines, c, [pre]);
        return true;
    }
    insertExpansion(view, from, sel.head, expandMarked(TEMPO[t.key].src, t.indent), false);
    return true;
}

// ---------------------------------------------------------------------------
// The vim leader: SPC in normal mode, then one key
// ---------------------------------------------------------------------------

const setLeader = StateEffect.define<boolean>();
const leaderField = StateField.define<boolean>({
    create: () => false,
    update(v, tr) {
        for (const e of tr.effects) if (e.is(setLeader)) return e.value;
        return v;
    },
});

export const LEADER: Record<string, { cmd: string; say: string }> = {
    t: { cmd: 'todoNext', say: 'next todo keyword' },
    T: { cmd: 'todoPrev', say: 'previous todo keyword' },
    x: { cmd: 'ctrlC', say: 'tick checkbox / recount / fix date (C-c C-c)' },
    X: { cmd: 'checkbox', say: 'add or remove a checkbox' },
    s: { cmd: 'schedule', say: 'schedule' },
    d: { cmd: 'deadline', say: 'deadline' },
    '.': { cmd: 'stamp', say: 'active timestamp' },
    '!': { cmd: 'stampInactive', say: 'inactive timestamp' },
    p: { cmd: 'property', say: 'set a property' },
    '|': { cmd: 'table', say: 'paragraph into a table (csv, tabs or spaces)' },
    n: { cmd: 'next', say: 'next item / heading' },
    N: { cmd: 'nextTodo', say: 'next TODO heading / checkbox' },
    h: { cmd: 'nextHeading', say: 'new heading after this subtree' },
    ',': { cmd: 'priorityUp', say: 'cycle priority' },
};

// Keys that mean the same in either key set and any vim mode: org's M- and
// S- arrows, and M-RET. A shifted arrow that has nothing org to do here (not
// on a heading or a timestamp) falls through to selecting.
function sharedKey(e: KeyboardEvent): string | null {
    if (e.ctrlKey || e.metaKey) return e.ctrlKey && !e.altKey && !e.shiftKey && e.key === 'Enter' ? 'nextHeading' : null;
    if (e.altKey) {
        switch (e.key) {
            case 'ArrowUp': return 'moveUp';
            case 'ArrowDown': return 'moveDown';
            case 'ArrowLeft': return e.shiftKey ? 'promoteTree' : 'promote';
            case 'ArrowRight': return e.shiftKey ? 'demoteTree' : 'demote';
            case 'Enter': return e.shiftKey ? 'nextTodo' : 'next';
        }
        return null;
    }
    if (e.shiftKey) {
        switch (e.key) {
            case 'ArrowUp': return 'shiftUp';
            case 'ArrowDown': return 'shiftDown';
            case 'ArrowLeft': return 'shiftLeft';
            case 'ArrowRight': return 'shiftRight';
        }
    }
    return null;
}

// Vim's normal mode adds M-h/j/k/l (by the physical key, since alt changes
// the character on a mac) for the arrows.
function vimNormalKey(e: KeyboardEvent): string | null {
    if (!e.altKey || e.ctrlKey || e.metaKey) return null;
    switch (e.code) {
        case 'KeyK': return 'moveUp';
        case 'KeyJ': return 'moveDown';
        case 'KeyH': return e.shiftKey ? 'promoteTree' : 'promote';
        case 'KeyL': return e.shiftKey ? 'demoteTree' : 'demote';
    }
    return null;
}

// Run before vim's own key handling and the keymaps, because TAB, ESC, the
// org keys and the menu's keys mean something here first.
const orgKeys = Prec.highest(EditorView.domEventHandlers({
    keydown(e, view) {
        const m = view.state.field(menuField);
        if (m) {
            if (menuKey(view, m, e)) { e.preventDefault(); return true; }
            return false;
        }
        // ⌘S anywhere; ctrl-S too in vim, where emacs has it as search.
        if (!e.altKey && e.key === 's' && (e.metaKey || (e.ctrlKey && getCM(view)))) {
            e.preventDefault();
            owners.get(view)?.save();
            return true;
        }
        if (e.key === 'F1') { e.preventDefault(); openEditorHelp(); return true; }
        const s = view.state.field(sessionField);
        const plain = !e.ctrlKey && !e.metaKey && !e.altKey;

        // SPC was pressed in vim's normal mode: this key says what for.
        if (view.state.field(leaderField)) {
            if (['Shift', 'Control', 'Alt', 'Meta'].includes(e.key)) return false;
            e.preventDefault();
            view.dispatch({ effects: setLeader.of(false) });
            if (e.key === '?') { openEditorHelp(); return true; }
            const l = LEADER[e.key];
            if (l) runOrg(view, l.cmd);
            return true;
        }
        if (plain && !e.shiftKey && e.key === ' ' && !typing(view)) {
            e.preventDefault();
            view.dispatch({ effects: setLeader.of(true) });
            return true;
        }

        const name = sharedKey(e) || (!typing(view) ? vimNormalKey(e) : null);
        if (name && runOrg(view, name)) { e.preventDefault(); return true; }

        if (e.key === 'Tab' && plain) {
            if (typing(view)) {
                if (!e.shiftKey && tryTempo(view)) { e.preventDefault(); return true; }
                if (s) { e.preventDefault(); return gotoField(view, e.shiftKey ? -1 : 1); }
            }
            if (e.shiftKey) return false;
            e.preventDefault();
            // TAB on a heading folds it, as org's does; on an empty list item
            // it indents the item, as org's does; anywhere else in text it
            // indents.
            if (onHeading(view) || !typing(view)) return toggleFold(view) || true;
            const line = view.state.doc.lineAt(view.state.selection.main.head);
            if (/^\s*(?:[-+]|\s\*|\d+[.)])\s+(?:\[[ xX-]\]\s*)?$/.test(line.text) && runOrg(view, 'demote')) return true;
            return insertTab(view);
        }
        if (s && (e.key === 'Escape' || (e.ctrlKey && e.key === 'g'))) {
            if (s.capture) cancelCapture(view);
            else finishSession(view);
            // Let it on through, so vim goes back to normal mode as well.
            return false;
        }
        return false;
    },
}));

// A small emacs: movement, the mark, killing and yanking, and C-x C-s. Not a
// whole emacs - just enough that the fingers do not have to change.
const markActive = StateField.define<boolean>({
    create: () => false,
    update(v, tr) {
        for (const e of tr.effects) if (e.is(setMark)) return e.value;
        return tr.docChanged ? false : v;
    },
});
const setMark = StateEffect.define<boolean>();
let killRing = '';

function emacsKeymap(): KeyBinding[] {
    const mv = (plain: Command, sel: Command): Command => view =>
        (view.state.field(markActive) ? sel : plain)(view);
    const killRange = (view: EditorView, from: number, to: number) => {
        if (to <= from) return false;
        killRing = view.state.sliceDoc(from, to);
        try { navigator.clipboard?.writeText(killRing); } catch { /* insecure context */ }
        view.dispatch({ changes: { from, to }, userEvent: 'delete.cut' });
        return true;
    };
    return [
        { key: 'Ctrl-f', run: mv(cursorCharRight, selectCharRight) },
        { key: 'Ctrl-b', run: mv(cursorCharLeft, selectCharLeft) },
        { key: 'Ctrl-n', run: mv(cursorLineDown, selectLineDown) },
        { key: 'Ctrl-p', run: mv(cursorLineUp, selectLineUp) },
        { key: 'Ctrl-a', run: mv(cursorLineStart, selectLineStart) },
        { key: 'Ctrl-e', run: mv(cursorLineEnd, selectLineEnd) },
        { key: 'Alt-f', run: mv(cursorGroupForward, selectGroupForward) },
        { key: 'Alt-b', run: mv(cursorGroupBackward, selectGroupBackward) },
        { key: 'Ctrl-v', run: mv(cursorPageDown, selectPageDown) },
        { key: 'Alt-v', run: mv(cursorPageUp, selectPageUp) },
        { key: 'Alt-<', run: mv(cursorDocStart, selectDocStart) },
        { key: 'Alt->', run: mv(cursorDocEnd, selectDocEnd) },
        { key: 'Ctrl-d', run: deleteCharForward },
        { key: 'Alt-d', run: deleteGroupForward },
        { key: 'Alt-Backspace', run: deleteGroupBackward },
        { key: 'Ctrl-t', run: transposeChars },
        { key: 'Ctrl-o', run: splitLine },
        { key: 'Ctrl-/', run: undo },
        { key: 'Ctrl-_', run: undo },
        { key: 'Ctrl-x u', run: undo },
        { key: 'Ctrl-Shift-/', run: redo },
        { key: 'Ctrl-s', run: openSearchPanel },
        { key: 'Ctrl-x Ctrl-s', run: view => { owners.get(view)?.save(); return true; } },
        { key: 'Ctrl-x Ctrl-c', run: view => { owners.get(view)?.close(false); return true; } },
        // Org's own C-c chords. (No C-h prefix: CodeMirror binds C-h on its own
        // on a mac, and a key that is both a binding and a prefix takes the
        // whole keymap down - help is F1.)
        { key: 'Ctrl-c Ctrl-c', run: orgCommand('ctrlC') },
        { key: 'Ctrl-c Ctrl-t', run: orgCommand('todoNext') },
        { key: 'Ctrl-c Ctrl-s', run: orgCommand('schedule') },
        { key: 'Ctrl-c Ctrl-d', run: orgCommand('deadline') },
        { key: 'Ctrl-c .', run: orgCommand('stamp') },
        { key: 'Ctrl-c !', run: orgCommand('stampInactive') },
        { key: 'Ctrl-c ,', run: orgCommand('priorityUp') },
        { key: 'Ctrl-c Ctrl-x p', run: orgCommand('property') },
        { key: 'Ctrl-c |', run: orgCommand('table') },
        { key: 'Ctrl-c Ctrl-x Ctrl-b', run: orgCommand('checkbox') },
        {
            key: 'Ctrl-Space', run: view => {
                const sel = view.state.selection.main;
                view.dispatch({ effects: setMark.of(true), selection: EditorSelection.cursor(sel.head) });
                return true;
            },
        },
        {
            key: 'Ctrl-g', run: view => {
                const sel = view.state.selection.main;
                view.dispatch({ effects: setMark.of(false), selection: EditorSelection.cursor(sel.head) });
                return true;
            },
        },
        {
            key: 'Ctrl-k', run: view => {
                const head = view.state.selection.main.head;
                const line = view.state.doc.lineAt(head);
                // At the end of a line, C-k takes the line break.
                return killRange(view, head, head === line.to ? Math.min(line.to + 1, view.state.doc.length) : line.to);
            },
        },
        {
            key: 'Ctrl-w', run: view => {
                const sel = view.state.selection.main;
                view.dispatch({ effects: setMark.of(false) });
                return killRange(view, sel.from, sel.to);
            },
        },
        {
            key: 'Alt-w', run: view => {
                const sel = view.state.selection.main;
                killRing = view.state.sliceDoc(sel.from, sel.to);
                try { navigator.clipboard?.writeText(killRing); } catch { /* insecure context */ }
                view.dispatch({ effects: setMark.of(false), selection: EditorSelection.cursor(sel.head) });
                return true;
            },
        },
        {
            key: 'Ctrl-y', run: view => {
                if (killRing === '') return true;
                view.dispatch(view.state.replaceSelection(killRing), { userEvent: 'input.paste' });
                return true;
            },
        },
    ];
}

let exDefined = false;
function defineEx() {
    if (exDefined) return;
    exDefined = true;
    const owner = (cm: any) => owners.get(cm.cm6 as EditorView);
    Vim.defineEx('write', 'w', (cm: any) => owner(cm)?.save());
    Vim.defineEx('wq', 'wq', (cm: any) => owner(cm)?.saveClose());
    Vim.defineEx('xit', 'x', (cm: any) => owner(cm)?.saveClose());
    Vim.defineEx('help', 'help', () => openEditorHelp());
    // jk or jj typed quickly in insert mode is ESC: the first letter is held
    // for insertModeEscKeysTimeout (200ms) and goes in as typed if nothing
    // follows in time.
    Vim.map('jk', '<Esc>', 'insert');
    Vim.map('jj', '<Esc>', 'insert');
    // `:q!` arrives as the command q with the argument "!".
    Vim.defineEx('quit', 'q', (cm: any, params: any) => owner(cm)?.close(((params && params.argString) || '').trim() === '!'));
    // This vim has no folding of its own; org's is the point of an outline.
    const fold = (keys: string, name: string, cmd: Command) => {
        Vim.defineAction(name, (cm: any) => { cmd(cm.cm6 as EditorView); });
        Vim.mapCommand(keys, 'action', name, {}, { context: 'normal' });
    };
    fold('za', 'orgFoldToggle', toggleFold);
    fold('zc', 'orgFold', foldCode);
    fold('zo', 'orgUnfold', unfoldCode);
    fold('zM', 'orgFoldAll', foldAll);
    fold('zR', 'orgUnfoldAll', unfoldAll);
}

function keysExtension(keys: Keys): Extension {
    if (keys === 'emacs') return [markActive, Prec.high(keymap.of(emacsKeymap()))];
    defineEx();
    return vim();
}

// ---------------------------------------------------------------------------
// The view
// ---------------------------------------------------------------------------

type VimMode = 'normal' | 'insert' | 'visual' | 'visual line' | 'visual block' | 'replace';

const MODE_LOOK: Record<string, { label: string; icon: React.ReactNode; color: string }> = {
    normal: { label: 'NORMAL', icon: <NavigationRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-primary-500)' },
    insert: { label: 'INSERT', icon: <EditRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-success-500)' },
    visual: { label: 'VISUAL', icon: <HighlightAltRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-warning-500)' },
    'visual line': { label: 'V-LINE', icon: <HighlightAltRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-warning-500)' },
    'visual block': { label: 'V-BLOCK', icon: <HighlightAltRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-warning-500)' },
    replace: { label: 'REPLACE', icon: <FindReplaceRoundedIcon sx={{ fontSize: 16 }} />, color: 'var(--joy-palette-danger-500)' },
};

type SaveState =
    | { kind: 'idle' }
    | { kind: 'saving' }
    | { kind: 'saved' }
    | { kind: 'changed' }            // the file moved underneath us
    | { kind: 'error'; msg: string }
    | { kind: 'closing' };           // asked to close with unsaved changes

export default function OrgTextEditor({
    filename, text, wrap = false, startLine = -1, onSaved, onClose, onDirty, onCursorLine,
}: {
    filename: string;
    // What the file held when editing began, and what a save is checked
    // against. Read once: a later change to it does not reset the editor.
    text: string;
    wrap?: boolean;
    startLine?: number;  // zero based
    onSaved: (text: string) => void;
    onClose: () => void;
    onDirty?: (dirty: boolean) => void;
    // The cursor's line, zero based, as it moves - the Files tab's links
    // panel follows the heading it is in.
    onCursorLine?: (line: number) => void;
}) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';
    const [themeKey] = useSetting('orgTheme');
    const [keys] = useSetting('editorKeys');
    const p = orgPalette(themeKey, dark);

    const host = React.useRef<HTMLDivElement | null>(null);
    const viewRef = React.useRef<EditorView | null>(null);
    const base = React.useRef(text);
    const theme = React.useRef(new Compartment());
    const keyComp = React.useRef(new Compartment());
    const wrapComp = React.useRef(new Compartment());

    const [vimMode, setVimMode] = React.useState<VimMode>('normal');
    const [dirty, setDirty] = React.useState(false);
    const [save, setSave] = React.useState<SaveState>({ kind: 'idle' });
    const [pos, setPos] = React.useState({ line: 1, col: 1 });
    const cursorCb = React.useRef(onCursorLine);
    cursorCb.current = onCursorLine;
    React.useEffect(() => { if (cursorCb.current) cursorCb.current(pos.line - 1); }, [pos.line]);
    const [step, setStep] = React.useState<{ at: number; of: number; capture: boolean } | null>(null);
    const [leader, setLeaderShown] = React.useState(false);

    const onDirtyRef = React.useRef(onDirty);
    onDirtyRef.current = onDirty;
    React.useEffect(() => { onDirtyRef.current?.(dirty); }, [dirty]);

    const doSave = React.useCallback(async (force: boolean = false): Promise<boolean> => {
        const view = viewRef.current;
        if (!view) return false;
        const now = view.state.doc.toString();
        setSave({ kind: 'saving' });
        try {
            const res = await ODb.saveOrgFile(filename, now, base.current, force);
            if (res && res.Ok) {
                base.current = now;
                setDirty(view.state.doc.toString() !== now);
                setSave({ kind: 'saved' });
                onSaved(now);
                return true;
            }
            if (res && res.Msg === 'changed') { setSave({ kind: 'changed' }); return false; }
            setSave({ kind: 'error', msg: (res && res.Msg) || 'The server would not save that.' });
        } catch (e: any) {
            setSave({ kind: 'error', msg: (e && e.message) || 'That did not go through.' });
        }
        return false;
    }, [filename, onSaved]);

    // Read off the document rather than kept as state, because ex commands
    // run outside React and would see a stale `dirty`.
    const isDirty = () => !!viewRef.current && viewRef.current.state.doc.toString() !== base.current;

    const owner = React.useRef<Owner>({ save: () => {}, close: () => {}, saveClose: () => {} });
    owner.current.save = () => { doSave(); };
    owner.current.saveClose = () => { doSave().then(ok => { if (ok) onClose(); }); };
    owner.current.close = (force: boolean) => {
        if (force || !isDirty()) { onClose(); return; }
        setSave({ kind: 'closing' });
    };

    // The editor is made once; settings that change while it is open are
    // reconfigured into it below.
    React.useEffect(() => {
        if (!host.current) return;
        const view = new EditorView({
            parent: host.current,
            state: EditorState.create({
                doc: base.current,
                extensions: [
                    orgKeys,
                    keyComp.current.of(keysExtension(keys as Keys)),
                    analysisField,
                    orgHighlight,
                    orgFolding,
                    codeFolding({ placeholderText: '…' }),
                    foldGutter({ openText: '▾', closedText: '▸' }),
                    sessionField,
                    mirrorFields,
                    leaveSession,
                    menuField,
                    leaderField,
                    lineNumbers(),
                    highlightActiveLine(),
                    highlightActiveLineGutter(),
                    drawSelection(),
                    history(),
                    search({ top: true }),
                    highlightSelectionMatches(),
                    keymap.of([...defaultKeymap, ...historyKeymap, ...searchKeymap, ...foldKeymap]),
                    wrapComp.current.of(wrap ? EditorView.lineWrapping : []),
                    theme.current.of(editorTheme(p, dark)),
                    EditorView.updateListener.of(u => {
                        if (u.docChanged) {
                            setDirty(u.state.doc.toString() !== base.current);
                            setSave(s => (s.kind === 'saved' ? { kind: 'idle' } : s));
                        }
                        if (u.docChanged || u.selectionSet) {
                            const head = u.state.selection.main.head;
                            const line = u.state.doc.lineAt(head);
                            setPos({ line: line.number, col: head - line.from + 1 });
                        }
                        setLeaderShown(u.state.field(leaderField));
                        const s = u.state.field(sessionField);
                        setStep(s ? { at: s.active + 1, of: s.order.length, capture: s.capture } : null);
                    }),
                ],
            }),
        });
        viewRef.current = view;
        owners.set(view, {
            save: () => owner.current.save(),
            close: f => owner.current.close(f),
            saveClose: () => owner.current.saveClose(),
        });
        if (startLine >= 0 && startLine < view.state.doc.lines) {
            const at = view.state.doc.line(startLine + 1).from;
            view.dispatch({ selection: EditorSelection.cursor(at), effects: EditorView.scrollIntoView(at, { y: 'start' }) });
        }
        view.focus();
        return () => { view.destroy(); viewRef.current = null; };
    }, []);

    React.useEffect(() => {
        viewRef.current?.dispatch({ effects: theme.current.reconfigure(editorTheme(p, dark)) });
    }, [themeKey, dark]);

    React.useEffect(() => {
        viewRef.current?.dispatch({ effects: wrapComp.current.reconfigure(wrap ? EditorView.lineWrapping : []) });
    }, [wrap]);

    // Switching keys while editing, and following vim's mode for the status
    // line. The vim plugin is rebuilt by the reconfigure, so the listener is
    // put on again each time.
    React.useEffect(() => {
        const view = viewRef.current;
        if (!view) return;
        view.dispatch({ effects: keyComp.current.reconfigure(keysExtension(keys as Keys)) });
        setVimMode('normal');
        if (keys !== 'vim') return;
        const cm = getCM(view) as any;
        if (!cm) return;
        const on = (e: { mode: string; subMode?: string }) => {
            const m = e.mode === 'visual' && e.subMode ? `visual ${e.subMode === 'linewise' ? 'line' : 'block'}` : e.mode;
            setVimMode(m as VimMode);
            // Leaving insert mode some other way than ESC (jk, jj) ends a field
            // step the way ESC does for a block - kept, not taken back out.
            // Deferred: vim says so from inside its own update.
            Promise.resolve().then(() => {
                if (e.mode === 'normal' && view.state.field(sessionField)) finishSession(view);
                if (e.mode !== 'normal' && view.state.field(leaderField)) view.dispatch({ effects: setLeader.of(false) });
            });
        };
        cm.on('vim-mode-change', on);
        return () => { cm.off && cm.off('vim-mode-change', on); };
    }, [keys]);

    // A tab closed with unsaved text asks first.
    React.useEffect(() => {
        if (!dirty) return;
        const warn = (e: BeforeUnloadEvent) => { e.preventDefault(); e.returnValue = ''; };
        window.addEventListener('beforeunload', warn);
        return () => window.removeEventListener('beforeunload', warn);
    }, [dirty]);

    const reload = async () => {
        const res = await ODb.getOrgFile(filename);
        const view = viewRef.current;
        if (!view || !res || !res.Ok) { setSave({ kind: 'error', msg: (res && res.Msg) || 'Could not read the file again.' }); return; }
        base.current = res.Msg;
        view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: res.Msg }, effects: endSession.of(null) });
        setDirty(false);
        setSave({ kind: 'idle' });
        onSaved(res.Msg);
    };

    const look = keys === 'vim' ? MODE_LOOK[vimMode] || MODE_LOOK.normal : null;

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', bgcolor: p.bg }}>
            <Box ref={host} sx={{ flex: 1, minHeight: 0, overflow: 'hidden', '& .cm-editor': { height: '100%' } }} />
            {/* The status line: the mode, where the cursor is, whether it is
                saved, and what a field step is waiting for. */}
            <Box
                sx={{
                    display: 'flex', alignItems: 'center', gap: 1.25, px: 1, py: 0.5, minHeight: 32,
                    borderTop: '1px solid', borderColor: 'divider', bgcolor: p.gutterBg, color: p.fg,
                    fontFamily: MONO, fontSize: 12, flexWrap: 'wrap',
                }}
            >
                {look ? (
                    <Box
                        title="vim mode"
                        sx={{
                            display: 'inline-flex', alignItems: 'center', gap: 0.5, px: 0.75, py: 0.25,
                            borderRadius: 'sm', bgcolor: look.color, color: '#fff', fontWeight: 700, letterSpacing: 0.5,
                        }}
                    >
                        {look.icon}{look.label}
                    </Box>
                ) : (
                    <Box sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5, px: 0.75, py: 0.25, borderRadius: 'sm', bgcolor: 'neutral.softBg', fontWeight: 700 }}>
                        <KeyboardRoundedIcon sx={{ fontSize: 16 }} />EMACS
                    </Box>
                )}
                {leader && (
                    <span title="vim leader: the next key runs an org command (SPC ? for the list)" style={{ fontWeight: 700, color: p.h1 || p.fg }}>
                        SPC-
                    </span>
                )}
                <span style={{ color: p.gutter }}>{pos.line}:{pos.col}</span>
                {step && (
                    <span style={{ color: p.gutter }}>
                        {step.capture ? 'capture' : 'snippet'} field {step.at}/{step.of} · Tab next · ⇧Tab back · Esc {step.capture ? 'cancel' : 'done'}
                    </span>
                )}
                <Box sx={{ ml: 'auto', display: 'flex', alignItems: 'center', gap: 1 }}>
                    {save.kind === 'changed' && (
                        <>
                            <Typography level="body-xs" color="warning">The file changed on disk since you started.</Typography>
                            <Button size="sm" variant="soft" color="warning" onClick={() => doSave(true)}>Overwrite</Button>
                            <Button size="sm" variant="plain" color="neutral" onClick={reload}>Discard mine and reload</Button>
                        </>
                    )}
                    {save.kind === 'closing' && (
                        <>
                            <Typography level="body-xs" color="warning">Unsaved changes.</Typography>
                            <Button size="sm" variant="soft" color="primary" onClick={() => owner.current.saveClose()}>Save and close</Button>
                            <Button size="sm" variant="plain" color="danger" onClick={onClose}>Discard</Button>
                            <Button size="sm" variant="plain" color="neutral" onClick={() => { setSave({ kind: 'idle' }); viewRef.current?.focus(); }}>Keep editing</Button>
                        </>
                    )}
                    {save.kind === 'error' && <Typography level="body-xs" color="danger">{save.msg}</Typography>}
                    <span style={{ color: dirty ? p.todo || p.fg : p.gutter }}>
                        {save.kind === 'saving' ? 'saving…' : dirty ? '● unsaved' : save.kind === 'saved' ? 'saved' : 'no changes'}
                    </span>
                    <Button
                        size="sm" variant="plain" color="neutral" startDecorator={<HelpOutlineRoundedIcon />}
                        onClick={() => openEditorHelp()}
                        title={keys === 'vim' ? 'F1, SPC ? or :help' : 'F1'}
                    >
                        Keys
                    </Button>
                    <Button
                        size="sm" variant="soft" color="primary" startDecorator={<SaveRoundedIcon />}
                        disabled={!dirty || save.kind === 'saving'}
                        onClick={() => { doSave(); viewRef.current?.focus(); }}
                        title={keys === 'vim' ? ':w or ⌘S' : 'C-x C-s or ⌘S'}
                    >
                        Save
                    </Button>
                    <Button
                        size="sm" variant="outlined" color="neutral" startDecorator={<CloseRoundedIcon />}
                        onClick={() => owner.current.close(false)}
                        title={keys === 'vim' ? ':q' : 'C-x C-c'}
                    >
                        Done
                    </Button>
                </Box>
            </Box>
        </Box>
    );
}
