// Importing contacts from a vCard (.vcf) file: the wire types of
// POST /contacts/import and the small pure pieces the import dialog needs.
//
// The server does the import - reading the cards, matching people already in
// the address book, merging, saving photos - so the terminal (`orgs contact
// import`) and this dialog cannot import one file two ways. What is here is
// the browser's half: turning the files somebody dropped into one text, and
// turning the server's plan into something a person can read before saying
// yes.

export type ImportMode = 'merge' | 'skip' | 'overwrite';

export type ContactImportChange = {
    Key: string;
    Value: string;
    // What the record says now, when it says something.
    Old: string;
    // "add" | "replace" | "kept"
    How: string;
};

export type ContactImportItem = {
    Card: number;
    Cards: number;
    Name: string;
    // "add" | "update" | "skip" | "error"
    Action: string;
    Reason: string;
    // "uid" | "email" | "name" | ""
    Match: string;
    Hash: string;
    Filename: string;
    LineNum: number;
    Changes: ContactImportChange[] | null;
    Tags: string[] | null;
    Notes: boolean;
    Warnings: string[] | null;
};

export type ContactImportResult = {
    Ok: boolean;
    Msg: string;
    DryRun: boolean;
    Mode: string;
    Type: string;
    Cards: number;
    Added: number;
    Updated: number;
    Skipped: number;
    Failed: number;
    Target: string;
    Items: ContactImportItem[] | null;
};

export type ContactImportRequest = {
    Text: string;
    Mode: ImportMode;
    DryRun: boolean;
    Type?: string;
    TargetHash?: string;
    Filename?: string;
};

// What each mode means, said once for the dialog.
export const MODES: { value: ImportMode; label: string; hint: string }[] = [
    { value: 'merge', label: 'Merge', hint: 'Add new people; fill in only what known people are missing. Nothing is overwritten.' },
    { value: 'skip', label: 'New only', hint: 'Add new people; leave everybody already here exactly as they are.' },
    { value: 'overwrite', label: 'Overwrite', hint: 'Add new people; where a known person differs, the card wins. Nothing is removed.' },
];

// ── Reading the files ────────────────────────────────────────────────────────

// The Windows-1252 characters in 0x80-0x9F, where it differs from Latin-1.
const CP1252_HIGH = [
    0x20AC, 0x81, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x8D, 0x017D, 0x8F,
    0x90, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x9D, 0x017E, 0x0178,
];

export function decodeCP1252(bytes: Uint8Array): string {
    let out = '';
    for (let i = 0; i < bytes.length; i++) {
        const b = bytes[i];
        out += String.fromCharCode(b >= 0x80 && b < 0xA0 ? CP1252_HIGH[b - 0x80] : b);
    }
    return out;
}

// Whether bytes are well formed UTF-8. Written out rather than asking a
// TextDecoder with fatal set, which the test environment does not have.
export function isUtf8(bytes: Uint8Array): boolean {
    let i = 0;
    while (i < bytes.length) {
        const b = bytes[i];
        let n = 0;
        if (b < 0x80) { i++; continue; }
        else if (b >= 0xC2 && b <= 0xDF) n = 1;
        else if (b >= 0xE0 && b <= 0xEF) n = 2;
        else if (b >= 0xF0 && b <= 0xF4) n = 3;
        else return false;
        if (i + n >= bytes.length) return false;
        for (let k = 1; k <= n; k++) {
            if ((bytes[i + k] & 0xC0) !== 0x80) return false;
        }
        i += n + 1;
    }
    return true;
}

function utf8Text(bytes: Uint8Array): string {
    if (typeof TextDecoder !== 'undefined') return new TextDecoder('utf-8').decode(bytes);
    // Only reached in tests: good enough for the BMP.
    let out = '';
    let i = 0;
    while (i < bytes.length) {
        const b = bytes[i];
        if (b < 0x80) { out += String.fromCharCode(b); i++; }
        else if (b < 0xE0) { out += String.fromCharCode(((b & 0x1F) << 6) | (bytes[i + 1] & 0x3F)); i += 2; }
        else if (b < 0xF0) { out += String.fromCharCode(((b & 0x0F) << 12) | ((bytes[i + 1] & 0x3F) << 6) | (bytes[i + 2] & 0x3F)); i += 3; }
        else {
            const cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3F) << 12) | ((bytes[i + 2] & 0x3F) << 6) | (bytes[i + 3] & 0x3F);
            out += String.fromCodePoint(cp); i += 4;
        }
    }
    return out;
}

// A .vcf file's bytes as text: UTF-8 when they are, Windows-1252 when they are
// not (an old Outlook export). Done here, before the text is sent, because JSON
// cannot carry a byte that is not UTF-8 - it would arrive as a question mark.
export function vcfText(bytes: Uint8Array): string {
    return isUtf8(bytes) ? utf8Text(bytes) : decodeCP1252(bytes);
}

// How many cards a text holds, for the file list before anything is sent.
export function countCards(text: string): number {
    const m = text.match(/^\s*﻿?BEGIN:VCARD\s*$/gim);
    return m ? m.length : 0;
}

// Several files sent as one: a vCard file is just a list of cards, so they are
// put one after the other, each starting on its own line.
export function joinVcfTexts(texts: string[]): string {
    return texts.map(t => t.replace(/\s+$/, '')).filter(t => t !== '').join('\n') + '\n';
}

// ── Reading the plan ─────────────────────────────────────────────────────────

export type PlanGroups = {
    add: ContactImportItem[];
    update: ContactImportItem[];
    skip: ContactImportItem[];
    error: ContactImportItem[];
};

export function groupPlan(res: ContactImportResult | null): PlanGroups {
    const g: PlanGroups = { add: [], update: [], skip: [], error: [] };
    for (const it of (res?.Items || [])) {
        const k = (it.Action in g ? it.Action : 'skip') as keyof PlanGroups;
        g[k].push(it);
    }
    const byName = (a: ContactImportItem, b: ContactImportItem) => a.Name.localeCompare(b.Name);
    g.add.sort(byName);
    g.update.sort(byName);
    return g;
}

// The keys of one person's changes of one kind.
export function changedKeys(it: ContactImportItem, how: string): string[] {
    return (it.Changes || []).filter(c => c.How === how).map(c => c.Key);
}

// One line saying what a new person brings: "6 fields · photo · 2 tags · note".
export function addSummary(it: ContactImportItem): string {
    const ch = it.Changes || [];
    const photo = ch.some(c => c.Key === 'IMAGE' && c.Value.startsWith('photo'));
    const n = ch.filter(c => c.How === 'add' && !(c.Key === 'IMAGE' && photo)).length;
    const parts = [`${n} field${n === 1 ? '' : 's'}`];
    if (photo) parts.push('photo');
    const tags = (it.Tags || []).length;
    if (tags > 0) parts.push(`${tags} tag${tags === 1 ? '' : 's'}`);
    if (it.Notes) parts.push('note');
    return parts.join(' · ');
}

// How the dialog's Import button reads: what will actually be written.
export function importLabel(res: ContactImportResult | null): string {
    if (!res) return 'Import';
    const n = res.Added + res.Updated;
    if (n === 0) return 'Nothing to import';
    const parts: string[] = [];
    if (res.Added > 0) parts.push(`add ${res.Added}`);
    if (res.Updated > 0) parts.push(`update ${res.Updated}`);
    const s = parts.join(', ');
    return s.charAt(0).toUpperCase() + s.slice(1);
}
