// What a card's buttons can ask for.
//
// `refile` and `copy` join `archive` because the three are one operation with
// three endings, and a board is exactly where you notice that: a card in the
// wrong column is often a heading in the wrong *file*, and having to go to the
// search tab to move it is the long way round.
export type CardAction = 'archive' | 'refile' | 'copy' | 'clockin' | 'clockout';


export function baseName(path: string): string {
    const parts = path.split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

export function isSetDate(d?: { Start?: string } | null): boolean {
    return !!(d && d.Start && !d.Start.startsWith('0001-01-01'));
}

// A date said the way a person reads it on a card: today and tomorrow by name,
// this year without the year, anything else in full.
export function dateLabel(iso: string): string {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const now = new Date();
    const days = Math.round((new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
        - new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()) / 86400000);
    if (days === 0) return 'today';
    if (days === 1) return 'tomorrow';
    if (days === -1) return 'yesterday';
    if (days > 1 && days < 7) return d.toLocaleDateString(undefined, { weekday: 'short' });
    const opts: Intl.DateTimeFormatOptions = d.getFullYear() === now.getFullYear()
        ? { month: 'short', day: 'numeric' }
        : { year: 'numeric', month: 'short', day: 'numeric' };
    return d.toLocaleDateString(undefined, opts);
}

export function isOverdue(iso: string): boolean {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return false;
    const now = new Date();
    return d.getTime() < new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
}

export const PRIORITY_COLOR: Record<string, string> = { A: '#e5484d', B: '#f5a524', C: '#3e63dd' };

// ---------------------------------------------------------------------------
// What is written under a heading
// ---------------------------------------------------------------------------

export interface HeadingBody {
    text: string;
    audio: string;
    image: string;
    list: Checklist;
    // The files this heading owns - its org-attach folder. Carried on the body
    // rather than fetched on its own because the card is already asking for
    // the body, and a second request per card is forty requests on a board of
    // forty cards.
    attachments: Attachment[];
    loading: boolean;
}

const EMPTY_BODY: HeadingBody = {
    text: '', audio: '', image: '',
    list: { items: [], done: 0, total: 0 },
    attachments: [],
    loading: true,
};

// The body of every heading the board has asked about, kept for as long as the
// page is open.
//
// A cache module-wide rather than per card on purpose: the front of a card
// wants to know whether there is a checklist and a picture, and the back wants
// the items themselves - and a card that fetched twice for that would be two
// requests per heading on a board of forty. Keyed by hash, which changes when
// the heading does, so nothing here can go stale against the file.
const bodies = new Map<string, HeadingBody>();
const inFlight = new Map<string, Promise<HeadingBody>>();
const listeners = new Set<() => void>();

function announce() { listeners.forEach(l => l()); }

// Read one back from the server, keeping what is on screen until the new one
// arrives.
//
// Dropping the old body first would be simpler and is wrong: the card would
// have nothing to draw for as long as the request takes, so ticking a box
// makes the whole checklist blink out and come back. What is there is stale
// for a moment; blank is worse than stale.
export function refreshBody(hash: string) {
    inFlight.delete(hash);
    fetchBody(hash);
}

// Every body the board is holding, for when it reads itself back. A heading's
// hash does not change when its text does, so nothing here expires on its own
// - and a card still showing the checklist from before somebody edited the
// file in another window is exactly the kind of wrong that looks right.
export function forgetAllBodies() {
    const known = Array.from(bodies.keys());
    inFlight.clear();
    known.forEach(h => fetchBody(h));
}

function fetchBody(hash: string): Promise<HeadingBody> {
    const going = inFlight.get(hash);
    if (going) return going;
    const p = ODb.todoBody(hash)
        .then(r => {
            const text = (r && r.Text) || '';
            const body: HeadingBody = {
                text,
                audio: (r && r.Audio) || '',
                image: (r && r.Image) || '',
                list: checklistOf(text),
                attachments: (r && (r as any).Attachments) || [],
                loading: false,
            };
            bodies.set(hash, body);
            inFlight.delete(hash);
            announce();
            return body;
        })
        .catch(() => {
            const body = { ...EMPTY_BODY, loading: false };
            bodies.set(hash, body);
            inFlight.delete(hash);
            announce();
            return body;
        });
    inFlight.set(hash, p);
    return p;
}

// What a heading says, fetched if nobody has asked yet.
export function useHeadingBody(hash: string): HeadingBody {
    const [, bump] = React.useReducer((n: number) => n + 1, 0);

    React.useEffect(() => {
        listeners.add(bump);
        return () => { listeners.delete(bump); };
    }, []);

    React.useEffect(() => {
        if (hash !== '' && !bodies.has(hash)) fetchBody(hash);
    }, [hash]);

    return bodies.get(hash) || EMPTY_BODY;
}

// ---------------------------------------------------------------------------
// The checklist
// ---------------------------------------------------------------------------

// The badge on the front of a card: the Trello mark, and how many of the boxes
// are ticked. It goes green when they all are, which is the one state worth
// seeing without reading the numbers.
export function ChecklistBadge({ list }: { list: Checklist }) {
    if (list.total === 0) return null;
    const all = list.done === list.total;
    return (
        <Tooltip size="sm" title={`${list.done} of ${list.total} ticked — turn the card over to change them`}>
            <Chip
                size="sm"
                variant={all ? 'soft' : 'outlined'}
                color={all ? 'success' : 'neutral'}
                startDecorator={<CheckBoxOutlinedIcon sx={{ fontSize: 12 }} />}
                sx={{ '--Chip-minHeight': '18px', fontSize: 10, fontVariantNumeric: 'tabular-nums' }}
            >
                {list.done}/{list.total}
            </Chip>
        </Tooltip>
    );
}

// The list itself, on the back of the card.
//
// Ticking a box writes that one line of the org file and nothing else. The box
// moves at once and is put back if the server refuses - which it will if the
// item has changed underneath, because the write names the text it expects as
// well as the position.
export function ChecklistPanel({ card, list }: {
    card: Card;
    list: Checklist;
}) {
    const [busy, setBusy] = React.useState<Record<number, boolean>>({});
    const [local, setLocal] = React.useState<Record<number, boolean>>({});
    const [failed, setFailed] = React.useState('');

    // A fresh body from the server is the truth again.
    React.useEffect(() => { setLocal({}); }, [list]);

    if (list.total === 0) return null;

    const stateOf = (i: CheckItem) => (local[i.index] === undefined ? i.done : local[i.index]);
    const done = list.items.filter(stateOf).length;

    const toggle = async (item: CheckItem) => {
        const want = !stateOf(item);
        setLocal(l => ({ ...l, [item.index]: want }));
        setBusy(b => ({ ...b, [item.index]: true }));
        setFailed('');
        try {
            const res: any = await ODb.setChecklistItem(card.Hash, item.index, item.text, want);
            if (!res || res.Ok === false) {
                setLocal(l => ({ ...l, [item.index]: !want }));
                setFailed((res && res.Msg) || 'That did not go through.');
            } else {
                // Read it back rather than trusting the optimistic tick: the
                // file is the only place this state really lives. Only this
                // heading - nothing the board itself shows has changed, and a
                // whole refresh to tick a box would redraw every card.
                refreshBody(card.Hash);
            }
        } catch {
            setLocal(l => ({ ...l, [item.index]: !want }));
            setFailed('The server did not take that.');
        }
        setBusy(b => ({ ...b, [item.index]: false }));
    };

    return (
        <Box sx={{ mb: 1 }} onClick={e => e.stopPropagation()}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, mb: 0.5 }}>
                <CheckBoxOutlinedIcon sx={{ fontSize: 13, color: 'text.tertiary' }} />
                <Typography level="body-xs" sx={{ color: 'text.tertiary', fontVariantNumeric: 'tabular-nums' }}>
                    {done}/{list.total}
                </Typography>
                <LinearProgress
                    determinate
                    value={list.total === 0 ? 0 : (done / list.total) * 100}
                    color={done === list.total ? 'success' : 'primary'}
                    sx={{ flex: 1, '--LinearProgress-thickness': '4px' }}
                />
            </Box>
            {list.items.map(item => (
                <Box
                    key={item.index}
                    sx={{ display: 'flex', alignItems: 'flex-start', gap: 0.75, pl: item.depth * 1.5, py: '1px' }}
                >
                    <Checkbox
                        size="sm"
                        checked={stateOf(item)}
                        disabled={busy[item.index]}
                        onChange={() => toggle(item)}
                        sx={{ '--Checkbox-size': '14px', mt: '1px' }}
                    />
                    <Typography
                        level="body-xs"
                        sx={{
                            fontSize: 11.5, lineHeight: 1.45, minWidth: 0,
                            textDecoration: stateOf(item) ? 'line-through' : 'none',
                            color: stateOf(item) ? 'text.tertiary' : 'text.secondary',
                            cursor: 'pointer',
                        }}
                        onClick={() => { if (!busy[item.index]) toggle(item); }}
                    >
                        {item.text}
                    </Typography>
                </Box>
            ))}
            {failed !== '' && (
                <Typography level="body-xs" sx={{ color: 'danger.softColor', mt: 0.5 }}>
                    {failed}
                </Typography>
            )}
        </Box>
    );
}

// ---------------------------------------------------------------------------
// Pasting a picture onto a card
// ---------------------------------------------------------------------------
//
// A paste has no target of its own: the event lands on the document, not on
// whatever the eye happens to be on. So the backs that are open keep a stack
// here and the last one to be turned over takes the paste - which is the one
// somebody is looking at, because turning a card over is what put it there.
//
// The picture goes into the org directory and a link is appended to the
// heading, which is what makes it turn up on the front of the card: the front
// already draws the first picture the heading points at, and this is now one.

const pasteStack: string[] = [];

function usePasteTarget(hash: string, onPaste: (file: Blob, type: string, name: string) => void) {
    const cb = React.useRef(onPaste);
    cb.current = onPaste;

    React.useEffect(() => {
        if (hash === '') return;
        pasteStack.push(hash);
        return () => {
            const at = pasteStack.lastIndexOf(hash);
            if (at >= 0) pasteStack.splice(at, 1);
        };
    }, [hash]);

    React.useEffect(() => {
        if (hash === '') return;
        const onDocPaste = (ev: ClipboardEvent) => {
            // The last card turned over is the one being looked at.
            if (pasteStack[pasteStack.length - 1] !== hash) return;
            // Anything typed into is somebody pasting text where text goes.
            const el = document.activeElement as HTMLElement | null;
            if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable)) return;

            const items = ev.clipboardData ? Array.from(ev.clipboardData.items) : [];
            const shot = items.find(i => i.kind === 'file' && i.type.indexOf('image/') === 0);
            if (!shot) return;
            const file = shot.getAsFile();
            if (!file) return;
            ev.preventDefault();
            cb.current(file, file.type || shot.type, file.name || 'paste');
        };
        document.addEventListener('paste', onDocPaste);
        return () => document.removeEventListener('paste', onDocPaste);
    }, [hash]);
}

// The line on the back of a card that says a picture can go here, and says
// what happened when one did.
export function CardPaste({ card }: { card: Card }) {
    const [state, setState] = React.useState<'idle' | 'saving' | 'done' | 'failed'>('idle');
    const [msg, setMsg] = React.useState('');

    usePasteTarget(card.Hash, async (blob, type, name) => {
        setState('saving');
        setMsg('Keeping the picture…');
        try {
            const res = await ODb.pasteImage(card.Hash, blob, type, name);
            if (!res || res.Ok === false) {
                setState('failed');
                setMsg((res && res.Msg) || 'That paste did not go through.');
                return;
            }
            // The front of the card draws the first picture the heading points
            // at, so reading the body back is all it takes to show it.
            refreshBody(card.Hash);
            setState('done');
            setMsg('Added to this heading.');
            window.setTimeout(() => { setState('idle'); setMsg(''); }, 2500);
        } catch (e: any) {
            setState('failed');
            setMsg((e && e.message) || 'That paste did not go through.');
        }
    });

    return (
        <Box
            sx={{
                display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0,
                color: state === 'failed' ? 'danger.softColor' : 'text.tertiary',
            }}
        >
            {state === 'saving'
                ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '12px' }} />
                : <ImageOutlinedIcon sx={{ fontSize: 12 }} />}
            <Typography level="body-xs" sx={{ fontSize: 10, color: 'inherit', minWidth: 0 }} noWrap title={msg}>
                {msg !== '' ? msg : 'Paste a picture to add it here'}
            </Typography>
        </Box>
    );
}


// ---------------------------------------------------------------------------
// Attachments
// ---------------------------------------------------------------------------

// A card you can drop a file onto.
//
// Dragging over the *document* is what is watched rather than the card itself,
// because a drag that starts outside the window and ends on a small card is a
// drag most people miss by a few pixels: the whole back of the card is the
// target, and it lights up as soon as a file is over the window at all so that
// there is somewhere obvious to aim.
//
// `dragenter`/`dragleave` fire for every element the pointer crosses, so a
// counter rather than a flag - otherwise moving from the card onto a word
// inside it reads as having left.
function useDropTarget(hash: string, onDrop: (files: File[]) => void) {
    const [over, setOver] = React.useState(false);
    const depth = React.useRef(0);
    const cb = React.useRef(onDrop);
    cb.current = onDrop;

    React.useEffect(() => {
        if (hash === '') return;
        const hasFiles = (e: DragEvent) =>
            !!e.dataTransfer && Array.from(e.dataTransfer.types || []).indexOf('Files') >= 0;
        const onEnter = (e: DragEvent) => {
            if (!hasFiles(e)) return;
            depth.current++;
            setOver(true);
        };
        const onLeave = (e: DragEvent) => {
            if (!hasFiles(e)) return;
            depth.current = Math.max(0, depth.current - 1);
            if (depth.current === 0) setOver(false);
        };
        // Without this the browser opens the file instead, which navigates
        // away from the board.
        const onOver = (e: DragEvent) => { if (hasFiles(e)) e.preventDefault(); };
        const onEnd = () => { depth.current = 0; setOver(false); };
        document.addEventListener('dragenter', onEnter);
        document.addEventListener('dragleave', onLeave);
        document.addEventListener('dragover', onOver);
        document.addEventListener('drop', onEnd);
        return () => {
            document.removeEventListener('dragenter', onEnter);
            document.removeEventListener('dragleave', onLeave);
            document.removeEventListener('dragover', onOver);
            document.removeEventListener('drop', onEnd);
        };
    }, [hash]);

    const handlers = {
        onDragOver: (e: React.DragEvent) => { e.preventDefault(); e.stopPropagation(); },
        onDrop: (e: React.DragEvent) => {
            e.preventDefault();
            e.stopPropagation();
            depth.current = 0;
            setOver(false);
            const files = e.dataTransfer ? Array.from(e.dataTransfer.files) : [];
            if (files.length) cb.current(files);
        },
    };
    return { over, handlers };
}

// How big a file is, said the way a person would.
export function sizeLabel(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} kB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

// The icon for a kind of file. The server decided the kind, so this is the one
// place that has to know what each of them looks like.
export function attachIcon(media: string) {
    const sx = { fontSize: 14 };
    switch (media) {
        case 'image': return <ImageOutlinedIcon sx={sx} />;
        case 'audio': return <AudiotrackIcon sx={sx} />;
        case 'video': return <MovieOutlinedIcon sx={sx} />;
        case 'pdf': return <PictureAsPdfOutlinedIcon sx={sx} />;
        case 'text': return <DescriptionOutlinedIcon sx={sx} />;
        default: return <InsertDriveFileOutlinedIcon sx={sx} />;
    }
}

// The files on the back of a card, and the place to drop another one.
export function CardAttachments({ card }: { card: Card }) {
    const body = useHeadingBody(card.Hash);
    const [busy, setBusy] = React.useState('');
    const [msg, setMsg] = React.useState('');
    const [failed, setFailed] = React.useState(false);
    const input = React.useRef<HTMLInputElement | null>(null);

    const send = React.useCallback(async (files: File[]) => {
        setFailed(false);
        for (const f of files) {
            setBusy(f.name);
            setMsg(`Attaching ${f.name}…`);
            try {
                const res = await ODb.attachFile(card.Hash, f, f.name);
                if (!res || res.Ok === false) {
                    setFailed(true);
                    setMsg((res && res.Msg) || `${f.name} did not go through.`);
                    break;
                }
                // Attaching can give the heading an :ID: and a tag, so the
                // card is saying more than "a file arrived".
                setMsg(res.NewId ? `${res.Name} attached — this heading was given an id` : `${res.Name} attached`);
            } catch (e: any) {
                setFailed(true);
                setMsg((e && e.message) || `${f.name} did not go through.`);
                break;
            }
        }
        setBusy('');
        refreshBody(card.Hash);
        window.setTimeout(() => { setMsg(''); setFailed(false); }, 3000);
    }, [card.Hash]);

    const { over, handlers } = useDropTarget(card.Hash, send);

    const remove = async (name: string) => {
        setBusy(name);
        try {
            const res = await ODb.deleteAttachment(card.Hash, name);
            setFailed(!res || res.Ok === false);
            setMsg((res && res.Msg) || '');
        } catch (e: any) {
            setFailed(true);
            setMsg((e && e.message) || 'That could not be deleted.');
        }
        setBusy('');
        refreshBody(card.Hash);
        window.setTimeout(() => { setMsg(''); setFailed(false); }, 3000);
    };

    const files = body.attachments || [];

    return (
        <Box
            {...handlers}
            onClick={e => e.stopPropagation()}
            sx={{
                mt: 1, p: 0.75, borderRadius: 'sm',
                border: '1px dashed',
                borderColor: over ? 'primary.400' : 'transparent',
                background: over ? 'primary.softBg' : 'transparent',
                transition: 'background .15s, border-color .15s',
            }}
        >
            {files.length > 0 && (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25, mb: 0.5 }}>
                    {files.map(a => (
                        <Box
                            key={a.Name}
                            sx={{
                                display: 'flex', alignItems: 'center', gap: 0.75, minWidth: 0,
                                color: 'text.secondary',
                                '&:hover .attach-bin': { opacity: 1 },
                            }}
                        >
                            {attachIcon(a.Media)}
                            <Link
                                href={a.Url}
                                target="_blank"
                                rel="noreferrer"
                                level="body-xs"
                                sx={{ fontSize: 11, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                                title={`${a.Name} · ${sizeLabel(a.Size)} · ${a.Modified}`}
                            >
                                {a.Name}
                            </Link>
                            <Typography level="body-xs" sx={{ fontSize: 10, color: 'text.tertiary', flex: 'none' }}>
                                {sizeLabel(a.Size)}
                            </Typography>
                            <IconButton
                                className="attach-bin"
                                size="sm"
                                variant="plain"
                                color="danger"
                                disabled={busy === a.Name}
                                onClick={() => remove(a.Name)}
                                sx={{ ml: 'auto', opacity: 0, transition: 'opacity .15s', '--IconButton-size': '20px' }}
                                title="throw this away"
                            >
                                <DeleteOutlineIcon sx={{ fontSize: 13 }} />
                            </IconButton>
                        </Box>
                    ))}
                </Box>
            )}

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0, color: failed ? 'danger.softColor' : 'text.tertiary' }}>
                {busy !== ''
                    ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '12px' }} />
                    : <AttachFileIcon sx={{ fontSize: 12 }} />}
                <Typography
                    level="body-xs"
                    sx={{ fontSize: 10, color: 'inherit', minWidth: 0, cursor: 'pointer' }}
                    noWrap
                    title={msg || 'drop a file here, or click to choose one'}
                    onClick={() => input.current && input.current.click()}
                >
                    {msg !== '' ? msg : (over ? 'Drop it to attach it here' : 'Drop a file here to attach it')}
                </Typography>
            </Box>
            <input
                ref={input}
                type="file"
                multiple
                style={{ display: 'none' }}
                onChange={e => {
                    const files = e.target.files ? Array.from(e.target.files) : [];
                    if (files.length) send(files);
                    e.target.value = '';
                }}
            />
        </Box>
    );
}

