// The player on the back of a card. Nothing is fetched until it is asked for,
// the same as the one the html export puts on a heading.
export function CardAudio({ src }: { src: string }) {
    if (src === '') return null;
    return (
        <Box sx={{ mb: 1 }} onClick={e => e.stopPropagation()}>
            <audio
                src={src}
                controls
                preload="none"
                style={{ width: '100%', height: 30, colorScheme: 'light dark' }}
            />
        </Box>
    );
}

// The picture on the front. Scaled to the card's width and cropped to a band
// rather than shown whole: a card is a summary, and a portrait photograph
// given its own way would be the whole card.
export function CardImage({ src, alt }: { src: string; alt: string }) {
    const [ok, setOk] = React.useState(true);
    if (src === '' || !ok) return null;
    return (
        <Box sx={{
            mb: 0.75,
            borderRadius: 'md',
            overflow: 'hidden',
            background: 'var(--joy-palette-background-level2)',
            // A hairline inside the frame rather than a border outside it:
            // the picture keeps its full width and the edge reads as part of
            // the card rather than as a box drawn round something.
            boxShadow: 'inset 0 0 0 1px var(--joy-palette-divider)',
            position: 'relative',
            // Nothing is known about what was pasted, and a photograph that
            // ends in white sits on a white card with no edge at all. A soft
            // wash at the foot gives it one without tinting the picture.
            '&::after': {
                content: '""',
                position: 'absolute', left: 0, right: 0, bottom: 0, height: '38%',
                background: 'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.16) 100%)',
                pointerEvents: 'none',
            },
        }}>
            <Box
                component="img"
                src={src}
                alt={alt}
                loading="lazy"
                onError={() => setOk(false)}
                sx={{ display: 'block', width: '100%', height: 96, objectFit: 'cover' }}
            />
        </Box>
    );
}

// What a heading says, under its own name: the text written under it and the
// properties on it, and the two things you can do to it from here. Shared by
// the back of a card and by a row of the list opened up, which are the same
// question asked in two layouts.
export function CardDetail({ card, board, clocked, onAct }: {
    card: Card; board: KanbanBoard; clocked: boolean;
    onAct: (what: CardAction, card: Card) => void;
}) {
    const [html, setHtml] = React.useState<string | null>(null);
    const [loading, setLoading] = React.useState(false);
    const wants = board.backShows === 'body' || board.backShows === 'both';

    // One fetch, when the back is first mounted - which the card only does once
    // it has been turned over, so a column of forty cards is not forty requests
    // for text nobody asked to read. Note what is *not* in the dependency list:
    // loading and html both change while this is running, and either of them in
    // there would tear the effect down and cancel the fetch it just started.
    React.useEffect(() => {
        if (!wants) return;
        let alive = true;
        setLoading(true);
        ODb.todoHtml(card.Hash).then(r => {
            if (!alive) return;
            setHtml((r && r.Content) || '');
            setLoading(false);
        }).catch(() => { if (alive) { setHtml(''); setLoading(false); } });
        return () => { alive = false; };
    }, [card.Hash, wants]);

    const props = card.Props || {};
    const propNames = Object.keys(props).filter(k => props[k] !== '');
    const showProps = board.backShows === 'properties' || board.backShows === 'both';

    // The recording and the checklist come from the heading's own text rather
    // than from the rendered html above, and both go before it: a list you can
    // tick and a thing you can play are what the back of the card is for.
    const body = useHeadingBody(card.Hash);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, minWidth: 0 }}>
            <Box sx={{ flex: 1, overflowY: 'auto', minHeight: 0, pr: 0.5 }}>
                <CardAudio src={body.audio} />
                <ChecklistPanel card={card} list={body.list} />
                {wants && (
                    loading ? <LinearProgress size="sm" sx={{ my: 1 }} /> : (
                        html === '' || html === null ? (
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                                Nothing written under this heading.
                            </Typography>
                        ) : (
                            <Box
                                sx={{
                                    fontSize: 11.5, lineHeight: 1.45, color: 'text.secondary',
                                    '& p': { m: 0, mb: 0.5 },
                                    '& ul, & ol': { m: 0, pl: 2 },
                                    '& img': { maxWidth: '100%' },
                                    '& pre': { fontSize: 10, overflowX: 'auto', p: 0.5, borderRadius: 4, background: 'var(--joy-palette-background-level2)' },
                                    '& table': { fontSize: 10, borderCollapse: 'collapse' },
                                    '& td, & th': { border: '1px solid var(--joy-palette-divider)', px: 0.5 },
                                    '& h1, & h2, & h3, & h4': { fontSize: 12, m: 0, mt: 0.5, mb: 0.25 },
                                }}
                                dangerouslySetInnerHTML={{ __html: html }}
                            />
                        )
                    )
                )}
                {showProps && propNames.length > 0 && (
                    <Box sx={{ mt: wants ? 1 : 0 }}>
                        {propNames.map(k => (
                            <Box key={k} sx={{ display: 'flex', gap: 1, fontSize: 10.5, lineHeight: 1.6, minWidth: 0 }}>
                                <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: 10, color: 'text.tertiary', flexShrink: 0 }}>
                                    {k}
                                </Typography>
                                <Typography level="body-xs" sx={{ fontSize: 10.5, minWidth: 0 }} noWrap title={props[k]}>
                                    {props[k]}
                                </Typography>
                            </Box>
                        ))}
                    </Box>
                )}
                {showProps && propNames.length === 0 && !wants && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        No properties on this heading.
                    </Typography>
                )}
            </Box>
            <CardPaste card={card} />
            <CardAttachments card={card} />
            <Divider sx={{ my: 0.75 }} />
            {/* Every one of these says what it *does*, not what it is called.
                They are three small glyphs at the bottom of a card and there is
                nothing else on screen to work them out from - "Archive" and
                "Archive this heading out of the file, where it stops matching
                the query" are not the same amount of help before pressing
                something that moves text out of a file. Placed above, because
                below is where the pointer already is. */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, minWidth: 0 }}>
                <Tooltip
                    size="sm"
                    placement="top-start"
                    enterDelay={300}
                    title={`This heading is line ${card.LineNum} of ${card.Filename}`}
                >
                    <Typography level="body-xs" sx={{ fontSize: 10, color: 'text.tertiary', minWidth: 0 }} noWrap>
                        <ArticleIcon sx={{ fontSize: 11, mr: 0.25, verticalAlign: '-1px' }} />
                        {baseName(card.Filename)}:{card.LineNum}
                    </Typography>
                </Tooltip>
                {/* Speaking into the heading. Beside the clock and the
                    archive, because it is the third thing you can do to a
                    heading from here. */}
                <CardVoice card={card} onDone={() => { /* the body reads itself back */ }} />
                <Box sx={{ ml: 'auto', display: 'flex', gap: 0.25 }} onClick={e => e.stopPropagation()}>
                    <Tooltip
                        size="sm"
                        placement="top"
                        enterDelay={300}
                        title={clocked
                            ? 'Stop the clock. The time since you started is written into this heading’s LOGBOOK.'
                            : 'Start the clock on this heading. Org records the time against it, and the Clock Report adds it up.'}
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color={clocked ? 'danger' : 'neutral'}
                            aria-label={clocked ? 'Stop the clock on this heading' : 'Start the clock on this heading'}
                            onClick={() => onAct(clocked ? 'clockout' : 'clockin', card)}
                        >
                            {clocked ? <StopIcon sx={{ fontSize: 14 }} /> : <PlayArrowIcon sx={{ fontSize: 14 }} />}
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Refile this heading somewhere else. A card in the wrong column is often a heading in the wrong file."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Refile this heading"
                            onClick={() => onAct('refile', card)}
                        >
                            <DriveFileMoveIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Copy this heading somewhere else, leaving it here as well."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Copy this heading"
                            onClick={() => onAct('copy', card)}
                        >
                            <ContentCopyIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                    <Tooltip
                        size="sm"
                        placement="top-end"
                        enterDelay={300}
                        title="Archive this heading. It is moved out of the file into its archive, so it stops matching the query and leaves the board."
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label="Archive this heading"
                            onClick={() => onAct('archive', card)}
                        >
                            <Inventory2Icon sx={{ fontSize: 14 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>
        </Box>
    );
}


