// The Refactor tab's requests: /refactor/* on the server
// (internal/app/orgs/refactor.go). Through ODb's own helpers so the auth
// header and the login retry are the ones every other request uses.

import { ODb } from './db';
import { Sets } from './config';
import {
    RefactorOp, RefactorPlan, RefactorRequest, RefactorTag, RefactorList, HeadingRow,
    applyRequest, headingQuery,
} from './refactor';

function url(path: string, params: Record<string, string> = {}): URL {
    const u = new URL(Sets.orgsConnection + path);
    for (const [k, v] of Object.entries(params)) u.searchParams.append(k, v);
    return u;
}

// A failed request comes back from ODb as [] (or a ResultMsg); either way the
// page wants a plan that says it failed.
function asPlan(res: any, fallback: string): RefactorPlan {
    if (res && typeof res === 'object' && !Array.isArray(res) && 'Ok' in res) {
        return { Files: [], Token: '', Op: '', Summary: '', ...res } as RefactorPlan;
    }
    return { Ok: false, Msg: fallback, Op: '', Summary: '', Files: [], Token: '' };
}

export async function refactorTags(): Promise<RefactorTag[]> {
    const res = await ODb.doGet<{ Ok: boolean; Tags: RefactorTag[] }>(url('/refactor/tags'));
    return res && Array.isArray(res.Tags) ? res.Tags : [];
}

export async function listsUnder(hash: string): Promise<{ Ok: boolean; Msg: string; Lists: RefactorList[] }> {
    const res = await ODb.doGet<any>(url('/refactor/lists', { hash }));
    if (res && Array.isArray(res.Lists)) return res;
    return { Ok: false, Msg: (res && res.Msg) || 'The server did not answer', Lists: [] };
}

export async function previewRefactor(op: RefactorOp, req: RefactorRequest): Promise<RefactorPlan> {
    return asPlan(await ODb.doPost<any>(url(`/refactor/${op}/preview`), req), 'The server did not answer the preview');
}

export async function applyRefactor(op: RefactorOp, req: RefactorRequest, plan: RefactorPlan): Promise<RefactorPlan> {
    return asPlan(await ODb.doPost<any>(url(`/refactor/${op}/apply`), applyRequest(req, plan)), 'The server did not answer');
}

// Headings for a picker, matched loosely on the server and ranked here.
export async function findHeadings(text: string, signal: AbortSignal): Promise<HeadingRow[]> {
    const q = headingQuery(text);
    if (!q) return [];
    const rows = await ODb.query(q, false, signal, '!IsArchived()');
    return Array.isArray(rows) ? rows as HeadingRow[] : [];
}

export async function orgDirs(): Promise<string[]> {
    return await ODb.getAllDirs();
}
