// The camera, and the one piece of real astronomy in here.
//
// Both functions write the point's screen coordinates in place, because they are
// called on every star (and every backdrop star, and every letter of every
// constellation name) every frame, and allocating a result would allocate tens of
// thousands of objects a second.

import { FOCAL, F2 } from './constants';
import { BlackHole, CameraState, Projectable } from './types';

// World space to screen space.
//
// Two modes. Orbiting, the camera looks at `ctr` from a distance set by the zoom;
// flying, it sits at `cam` and looks along its own heading. `near` marks a point
// so close to the camera that drawing it would smear it across the whole screen,
// and `nf` is the fade that stops things popping as they cross that line.
export function project(n: Projectable, cam: CameraState, W: number, H: number): void {
    const cy = Math.cos(cam.yaw), sy = Math.sin(cam.yaw);
    const cp = Math.cos(cam.pitch), sp = Math.sin(cam.pitch);

    if (cam.flightMode) {
        const nx = n.x - cam.cam.x, ny = n.y - cam.cam.y, nz = n.z - cam.cam.z;
        const x = nx * cy + nz * sy;
        let z = -nx * sy + nz * cy;
        const y = ny * cp - z * sp;
        z = ny * sp + z * cp;
        n.near = z < 70;
        n.nf = Math.min(1, Math.max(0, (z - 70) / 140));
        const s = Math.min(8, F2 / Math.max(70, z));
        n.sx = W / 2 + x * s;
        n.sy = H / 2 + y * s;
        n.ss = s;
        n.sd = z - FOCAL / (0.9 * cam.zoom);
        return;
    }

    const nx = n.x - cam.ctr.x, ny = n.y - cam.ctr.y, nz = n.z - cam.ctr.z;
    const x = nx * cy + nz * sy;
    let z = -nx * sy + nz * cy;
    const y = ny * cp - z * sp;
    z = ny * sp + z * cp;
    const den = FOCAL + z * cam.zoom * 0.9;
    n.near = den < 140;
    n.nf = Math.min(1, Math.max(0, (den - 140) / 200));
    const s = Math.min(6, FOCAL / Math.max(140, den) * cam.zoom);
    n.sx = W / 2 + x * s;
    n.sy = H / 2 + y * s;
    n.ss = s;
    n.sd = z;
}

// Gravitational lensing, the point-mass lens equation.
//
// A star behind the hole appears further from it than it is: at impact parameter
// b the image sits at (b + sqrt(b² + 4θE²)) / 2, so a star dead behind the hole
// (b → 0) lands on the Einstein ring itself. Only things actually *behind* it are
// bent, and only within seven Einstein radii - past that the deflection is under
// a pixel and the whole screen would be walked for nothing.
export function lensPoint(p: Projectable, hole: BlackHole): void {
    const thE = hole.lens || 0;
    if (thE <= 0 || hole.near || p.sd <= hole.sd + 10) return;
    const dx = p.sx - hole.sx, dy = p.sy - hole.sy;
    const b = Math.sqrt(dx * dx + dy * dy) || 0.001;
    if (b > thE * 7) return;
    const k = ((b + Math.sqrt(b * b + 4 * thE * thE)) / 2) / b;
    p.sx = hole.sx + dx * k;
    p.sy = hole.sy + dy * k;
}
