// POST /import/ipynb: a notebook into an org file. Its own module rather than
// a method on ODb, so the import dialog's one request lives beside nothing
// else's; the wire shape is internal/common/ipynb.go.

import { ODb } from './db';
import { Sets } from './config';

export type IpynbImported = {
    Ok: boolean;
    Msg: string;
    Filename: string;
    Files: string[] | null;
    Title: string;
    Language: string;
    Session: string;
    Nbformat: number;
    Cells: number;
    Markdown: number;
    Code: number;
    Raw: number;
    Blocks: number;
    Outputs: number;
    Images: number;
    Errors: number;
    Warnings?: string[];
};

export async function importNotebook(req: {
    notebook: string;
    name: string;
    filename: string;
    overwrite?: boolean;
}): Promise<IpynbImported> {
    const url = new URL(Sets.orgsConnection + '/import/ipynb');
    const res = await ODb.doPost<IpynbImported>(url, {
        Notebook: req.notebook,
        Name: req.name,
        Filename: req.filename,
        Overwrite: !!req.overwrite,
    });
    // doPost answers [] when the request itself failed (no server, no route).
    if (!res || Array.isArray(res) || typeof (res as any).Ok !== 'boolean') {
        return { Ok: false, Msg: 'The server did not answer the import (is it new enough to have /import/ipynb?)' } as IpynbImported;
    }
    return res;
}
