// Encrypted headings (org-crypt), as the reading views see them.
//
// The server decides what is secret and holds the only code that decrypts
// (crypt.go, cryptui.go). What lives here is finding the ciphertext in what a
// view already has - the file's lines in the source view, the exporter's html
// in the rendered view and the inspect dialog - so it can be swapped for a
// locked placeholder before anybody has to look at forty lines of base64.
//
// Finding it in the lines has to agree with crypt.go exactly, or the
// placeholder goes over the wrong rows: a heading's secret is everything after
// its planning line and drawers to the end of its subtree (`cryptRange`, with
// `headEnd` and `subtreeEndRow`), and it is ciphertext when the first non-blank
// line of that starts with the armour header (`isArmored`). Pinned by
// crypt.test.ts.

export const ARMOR_BEGIN = '-----BEGIN PGP MESSAGE-----';
export const ARMOR_END = '-----END PGP MESSAGE-----';

// `subtreeEndRow`'s idea of a heading: stars then a space, in column zero.
const HEADING = /^(\*+) (.*)$/;
// `planningRe`, `drawerOpenRe`, `drawerEndRe` in records.go.
const PLANNING = /^\s*(SCHEDULED|DEADLINE|CLOSED):/;
const DRAWER_OPEN = /^\s*:([A-Za-z][A-Za-z0-9_-]*):\s*$/;
const DRAWER_END = /^\s*:END:\s*$/;
const TAGS = /\s+:([^\s:]+(?::[^\s:]+)*):\s*$/;

export interface CryptLines {
    // The headline's row, zero based - what the server names it by.
    head: number;
    level: number;
    title: string;
    tags: string[];
    // Carries the crypt tag itself (not inherited, as crypt.go reads it).
    tagged: boolean;
    // Whether the body is ciphertext now.
    encrypted: boolean;
    // The secret: from after the drawers to the end of the subtree.
    bodyStart: number;
    bodyEnd: number;
    // The armoured block itself, when encrypted; -1 otherwise.
    armorStart: number;
    armorEnd: number;
}

export function headingTags(line: string): string[] {
    const m = TAGS.exec(line);
    return m ? m[1].split(':').filter(t => t !== '') : [];
}

function headingTitle(rest: string): string {
    return rest.replace(TAGS, '').trim();
}

// The last row of a heading's subtree: up to the next heading at its level or
// above, or the end of the file.
export function subtreeEnd(lines: string[], row: number, level: number): number {
    for (let i = row + 1; i < lines.length; i++) {
        const m = /^(\*+) /.exec(lines[i]);
        if (m && m[1].length <= level) return i - 1;
    }
    return lines.length - 1;
}

// The first row after the headline's planning lines and drawers.
export function headEnd(lines: string[], from: number, to: number): number {
    let i = from + 1;
    while (i <= to && i < lines.length) {
        const line = lines[i];
        if (PLANNING.test(line)) { i++; continue; }
        if (DRAWER_OPEN.test(line)) {
            let j = i + 1;
            while (j <= to && j < lines.length && !DRAWER_END.test(lines[j])) j++;
            if (j > to || j >= lines.length) return i;
            i = j + 1;
            continue;
        }
        break;
    }
    return i;
}

// Every heading that is tagged for encryption or has ciphertext for a body,
// in file order. An untagged heading with an armoured body is included: the
// server reveals it all the same, and hiding the block is the point.
export function cryptLines(text: string, tag: string = 'crypt'): CryptLines[] {
    const lines = text.replace(/\r\n/g, '\n').split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
    const want = (tag || 'crypt').toLowerCase();
    const out: CryptLines[] = [];
    for (let row = 0; row < lines.length; row++) {
        const h = HEADING.exec(lines[row]);
        if (h === null) continue;
        const level = h[1].length;
        const tags = headingTags(lines[row]);
        const tagged = tags.some(t => t.toLowerCase() === want);
        const end = subtreeEnd(lines, row, level);
        const start = headEnd(lines, row, end);
        let first = -1;
        for (let i = start; i <= end; i++) {
            if (lines[i].trim() !== '') { first = i; break; }
        }
        const encrypted = first >= 0 && lines[first].trim().startsWith(ARMOR_BEGIN);
        if (!tagged && !encrypted) continue;
        let armorEnd = -1;
        if (encrypted) {
            armorEnd = end;
            for (let i = first; i <= end; i++) {
                if (lines[i].trim().startsWith(ARMOR_END)) { armorEnd = i; break; }
            }
        }
        out.push({
            head: row, level, title: headingTitle(h[2]), tags, tagged, encrypted,
            bodyStart: start, bodyEnd: end,
            armorStart: encrypted ? first : -1, armorEnd,
        });
        // The rows inside an armoured block are base64, never headings, so
        // there is nothing to find there - but a plain tagged heading's
        // children are headings of their own and are walked as usual.
        if (encrypted) row = Math.max(row, armorEnd);
    }
    return out;
}

// ---------------------------------------------------------------------------
// The rendered views
// ---------------------------------------------------------------------------

// The exporter's version of an armoured block is not the block. Seen from the
// html exporter: the dashes come out as typography (`-----` is an em dash and
// an en dash, `—–BEGIN PGP MESSAGE—–`), the blank line after the header makes
// it two paragraphs, and the base64 inside may have been read as emphasis,
// since it is full of `/` and `+`. So only the two marker lines are relied on,
// with their dashes in any of those spellings, and the match runs from the
// element holding the first to the end of the element holding the second.
const DASHES = '(?:-|\u2013|\u2014|&[mn]dash;|&#821[12];)+';
const MARK_BEGIN = DASHES + 'BEGIN PGP MESSAGE' + DASHES;
const MARK_END = DASHES + 'END PGP MESSAGE' + DASHES;
const ARMOR_ELEMENT = new RegExp(
    '<(p|pre|div)\\b[^>]*>\\s*' + MARK_BEGIN + '[\\s\\S]*?' + MARK_END + '\\s*</(?:p|pre|div)>', 'g');
const ARMOR_BARE = new RegExp(MARK_BEGIN + '[\\s\\S]*?' + MARK_END, 'g');

export const PLACEHOLDER_CLASS = 'orgs-crypt';

// Swap every armoured block in exported html for what `placeholder(n)` says,
// n counting from zero in document order. Answers the html and how many were
// swapped.
export function replaceArmorHtml(html: string, placeholder: (n: number) => string): { html: string; count: number } {
    let n = 0;
    let out = html.replace(ARMOR_ELEMENT, () => placeholder(n++));
    // Anything the exporter wrapped some other way still never shows.
    out = out.replace(ARMOR_BARE, () => placeholder(n++));
    return { html: out, count: n };
}

// Exported html with each armoured block said in two words rather than shown,
// for a preview too small to reveal anything in.
export function lockedHtml(html: string): string {
    if (!hasArmor(html)) return html;
    return replaceArmorHtml(html, () => '<p><span aria-hidden="true">🔒</span> <em>Encrypted</em></p>').html;
}

// Raw text or exported html: the words survive the exporter, the dashes do not.
export function hasArmor(text: string): boolean {
    return text.indexOf('BEGIN PGP MESSAGE') >= 0;
}

// How long revealed text stays on screen with nobody touching it. The
// server's unlock window when it has one, since that is the reader's own
// statement of how long a secret may sit open; otherwise five minutes.
export function revealIdleMs(unlockSeconds: number): number {
    const secs = unlockSeconds > 0 ? unlockSeconds : 300;
    return Math.max(60, secs) * 1000;
}

// "4 min", "45 s": the time left on an unlock, for a chip.
export function shortLeft(seconds: number): string {
    if (seconds <= 0) return '';
    if (seconds < 90) return `${seconds} s`;
    return `${Math.round(seconds / 60)} min`;
}
