import { useWatches, saveWatch, removeWatch } from '../querywatchApi';
import { watchOf, plainWatch } from '../querywatch';

interface StoredQuery {
  name: string;
  query: string;
}

// Where a saved query is used.
//
// Only one thing in worg *stores* a reference to one: a kanban board, which
// names it and reads it afresh every time the board is opened. The gantt and
// mind map tabs offer the list and pick one while you are looking at them,
// which is not a use anything could go and check - so those are said once, as
// a note, rather than listed per query as though they were links.
//
// The point of the column is the question you ask before pressing delete.
const OFFERED_IN = ['Gantt Chart', 'Mind Map'];

interface QueryUse {
    // The boards naming this query, by board name.
    boards: string[];
}

function usesOf(boards: KanbanBoard[]): Record<string, QueryUse> {
    const out: Record<string, QueryUse> = {};
    for (const b of boards) {
        const name = (b.storedQuery || '').trim();
        if (name === '') continue;
        if (!out[name]) out[name] = { boards: [] };
        out[name].boards.push(b.name);
    }
    for (const k of Object.keys(out)) out[k].boards.sort();
    return out;
}

interface PreviewResult {
  count: number;
  samples: { Headline: string; Status: string }[];
  loading: boolean;
  // The server's complaint when the expression does not parse, so a typo
  // reads as a typo rather than as "0 matches".
  error: string;
}

const NO_PREVIEW: PreviewResult = { count: 0, samples: [], loading: false, error: '' };

// What a saved text finds, run exactly as written.
//
// The base filter is empty on purpose. This used to go through ODb.query's
// default of `!IsArchived() && IsTodo()`, so every preview quietly dropped
// notes, finished tasks and projects - and a query that matched them looked
// broken here while working everywhere else. The only-open-todos switch now
// puts that filter into the text itself, where it can be seen.
function usePreview(text: string, delay: number): PreviewResult {
  const [preview, setPreview] = React.useState<PreviewResult>(NO_PREVIEW);
  React.useEffect(() => {
    if (!text.trim()) {
      setPreview(NO_PREVIEW);
      return;
    }
    // Loading from the moment the text changes, not from when the debounce
    // fires - or the old count sits there for 400ms looking like the answer.
    setPreview(p => ({ ...p, loading: true }));
    const controller = new AbortController();
    const timer = setTimeout(() => {
      ODb.query(text, false, controller.signal, '').then(results => {
        if (controller.signal.aborted) return;
        // No matches is `null` from an older server (a nil list in Go) and
        // `[]` from a newer one - both are zero, not an error. It was read as
        // an error, which reported every query that found nothing as one
        // that did not parse.
        if (results == null) results = [];
        if (!Array.isArray(results)) {
          // A query that does not parse comes back as an object: `{Ok, Msg}`
          // with the reason, or `{}` from a server older than that.
          const msg = (results as any).Msg;
          setPreview({ ...NO_PREVIEW, error: msg ? `Does not parse: ${msg}` : 'The expression does not parse' });
          return;
        }
        setPreview({
          count: results.length,
          samples: results.slice(0, 5).map(r => ({ Headline: r.Headline, Status: r.Status })),
          loading: false,
          error: '',
        });
      }).catch(e => {
        if (!controller.signal.aborted) {
          setPreview({ ...NO_PREVIEW, error: String((e && e.message) || 'The query failed') });
        }
      });
    }, delay);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [text, delay]);
  return preview;
}

function PreviewSamples({ preview }: { preview: PreviewResult }) {
  return (
    <Box sx={{ mt: 0.5 }}>
      {preview.samples.map((s, i) => (
        <Typography key={i} level="body-xs" sx={{ color: 'text.secondary' }}>
          {s.Status && <Chip size="sm" variant="outlined" sx={{ mr: 0.5 }}>{s.Status}</Chip>}
          {s.Headline}
        </Typography>
      ))}
      {preview.count > 5 && (
        <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
          ...and {preview.count - 5} more
        </Typography>
      )}
    </Box>
  );
}

function PreviewCount({ preview, color }: { preview: PreviewResult; color: 'primary' | 'success' }) {
  if (preview.error) {
    return <Chip size="sm" variant="soft" color="danger">{preview.error}</Chip>;
  }
  return (
    <Chip size="sm" variant="soft" color={preview.count > 0 ? color : 'neutral'}>
      {preview.count} match{preview.count !== 1 ? 'es' : ''}
    </Chip>
  );
}

function QueryPreview({ query }: { query: string }) {
  const preview = usePreview(query, 0);
  const [expanded, setExpanded] = React.useState(false);

  if (preview.loading) {
    return <CircularProgress size="sm" />;
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <PreviewCount preview={preview} color="primary" />
        {preview.samples.length > 0 && (
          <IconButton size="sm" variant="plain" onClick={() => setExpanded(!expanded)}>
            {expanded ? <ExpandLessIcon fontSize="small" /> : <ExpandMoreIcon fontSize="small" />}
          </IconButton>
        )}
      </Box>
      {expanded && preview.samples.length > 0 && <Box sx={{ pl: 1 }}><PreviewSamples preview={preview} /></Box>}
    </Box>
  );
}

export default function StoredQueries() {
  const [queries, setQueries] = React.useState<StoredQuery[]>([]);
  const [loading, setLoading] = React.useState(true);
  // The form at the top is both "add" and "edit": `editing` is the name of
  // the query being changed, or null for a new one.
  const [editing, setEditing] = React.useState<string | null>(null);
  const [newName, setNewName] = React.useState('');
  const [newQuery, setNewQuery] = React.useState('');
  // On for a new query: most saved queries are task lists, and it is what
  // the preview used to assume without saying so.
  const [todosOnly, setTodosOnly] = React.useState(true);
  const [saving, setSaving] = React.useState(false);
  const [saveError, setSaveError] = React.useState('');
  const [boards, setBoards] = React.useState<KanbanBoard[]>([]);
  const formRef = React.useRef<HTMLDivElement | null>(null);
  // Which queries are watched (the bell on each row), live from the shared
  // store the header bell reads.
  const { watches } = useWatches();

  // What will be saved, and so what the preview runs.
  const savedText = withTodoFilter(newQuery, todosOnly);
  // Shown once something has been typed (or a query is open for editing): an
  // empty form with the switch on would otherwise preview every open todo.
  const showing = newQuery.trim() !== '' || editing !== null;
  const newQueryPreview = usePreview(showing ? savedText : '', 400);

  const fetchQueries = React.useCallback(async () => {
    setLoading(true);
    try {
      const result = await ODb.getStoredQueries();
      setQueries(result || []);
    } catch {
      setQueries([]);
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    fetchQueries();
  }, [fetchQueries]);

  // The boards, for the Used by column. Read once beside the queries: a board
  // is a small thing and there are never many of them.
  React.useEffect(() => {
    let alive = true;
    ODb.getKanbanBoards()
      .then(r => { if (alive) setBoards(Array.isArray(r) ? r : []); })
      .catch(() => { if (alive) setBoards([]); });
    return () => { alive = false; };
  }, []);

  const uses = React.useMemo(() => usesOf(boards), [boards]);

  // A board naming a query that is not there any more. Worth saying out loud:
  // the board opens, finds nothing, and looks like a board whose query stopped
  // matching rather than one pointing at a name nobody kept.
  const dangling = React.useMemo(() => {
    const have = new Set(queries.map(q => q.name));
    return boards
      .filter(b => (b.storedQuery || '').trim() !== '' && !have.has(b.storedQuery))
      .map(b => ({ board: b.name, query: b.storedQuery }));
  }, [boards, queries]);

  const resetForm = () => {
    setEditing(null);
    setNewName('');
    setNewQuery('');
    setTodosOnly(true);
    setSaveError('');
  };

  const startEdit = (q: StoredQuery) => {
    const parts = splitTodoFilter(q.query);
    setEditing(q.name);
    setNewName(q.name);
    setNewQuery(parts.query);
    setTodosOnly(parts.todosOnly);
    setSaveError('');
    // The form is at the top of a list that can be long.
    window.setTimeout(() => formRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0);
  };

  // A name already taken by a different query. Saving would replace that one
  // without a word - the server saves by name.
  const clash = React.useMemo(() => {
    const n = newName.trim();
    return n !== '' && n !== editing && queries.some(q => q.name === n);
  }, [newName, editing, queries]);

  const canSave = newName.trim() !== '' && savedText !== '' && !clash;

  const handleSave = async () => {
    if (!canSave) return;
    const name = newName.trim();
    setSaving(true);
    setSaveError('');
    try {
      await ODb.saveStoredQuery(name, savedText);
      if (editing !== null && editing !== name) {
        // A rename. The boards and decks that read this query name it, so
        // they are pointed at the new name before the old one goes - or they
        // would be left reading a query that is not there any more.
        // Read afresh rather than from when the page opened, so a board
        // changed in another tab since is not written back over.
        const fresh = await ODb.getKanbanBoards().catch(() => boards);
        const b = renamed(Array.isArray(fresh) ? fresh : boards, editing, name);
        if (b.changed > 0) {
          await ODb.saveKanbanBoards(b.all);
          setBoards(b.all);
        }
        const decks = await ODb.getDrillDecks().catch(() => [] as DrillDeck[]);
        const d = renamed(decks, editing, name);
        if (d.changed > 0) await ODb.saveDrillDecks(d.all);
        // A watch follows its query to the new name, rather than being left
        // watching a name that is about to stop existing.
        const w = watchOf(watches.watches, editing);
        if (w) {
          await saveWatch({ ...plainWatch(w), name: w.name === editing ? name : w.name, storedQuery: name });
          if (w.name === editing) await removeWatch(editing);
        }
        await ODb.deleteStoredQuery(editing);
      }
      resetForm();
      await fetchQueries();
    } catch (e: any) {
      setSaveError(String((e && e.message) || e || 'Saving failed'));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (name: string) => {
    // A query a board is built on is not deleted on one click. The board does
    // not break loudly when its query goes - it just finds nothing - so this
    // is the only moment anybody is in a position to notice.
    const used = uses[name];
    if (used && used.boards.length > 0) {
      const which = used.boards.join(', ');
      const ok = window.confirm(
        `“${name}” is what ${used.boards.length === 1 ? 'the board' : 'the boards'} ${which} `
        + `${used.boards.length === 1 ? 'reads' : 'read'}. Deleting it leaves `
        + `${used.boards.length === 1 ? 'that board' : 'those boards'} with nothing to show.\n\nDelete it anyway?`,
      );
      if (!ok) return;
    }
    await ODb.deleteStoredQuery(name);
    // Its watch would only report that the query is gone.
    const w = watchOf(watches.watches, name);
    if (w) await removeWatch(w.name);
    if (editing === name) resetForm();
    await fetchQueries();
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      {/* The form: adds a query, or changes the one whose pencil was pressed. */}
      <Sheet
        ref={formRef}
        variant="outlined"
        color={editing !== null ? 'primary' : 'neutral'}
        sx={{ borderRadius: 'sm', p: 2, scrollMarginTop: 16 }}
      >
        <Typography level="title-md" sx={{ mb: 1.5 }}>
          {editing !== null ? <>Edit <b>{editing}</b></> : 'Add Query'}
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
          <Input
            placeholder="Query name"
            value={newName}
            onChange={e => setNewName(e.target.value)}
            size="sm"
            color={clash ? 'danger' : 'neutral'}
          />
          {clash && (
            <Typography level="body-xs" color="danger">
              There is already a query called “{newName.trim()}”. Pick another name, or edit that one instead.
            </Typography>
          )}
          {editing !== null && newName.trim() !== '' && newName.trim() !== editing && !clash
            && (uses[editing]?.boards.length || 0) > 0 && (
            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
              Renaming it also re-points {uses[editing].boards.join(', ')} at the new name.
            </Typography>
          )}
          {/* The same box as the search tab: function names as you type,
              and inside the quotes the keywords, tags, properties and values
              that are actually in the org files. */}
          <QueryBox
            placeholder='Query expression, e.g. IsStatus("TODO") && HasTags("work")'
            value={newQuery}
            onChange={setNewQuery}
            onEnter={handleSave}
          />
          <Checkbox
            size="sm"
            checked={todosOnly}
            onChange={e => setTodosOnly(e.target.checked)}
            label={
              <span>
                Only open todos — adds{' '}
                <Box component="code" sx={{ fontSize: 12 }}>{TODO_FILTER}</Box>
                {' '}in front of the query
              </span>
            }
          />
          {showing && savedText !== '' && (
            <Typography level="body-xs" sx={{ color: 'text.tertiary', fontFamily: 'monospace', wordBreak: 'break-all' }}>
              Saved as: {savedText}
            </Typography>
          )}
          {showing && savedText !== '' && (
            <Box sx={{ pl: 1 }}>
              {newQueryPreview.loading ? (
                <CircularProgress size="sm" />
              ) : (
                <Box>
                  <PreviewCount preview={newQueryPreview} color="success" />
                  {newQueryPreview.samples.length > 0 && <PreviewSamples preview={newQueryPreview} />}
                </Box>
              )}
            </Box>
          )}
          {saveError && <Typography level="body-xs" color="danger">{saveError}</Typography>}
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              startDecorator={editing !== null ? <SaveIcon /> : <AddIcon />}
              onClick={handleSave}
              loading={saving}
              disabled={!canSave}
              size="sm"
            >
              {editing !== null ? 'Save Changes' : 'Add Query'}
            </Button>
            {editing !== null && (
              <Button size="sm" variant="plain" color="neutral" onClick={resetForm}>
                Cancel
              </Button>
            )}
          </Box>
        </Box>
      </Sheet>

      {dangling.length > 0 && (
        <Alert size="sm" variant="soft" color="warning" startDecorator={<WarningIcon />}>
          <Box>
            {dangling.map(d => (
              <Typography key={`${d.board}/${d.query}`} level="body-sm">
                The board <b>{d.board}</b> reads a saved query called <b>{d.query}</b>, which is not here.
              </Typography>
            ))}
          </Box>
        </Alert>
      )}

      {/* Existing queries list */}
      <Sheet variant="outlined" sx={{ borderRadius: 'sm', overflow: 'auto' }}>
        {queries.length === 0 ? (
          <Box sx={{ p: 3, textAlign: 'center' }}>
            <Typography level="body-md" sx={{ color: 'text.secondary' }}>
              No stored queries yet. Add one above.
            </Typography>
          </Box>
        ) : (
          <Table stickyHeader hoverRow sx={{ '& tr > *:last-child': { textAlign: 'right' } }}>
            <thead>
              <tr>
                <th style={{ width: '16%' }}>Name</th>
                <th style={{ width: '28%' }}>Query</th>
                <th style={{ width: '24%' }}>Preview</th>
                <th style={{ width: '18%' }}>Used by</th>
                <th style={{ width: '14%' }}></th>
              </tr>
            </thead>
            <tbody>
              {queries.map(q => (
                <tr key={q.name}>
                  <td>
                    <Typography level="body-sm" fontWeight="md">{q.name}</Typography>
                  </td>
                  <td>
                    {splitTodoFilter(q.query).todosOnly && (
                      <Tooltip size="sm" title={`Starts with ${TODO_FILTER}`}>
                        <Chip size="sm" variant="soft" color="success" sx={{ mb: 0.5 }}>Open todos only</Chip>
                      </Tooltip>
                    )}
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', wordBreak: 'break-all' }}>
                      {splitTodoFilter(q.query).todosOnly ? splitTodoFilter(q.query).query || '(nothing else)' : q.query}
                    </Typography>
                  </td>
                  <td>
                    <QueryPreview query={q.query} />
                  </td>
                  <td>
                    {(uses[q.name] ? uses[q.name].boards : []).length === 0 ? (
                      <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        Nothing is built on it
                      </Typography>
                    ) : (
                      <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                        {uses[q.name].boards.map(b => (
                          <Tooltip key={b} size="sm" title={`The kanban board “${b}” reads this query`}>
                            <Chip
                              size="sm"
                              variant="soft"
                              color="primary"
                              startDecorator={<ViewKanbanIcon sx={{ fontSize: 13 }} />}
                            >
                              {b}
                            </Chip>
                          </Tooltip>
                        ))}
                      </Box>
                    )}
                  </td>
                  <td>
                    <Box sx={{ display: 'inline-flex', gap: 0.5 }}>
                    <WatchToggle
                      query={q.name}
                      watch={watchOf(watches.watches, q.name)}
                      desktopAvailable={watches.desktop}
                    />
                    <Tooltip size="sm" title="Edit this query">
                      <IconButton
                        size="sm"
                        variant={editing === q.name ? 'solid' : 'soft'}
                        color="primary"
                        aria-label={`Edit the saved query ${q.name}`}
                        onClick={() => startEdit(q)}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip
                      size="sm"
                      title={(uses[q.name] ? uses[q.name].boards : []).length > 0
                        ? 'Delete this query — it will ask first, because a board is built on it'
                        : 'Delete this query'}
                    >
                      <IconButton
                        size="sm"
                        variant="soft"
                        color="danger"
                        aria-label={`Delete the saved query ${q.name}`}
                        onClick={() => handleDelete(q.name)}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    </Box>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        )}
      </Sheet>

      {/* Said once rather than against every row: these two tabs offer the
          whole list and pick one while you are looking at them, so no saved
          query is any more "used by" them than any other. */}
      <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
        Every saved query is also offered in the {OFFERED_IN.join(' and ')} tabs, which choose one
        when you open them rather than keeping a reference to it.
      </Typography>
    </Box>
  );
}
