// What colour each constellation is.
//
// The seven base hues are hand picked and the biggest constellations ride them.
// Everything after that mints its own, at the hue furthest from every colour
// already in the sky and then at whichever saturation and lightness is furthest
// from every colour already in the sky - because an org database has as many
// constellations as you have folders (or files), and a fourteenth one drawn in
// almost-the-same-teal as the third is a constellation nobody can pick out.
//
// This is a pure function of the family list rather than a mutated registry. The
// original it is ported from kept one module-level map and added to it, which is
// fine in a plugin that opens one view and wrong here: a tab that is mounted,
// looked at, left and come back to would accumulate colours for constellations
// that no longer exist and hand out different ones each time.

import { BASE_HUES, PENTA } from './constants';
import { hslCol, hueOfHex, rgbDist, rgbOfHex, rotHue } from './color';
import { Family, FamilyLook, Palette } from './types';

// The saturation and lightness pairs a minted colour may use, tried in turn and
// judged by how far the result lands from everything already chosen. Three is
// enough: they are light, pale and deep, and a hue has no fourth distinct
// reading at three pixels across.
const SL: [number, number][] = [[0.68, 0.63], [0.50, 0.72], [0.80, 0.53]];

// The colour for the nth constellation past the base hues.
//
// `chosen` is everything already in the sky, as bare triplets, and is added to.
function mintColour(chosen: string[], hues: number[]): { css: string; rgb: string; hue: number } {
    let bestH = 0;
    let bestGap = -1;
    for (let h = 0; h < 360; h += 3) {
        let nearest = 360;
        for (const u of hues) {
            let gap = Math.abs(h - u) % 360;
            if (gap > 180) gap = 360 - gap;
            if (gap < nearest) nearest = gap;
        }
        if (nearest > bestGap) {
            bestGap = nearest;
            bestH = h;
        }
    }
    let best: { css: string; rgb: string; hue: number } | null = null;
    let bestD = -1;
    for (const [s, l] of SL) {
        const cand = hslCol(bestH, s, l);
        let nearest = Infinity;
        for (const o of chosen) {
            const d = rgbDist(cand.rgb, o);
            if (d < nearest) nearest = d;
        }
        if (nearest > bestD) {
            bestD = nearest;
            best = { ...cand, hue: bestH };
        }
    }
    return best as { css: string; rgb: string; hue: number };
}

// One look per constellation, in the order they were given - which is the order
// the server sorts them, busiest first, so the base hues land on the biggest
// constellations and stay on them between reads.
//
// `hueRot` is the universe hue slider. It is applied last, to every colour at
// once, so rotating the sky cannot make two constellations collide: the whole
// arrangement turns together.
export function buildPalette(families: Family[], hueRot: number = 0): Palette {
    const out: Palette = {};
    const chosen: string[] = BASE_HUES.map(rgbOfHex);
    const hues: number[] = BASE_HUES.map(hueOfHex);

    families.forEach((fam, i) => {
        let css: string;
        let rgb: string;
        let hue: number;
        if (i < BASE_HUES.length) {
            css = BASE_HUES[i];
            rgb = rgbOfHex(css);
            hue = hueOfHex(css);
        } else {
            const c = mintColour(chosen, hues);
            css = c.css;
            rgb = c.rgb;
            hue = c.hue;
            chosen.push(rgb);
            hues.push(hue);
        }
        if (hueRot) {
            // rotHue wants hex. A minted colour is hex and so is a base hue, so
            // this always has one to work from.
            const r = rotHue(css, hueRot);
            css = r.css;
            rgb = r.rgb;
            hue = (hue + hueRot) % 360;
        }
        out[fam.key] = {
            key: fam.key,
            name: fam.name,
            css,
            rgb,
            hue,
            // Past the pentatonic set the notes start again an octave down, so a
            // database with thirty constellations still sounds like one
            // instrument rather than like a phone book.
            snd: PENTA[i % PENTA.length] * (i >= PENTA.length ? 0.5 : 1),
        };
    });
    return out;
}

// The look for a key that may not be in the palette at all - a star whose
// constellation was filtered out from under it. Grey, and never a crash in the
// middle of a render loop.
const UNKNOWN: FamilyLook = {
    key: '', name: '', css: '#8FA0C0', rgb: '143,160,192', hue: 220, snd: 440,
};

export function lookOf(pal: Palette, key: string): FamilyLook {
    return pal[key] || UNKNOWN;
}
