// The links panel's own model: the wire types of /links/heading, /mentions and
// /mentions/link, and the small pieces of logic the panel would otherwise
// carry inline - which heading the reader is on, how a mention's sentence is
// cut to fit and where its match sits, and how a list of mentions is gathered
// under files and headings.
//
// What counts as a mention is decided by the server (mentions.go) and nowhere
// else; nothing here looks for one.

import { OrgLink } from './db';

export type LinkTarget = {
    Kind: 'heading' | 'file' | string;
    Filename: string;
    Hash: string;
    Headline: string;
    Olp: string[] | null;
    Line: number;
    Title: string;
    Id: string;
    Terms: string[] | null;
    Skipped: string[] | null;
};

// The line a link is written on; Before/Shown/After are the same line cut at
// the link itself, empty when the server could not find it there.
export type LinkInContext = OrgLink & { Context: string; Before: string; Shown: string; After: string };

export type LinksAround = {
    Ok: boolean;
    Msg: string;
    Target: LinkTarget;
    In: LinkInContext[] | null;
    Out: LinkInContext[] | null;
};

export type Mention = {
    Filename: string;
    Line: number;  // zero based
    Col: number;   // a byte offset on the server's side: handed back, never used here
    Text: string;
    Term: string;
    Before: string;
    After: string;
    Hash: string;
    Headline: string;
    Olp: string[] | null;
    InHeadline: boolean;
};

export type MentionsResult = {
    Ok: boolean;
    Msg: string;
    Target: LinkTarget;
    Mentions: Mention[] | null;
    Total: number;
    Truncated: boolean;
};

export type MentionRef = { Filename: string; Line: number; Col: number; Text: string };

export type MentionLinkRequest = { Hash: string; Filename: string; Mentions: MentionRef[] };

export type MentionLinkOutcome = MentionRef & { Ok: boolean; Msg: string; Link: string };

export type MentionLinkResult = {
    Ok: boolean;
    Msg: string;
    Linked: number;
    Id: string;
    NewId: boolean;
    Results: MentionLinkOutcome[] | null;
};

// ---------------------------------------------------------------------------
// Which heading the reader is on
// ---------------------------------------------------------------------------

// A heading of the open file, as /filecontents/headings answers it.
export type OutlineHeading = { Hash: string; Headline: string; LineNum: number; Level: number };

// The heading a line is under: the last one starting at or above it. A line
// above the first heading is under none, and the file is what is being read.
export function headingAt(heads: OutlineHeading[], line: number): OutlineHeading | null {
    let best: OutlineHeading | null = null;
    for (const h of heads) {
        if (h.LineNum > line) continue;
        if (best === null || h.LineNum >= best.LineNum) best = h;
    }
    return best;
}

function norm(s: string): string {
    return s.replace(/\s+/g, ' ').trim().toLowerCase();
}

// The heading a rendered page's <h2> stands for. The exported page has no
// line numbers and its heading text carries the keyword, tags and section
// numbers as well as the title, so a heading is found by its title being in
// the text - and `nth` (how many headings before this one on the page read the
// same) tells two headings of the same name apart.
export function headingForRendered(heads: OutlineHeading[], text: string, nth: number = 0): OutlineHeading | null {
    const want = norm(text);
    if (want === '') return null;
    const exact = heads.filter(h => norm(h.Headline) === want);
    const loose = exact.length > 0 ? exact : heads
        .filter(h => norm(h.Headline) !== '' && want.indexOf(norm(h.Headline)) >= 0)
        // The longest title in the text is the one it is about: "Apollo" is
        // in "TODO Apollo launch", but so is "Apollo launch".
        .sort((a, b) => norm(b.Headline).length - norm(a.Headline).length);
    if (loose.length === 0) return null;
    if (exact.length > 0) return exact[Math.min(nth, exact.length - 1)];
    const longest = norm(loose[0].Headline).length;
    const same = loose.filter(h => norm(h.Headline).length === longest);
    return same[Math.min(nth, same.length - 1)];
}

// ---------------------------------------------------------------------------
// Drawing a mention
// ---------------------------------------------------------------------------

// A sentence cut down to about `width` characters around its match, cut at a
// word where there is one near, and marked with an ellipsis where it was cut.
// The match itself is never cut: it is the thing being shown.
export function snippet(before: string, match: string, after: string, width: number = 72): [string, string, string] {
    const room = Math.max(0, width - match.length);
    // A little more of what comes before than after: the words leading up to
    // a name are what say how it is being used.
    let b = before;
    let a = after;
    const wantB = Math.ceil(room * 0.55);
    const wantA = room - Math.min(b.length, wantB);
    if (b.length > wantB) {
        let cut = b.slice(b.length - wantB);
        const sp = cut.search(/\s/);
        if (sp >= 0 && sp < 12) cut = cut.slice(sp + 1);
        b = '…' + cut.replace(/^…/, '');
    }
    if (a.length > wantA) {
        let cut = a.slice(0, Math.max(0, wantA));
        const sp = cut.search(/\s\S*$/);
        if (sp > 0 && cut.length - sp < 12) cut = cut.slice(0, sp);
        a = cut.replace(/…$/, '') + '…';
    }
    return [b, match, a];
}

// The first place a needle is in a line, case insensitively, as the three
// parts around it - for picking out a link's text in the line it was written
// on. Null when it is not there.
export function splitOn(text: string, needle: string): [string, string, string] | null {
    const n = needle.trim();
    if (n === '') return null;
    const i = text.toLowerCase().indexOf(n.toLowerCase());
    if (i < 0) return null;
    return [text.slice(0, i), text.slice(i, i + n.length), text.slice(i + n.length)];
}

// The link's own words, which is what to pick out of its line: the text it
// was written with, or the target as written for a bare link.
export function linkWords(l: OrgLink): string {
    if (l.Desc !== '') return l.Desc;
    return l.Raw.replace(/^(file|id):/, '').replace(/::.*$/, '').replace(/^\*/, '');
}

export function mentionKey(m: MentionRef): string {
    return `${m.Filename}:${m.Line}:${m.Col}`;
}

export function refOf(m: Mention): MentionRef {
    return { Filename: m.Filename, Line: m.Line, Col: m.Col, Text: m.Text };
}

// ---------------------------------------------------------------------------
// Gathering
// ---------------------------------------------------------------------------

export type MentionGroup = {
    file: string;
    headings: { hash: string; headline: string; olp: string[]; mentions: Mention[] }[];
    count: number;
};

// Mentions under their file, then under the heading they are written in, in
// the order they came - which is the server's file and line order.
export function groupMentions(ms: Mention[]): MentionGroup[] {
    const out: MentionGroup[] = [];
    for (const m of ms) {
        let g = out.length > 0 && out[out.length - 1].file === m.Filename ? out[out.length - 1] : null;
        if (g === null) {
            g = { file: m.Filename, headings: [], count: 0 };
            out.push(g);
        }
        const last = g.headings.length > 0 ? g.headings[g.headings.length - 1] : null;
        if (last !== null && last.hash === m.Hash) {
            last.mentions.push(m);
        } else {
            g.headings.push({ hash: m.Hash, headline: m.Headline, olp: m.Olp || [], mentions: [m] });
        }
        g.count++;
    }
    return out;
}

// What the panel calls its target.
export function targetLabel(t: LinkTarget | null | undefined): string {
    if (!t) return '';
    if (t.Kind === 'heading') return t.Headline || t.Title;
    return t.Title || t.Filename.split('/').pop() || t.Filename;
}

// The panel says what was looked for and what was left out, because "no
// mentions" of a heading called Notes and of one called Apollo mean different
// things.
export function searchedNote(t: LinkTarget | null | undefined): string {
    if (!t) return '';
    const terms = t.Terms || [];
    const skipped = t.Skipped || [];
    const parts: string[] = [];
    if (terms.length > 0) parts.push(`Looking for ${terms.map(s => `“${s}”`).join(', ')}`);
    if (skipped.length > 0) parts.push(`not searched: ${skipped.join('; ')}`);
    return parts.join(' · ');
}
