// Saved-query notifications as the rest of worg sees them: the endpoints, and
// one live copy of the notification list that the header bell (desktop and
// phone) and the Saved Queries tab share.
//
// One store for the same reason focusApi.ts has one: the bell is drawn twice
// (breadcrumb row and phone header), and two streams and two pollers for one
// list would be silly. It opens /events (kinds=querymatch) when the first view
// subscribes and closes it when the last one goes. A `querymatch` is folded
// straight into the list, then the list is asked for again to pick up anything
// the stream missed. Polls every 60 seconds with the stream up, every 20
// without it, and when the tab comes back into view.

import * as React from 'react';
import { ODb } from './db';
import { Sets } from './config';
import { openEventStream } from './eventStream';
import { notificationsSupported } from './focusApi';
import {
    NoticeList, WatchList, QueryWatch, EMPTY_NOTICES, EMPTY_WATCHES, asNoticeList, asWatchList,
    noticeFromEvent, withNotice, markedRead, browserNotice, WatchNotice,
} from './querywatch';

function url(path: string): URL {
    return new URL(Sets.orgsConnection + path);
}

export async function getWatches(): Promise<WatchList> {
    return asWatchList(await ODb.doGet<WatchList>(url('/watches')));
}

// Start watching, or change a watch with the same name. The answer is the list
// after it; ok false with the reason when the query is gone or does not parse.
export async function saveWatch(w: QueryWatch): Promise<WatchList> {
    const res = asWatchList(await ODb.doPost<WatchList>(url('/watches'), w));
    if (res.ok) watchStore.takeWatches(res);
    return res;
}

export async function removeWatch(name: string): Promise<WatchList> {
    const u = url('/watches');
    u.searchParams.set('name', name);
    const res = asWatchList(await ODb.doDelete<WatchList>(u, {}));
    if (res.ok) watchStore.takeWatches(res);
    return res;
}

export async function getNotifications(unread = false): Promise<NoticeList> {
    const u = url('/notifications');
    if (unread) u.searchParams.set('unread', 't');
    return asNoticeList(await ODb.doGet<NoticeList>(u));
}

export async function markRead(ids: string[] | 'all'): Promise<NoticeList> {
    watchStore.takeNotices(markedRead(watchStore.get().notices, ids));
    const body = ids === 'all' ? { all: true } : { ids };
    const res = asNoticeList(await ODb.doPost<NoticeList>(url('/notifications/read'), body));
    if (res.ok) watchStore.takeNotices(res);
    return res;
}

export async function clearNotifications(): Promise<NoticeList> {
    const res = asNoticeList(await ODb.doPost<NoticeList>(url('/notifications/clear'), { all: true }));
    if (res.ok) watchStore.takeNotices(res);
    return res;
}

// ---------------------------------------------------------------------------
// The store
// ---------------------------------------------------------------------------

export type WatchSnapshot = {
    notices: NoticeList;
    watches: WatchList;
    // The stream is up.
    live: boolean;
    // The first answer has arrived.
    loaded: boolean;
};

type Listener = (s: WatchSnapshot) => void;

const NOTIFY_KEY = 'watchNotify';

class WatchStore {
    private snap: WatchSnapshot = { notices: EMPTY_NOTICES, watches: EMPTY_WATCHES, live: false, loaded: false };
    private listeners = new Set<Listener>();
    private closeStream: (() => void) | null = null;
    private poll: ReturnType<typeof setInterval> | null = null;
    private asking = false;

    get(): WatchSnapshot {
        return this.snap;
    }

    subscribe(l: Listener): () => void {
        this.listeners.add(l);
        if (this.listeners.size === 1) this.open();
        l(this.snap);
        return () => {
            this.listeners.delete(l);
            if (this.listeners.size === 0) this.close();
        };
    }

    takeNotices(n: NoticeList) {
        this.snap = { ...this.snap, notices: n, loaded: true };
        this.emit();
    }

    takeWatches(w: WatchList) {
        this.snap = { ...this.snap, watches: w };
        this.emit();
    }

    async refresh() {
        if (this.asking) return;
        this.asking = true;
        try {
            const [n, w] = await Promise.all([getNotifications(), getWatches()]);
            // A failed read keeps what is on screen: blank is worse than stale.
            if (n.ok) this.snap = { ...this.snap, notices: n, loaded: true };
            if (w.ok) this.snap = { ...this.snap, watches: w };
            this.emit();
        } finally {
            this.asking = false;
        }
    }

    private emit() {
        this.listeners.forEach(l => l(this.snap));
    }

    private open() {
        this.refresh();
        this.closeStream = openEventStream('querymatch', {
            onEvent: e => {
                const n = noticeFromEvent(e);
                if (n) {
                    this.takeNotices(withNotice(this.snap.notices, n));
                    this.notify(n);
                }
                this.refresh();
            },
            onLive: live => {
                if (live === this.snap.live) return;
                this.snap = { ...this.snap, live };
                this.schedulePoll();
                this.emit();
                // Back after a drop: catch up on what happened meanwhile.
                if (live) this.refresh();
            },
        });
        this.schedulePoll();
        document.addEventListener('visibilitychange', this.onVisible);
    }

    private close() {
        this.closeStream?.();
        this.closeStream = null;
        if (this.poll) clearInterval(this.poll);
        this.poll = null;
        document.removeEventListener('visibilitychange', this.onVisible);
    }

    private onVisible = () => {
        if (document.visibilityState === 'visible') this.refresh();
    };

    private schedulePoll() {
        if (this.poll) clearInterval(this.poll);
        if (this.listeners.size === 0) return;
        this.poll = setInterval(() => this.refresh(), this.snap.live ? 60000 : 20000);
    }

    private notify(n: WatchNotice) {
        if (!watchNotificationsOn()) return;
        const { title, body } = browserNotice(n);
        try {
            const note = new Notification(title, { body, tag: 'orgs-watch-' + n.id });
            note.onclick = () => { window.focus(); note.close(); };
        } catch {
            // Some browsers only allow notifications from a service worker.
        }
    }
}

export const watchStore = new WatchStore();

// The notifications and watches, live, for a component.
export function useWatches(): WatchSnapshot {
    const [snap, setSnap] = React.useState<WatchSnapshot>(watchStore.get());
    React.useEffect(() => watchStore.subscribe(setSnap), []);
    return snap;
}

// ---------------------------------------------------------------------------
// Browser notifications
// ---------------------------------------------------------------------------

export function watchNotificationsOn(): boolean {
    if (!notificationsSupported() || Notification.permission !== 'granted') return false;
    try {
        return localStorage.getItem(NOTIFY_KEY) === 'on';
    } catch {
        return false;
    }
}

// Asked from a click, never on load (browsers ignore, and some penalise, a
// permission prompt nobody asked for). Off unless turned on: the bell is
// already the notification.
export async function setWatchNotifications(on: boolean): Promise<boolean> {
    try {
        localStorage.setItem(NOTIFY_KEY, on ? 'on' : 'off');
    } catch {
        // private mode
    }
    if (!on || !notificationsSupported()) return false;
    if (Notification.permission === 'default') {
        await Notification.requestPermission();
    }
    return watchNotificationsOn();
}
