const OP_ICON: Record<RefactorOp, React.ReactNode> = {
    tag: <LocalOfferIcon />,
    split: <CallSplitIcon />,
    merge: <MergeTypeIcon />,
    list: <ListIcon />,
};

const OP_LINE: Record<RefactorOp, string> = {
    tag: 'Rename, merge or delete a tag in every file',
    split: 'Move a subtree into its own file, leaving a link',
    merge: 'Fold one heading into another',
    list: 'Make a list’s items into child headings',
};

const LAST_OP = 'worg.refactor.last';

function remembered(): RefactorOp {
    try {
        const v = localStorage.getItem(LAST_OP);
        if (REFACTOR_OPS.some(o => o.op === v)) return v as RefactorOp;
    } catch { /* private window */ }
    return 'tag';
}

