// Small parts
// ---------------------------------------------------------------------------

// Text with the letters a search matched drawn in the primary colour.
function Marked({ text, hits }: { text: string; hits: number[] }) {
    if (!hits.length) return <>{text}</>;
    const on = new Set(hits);
    const out: React.ReactNode[] = [];
    let run = '';
    let runOn = false;
    const flush = (k: number) => {
        if (!run) return;
        out.push(runOn
            ? <Box key={k} component="span" sx={{ color: 'primary.plainColor', fontWeight: 700 }}>{run}</Box>
            : <React.Fragment key={k}>{run}</React.Fragment>);
        run = '';
    };
    Array.from(text).forEach((ch, i) => {
        const h = on.has(i);
        if (h !== runOn) { flush(i); runOn = h; }
        run += ch;
    });
    flush(text.length);
    return <>{out}</>;
}

// The list under a search box, fzf style: the row under the cursor marked,
// ↑/↓ moved from the box, Enter or a click takes it.
function PickList<T>({ rows, cursor, setCursor, onPick, render, empty, keyOf }: {
    rows: T[];
    cursor: number;
    setCursor: (i: number) => void;
    onPick: (row: T) => void;
    render: (row: T, active: boolean) => React.ReactNode;
    empty: React.ReactNode;
    keyOf: (row: T) => string;
}) {
    const ref = React.useRef<HTMLDivElement>(null);
    React.useEffect(() => {
        const el = ref.current?.querySelector(`[data-row="${cursor}"]`) as HTMLElement | null;
        el?.scrollIntoView({ block: 'nearest' });
    }, [cursor]);
    return (
        <Box ref={ref} role="listbox" sx={{
            mt: 0.75, maxHeight: 220, overflowY: 'auto', borderRadius: 'sm',
            border: '1px solid', borderColor: 'neutral.outlinedBorder', bgcolor: 'background.level1', fontSize: 13,
        }}>
            {rows.length === 0 && <Typography level="body-xs" sx={{ p: 1, color: 'text.tertiary' }}>{empty}</Typography>}
            {rows.map((r, i) => (
                <Box key={keyOf(r)} data-row={i} role="option" aria-selected={i === cursor}
                    onMouseEnter={() => setCursor(i)}
                    onMouseDown={e => { e.preventDefault(); onPick(r); }}
                    sx={{
                        display: 'flex', alignItems: 'center', gap: 0.75, px: 1, py: 0.5, cursor: 'pointer', minWidth: 0,
                        bgcolor: i === cursor ? 'primary.softBg' : 'transparent',
                    }}>
                    <Box component="span" sx={{ color: 'primary.500', width: 10, flex: 'none' }}>{i === cursor ? '›' : ''}</Box>
                    {render(r, i === cursor)}
                </Box>
            ))}
        </Box>
    );
}

function listKeys(e: React.KeyboardEvent, n: number, cursor: number, setCursor: (i: number) => void, pick: () => void) {
    if (e.key === 'ArrowDown') { setCursor(Math.min(cursor + 1, n - 1)); e.preventDefault(); }
    else if (e.key === 'ArrowUp') { setCursor(Math.max(cursor - 1, 0)); e.preventDefault(); }
    else if (e.key === 'Enter' && n > 0) { pick(); e.preventDefault(); }
}

// A tag, typed or picked from the ones in use (with how much each is used).
function TagField({ label, value, onChange, tags, placeholder, helper, autoFocus }: {
    label: string; value: string; onChange: (v: string) => void; tags: RefactorTag[];
    placeholder: string; helper?: React.ReactNode; autoFocus?: boolean;
}) {
    const [open, setOpen] = React.useState(false);
    const [cursor, setCursor] = React.useState(0);
    const rows = React.useMemo(() => rankTags(tags, value).slice(0, 60), [tags, value]);
    React.useEffect(() => { setCursor(0); }, [value]);
    const err = tagError(value);
    const pick = (t: RefactorTag) => { onChange(t.Tag); setOpen(false); };
    const f = cleanTag(value).toLowerCase();
    return (
        <FormControl size="sm" error={!!err} sx={{ flex: 1, minWidth: 180 }}>
            <FormLabel>{label}</FormLabel>
            <Input size="sm" value={value} autoFocus={autoFocus} placeholder={placeholder}
                startDecorator={<LocalOfferIcon sx={{ fontSize: 16 }} />}
                onChange={e => { onChange(e.target.value); setOpen(true); }}
                onFocus={() => setOpen(true)}
                onBlur={() => setOpen(false)}
                onKeyDown={e => {
                    if (!open) return;
                    if (e.key === 'Escape') { setOpen(false); return; }
                    listKeys(e, rows.length, cursor, setCursor, () => pick(rows[cursor]));
                }}
                slotProps={{ input: { spellCheck: false, autoComplete: 'off' } }}
                sx={{ fontFamily: 'monospace' }}
            />
            {open && rows.length > 0 && (
                <PickList rows={rows} cursor={cursor} setCursor={setCursor} onPick={pick} keyOf={t => t.Tag}
                    empty="No tag matches"
                    render={t => (
                        <>
                            <Box component="span" sx={{ fontFamily: 'monospace', flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                :<Marked text={t.Tag} hits={f ? matchPositions([f], t.Tag) : []} />:
                            </Box>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', flex: 'none' }}>{usage(t)}</Typography>
                        </>
                    )} />
            )}
            {(err || helper) && <FormHelperText>{err || helper}</FormHelperText>}
        </FormControl>
    );
}

// One heading, found by typing: the server narrows loosely, the page ranks.
function HeadingField({ label, value, onChange, placeholder, autoFocus, exclude }: {
    label: string; value: HeadingRow | null; onChange: (h: HeadingRow | null) => void;
    placeholder: string; autoFocus?: boolean; exclude?: string;
}) {
    const [text, setText] = React.useState('');
    const [rows, setRows] = React.useState<HeadingRow[]>([]);
    const [looking, setLooking] = React.useState(false);
    const [cursor, setCursor] = React.useState(0);
    const inputRef = React.useRef<HTMLInputElement>(null);

    // Debounced, and each request aborts the one before, as the palette does.
    React.useEffect(() => {
        const t = text.trim();
        if (value || t.length < 2) { setRows([]); setLooking(false); return; }
        const ctrl = new AbortController();
        setLooking(true);
        const timer = window.setTimeout(async () => {
            try {
                const found = await findHeadings(t, ctrl.signal);
                if (!ctrl.signal.aborted) setRows(rankHeadings(found.filter(r => r.Hash !== exclude), t).slice(0, 40));
            } catch {
                if (!ctrl.signal.aborted) setRows([]);
            }
            if (!ctrl.signal.aborted) setLooking(false);
        }, 180);
        return () => { window.clearTimeout(timer); ctrl.abort(); };
    }, [text, value, exclude]);
    React.useEffect(() => { setCursor(0); }, [rows]);

    const terms = fuzzyTerms(text);
    const pick = (h: HeadingRow) => { onChange(h); setText(''); };

    if (value) {
        return (
            <FormControl size="sm" sx={{ flex: 1, minWidth: 220 }}>
                <FormLabel>{label}</FormLabel>
                <Sheet variant="soft" color="primary" sx={{
                    display: 'flex', alignItems: 'center', gap: 1, px: 1.25, py: 0.75, borderRadius: 'sm', minWidth: 0,
                }}>
                    <Box sx={{ minWidth: 0, flex: 1 }}>
                        <Typography level="title-sm" noWrap>
                            {value.Status ? <Box component="span" sx={{ color: 'text.tertiary', mr: 0.75 }}>{value.Status}</Box> : null}
                            {value.Headline}
                        </Typography>
                        <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>
                            {baseName(value.Filename)}{value.LineNum !== undefined ? `:${value.LineNum + 1}` : ''}
                            {value.Tags && value.Tags.length ? `  :${value.Tags.join(':')}:` : ''}
                        </Typography>
                    </Box>
                    <IconButton size="sm" variant="plain" aria-label="Choose another heading"
                        onClick={() => { onChange(null); window.setTimeout(() => inputRef.current?.focus(), 0); }}>
                        <CloseIcon />
                    </IconButton>
                </Sheet>
            </FormControl>
        );
    }
    return (
        <FormControl size="sm" sx={{ flex: 1, minWidth: 220 }}>
            <FormLabel>{label}</FormLabel>
            <Input size="sm" value={text} autoFocus={autoFocus} placeholder={placeholder}
                startDecorator={<SearchIcon />}
                endDecorator={looking ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '16px' }} /> : null}
                onChange={e => setText(e.target.value)}
                onKeyDown={e => listKeys(e, rows.length, cursor, setCursor, () => pick(rows[cursor]))}
                slotProps={{ input: { ref: inputRef, spellCheck: false, autoComplete: 'off' } }}
            />
            {text.trim().length >= 2 && !looking && (
                <PickList rows={rows} cursor={cursor} setCursor={setCursor} onPick={pick} keyOf={r => r.Hash}
                    empty="No heading matches"
                    render={r => (
                        <>
                            <Box sx={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                {r.Status ? <Box component="span" sx={{ color: 'text.tertiary', mr: 0.5, fontSize: 11 }}>{r.Status}</Box> : null}
                                <Marked text={r.Headline || ''} hits={matchPositions(terms, r.Headline || '')} />
                            </Box>
                            <Typography level="body-xs" sx={{ color: 'text.tertiary', flex: 'none', fontFamily: 'monospace' }}>
                                {baseName(r.Filename)}{r.LineNum !== undefined ? `:${r.LineNum + 1}` : ''}
                            </Typography>
                        </>
                    )} />
            )}
        </FormControl>
    );
}

// A folder under the org directories, picked the way the new-file dialog
// picks one (src/newfile.ts).
function FolderField({ value, onChange }: { value: string; onChange: (d: string) => void }) {
    const [dirs, setDirs] = React.useState<string[]>([]);
    const [filter, setFilter] = React.useState('');
    const [cursor, setCursor] = React.useState(0);
    const [open, setOpen] = React.useState(false);
    React.useEffect(() => {
        let gone = false;
        orgDirs().then(d => { if (!gone) setDirs(Array.isArray(d) ? d : []); }).catch(() => { });
        return () => { gone = true; };
    }, []);
    const roots = React.useMemo(() => rootsOf(dirs), [dirs]);
    const ranked = React.useMemo(() => rankDirs(dirs, filter, roots).slice(0, 150), [dirs, filter, roots]);
    React.useEffect(() => { setCursor(0); }, [filter]);
    const pick = (d: string) => { onChange(d); setOpen(false); setFilter(''); };
    return (
        <FormControl size="sm" sx={{ flex: 1, minWidth: 220 }}>
            <FormLabel>Folder</FormLabel>
            <Input size="sm"
                value={open ? filter : (value ? dirLabel(value, roots) : '')}
                placeholder="Beside the heading’s own file - or type to find a folder"
                startDecorator={<FolderIcon sx={{ fontSize: 16 }} />}
                endDecorator={value && !open ? (
                    <IconButton size="sm" variant="plain" aria-label="Back to the heading’s own folder" onClick={() => onChange('')}>
                        <CloseIcon />
                    </IconButton>
                ) : null}
                onFocus={() => setOpen(true)}
                onBlur={() => setOpen(false)}
                onChange={e => setFilter(e.target.value)}
                onKeyDown={e => {
                    if (e.key === 'Escape') { setOpen(false); return; }
                    listKeys(e, ranked.length, cursor, setCursor, () => pick(ranked[cursor].dir));
                }}
                slotProps={{ input: { spellCheck: false, autoComplete: 'off' } }}
                sx={{ fontFamily: 'monospace' }}
            />
            {open && (
                <PickList rows={ranked} cursor={cursor} setCursor={setCursor} onPick={r => pick(r.dir)} keyOf={r => r.dir}
                    empty="No folder matches"
                    render={r => (
                        <>
                            <FolderIcon sx={{ fontSize: 15, color: 'text.tertiary', flex: 'none' }} />
                            <Box component="span" sx={{ fontFamily: 'monospace', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                <Marked text={r.label} hits={r.hits} />
                            </Box>
                        </>
                    )} />
            )}
        </FormControl>
    );
}

// ---------------------------------------------------------------------------
// The preview: summary, what it could not do, and the diff per file
// ---------------------------------------------------------------------------

function PlanView({ plan, busy, onApply, onDiscard }: {
    plan: RefactorPlan; busy: boolean; onApply: () => void; onDiscard: () => void;
}) {
    const [file, setFile] = React.useState(0);
    React.useEffect(() => { setFile(0); }, [plan]);
    const t = planTotals(plan);
    const f = plan.Files[Math.min(file, plan.Files.length - 1)];
    const where = (p: string) => baseName(p);
    return (
        <Sheet variant="outlined" sx={{ borderRadius: 'md', p: { xs: 1, sm: 1.5 }, display: 'flex', flexDirection: 'column', gap: 1.25 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Typography level="title-md" sx={{ flex: '1 1 260px', minWidth: 0 }}>{plan.Summary}</Typography>
                {t.files > 0 && (
                    <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                        <Chip size="sm" variant="soft" color="success">+{t.added}</Chip>
                        <Chip size="sm" variant="soft" color="danger">−{t.removed}</Chip>
                        <Chip size="sm" variant="outlined">{t.files} file{t.files === 1 ? '' : 's'}</Chip>
                    </Box>
                )}
            </Box>

            {(plan.Warnings || []).length > 0 && (
                <Alert size="sm" variant="soft" color="warning" startDecorator={<WarningIcon />} sx={{ alignItems: 'flex-start' }}>
                    <Box component="ul" sx={{ m: 0, pl: 2 }}>
                        {(plan.Warnings || []).map((w, i) => <li key={i}><Typography level="body-sm">{w}</Typography></li>)}
                    </Box>
                </Alert>
            )}
            {(plan.Mentions || []).length > 0 && (
                <Alert size="sm" variant="soft" color="neutral" sx={{ alignItems: 'flex-start', flexDirection: 'column', gap: 0.5 }}>
                    <Typography level="title-sm">Named elsewhere too - left for you to change</Typography>
                    {(plan.Mentions || []).map((m, i) => (
                        <Typography key={i} level="body-sm" sx={{ wordBreak: 'break-word' }}>
                            <Chip size="sm" variant="outlined" sx={{ mr: 0.75 }}>{m.Kind}</Chip>
                            <b>{m.Name}</b>{' '}
                            <Box component="span" sx={{ fontFamily: 'monospace', fontSize: 12, color: 'text.secondary' }}>{m.Text}</Box>
                        </Typography>
                    ))}
                </Alert>
            )}

            {t.files === 0 ? (
                <Typography level="body-sm" sx={{ color: 'text.tertiary', py: 2, textAlign: 'center' }}>Nothing to change.</Typography>
            ) : (
                <>
                    {plan.Files.length > 1 && (
                        <Box sx={{ display: 'flex', gap: 0.75, overflowX: 'auto', pb: 0.25 }}>
                            {plan.Files.map((pf, i) => (
                                <Chip key={pf.Filename} size="md" variant={i === file ? 'solid' : 'outlined'}
                                    color={i === file ? 'primary' : 'neutral'} onClick={() => setFile(i)}
                                    startDecorator={<FileIcon sx={{ fontSize: 15 }} />}
                                    title={pf.Filename}
                                    sx={{ flex: 'none' }}>
                                    {where(pf.Filename)}
                                    <Box component="span" sx={{ ml: 0.75, opacity: 0.8, fontSize: 11 }}>
                                        {pf.Created ? 'new' : `+${pf.Added} −${pf.Removed}`}
                                    </Box>
                                </Chip>
                            ))}
                        </Box>
                    )}
                    {f && (
                        <Box sx={{ height: { xs: '62dvh', md: '56vh' }, minHeight: 320, display: 'flex', flexDirection: 'column' }}>
                            <DiffView
                                left={f.Created
                                    ? { text: '', label: 'New file', detail: f.Filename, missing: true }
                                    : { text: f.Before, label: 'Before', detail: f.Filename }}
                                right={{ text: f.After, label: 'After', detail: f.Filename }}
                            />
                        </Box>
                    )}
                </>
            )}

            <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                <Button variant="plain" color="neutral" onClick={onDiscard} disabled={busy}>Discard</Button>
                {t.files > 0 && (
                    <Button color="primary" loading={busy} onClick={onApply} startDecorator={<CheckIcon />}>
                        Apply to {t.files} file{t.files === 1 ? '' : 's'}
                    </Button>
                )}
            </Box>
        </Sheet>
    );
}

// ---------------------------------------------------------------------------
// The page
// ---------------------------------------------------------------------------

export default function Refactor(_props: any) {
    const nav = useNav();
    const [op, setOpState] = React.useState<RefactorOp>(() => takeRefactorOp() || remembered());
    const setOp = (o: RefactorOp) => {
        setOpState(o);
        try { localStorage.setItem(LAST_OP, o); } catch { /* private window */ }
    };
    // The palette asking while the tab is already open.
    React.useEffect(() => {
        const on = (e: Event) => {
            const o = (e as CustomEvent).detail as RefactorOp;
            takeRefactorOp();
            if (REFACTOR_OPS.some(x => x.op === o)) setOp(o);
        };
        window.addEventListener(REFACTOR_EVENT, on);
        return () => window.removeEventListener(REFACTOR_EVENT, on);
    }, []);

    const [tags, setTags] = React.useState<RefactorTag[]>([]);
    const loadTags = React.useCallback(() => { refactorTags().then(setTags).catch(() => setTags([])); }, []);
    React.useEffect(() => { loadTags(); }, [loadTags]);

    // Rename a tag
    const [oldTag, setOldTag] = React.useState('');
    const [newTag, setNewTag] = React.useState('');
    const [delTag, setDelTag] = React.useState(false);
    const [tagQuery, setTagQuery] = React.useState('');
    // Split
    const [splitHeading, setSplitHeading] = React.useState<HeadingRow | null>(null);
    const [splitFolder, setSplitFolder] = React.useState('');
    const [splitName, setSplitName] = React.useState('');
    // Merge
    const [into, setInto] = React.useState<HeadingRow | null>(null);
    const [from, setFrom] = React.useState<HeadingRow | null>(null);
    // List to headings
    const [listHeading, setListHeading] = React.useState<HeadingRow | null>(null);
    const [lists, setLists] = React.useState<RefactorList[] | null>(null);
    const [listsMsg, setListsMsg] = React.useState('');
    const [listLine, setListLine] = React.useState(-1);
    React.useEffect(() => {
        setLists(null); setListsMsg(''); setListLine(-1);
        if (!listHeading) return;
        let gone = false;
        listsUnder(listHeading.Hash).then(r => {
            if (gone) return;
            setLists(r.Lists);
            setListsMsg(r.Ok ? (r.Lists.length ? '' : 'There is no list in that heading’s own text.') : r.Msg);
            if (r.Lists.length) setListLine(r.Lists[0].Line);
        });
        return () => { gone = true; };
    }, [listHeading]);

    const [plan, setPlan] = React.useState<RefactorPlan | null>(null);
    const [planReq, setPlanReq] = React.useState<RefactorRequest | null>(null);
    const [busy, setBusy] = React.useState(false);
    const [error, setError] = React.useState('');
    const [stale, setStale] = React.useState(false);
    const [done, setDone] = React.useState<RefactorPlan | null>(null);
    const previewRef = React.useRef<HTMLDivElement>(null);

    // A preview is of the inputs it was made from; changing one puts it away.
    React.useEffect(() => {
        setPlan(null); setPlanReq(null); setError(''); setStale(false);
    }, [op, oldTag, newTag, delTag, tagQuery, splitHeading, splitFolder, splitName, into, from, listHeading, listLine]);

    // The request the inputs make, or why there is none yet.
    const built: { req: RefactorRequest | null; why: string } = React.useMemo(() => {
        switch (op) {
            case 'tag': {
                const o = cleanTag(oldTag), n = cleanTag(newTag);
                if (!o) return { req: null, why: 'Pick the tag to change' };
                if (tagError(o) || (!delTag && tagError(n))) return { req: null, why: 'Fix the tag name' };
                if (!delTag && !n) return { req: null, why: 'Say what to rename it to' };
                if (!delTag && n === o) return { req: null, why: 'That is the same name' };
                return { req: { Old: o, New: delTag ? '' : n, Delete: delTag, Query: tagQuery.trim() || undefined }, why: '' };
            }
            case 'split': {
                if (!splitHeading) return { req: null, why: 'Pick the heading to split out' };
                if (splitNameError(splitName)) return { req: null, why: 'Fix the file name' };
                return { req: { Hash: splitHeading.Hash, To: splitTarget(splitFolder, splitName) || undefined }, why: '' };
            }
            case 'merge': {
                if (!into || !from) return { req: null, why: 'Pick both headings' };
                if (into.Hash === from.Hash) return { req: null, why: 'Those are the same heading' };
                return { req: { Into: into.Hash, From: from.Hash }, why: '' };
            }
            case 'list': {
                if (!listHeading) return { req: null, why: 'Pick the heading with the list' };
                if (!lists || lists.length === 0) return { req: null, why: listsMsg || 'Looking for its lists…' };
                return { req: { Hash: listHeading.Hash, Line: listLine }, why: '' };
            }
        }
        return { req: null, why: '' };
    }, [op, oldTag, newTag, delTag, tagQuery, splitHeading, splitFolder, splitName, into, from, listHeading, lists, listsMsg, listLine]);

    const preview = async () => {
        if (!built.req) return;
        setBusy(true); setError(''); setStale(false); setDone(null);
        try {
            const res = await previewRefactor(op, built.req);
            if (res.Ok) {
                setPlan(res); setPlanReq(built.req);
                window.setTimeout(() => previewRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
            } else {
                setPlan(null); setError(res.Msg || 'The preview failed');
            }
        } catch (e: any) {
            setError(e?.message || 'The preview failed');
        } finally {
            setBusy(false);
        }
    };

    const apply = async () => {
        if (!plan || !planReq) return;
        setBusy(true); setError('');
        try {
            const res = await applyRefactor(op, planReq, plan);
            if (res.Ok && res.Applied) {
                setDone({ ...res, NewFile: res.NewFile || plan.NewFile });
                setPlan(null); setPlanReq(null);
                // The headings picked have moved, been rewritten or gone.
                setSplitHeading(null); setInto(null); setFrom(null); setListHeading(null);
                setOldTag(''); setNewTag(''); setDelTag(false);
                loadTags();
            } else {
                setStale(!!res.Stale);
                setError(res.Msg || 'Nothing was written');
            }
        } catch (e: any) {
            setError(e?.message || 'Nothing was written');
        } finally {
            setBusy(false);
        }
    };

    const onEnter = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
            e.preventDefault();
            if (plan) apply(); else preview();
        }
    };

    const tagHelper = renameNote(oldTag, newTag, tags, delTag);

    return (
        <Box onKeyDown={onEnter} sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, flex: 1, minHeight: 0, overflowY: 'auto', pb: 2 }}>
            <Box role="tablist" sx={{ display: 'grid', gap: 1, gridTemplateColumns: { xs: '1fr 1fr', md: 'repeat(4, minmax(0, 1fr))' } }}>
                {REFACTOR_OPS.map(o => {
                    const on = o.op === op;
                    return (
                        <Sheet key={o.op} role="tab" aria-selected={on} tabIndex={0}
                            variant={on ? 'soft' : 'outlined'} color={on ? 'primary' : 'neutral'}
                            onClick={() => setOp(o.op)}
                            onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOp(o.op); } }}
                            sx={{
                                p: { xs: 1, sm: 1.5 }, borderRadius: 'md', cursor: 'pointer', display: 'flex', gap: 1.25, alignItems: 'flex-start',
                                transition: 'background-color .15s, border-color .15s',
                                borderColor: on ? 'primary.outlinedBorder' : undefined,
                                '&:hover': { borderColor: 'primary.outlinedHoverBorder' },
                                '&:focus-visible': { outline: '2px solid', outlineColor: 'focusVisible' },
                            }}>
                            <Box sx={{ color: on ? 'primary.500' : 'text.tertiary', display: 'flex', mt: 0.25, '& svg': { fontSize: 22 } }}>{OP_ICON[o.op]}</Box>
                            <Box sx={{ minWidth: 0 }}>
                                <Typography level="title-sm">{o.short}</Typography>
                                <Typography level="body-xs" sx={{ color: 'text.tertiary', display: { xs: 'none', sm: 'block' } }}>{OP_LINE[o.op]}</Typography>
                            </Box>
                        </Sheet>
                    );
                })}
            </Box>

            <Sheet variant="outlined" sx={{ borderRadius: 'md', p: { xs: 1.25, sm: 2 }, display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                {op === 'tag' && (
                    <>
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-start' }}>
                            <TagField label="Tag" value={oldTag} onChange={setOldTag} tags={tags} placeholder="old tag" autoFocus />
                            {!delTag && (
                                <TagField label="Rename to" value={newTag} onChange={setNewTag} tags={tags}
                                    placeholder="new name, or an existing tag to merge into" />
                            )}
                        </Box>
                        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'center' }}>
                            <Typography component="label" level="body-sm" startDecorator={
                                <Switch size="sm" checked={delTag} onChange={e => setDelTag(e.target.checked)} />}>
                                Delete it instead
                            </Typography>
                            <Input size="sm" value={tagQuery} onChange={e => setTagQuery(e.target.value)}
                                placeholder="Only headings matching a query (optional), e.g. IsProject()"
                                startDecorator={<SearchIcon />}
                                slotProps={{ input: { spellCheck: false } }}
                                sx={{ flex: '1 1 280px', fontFamily: 'monospace' }} />
                        </Box>
                        {tagHelper && <Typography level="body-sm" sx={{ color: 'text.secondary' }}>{tagHelper}</Typography>}
                    </>
                )}

                {op === 'split' && (
                    <>
                        <HeadingField label="Heading" value={splitHeading} onChange={setSplitHeading} placeholder="Find the heading to split out" autoFocus />
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-start' }}>
                            <FolderField value={splitFolder} onChange={setSplitFolder} />
                            <FormControl size="sm" error={!!splitNameError(splitName)} sx={{ flex: '0 1 260px', minWidth: 180 }}>
                                <FormLabel>File name</FormLabel>
                                <Input size="sm" value={splitName} onChange={e => setSplitName(e.target.value)}
                                    placeholder={splitHeading ? `${slugOf(splitHeading.Headline)}.org` : 'named for the heading'}
                                    endDecorator={<Typography level="body-xs" sx={{ color: 'text.tertiary' }}>.org</Typography>}
                                    slotProps={{ input: { spellCheck: false } }} sx={{ fontFamily: 'monospace' }} />
                                {splitNameError(splitName) && <FormHelperText>{splitNameError(splitName)}</FormHelperText>}
                            </FormControl>
                        </Box>
                        <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                            The heading and everything under it move to the new file, promoted to the top level, keeping its
                            properties - it gets an ID if it has none, so links to it still land. Where it was, one heading
                            stays behind whose title is a link to it.
                        </Typography>
                    </>
                )}

                {op === 'merge' && (
                    <>
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-start' }}>
                            <HeadingField label="Merge this heading…" value={from} onChange={setFrom}
                                placeholder="Find the heading that goes away" autoFocus exclude={into?.Hash} />
                            <Box sx={{ alignSelf: 'center', color: 'text.tertiary', display: { xs: 'none', sm: 'flex' }, mt: 2.5 }}>
                                <ArrowDownwardIcon sx={{ transform: 'rotate(-90deg)' }} />
                            </Box>
                            <HeadingField label="…into this one" value={into} onChange={setInto}
                                placeholder="Find the heading that stays" exclude={from?.Hash} />
                        </Box>
                        <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                            Its text goes after the other’s text and its children after the other’s children; tags are joined
                            and properties added where the one that stays has none (it wins any conflict). If both have an ID,
                            links to the merged one are re-pointed - shown in the preview.
                        </Typography>
                    </>
                )}

                {op === 'list' && (
                    <>
                        <HeadingField label="Heading" value={listHeading} onChange={setListHeading} placeholder="Find the heading whose list it is" autoFocus />
                        {listHeading && lists === null && (
                            <Typography level="body-sm" startDecorator={<CircularProgress size="sm" />}>Reading its lists…</Typography>
                        )}
                        {lists && lists.length > 0 && (
                            <FormControl size="sm">
                                <FormLabel>Which list</FormLabel>
                                <ToggleButtonGroup size="sm" value={String(listLine)} sx={{ flexWrap: 'wrap' }}
                                    onChange={(_e, v) => v !== null && setListLine(Number(v))}>
                                    {lists.map(l => (
                                        <Button key={l.Line} value={String(l.Line)}>
                                            {l.First ? `“${l.First.length > 28 ? l.First.slice(0, 27) + '…' : l.First}”` : 'list'}
                                            <Box component="span" sx={{ ml: 0.75, opacity: 0.7, fontSize: 11 }}>
                                                {l.Items} item{l.Items === 1 ? '' : 's'}{l.Checkboxes ? ` · ${l.Checkboxes} ☐` : ''} · line {l.Line + 1}
                                            </Box>
                                        </Button>
                                    ))}
                                </ToggleButtonGroup>
                            </FormControl>
                        )}
                        {listsMsg && <Typography level="body-sm" color="warning">{listsMsg}</Typography>}
                        <Typography level="body-sm" sx={{ color: 'text.secondary' }}>
                            Each item becomes a child heading (nested items go deeper), [ ] becomes TODO and [X] DONE, and the
                            lines under an item become its heading’s text.
                        </Typography>
                    </>
                )}

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                    {!built.req && built.why && <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{built.why}</Typography>}
                    <Box sx={{ flex: 1 }} />
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', display: { xs: 'none', md: 'block' } }}>⌘/Ctrl-Enter</Typography>
                    <Button onClick={preview} disabled={!built.req || busy} loading={busy && !plan} variant={plan ? 'outlined' : 'solid'}>
                        {plan ? 'Preview again' : 'Preview'}
                    </Button>
                </Box>
            </Sheet>

            {error && (
                <Alert color={stale ? 'warning' : 'danger'} variant="soft"
                    endDecorator={stale ? <Button size="sm" variant="solid" color="warning" onClick={preview} disabled={!built.req}>Preview again</Button> : null}>
                    {error}
                </Alert>
            )}
            {done && (
                <Alert color="success" variant="soft" startDecorator={<CheckIcon />}
                    endDecorator={<Box sx={{ display: 'flex', gap: 0.5 }}>
                        {done.NewFile && (
                            <Button size="sm" variant="soft" color="success" onClick={() => nav.toFile({ filename: done.NewFile! })}>Open the new file</Button>
                        )}
                        <IconButton size="sm" variant="plain" color="success" aria-label="Dismiss" onClick={() => setDone(null)}><CloseIcon /></IconButton>
                    </Box>}>
                    <Box>
                        <Typography level="title-sm">{done.Summary}</Typography>
                        <Typography level="body-xs">Written to {done.Files.map(f => baseName(f.Filename)).join(', ')}.</Typography>
                    </Box>
                </Alert>
            )}

            <div ref={previewRef} />
            {plan && <PlanView plan={plan} busy={busy} onApply={apply} onDiscard={() => { setPlan(null); setPlanReq(null); }} />}
        </Box>
    );
}
