// The review endpoints (internal/app/orgs/review_wizard.go), for the Inbox and
// Weekly Review tabs. Kept out of db.ts so the two tabs' calls live together.
//
// Every decision goes through `POST /review/act` rather than /move,
// /date/change and the rest: it does the same writes (it calls the same
// functions) and hands back an undo token, which is what makes one-key triage
// safe to be quick with.

import { ODb } from './db';
import { Sets } from './config';
import { ReviewList, WeeklyReview, ReviewLast, ReviewAct, ReviewActResult } from './review';

function url(path: string): URL {
    return new URL(Sets.orgsConnection + path);
}

// A failed fetch comes back from doGet/doPost as `[]`; say so instead of
// letting a list that is not there read as an empty inbox.
function failed<T extends { Ok: boolean; Msg: string }>(r: any, what: string): T {
    if (!r || Array.isArray(r)) return { Ok: false, Msg: `could not reach the server for ${what}` } as T;
    return r as T;
}

export class ReviewApi {
    static async inbox(): Promise<ReviewList> {
        return failed<ReviewList>(await ODb.doGet<ReviewList>(url('/review/inbox')), 'the inbox');
    }

    static async someday(): Promise<ReviewList> {
        return failed<ReviewList>(await ODb.doGet<ReviewList>(url('/review/someday')), 'the someday list');
    }

    static async weekly(waitingDays?: number): Promise<WeeklyReview> {
        const u = url('/review/weekly');
        if (waitingDays !== undefined) u.searchParams.set('waitingDays', String(waitingDays));
        return failed<WeeklyReview>(await ODb.doGet<WeeklyReview>(u), 'the review');
    }

    static async act(req: ReviewAct): Promise<ReviewActResult> {
        return failed<ReviewActResult>(await ODb.doPost<ReviewActResult>(url('/review/act'), req), 'that');
    }

    static async undo(token: string): Promise<ReviewActResult> {
        return failed<ReviewActResult>(await ODb.doPost<ReviewActResult>(url('/review/undo'), { Token: token }), 'the undo');
    }

    static async last(): Promise<ReviewLast> {
        return failed<ReviewLast>(await ODb.doGet<ReviewLast>(url('/review/last')), 'the last review');
    }

    // Where a review in progress is, and what it has done so far.
    static async step(step: number, tally?: { [k: string]: number }): Promise<ReviewLast> {
        return failed<ReviewLast>(await ODb.doPost<ReviewLast>(url('/review/step'), { Step: step, Tally: tally }), 'the step');
    }

    static async done(summary: { [k: string]: number }): Promise<ReviewLast> {
        return failed<ReviewLast>(await ODb.doPost<ReviewLast>(url('/review/done'), { Summary: summary }), 'the review');
    }
}
