// The bell on a saved query's row: watch it, or change how it is watched.
//
// One click on a quiet bell starts watching with the defaults (new matches
// only, no desktop popup) - the common case should not need a form. On a
// watched query the bell opens its options: say when a heading stops
// matching, pop up on the server's desktop, a label, pause, stop watching.
//
// Starting a watch takes a silent baseline on the server: what the query finds
// now is what you already know about, and only what it finds after is news.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Input from '@mui/joy/Input';
import Switch from '@mui/joy/Switch';
import Tooltip from '@mui/joy/Tooltip';
import Divider from '@mui/joy/Divider';
import Popper from '@mui/material/Popper';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import BellIcon from '@mui/icons-material/NotificationsNone';
import BellOnIcon from '@mui/icons-material/NotificationsActive';
import BellPausedIcon from '@mui/icons-material/NotificationsPaused';
import BellErrorIcon from '@mui/icons-material/NotificationImportant';

import { saveWatch, removeWatch } from '../querywatchApi';
import { WatchStatus, QueryWatch, watchForQuery, plainWatch, relativeTime } from '../querywatch';

type Props = {
    query: string;
    watch?: WatchStatus;
    // The server has a notify plugin, so a desktop popup can happen.
    desktopAvailable: boolean;
};

function Option({ label, hint, checked, disabled, onChange }: {
    label: string; hint: string; checked: boolean; disabled?: boolean; onChange: (v: boolean) => void;
}) {
    return (
        <Typography
            component="label"
            level="body-sm"
            sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, cursor: disabled ? 'default' : 'pointer', opacity: disabled ? 0.6 : 1 }}
            startDecorator={<Switch size="sm" checked={checked} disabled={disabled} onChange={e => onChange(e.target.checked)} sx={{ mt: 0.25 }} />}
        >
            <Box component="span">
                {label}
                <Typography component="span" level="body-xs" sx={{ display: 'block', color: 'text.tertiary' }}>{hint}</Typography>
            </Box>
        </Typography>
    );
}

export default function WatchToggle({ query, watch, desktopAvailable }: Props) {
    const anchor = React.useRef<HTMLButtonElement | null>(null);
    const [open, setOpen] = React.useState(false);
    const [busy, setBusy] = React.useState(false);
    const [msg, setMsg] = React.useState('');
    const [label, setLabel] = React.useState(watch?.label || '');
    React.useEffect(() => { setLabel(watch?.label || ''); }, [watch?.label]);

    const write = async (w: QueryWatch) => {
        setBusy(true);
        setMsg('');
        const res = await saveWatch(w);
        setBusy(false);
        if (!res.ok) setMsg(res.msg || 'That did not work.');
        return res.ok;
    };

    const start = async () => {
        // Started quietly - the bell filling in says so. Only a refusal opens
        // the panel, to say why.
        if (!(await write(watchForQuery(query)))) setOpen(true);
    };

    const change = (patch: Partial<QueryWatch>) => {
        if (!watch) return;
        write({ ...plainWatch(watch), ...patch });
    };

    const stop = async () => {
        if (!watch) return;
        setBusy(true);
        const res = await removeWatch(watch.name);
        setBusy(false);
        if (!res.ok) setMsg(res.msg || 'That did not work.');
        else setOpen(false);
    };

    const icon = !watch ? <BellIcon fontSize="small" />
        : watch.error ? <BellErrorIcon fontSize="small" />
            : watch.paused ? <BellPausedIcon fontSize="small" />
                : <BellOnIcon fontSize="small" />;
    const tip = !watch ? 'Watch this query: tell me when it finds something new'
        : watch.error ? `Watched, but: ${watch.error}`
            : watch.paused ? 'Watching is paused'
                : 'Watched — click for options';

    return (
        <>
            <Tooltip size="sm" title={tip}>
                <IconButton
                    ref={anchor}
                    size="sm"
                    variant={watch && !watch.paused ? 'solid' : 'soft'}
                    color={watch?.error ? 'danger' : watch ? 'primary' : 'neutral'}
                    aria-label={watch ? `Watch options for ${query}` : `Watch the saved query ${query}`}
                    aria-pressed={!!watch}
                    disabled={busy && !open}
                    onClick={() => (watch ? setOpen(o => !o) : start())}
                >
                    {icon}
                </IconButton>
            </Tooltip>
            <Popper
                open={open}
                anchorEl={anchor.current}
                placement="bottom-end"
                style={{ zIndex: 10000 }}
                modifiers={[{ name: 'offset', options: { offset: [0, 6] } }]}
            >
                <ClickAwayListener onClickAway={() => setOpen(false)}>
                    <Sheet
                        variant="outlined"
                        onKeyDown={e => { if (e.key === 'Escape') setOpen(false); }}
                        sx={{ p: 1.5, borderRadius: 'md', boxShadow: 'lg', width: 'min(300px, calc(100vw - 16px))', display: 'flex', flexDirection: 'column', gap: 1, textAlign: 'left' }}
                    >
                        <Box>
                            <Typography level="title-sm">Watching “{query}”</Typography>
                            {watch && (
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                    {watch.count >= 0 ? `${watch.count} matching` : 'Not checked yet'}
                                    {watch.checked ? ` · checked ${relativeTime(watch.checked)}` : ''}
                                </Typography>
                            )}
                            <Typography level="body-xs" sx={{ color: 'text.secondary', mt: 0.5 }}>
                                What it finds now counts as known. Anything it finds from here on shows up under the bell at the top of the page.
                            </Typography>
                        </Box>
                        {watch?.error && <Typography level="body-xs" color="danger">{watch.error}</Typography>}
                        {msg && <Typography level="body-xs" color="danger">{msg}</Typography>}
                        {watch && (
                            <>
                                <Option
                                    label="Also when a heading leaves"
                                    hint="Say when something stops matching, too."
                                    checked={!!watch.left}
                                    disabled={busy}
                                    onChange={v => change({ left: v })}
                                />
                                <Option
                                    label="Desktop popup"
                                    hint={desktopAvailable
                                        ? "On the server's desktop, through the notify plugin."
                                        : 'Needs the notify plugin in server.plugins; saved, but nothing pops up until then.'}
                                    checked={!!watch.desktop}
                                    disabled={busy}
                                    onChange={v => change({ desktop: v })}
                                />
                                <Option
                                    label="Paused"
                                    hint="Keep the watch but stop checking. Resuming starts afresh."
                                    checked={!!watch.paused}
                                    disabled={busy}
                                    onChange={v => change({ paused: v })}
                                />
                                <Input
                                    size="sm"
                                    placeholder={`Label (default: ${watch.name})`}
                                    value={label}
                                    onChange={e => setLabel(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') change({ label: label.trim() }); }}
                                    onBlur={() => { if (label.trim() !== (watch.label || '')) change({ label: label.trim() }); }}
                                />
                                <Divider />
                                <Box sx={{ display: 'flex', gap: 1 }}>
                                    <Button size="sm" variant="soft" color="danger" disabled={busy} onClick={stop}>
                                        Stop watching
                                    </Button>
                                    <Button size="sm" variant="plain" color="neutral" sx={{ ml: 'auto' }} onClick={() => setOpen(false)}>
                                        Done
                                    </Button>
                                </Box>
                            </>
                        )}
                    </Sheet>
                </ClickAwayListener>
            </Popper>
        </>
    );
}
