// --- what is being typed ----------------------------------------------------

export interface WordAt {
    // The word under the caret, and where it starts.
    word: string;
    start: number;
}

// The identifier the caret is in or at the end of. Only letters count: a
// function name has nothing else in it, and stopping at anything else is what
// keeps `IsTodo() && Has` from offering completions for the whole line.
export function wordAt(text: string, caret: number): WordAt {
    let start = caret;
    while (start > 0 && /[A-Za-z]/.test(text.charAt(start - 1))) start -= 1;
    return { word: text.slice(start, caret), start };
}

// Whether the caret is inside a quoted string, where a function name means
// nothing and suggesting one would be noise.
export function inString(text: string, caret: number): boolean {
    let single = false;
    let double = false;
    for (let i = 0; i < caret && i < text.length; i++) {
        const c = text.charAt(i);
        if (c === '\\') { i += 1; continue; }
        if (c === '"' && !single) double = !double;
        else if (c === "'" && !double) single = !single;
    }
    return single || double;
}

// The functions a half-typed word could become.
//
// Prefix first and in the catalogue's order, then the ones that merely contain
// it: somebody typing `Tag` means `HasTags` sooner than they mean
// `InTagGroup`, but both are worth offering.
export function completionsFor(word: string): QueryFn[] {
    if (word === '') return [];
    const w = word.toLowerCase();
    const starts = QUERY_FUNCTIONS.filter(f => f.name.toLowerCase().indexOf(w) === 0);
    const contains = QUERY_FUNCTIONS.filter(
        f => f.name.toLowerCase().indexOf(w) > 0,
    );
    return starts.concat(contains);
}

// What to offer, given the whole box and where the caret is.
export function completionsAt(text: string, caret: number): { from: number; word: string; options: QueryFn[] } {
    if (inString(text, caret)) return { from: caret, word: '', options: [] };
    const { word, start } = wordAt(text, caret);
    return { from: start, word, options: completionsFor(word) };
}

// Putting a chosen function in. The name, its brackets, and the caret left
// where the next thing gets typed: inside the brackets when it takes
// arguments, after them when it does not.
export function applyCompletion(
    text: string, from: number, caret: number, fn: QueryFn,
): { text: string; caret: number } {
    const before = text.slice(0, from);
    const after = text.slice(caret);
    // Brackets that are already there are not doubled.
    const already = after.charAt(0) === '(';
    const insert = already ? fn.name : `${fn.name}()`;
    const bare = fn.args === '' || !!fn.optional;
    const at = bare
        ? before.length + insert.length
        : before.length + fn.name.length + 1;
    return {
        text: before + insert + after,
        caret: bare && !already ? before.length + insert.length : at,
    };
}

// --- what goes inside the brackets -----------------------------------------

// The words a query is written in that are not function names: the keywords,
// tags and properties actually used in the org files, and the yaml's tag
// groups, filters and collections. The server is asked for these once (see
// `useQueryVocab`); everything here only reads them.
export interface QueryVocab {
    statuses: string[];
    tags: string[];
    tagGroups: string[];
    // Commonest first, each with its most frequent values.
    properties: { name: string; count: number; values: string[] }[];
    filters: { name: string; query: string }[];
    collections: string[];
}

export const EMPTY_VOCAB: QueryVocab = {
    statuses: [], tags: [], tagGroups: [], properties: [], filters: [], collections: [],
};

// Where the caret is, as far as which argument of which call it is in.
export interface CallAt {
    // The function whose brackets the caret is inside, or '' at the top.
    fn: string;
    // Which argument, counting from 0.
    arg: number;
    // The quote the caret is inside, or -1 when it is not in a string.
    quote: number;
    // The arguments already written before this one, for MatchProperty's
    // second argument, which depends on its first.
    before: string[];
}

// Read the box from the start to the caret, keeping a stack of the calls that
// are open. A backwards scan cannot tell an opening quote from a closing one,
// which is why this goes forwards.
export function callAt(text: string, caret: number): CallAt {
    interface Frame { fn: string; arg: number; args: string[]; argStart: number }
    const stack: Frame[] = [];
    let quote = -1;
    let qc = '';
    for (let i = 0; i < caret && i < text.length; i++) {
        const c = text.charAt(i);
        if (quote >= 0) {
            if (c === '\\') { i += 1; continue; }
            if (c === qc) quote = -1;
            continue;
        }
        if (c === '"' || c === "'") { quote = i; qc = c; continue; }
        if (c === '(') {
            const { word } = wordAt(text, i);
            stack.push({ fn: word, arg: 0, args: [], argStart: i + 1 });
        } else if (c === ')') {
            stack.pop();
        } else if (c === ',' && stack.length > 0) {
            const top = stack[stack.length - 1];
            top.args.push(unquote(text.slice(top.argStart, i)));
            top.arg += 1;
            top.argStart = i + 1;
        }
    }
    const top = stack[stack.length - 1];
    return top
        ? { fn: top.fn, arg: top.arg, quote, before: top.args }
        : { fn: '', arg: 0, quote, before: [] };
}

// An argument as written, without its quotes or its escapes.
function unquote(raw: string): string {
    const t = raw.trim();
    if (t.length >= 2 && (t[0] === '"' || t[0] === "'") && t[t.length - 1] === t[0]) {
        return t.slice(1, -1).replace(/\\(.)/g, '$1');
    }
    return t;
}

// A value going into a regular expression that should match only itself.
export function escapeRe(v: string): string {
    return v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// One thing the popup can offer. Function names and the values that go inside
// them are offered by the same list, so they share a shape: what to show, and
// what to put where.
export interface Suggestion {
    key: string;
    label: string;
    // The bracket hint after a function's name; absent for a value.
    args?: string;
    group: string;
    summary: string;
    // The text replaced runs from `from` to `to`, and the caret lands `caret`
    // characters into what replaces it.
    from: number;
    to: number;
    insert: string;
    caret: number;
}

// Prefix matches first, then the ones that merely contain it - the same rule
// the function names use. Nothing typed offers everything, because inside a
// fresh `HasTags("` the whole list *is* the suggestion.
export function rank<T>(items: T[], word: string, name: (t: T) => string): T[] {
    if (word === '') return items.slice();
    const w = word.toLowerCase();
    const starts: T[] = [];
    const contains: T[] = [];
    for (const it of items) {
        const at = name(it).toLowerCase().indexOf(w);
        if (at === 0) starts.push(it);
        else if (at > 0) contains.push(it);
    }
    return starts.concat(contains);
}

// The values an argument of a function can be, or null for an argument that is
// free text (a regular expression, a date) where any list would be a guess.
function valuesFor(
    fn: string, arg: number, before: string[], v: QueryVocab,
): { group: string; items: { value: string; summary: string }[]; regex?: boolean } | null {
    const plain = (group: string, xs: string[], summary: string) =>
        ({ group, items: xs.map(x => ({ value: x, summary })) });
    switch (fn) {
        case 'IsStatus':
            return arg === 0 ? plain('Keyword', v.statuses, 'A keyword this server knows') : null;
        case 'HasTags':
            // Every argument is a tag: HasTags("work", "urgent").
            return plain('Tag', v.tags.filter(t => before.indexOf(t) < 0), 'A tag used in the org files');
        case 'InTagGroup':
            return arg === 0 ? plain('Tag group', v.tagGroups, 'A tag group from the yaml') : null;
        case 'IsPriority':
            return arg === 0 ? plain('Priority', ['A', 'B', 'C'], 'A priority cookie') : null;
        case 'IsRecord':
        case 'InCollection':
            return arg === 0 ? plain('Collection', v.collections, 'A record collection') : null;
        case 'HasProperty':
        case 'MatchProperty':
            if (arg === 0) {
                return {
                    group: 'Property',
                    items: v.properties.map(p => ({
                        value: p.name,
                        summary: `On ${p.count} heading${p.count === 1 ? '' : 's'}`
                            + (p.values.length ? ` — e.g. ${p.values.slice(0, 3).join(', ')}` : ''),
                    })),
                };
            }
            if (fn === 'MatchProperty' && arg === 1) {
                const name = (before[0] || '').toLowerCase();
                const p = v.properties.find(x => x.name.toLowerCase() === name);
                if (!p) return null;
                return { ...plain('Value', p.values, `A value ${p.name} is given`), regex: true };
            }
            return null;
        default:
            return null;
    }
}

// Every suggestion for the box as it stands. `max` caps the function names
// only: a value list scrolls, and cutting the tags at eight would hide the one
// being looked for behind the ones that sort first.
export function suggestAt(text: string, caret: number, v: QueryVocab, max: number = 8): { word: string; options: Suggestion[] } {
    const at = callAt(text, caret);

    // Inside a string: the values that argument can be.
    if (at.quote >= 0) {
        const want = valuesFor(at.fn, at.arg, at.before, v);
        if (!want) return { word: '', options: [] };
        const q = text.charAt(at.quote);
        const start = at.quote + 1;
        const word = text.slice(start, caret).replace(/\\(.)/g, '$1');
        // What is already written after the caret up to the closing quote is
        // replaced too, so picking a tag over a half-typed one does not leave
        // the tail of the old one behind.
        let end = caret;
        while (end < text.length && text.charAt(end) !== q && text.charAt(end) !== ')') end++;
        const closed = text.charAt(end) === q;
        const to = closed ? end + 1 : end;
        // A one-argument call is finished once its value is in, so the caret
        // goes past the bracket as well; MatchProperty has another to come.
        const more = at.fn === 'MatchProperty' && at.arg === 0;
        const options = rank(want.items, word, x => x.value).map(x => {
            const raw = want.regex ? escapeRe(x.value) : x.value;
            const body = q === '"'
                ? quoteForQuery(raw)
                : raw.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            const insert = body + q;
            let caretIn = insert.length;
            if (!more && text.charAt(to) === ')') caretIn += 1;
            return {
                key: `${want.group}:${x.value}`, label: x.value, group: want.group,
                summary: x.summary, from: start, to, insert, caret: caretIn,
            };
        });
        return { word, options };
    }

    // A filter: `{{ AllTasks }}`, which the server expands before it parses.
    const before = text.slice(0, caret);
    const braces = /\{\{\s*([A-Za-z_]*)$/.exec(before);
    if (braces) {
        const word = braces[1];
        const from = caret - word.length;
        let to = caret;
        while (to < text.length && /[A-Za-z_]/.test(text.charAt(to))) to++;
        const rest = text.slice(to);
        const close = /^\s*\}\}/.exec(rest);
        const options = rank(v.filters, word, f => f.name).map(f => {
            const insert = close ? f.name : `${f.name} }}`;
            return {
                key: `Filter:${f.name}`, label: f.name, group: 'Filter', summary: f.query,
                from, to: close ? to + close[0].length : to,
                insert: close ? insert + close[0] : insert,
                caret: (close ? insert + close[0] : insert).length,
            };
        });
        return { word, options };
    }

    // A name: the functions, and the filters as `{{ Name }}`.
    const { word, start } = wordAt(text, caret);
    if (word === '') return { word, options: [] };
    const fns: Suggestion[] = completionsFor(word).slice(0, max).map(fn => {
        const r = applyCompletion(text, start, caret, fn);
        const insert = r.text.slice(start, r.text.length - (text.length - caret));
        return {
            key: `fn:${fn.name}`, label: fn.name,
            args: fn.optional ? `[${fn.args}]` : fn.args,
            group: fn.group, summary: fn.summary,
            from: start, to: caret, insert, caret: r.caret - start,
        };
    });
    // Behind the functions: a filter is the less common thing to be reaching for.
    const filters: Suggestion[] = rank(v.filters, word, f => f.name).slice(0, 3).map(f => {
        const insert = `{{ ${f.name} }}`;
        return {
            key: `Filter:${f.name}`, label: insert, group: 'Filter', summary: f.query,
            from: start, to: caret, insert, caret: insert.length,
        };
    });
    return { word, options: fns.concat(filters) };
}

export function applySuggestion(text: string, s: Suggestion): { text: string; caret: number } {
    return {
        text: text.slice(0, s.from) + s.insert + text.slice(s.to),
        caret: s.from + s.caret,
    };
}

// --- brackets and quotes ----------------------------------------------------

const PAIRS: Record<string, string> = { '(': ')', '[': ']', '{': '}', '"': '"', "'": "'" };
const CLOSERS = new Set([')', ']', '}', '"', "'"]);

export interface PairEdit {
    text: string;
    caret: number;
}

// What typing one character should do, or null to let it be typed normally.
//
// Three rules, and the third is the one that makes the other two bearable:
//
// 1. An opener inserts its partner and leaves the caret between them.
// 2. Typing a closer when that closer is already under the caret steps over it
//    rather than adding a second one - otherwise auto-pairing means deleting a
//    bracket every time you finish a call by hand.
// 3. A quote is both, so it only opens when the caret is not already on one.
export function typePair(text: string, start: number, end: number, typed: string): PairEdit | null {
    const selected = text.slice(start, end);

    // Typing a closer that is already there: step over it.
    if (CLOSERS.has(typed) && selected === '' && text.charAt(start) === typed) {
        // For a quote this is also how it closes, which is why it comes first.
        return { text, caret: start + 1 };
    }

    const partner = PAIRS[typed];
    if (!partner) return null;

    // Around a selection: wrap it, and keep it selected-ish by leaving the
    // caret after what was wrapped.
    if (selected !== '') {
        return {
            text: text.slice(0, start) + typed + selected + partner + text.slice(end),
            caret: end + 2,
        };
    }

    // A quote in the middle of a word is an apostrophe, not the start of a
    // string.
    if ((typed === '"' || typed === "'") && /[A-Za-z0-9]/.test(text.charAt(start - 1))) {
        return null;
    }

    return {
        text: text.slice(0, start) + typed + partner + text.slice(end),
        caret: start + 1,
    };
}

// Backspace between a pair takes both, which is what somebody who did not want
// the pair is reaching for.
export function backspacePair(text: string, start: number, end: number): PairEdit | null {
    if (start !== end || start === 0) return null;
    const before = text.charAt(start - 1);
    const after = text.charAt(start);
    if (PAIRS[before] && PAIRS[before] === after) {
        return { text: text.slice(0, start - 1) + text.slice(start + 1), caret: start - 1 };
    }
    return null;
}

// --- putting a regular expression into a query -------------------------------

// A string that is going inside "..." in an expression.
export function quoteForQuery(re: string): string {
    return re.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// The query with a content match added, or the plain content match when there
// was no query. Written as a separate clause rather than folded into whatever
// was typed, so turning it off again takes it away cleanly.
// The same query with records left out - or put back in.
//
// A record is a contact, a piece of equipment, anything with a RECORD property
// on it, and a collection's container heading is the thing they are filed
// under. Neither is usually what somebody is searching for: a contact matches
// "jane" as readily as the task about ringing her, and there can be hundreds
// of them.
//
// Added as a clause of its own rather than folded into what was typed, so that
// turning the toggle back on takes it away again cleanly - the same reason the
// content match is a clause of its own.
export function withoutRecords(query: string, include: boolean): string {
    if (include) return query;
    const clause = '!IsRecord() && !IsCollection()';
    const q = (query || '').trim();
    return q === '' ? clause : `(${q}) && ${clause}`;
}

export function withContentMatch(query: string, re: string): string {
    const clean = (re || '').trim();
    if (clean === '') return query;
    const clause = `MatchContent("${quoteForQuery(clean)}")`;
    const q = (query || '').trim();
    return q === '' ? clause : `(${q}) && ${clause}`;
}
